// computed dashboard data (base64-encoded JSON) — injected by tools/gen_dash.py
const String _dashB64 =
    '';

Color _colOf(String? k) => _catColors[k] ?? const Color(0xFF6E6E86);
IconData _iconOf(String? k) => _catIcons[k] ?? Icons.swap_horiz_rounded;

// The merchant name a feed row's logo resolves from — the backend's canonical
// `mkey` (e.g. "chatgpt") first, else the raw bank name. CategoryIcon turns it
// into a bundled logo, a favicon, or the category tile. Never matched loosely:
// see logo_service.
String _logoOf(Map row) => (row['mkey'] ?? row['nm'] ?? '').toString();
// The resolver's guess at the merchant's own domain (dashboard.py's `dom`
// field) — CategoryIcon's fallback once the bundled set above has nothing,
// before it gives up and shows the category tile.
String? _domOf(Map row) => (row['dom'] as String?)?.trim();
String _eur(num v, {bool signed = false}) =>
    Money.format(v.toDouble(), signed: signed);

// Whole-number format (no cents) for headline balances, e.g. "7 049 €".
// Currency-aware like [Money.format]: amounts are stored in EUR, so convert to
// the chosen display currency ([Money.rate]) and show its symbol ([Money.symbol]).
String _eur0(num v) {
  final c = v.toDouble() * Money.rate;
  final digits = c.abs().round().toString();
  final b = StringBuffer();
  for (var i = 0; i < digits.length; i++) {
    if (i != 0 && (digits.length - i) % 3 == 0) b.write(' ');
    b.write(digits[i]);
  }
  return '${c < 0 ? '−' : ''}$b ${Money.symbol}';
}

// ── Safe reads of the raw per-transaction fields the backend sends.
//
// These were forced casts and bare substrings at ~10 call sites — `(t['d'] as
// String).substring(8, 10)`, `t['nm'] as String`. The backend always stamps
// these fields, but the phone also feeds this code its own cache (from an older
// build, a bank with an odd payload), and a single malformed row throwing a
// TypeError or RangeError takes the whole screen down. One row's bad data must
// cost that row, not the dashboard — so these degrade to a harmless default.
// The safe idiom (`padRight` before slicing) was already used once in this
// file; this just applies it everywhere raw rows are read.
String _dOf(Map t) => (t['d'] as String?) ?? '';
String _nmOf(Map t) => (t['nm'] as String?) ?? '';
String _ymOf(Map t) => _dOf(t).padRight(7).substring(0, 7); // 'YYYY-MM'
int _dayOf(Map t) {
  final d = _dOf(t);
  return d.length >= 10 ? (int.tryParse(d.substring(8, 10)) ?? 1) : 1;
}

// Safe amount read: a row with a missing/odd `a` (a quiet-bank or cached row)
// must degrade to 0, never crash a money aggregation.
num _aOf(Map t) {
  final v = t['a'];
  return v is num ? v : (num.tryParse('$v') ?? 0);
}

// Formats a SINGLE transaction's amount, correctly, in the user's chosen
// display currency.
//
// The backend converts every amount to EUR with an approximate, static rate
// (functions/fx.py) so it can sum mixed-currency accounts into one total.
// This screen then reconverts EUR -> the display currency with a LIVE ECB
// rate (FxRates). Round-tripping a NOK transaction through EUR with two
// rates that don't agree came out ~6% off the real number — quietly, on
// every transaction in a non-EUR account, which is exactly the account a
// non-EUR user actually watches this screen to check.
//
// When the display currency matches this row's OWN currency (`t['raw']` /
// `t['cur']`, the figure straight from the bank, added in dashboard.py) that
// exact figure is shown instead — no conversion, no rate to disagree with.
// Anything else (a different currency, or an older cached row from before
// these fields existed) falls back to the existing EUR-derived amount.
String _eurTx(Map t, {bool signed = false}) {
  final cur = (t['cur'] as String?)?.toUpperCase();
  final raw = t['raw'];
  if (cur != null && raw is num && cur == AppPrefs.currencyCode.value) {
    return _eur(Money.rate == 0 ? 0 : raw.toDouble() / Money.rate, signed: signed);
  }
  return _eur(_aOf(t).toDouble(), signed: signed);
}

// Same fix as [_eurTx], for an ACCOUNT balance instead of a transaction.
// dashboard.py's `_balance_block` now stamps `raw`/`origCurrency` (the
// account's own pre-conversion balance) alongside the EUR-converted `amount`
// — this only ever existed on transaction rows before, so a NOK/SEK/etc.
// account's headline balance was still round-tripping through two
// disagreeing rates (the ~6% drift already fixed for individual
// transactions, silently still present on the one figure a non-EUR user
// checks first).
String _eurAcct(Map a) {
  final cur = (a['origCurrency'] as String?)?.toUpperCase();
  final raw = a['raw'];
  if (cur != null && raw is num && cur == AppPrefs.currencyCode.value) {
    return _eur(Money.rate == 0 ? 0 : raw.toDouble() / Money.rate);
  }
  return _eur(((a['amount'] ?? 0) as num).toDouble());
}

// Bank subtotal across possibly several accounts. Only takes the raw-amount
// shortcut when EVERY account in the group shares one native currency (a
// mixed EUR+NOK subtotal has no single "raw" figure to show) — otherwise
// falls back to summing the EUR-converted amounts, same as before.
String _eurAcctGroup(List<Map<String, dynamic>> accts) {
  final curs = accts.map((a) => (a['origCurrency'] as String?)?.toUpperCase()).toSet();
  if (curs.length == 1) {
    final cur = curs.first;
    if (cur != null && cur == AppPrefs.currencyCode.value) {
      final rawSum = accts.fold<double?>(0, (s, a) {
        final r = a['raw'];
        return (s == null || r is! num) ? null : s + r.toDouble();
      });
      if (rawSum != null) {
        return _eur(Money.rate == 0 ? 0 : rawSum / Money.rate);
      }
    }
  }
  final subtotal =
      accts.fold(0.0, (s, a) => s + ((a['amount'] ?? 0) as num).toDouble());
  return _eur(subtotal);
}

// Safe section reads: a row with a missing/odd `sec`/`secc` (a quiet-bank or
// cached row) must degrade to a neutral bucket, never crash an aggregation with
// a `null is not a String` TypeError.
String _secOf(Map t) => (t['sec'] as String?) ?? 'Kita';
String _seccOf(Map t) => (t['secc'] as String?) ?? 'indigo';

// Safe month number (1–12) from a 'YYYY-MM…' key. A cached row with no date can
// yield a whitespace month key; int.parse('  ') throws a FormatException that
// red-screens the whole screen. Degrade to 1 instead.
int _moInt(String? key) {
  final k = key ?? '';
  final n = k.length >= 7 ? int.tryParse(k.substring(5, 7)) : null;
  return (n ?? 1).clamp(1, 12);
}

// 2026-08-30: the tracked "Grynieji" cash-on-hand balance (DashboardStore.
// manualAssets, matched by label — see _DashboardPreviewState._cashAsset's
// own doc) needs the SAME add/subtract logic from two unrelated screens:
// _openCashExpense (logging a cash expense — subtract) and _TxDetailScreen's
// ATM-withdrawal card (confirming a bank withdrawal became cash-on-hand —
// add). Top-level, not a method on either screen's State class, so both can
// call the exact same code instead of two hand-copies drifting apart.
Future<void> _deductFromCashAsset(double amountEur) async {
  final list = DashboardStore.manualAssets();
  final idx = list
      .indexWhere((a) => ((a['label'] as String?) ?? '').trim() == 'Grynieji');
  if (idx < 0) return; // nothing tracked yet — nothing to deduct from
  final current = (list[idx]['amount'] as num?)?.toDouble() ?? 0;
  final next = (current - amountEur).clamp(0.0, double.infinity);
  final updated = [...list];
  // Same "remove rather than persist a hollow €0 row" rule the manual
  // Grynieji-edit sheet's own save path uses (_promptCash).
  if (next <= 0) {
    updated.removeAt(idx);
  } else {
    updated[idx] = {...list[idx], 'amount': next};
  }
  await DashboardStore.setManualAssets(updated);
}

Future<void> _addToCashAsset(double amountEur) async {
  final list = DashboardStore.manualAssets();
  final idx = list
      .indexWhere((a) => ((a['label'] as String?) ?? '').trim() == 'Grynieji');
  final current = idx >= 0 ? ((list[idx]['amount'] as num?)?.toDouble() ?? 0) : 0.0;
  final updated = [...list];
  final entry = {
    'id': idx >= 0
        ? updated[idx]['id']
        : DateTime.now().microsecondsSinceEpoch.toString(),
    'label': 'Grynieji',
    'amount': current + amountEur,
  };
  if (idx >= 0) {
    updated[idx] = entry;
  } else {
    updated.add(entry);
  }
  await DashboardStore.setManualAssets(updated);
}

// Safe YEAR from a "YYYY-MM"/"YYYY-MM-DD" key. A blank or short month key made a
// bare `int.parse(month.substring(0,4))` throw (FormatException/RangeError) and
// red-screen the month review + Overview calendar; the month half was already
// guarded via _moInt, this closes the year half.
int _yInt(String? key) {
  final k = key ?? '';
  final n = k.length >= 4 ? int.tryParse(k.substring(0, 4)) : null;
  return n ?? DateTime.now().year;
}

// Safe reads for balance-history series points ({d: 'YYYY-MM-DD', v: num}). The
// series is a separate payload from the tx feed, so it bypasses _dOf/_aOf; a
// missing/odd `d` or `v` from a quiet-bank or cached row must degrade, never
// crash the balance chart. `_pDate` never throws (unlike DateTime.parse).
DateTime _pDate(dynamic v) => DateTime.tryParse('$v') ?? DateTime(2000, 1, 1);
double _vOf(Map p) {
  final v = p['v'];
  return v is num ? v.toDouble() : (double.tryParse('$v') ?? 0);
}

// Keep only well-formed points (parseable date + numeric value), so everything
// downstream (first/last, min/max, scrub) is guaranteed valid.
List<Map<String, dynamic>> _cleanSeries(dynamic raw) {
  if (raw is! List) return const [];
  final out = <Map<String, dynamic>>[];
  for (final e in raw) {
    if (e is! Map) continue;
    if (DateTime.tryParse('${e['d']}') == null) continue;
    if (e['v'] is! num) continue;
    out.add(Map<String, dynamic>.from(e));
  }
  return out;
}

// ── Canonical money rule — the ONE definition every screen uses so the same
// concept shows the same number everywhere (mirrors functions/dashboard.py
// _flow/_totals). Direction decides income vs expense; transfers/exchange are
// excluded from both; a refund nets spending down. NEVER raw-sum amounts for a
// displayed "net" — that double-counts transfers between the user's own accounts.
String _flowOf(Map t) {
  // Use the safe section read (a missing `sec` on an older cached row defaults to
  // 'Kita'), so a malformed credit row is treated as income, not a refund.
  final sec = _secOf(t);
  if (sec == 'Pervedimai') return 'transfer';
  if (t['cat'] == 'Grąžinimas') return 'refund';
  final a = _aOf(t);
  // Money back from a RECOGNISED spending category is a refund whatever the bank
  // called it (mirrors functions/dashboard.py _flow). Without this, a returned
  // purchase the bank didn't stamp with a refund code flipped to INCOME the moment
  // totals recomputed client-side (any manual add/edit), so net was wrong by twice
  // the refund. "Kita" is unattributed → a credit there is income (freelance /
  // interest), not a refund; Pajamos/Pervedimai never reach here as spending.
  if (a > 0 && sec != 'Pajamos' && sec != 'Pervedimai' && sec != 'Kita') {
    return 'refund';
  }
  return a > 0 ? 'income' : 'expense';
}

// A transaction's contribution to "spent": an outflow counts, a refund nets down.
double _spendOf(Map t) {
  final f = _flowOf(t);
  return (f == 'expense' || f == 'refund') ? -_aOf(t).toDouble() : 0.0;
}

double _sumExpenses(Iterable rows) =>
    rows.fold(0.0, (s, t) => s + _spendOf(t as Map));

// 2026-08-15: the week bar chart's height scale. A LINEAR v/maxV made one
// big one-off day (rent, insurance) flatten every ordinary day into an
// invisible sliver next to it — real accounts hit this constantly, not just
// as an edge case. Square root compresses that outlier while still giving
// small days a real, comparable height. _WeekAvgPainter's gridlines and
// average line use this SAME mapping so they stay aligned with the bars.
double _weekBarFrac(double v, double maxV) =>
    maxV <= 0 ? 0 : math.sqrt(v.clamp(0, double.infinity)) / math.sqrt(maxV);

/// Money that LEFT the account without being spending — a transfer to a person,
/// cash withdrawn. Drawn on the week bars so a day whose balance clearly moved
/// is never blank, and added to NO total: spending, categories, budgets and the
/// savings rate never see it.
///
/// Own-account moves and currency conversions are excluded on purpose. That
/// money never left the user, and drawing a 500 € bar for SEB → Revolut would
/// read as a 500 € spending day — a worse lie than the empty bar this fixes.
/// Mirrors `_week` in dashboard.py; the two must agree, because the filtered
/// feed recomputes here while the unfiltered one comes from the server.
double _goneOf(Map t) {
  final a = _aOf(t).toDouble();
  if (a >= 0 || _flowOf(t) != 'transfer') return 0.0;
  final cat = (t['cat'] as String?) ?? '';
  if (cat == 'Savas pervedimas' || cat == 'Valiutos keitimas') return 0.0;
  return -a;
}

double _sumIncome(Iterable rows) => rows.fold(0.0,
    (s, t) => s + (_flowOf(t as Map) == 'income' ? _aOf(t).toDouble() : 0.0));

// "Gauta" — money that actually LANDED in the account from outside: genuine
// income plus incoming transfers (P2P from people, top-ups). This is a
// DISPLAY-ONLY figure layered on top of the canonical rule; it must NEVER feed
// net / savings / budgets (those stay on _sumIncome). Refunds are excluded —
// they already net down "Išleista", so counting them here would double-represent
// the same money. Only positive legs count, so an outgoing transfer never
// reduces it.
//
// Multi-bank own-account transfers ARE neutralised — see the "Savas
// pervedimas" check below — but ONLY when the bank exposes the counterparty
// IBAN; when it doesn't, that leg still counts here, and _showReceivedBreakdown
// says so out loud rather than hiding the gap. This was reported live as a
// discrepancy ("Gauta" bigger than the "Pajamos" category, net looking like a
// third, unrelated number) — the figures were correct, but nothing on screen
// said the "Gauta" circle could be tapped for the explanation. It now carries
// a small ⓘ.
double _receivedOf(Map t) {
  // Own-account transfers (SEB → Revolut etc., tagged "Savas pervedimas" by the
  // multi-bank backend) are the user's own money moving — never "received".
  if (t['cat'] == 'Savas pervedimas') return 0.0;
  final f = _flowOf(t);
  final a = _aOf(t).toDouble();
  return (a > 0 && (f == 'income' || f == 'transfer')) ? a : 0.0;
}

double _sumReceived(Iterable rows) =>
    rows.fold(0.0, (s, t) => s + _receivedOf(t as Map));

// Breakdown sheet for "Gauta": recognised income vs everything else that came in
// (personal transfers, top-ups). Keeps the honest message that not every inflow
// is "earned" income. Shared by both Overview screens.
//
// [rows] and [monthName] are optional so old call sites (and any I've missed)
// keep compiling — but without [rows] the "Kiti pervedimai / įplaukos" figure
// is a number with nothing behind it. Reported live: "kur kiti 5k, nematau
// transakcijose" (where's the other 5k, I don't see it in transactions) — the
// figure was correct, but there was no way to see WHICH rows it came from,
// so it read as an unverifiable claim rather than real money. Tapping it now
// opens the exact rows _receivedOf counted as "other", reusing
// _CategoryDetailScreen (the same screen every category in the list already
// opens into) rather than inventing a second way to browse transactions.
void _showReceivedBreakdown(BuildContext context, double income, double other,
    {List<Map<String, dynamic>>? rows, String? monthName}) {
  final otherRows = rows == null
      ? null
      : rows
          .where((t) => _receivedOf(t) > 0 && _flowOf(t) != 'income')
          .toList();
  showModalBottomSheet(
    context: context,
    backgroundColor: _card,
    shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(22))),
    // Named, not `(_)`: the tap-through below must pop the SHEET's own route,
    // not the screen underneath it — using the outer `context` for that pop
    // would have closed Overview itself instead of the sheet.
    builder: (sheetCtx) => SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(22, 18, 22, 24),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(children: [
              Text(tr('Gauta'),
                  style: TextStyle(
                      fontSize: 20, fontWeight: FontWeight.w800, color: _ink)),
              const Spacer(),
              Text(_eur0(income + other),
                  style: TextStyle(
                      fontSize: 20, fontWeight: FontWeight.w800, color: _ink)),
            ]),
            const SizedBox(height: 4),
            Text(tr('Visi pinigai, kurie įkrito į tavo sąskaitą.'),
                style: TextStyle(fontSize: 13.5, color: _muted)),
            const SizedBox(height: 16),
            _breakdownRow(_secColor['amber']!, tr('Atpažintos pajamos'),
                tr('atlyginimas, reguliarios įplaukos'), income),
            const SizedBox(height: 12),
            _breakdownRow(
              _secColor['indigo']!,
              tr('Kiti pervedimai / įplaukos'),
              tr('pavedimai iš žmonių, papildymai'),
              other,
              onTap:
                  (otherRows == null || otherRows.isEmpty || monthName == null)
                      ? null
                      : () {
                          Navigator.of(sheetCtx)
                              .pop(); // close the sheet, not the screen behind it
                          Navigator.of(context).push(MaterialPageRoute(
                            builder: (_) => _CategoryDetailScreen(
                              section: _SecAgg(
                                  tr('Kiti pervedimai / įplaukos'), 'indigo')
                                ..net = other,
                              rows: otherRows,
                              monthName: monthName,
                            ),
                          ));
                        },
            ),
            const SizedBox(height: 16),
            Text(
                tr('Į santaupų normą įskaičiuojamos tik atpažintos pajamos — pervedimai iš kitų nelaikomi uždarbiu.'),
                style: TextStyle(fontSize: 12.5, color: _faint, height: 1.35)),
            // Said out loud rather than guessed at.
            //
            // With two banks connected, a transfer from your own SEB account to
            // your own Revolut is recognised as your own money ONLY when the bank
            // exposes the counterparty IBAN. Some do not, and that leg then
            // counts here as money received. We could try to pair it by amount
            // and date instead — but a wrong guess would hide REAL income, which
            // is the worse of the two errors, so the number stays honest and the
            // caveat is stated where the number is read.
            if (DashboardStore.bankCount > 1) ...[
              const SizedBox(height: 8),
              Text(
                  tr('Prijungus kelis bankus, pervedimai tarp tavo paties sąskaitų čia gali būti suskaičiuoti kaip įplauka, jei bankas neatskleidžia gavėjo sąskaitos.'),
                  style: TextStyle(fontSize: 12.5, color: _faint, height: 1.35)),
            ],
          ],
        ),
      ),
    ),
  );
}

Widget _breakdownRow(Color color, String title, String sub, double amount,
    {VoidCallback? onTap}) {
  final row = Row(children: [
    Container(
        width: 12,
        height: 12,
        decoration: BoxDecoration(color: color, shape: BoxShape.circle)),
    const SizedBox(width: 12),
    Expanded(
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(title,
            style: TextStyle(
                fontSize: 15, fontWeight: FontWeight.w700, color: _ink)),
        Text(sub, style: TextStyle(fontSize: 12.5, color: _muted)),
      ]),
    ),
    Text(_eur0(amount),
        style:
            TextStyle(fontSize: 16, fontWeight: FontWeight.w800, color: _ink)),
    // Only drawn when there's somewhere to go — a chevron promising a tap
    // that does nothing is worse than no chevron at all.
    if (onTap != null) ...[
      const SizedBox(width: 2),
      Icon(Icons.chevron_right_rounded, size: 18, color: _faint),
    ],
  ]);
  if (onTap == null) return row;
  return InkWell(
      borderRadius: BorderRadius.circular(10), onTap: onTap, child: row);
}

// ── Recurring lifecycle (client side) ───────────────────────────────────────
// The backend now tags each recurring stream with a lifecycle status and a
// monthly-normalized amount, and only ACTIVE bills feed the projection (a
// finished tax plan / paid-off loan drops out). These helpers read that shape
// and layer the user's manual overrides on top (Monarch/Copilot-style).

// User-given names for anonymous recurring series (e.g. an "APPLE.COM/BILL"
// stream the user labelled "ChatGPT"), keyed by the series id (sid). Cached so
// rendering doesn't re-read Hive per row; reloaded after an edit.
Map<String, String>? _subAliasCache;
Map<String, String> _subAliases() =>
    _subAliasCache ??= DashboardStore.subscriptionAliases();
void _reloadSubAliases() =>
    _subAliasCache = DashboardStore.subscriptionAliases();

/// Display name for a recurring item — the user's alias if the series is named,
/// otherwise the (shortened) merchant name.
String _recName(Map it) {
  final sid = it['sid'] as String?;
  if (sid != null) {
    final a = _subAliases()[sid];
    if (a != null && a.isNotEmpty) return a;
  }
  return _shortNm((it['name'] as String?) ?? '—');
}

/// Display name for a transaction feed row — the subscription alias if this row
/// belongs to a named recurring series (by sid), otherwise the merchant name.
String _txDisplayName(Map r) {
  final sid = r['sid'] as String?;
  if (sid != null) {
    final a = _subAliases()[sid];
    if (a != null && a.isNotEmpty) return a;
  }
  final base = (r['nm'] as String?) ?? '—';
  // A split child (see _applyTxSplits) shares its parent's name across every
  // line item — without a suffix, 3 receipt lines from one Maxima trip read
  // as 3 unrelated duplicate charges in the day feed.
  final i = r['splitIndex'] as int?, n = r['splitCount'] as int?;
  if (i != null && n != null && n > 1) return '$base (${i + 1}/$n)';
  return base;
}

/// Local "HH:MM" from the backend's UTC epoch-seconds, or null when absent.
/// Revolut carries the transaction time in its id; banks that send only a date
/// (SEB) have no `ts`, so the time simply isn't shown for them.
String? _hm(Object? ts) {
  if (ts is! int) return null;
  final d =
      DateTime.fromMillisecondsSinceEpoch(ts * 1000, isUtc: true).toLocal();
  String two(int n) => n.toString().padLeft(2, '0');
  return '${two(d.hour)}:${two(d.minute)}';
}

/// The baked "App Review" sample account's recurring items are privacy-safe
/// placeholder names (Streamly, CloudDrive, …) with no bundled logo, and no
/// bill-type items at all — fine for App Review, useless for eyeballing the
/// Prenumeratos/Sąskaitos redesign (2026-08-13), which needs real recognised
/// brands to show its logo tier and needs BOTH pools populated to show the
/// split. Swaps in a small real-brand catalogue instead, subs AND bills,
/// matching the names used in the standalone subs_sort_demo.dart /
/// bills_sort_demo.dart demos so this reads as the same picture. Gated on
/// `designPreviewFakeRecurring`, NOT `designPreviewPalette` — see that
/// flag's own doc comment for why they must stay separate. Never touches a
/// real signed-in user's actual synced data.
Map<String, dynamic> _maybePatchPreviewRecurring(Map<String, dynamic> d) {
  if (!designPreviewFakeRecurring) return d;
  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);

  // 2026-08-19: was "day X of LAST month" — predictedDueDate then rolls
  // each item forward past today independently, and whether that lands in
  // THIS month or NEXT month depends on whether X is before or after
  // TODAY'S OWN day-of-month. Since _dueDateCalendar only draws dots for
  // whichever month the EARLIEST due date falls in, items that happened to
  // roll into a different month than the others silently lost their dot —
  // "rodo kokias 5 sąskaitas bet kalendoriuje tik 1 diena pažymėta".
  // Targeting each item at a fixed, small OFFSET FROM TODAY instead — all
  // in the near future, so (bar an actual month-boundary week) they land
  // in the same month regardless of what day "today" happens to be — then
  // working out the lastCharge that predicts exactly that date is robust
  // on any day this demo is ever opened, not just the day it was written.
  String lastChargeFor(DateTime targetDue) {
    final priorMonth = DateTime(targetDue.year, targetDue.month - 1, 1);
    final clampedDay = targetDue.day
        .clamp(1, DateTime(priorMonth.year, priorMonth.month + 1, 0).day);
    return _DashboardPreviewState._ymd(
        DateTime(priorMonth.year, priorMonth.month, clampedDay));
  }

  Map<String, dynamic> item(String name, double amount, String type, int occ,
          String sid, int daysFromNow, {required bool reviewed}) =>
      {
        'name': name,
        'monthly': amount,
        'cost': amount,
        'cycle': 'monthly',
        'status': 'active',
        'active': true,
        'type': type,
        'occ': occ,
        'sid': sid,
        'lastCharge': lastChargeFor(today.add(Duration(days: daysFromNow))),
        '_reviewed': reviewed, // read below, not by _LiveItem — see note
      };
  final subs = (d['subs'] as Map?)?.cast<String, dynamic>() ?? <String, dynamic>{};
  // _dueDateCalendar only draws a dot for a date landing in the SAME month
  // as the group's own earliest due date — so each group (confirmed bills,
  // confirmed subs) needs ALL its own offsets small enough that
  // today.day + offset can't cross a month boundary on any day of the
  // month this demo happens to run. Kept under 8 for exactly that reason;
  // the pending items don't feed a calendar, so their offsets just keep
  // them a little further out, no tight bound needed.
  final items = [
    // Confirmed — the list + calendar a viewer sees immediately.
    item('Netflix', 12.99, 'subscription', 5, 'pv_netflix', 3, reviewed: true),
    item('Spotify', 9.99, 'subscription', 6, 'pv_spotify', 5, reviewed: true),
    item('Google One', 2.99, 'subscription', 4, 'pv_google_one', 7,
        reviewed: true),
    item('SEB', 420.00, 'bill', 5, 'pv_seb', 2, reviewed: true),
    item('Ignitis', 45.20, 'bill', 6, 'pv_ignitis', 4, reviewed: true),
    item('Telia', 24.99, 'bill', 6, 'pv_telia', 6, reviewed: true),
    // Left unreviewed on purpose — "Rasti naują prenumeratą/sąskaitą" needs
    // real candidates to show, or it opens on a blank list. Marking every
    // fake item reviewed (the previous fix) solved the confirmed view but
    // broke this one; some of each pool has to stay pending.
    item('Apple Music', 10.99, 'subscription', 5, 'pv_apple_music', 10,
        reviewed: false),
    item('Apple Pay', 4.99, 'subscription', 4, 'pv_apple_pay', 12,
        reviewed: false),
    item('Vilniaus vandenys', 18.40, 'bill', 4, 'pv_vandenys', 9,
        reviewed: false),
    item('Lietuvos draudimas', 12.50, 'bill', 3, 'pv_ld', 11, reviewed: false),
  ];
  // _LiveItem.reviewed (subs_bills_live.dart) reads DashboardStore's own
  // persisted "reviewed" set, not anything on the raw item map — a fake
  // sid nobody has ever actually reviewed reads as unreviewed forever,
  // which is what put LiveRecurringScreen into its "Rask savo sąskaitas"
  // candidate-review empty state instead of the real confirmed-list view
  // every time the demo opened it. Marking the CONFIRMED half reviewed
  // here — fire and forget, this is a local Hive write that only ever
  // runs under designPreviewFakeRecurring — makes that half of the fake
  // catalogue look like an account someone has actually used; the other
  // half stays pending on purpose (see above). `_reviewed` was only ever
  // this function's own marker — stripped back off before the items reach
  // any real UI/storage code, none of which expects it.
  for (final it in items) {
    final sid = it['sid'] as String;
    if (it.remove('_reviewed') == true) {
      DashboardStore.markRecurringReviewed(sid);
    } else {
      // Explicitly cleared, not just left alone — an EARLIER run of this
      // same demo (before a sid moved from the confirmed half to the
      // pending half, or on a simulator/device that already ran an older
      // build) may have marked it reviewed already, and Hive remembers
      // that across launches. Without this, a sid meant to stay pending
      // could keep reading as reviewed forever.
      DashboardStore.unmarkRecurringReviewed(sid);
    }
  }
  subs['items'] = items;
  d['subs'] = subs;
  return d;
}

/// The backend `subs.items` as typed maps
/// ({name, monthly, cost, cycle, status, active, type, occ, lastCharge}).
/// Tolerant of the legacy baked-preview shape (a `[name, cost]` pair) so the
/// standalone design preview keeps rendering.
List<Map<String, dynamic>> _recItems(Map subs) {
  final raw = (subs['items'] as List?) ?? const [];
  return raw.map<Map<String, dynamic>>((e) {
    if (e is Map) return e.cast<String, dynamic>();
    if (e is List && e.length >= 2) {
      return {
        'name': e[0],
        'monthly': e[1],
        'cost': e[1],
        'cycle': 'monthly',
        'status': 'active',
        'active': true,
        'type': 'subscription',
        'occ': 0,
      };
    }
    return {'name': '—', 'monthly': 0, 'active': false, 'type': 'subscription'};
  }).toList();
}

/// The EFFECTIVE type of a recurring stream — the user's reclassification
/// (subscription <-> bill) if set, otherwise the engine's guess.
String _recType(Map it) {
  final sid = it['sid'] as String?;
  if (sid != null) {
    final o = DashboardStore.recurringTypes()[sid];
    if (o != null) return o;
  }
  return (it['type'] as String?) ?? 'subscription';
}

/// Backend recurring items PLUS the user's hand-added manual entries — the full
/// set shown and totalled everywhere the recurring block appears.
///
/// A manual entry only stands in until the backend confirms the same merchant
/// as a real stream (≥2 occurrences) — once it does, the real item takes over
/// (no duplicate row), but keeps the bill/subscription type the user picked by
/// hand, so a payment they classified once doesn't ask again the next time it
/// recurs automatically.
List<Map<String, dynamic>> _recItemsFull(Map subs) {
  final real = _recItems(subs);
  final manual = DashboardStore.manualRecurring();
  final manualByName = <String, Map<String, dynamic>>{
    for (final e in manual) _fold(((e['name'] as String?) ?? '').trim()): e,
  };
  final matched = <String>{};
  for (final it in real) {
    final key = _fold(((it['name'] as String?) ?? '').trim());
    final m = manualByName[key];
    if (m != null) {
      matched.add(key);
      it['type'] = m['type'] ?? it['type'];
      if (m['category'] != null) it['category'] = m['category'];
    }
  }
  final onlyManual = manual.where(
      (e) => !matched.contains(_fold(((e['name'] as String?) ?? '').trim())));
  return [...real, ...onlyManual];
}

/// Whether a stream counts toward the monthly commitment: the backend says it's
/// an ACTIVE bill (not a transfer), unless the user overrode that verdict.
/// A key for the user's verdict on a recurring stream that SURVIVES re-detection.
///
/// `sid` is an ordinal the backend assigns while splitting a merchant's payments
/// into streams (`recurring.py` emits `key#0`, `key#1`, …). One more transaction
/// re-splits the group and every ordinal after it shifts — so the fast 3-month
/// scan and the deeper 12-month scan that replaces it produce DIFFERENT sids for
/// the same stream. Every verdict was stored under the old sid and silently
/// stopped matching: the review sheet asked the same three questions again right
/// after a bank connect, and worse, a payment the user had removed came back into
/// the monthly total.
///
/// Name + monthly amount is stable across a re-split and still separates the case
/// a plain name key got wrong (iCloud €2.99 vs Apple One €19.95 share a name).
// NOT tr('Sąskaita') — that key already means "Bill" (a recurring-bill badge
// on a transaction row, see _badge/dashboard.py's "rec" tag), a different
// Lithuanian word that happens to be spelled the same as this one's meaning:
// a bank ACCOUNT's own fallback display name when it has neither a bank
// label nor its own name. Same collision, same fix as the plural "Sąskaitos"
// pill (_heroAccountsButton) — branch on locale directly instead of reusing
// the taken key. Top-level (not a State method) since it's needed from
// several different screens' classes, not just one.
String acctFallbackName() =>
    effectiveLocale().languageCode == 'en' ? 'Account' : 'Sąskaita';

String _recKey(Map it) {
  // The backend's series id, which is now built to survive exactly the things
  // that used to move it: a deeper scan changing the average, a price rise, the
  // streams being re-split (see _series_id in dashboard.py — merchant + cadence
  // + an amount BAND, not the exact cents).
  //
  // The client used to key verdicts on `name|monthly` to two decimals. That is
  // the same mistake one layer up: `monthly` is an average, so it shifts when
  // the window shifts — which incremental sync does on every refresh, and
  // connecting another bank does again. Each shift silently discarded every
  // decision the user had made, and the review sheet asked the same questions
  // for the fourth time.
  final sid = ((it['sid'] as String?) ?? '').trim();
  if (sid.isNotEmpty) return sid;
  // Only for a payload old enough to carry no sid.
  final name = ((it['name'] as String?) ?? '').trim().toLowerCase();
  if (name.isEmpty) return '';
  final monthly = ((it['monthly'] ?? 0) as num).toDouble();
  return '$name|${monthly.toStringAsFixed(2)}';
}

/// True when [set] holds a verdict for this stream under EITHER key: the stable
/// one, or the sid a previous build stored it under. Keeps decisions already on
/// the device working instead of silently resetting them all once.
bool _recHasVerdict(Set<String> set, Map it) =>
    _recAliases(it).any(set.contains);

/// Every key this stream may already be stored under: the old positional sid and
/// the bare lowercase name that even earlier builds used. A write must clear ALL
/// of them, or a stale entry keeps winning the lookup — see setRecurringOverride.
List<String> _recAliases(Map it) {
  final name = ((it['name'] as String?) ?? '').trim().toLowerCase();
  final monthly = ((it['monthly'] ?? 0) as num).toDouble();
  return [
    _recKey(it),
    ((it['sid'] as String?) ?? '').trim(),
    // The two shapes earlier builds wrote: name|monthly, and the bare name.
    if (name.isNotEmpty) '$name|${monthly.toStringAsFixed(2)}',
    name,
  ].where((s) => s.isNotEmpty).toSet().toList();
}

bool _recCounted(Map it, Set<String> excl, Set<String> incl) {
  // A transfer (person-to-person, own-account, exchange) is NEVER a commitment —
  // not even if the user tapped "keep" on it. This check must come FIRST: letting
  // `incl` override it let one tap on a person's row add their transfer to the
  // monthly total. (The backend already drops transfers from the list; this is
  // the belt-and-braces for any older cached dashboard that still carries one.)
  if (it['type'] == 'transfer') return false;
  // Keyed by name+amount, not by name alone: same-merchant streams at different
  // prices must be toggled independently (a name key turned both off). Both the
  // stable key and the legacy sid are honoured — see _recKey.
  if (_recHasVerdict(excl, it)) return false;
  if (_recHasVerdict(incl, it)) return true;
  return it['active'] == true;
}

double _recMonthlyTotal(
        List<Map<String, dynamic>> items, Set<String> excl, Set<String> incl) =>
    items.fold(
        0.0,
        (s, it) =>
            s +
            (_recCounted(it, excl, incl)
                ? ((it['monthly'] ?? 0) as num).toDouble()
                : 0.0));

List<String> _recStatusMeta(String? status) {
  // label + whether it reads as "live"
  switch (status) {
    case 'active':
      return ['Aktyvus', '1'];
    case 'late':
      return ['Vėluoja', '0'];
    case 'ended':
      return ['Baigėsi', '0'];
    case 'early':
      return ['Naujas', '0'];
    default:
      return ['', '0'];
  }
}

String _recCycleLabel(String? cycle) {
  switch (cycle) {
    case 'weekly':
      return 'kas savaitę';
    case 'quarterly':
      return 'kas ketvirtį';
    case 'yearly':
      return 'kas metus';
    default:
      return 'kas mėnesį';
  }
}

const _recMonLt = [
  '',
  'sausio',
  'vasario',
  'kovo',
  'balandžio',
  'gegužės',
  'birželio',
  'liepos',
  'rugpjūčio',
  'rugsėjo',
  'spalio',
  'lapkričio',
  'gruodžio'
];

// "kas mėnesį · paskutinį kartą liepos 14 · ×6" — helps the user judge each row.
String _recDetail(Map it) {
  final parts = <String>[tr(_recCycleLabel(it['cycle'] as String?))];
  final last = it['lastCharge'] as String?;
  final d = last != null ? DateTime.tryParse(last) : null;
  if (d != null) {
    final mon = _enUi ? _monAbbrEn[d.month - 1] : _recMonLt[d.month];
    parts.add('${tr('paskutinį kartą')} $mon ${d.day}');
  }
  final occ = ((it['occ'] ?? 0) as num).toInt();
  if (occ >= 2) parts.add('×$occ');
  return parts.join(' · ');
}

// Correct Lithuanian plural for "aktyvus" (1 aktyvus · 2–9 aktyvūs · 10–20 /
// 0 aktyvių), so a tile never reads "1 aktyvūs".
String _ltActive(int n) {
  final t = n % 100;
  if (t >= 11 && t <= 19) return 'aktyvių';
  switch (n % 10) {
    case 1:
      return 'aktyvus';
    case 2:
    case 3:
    case 4:
    case 5:
    case 6:
    case 7:
    case 8:
    case 9:
      return 'aktyvūs';
    default:
      return 'aktyvių';
  }
}

String _activeLabel(int n) => _enUi ? '$n active' : '$n ${_ltActive(n)}';

// A category glyph for a recurring row's tile (CategoryIcon falls back to this
// when no bundled brand logo resolves). Keyed by the backend `category` string.
IconData _reviewCatIcon(String? cat) {
  switch (cat) {
    case 'food':
      return Icons.restaurant_rounded;
    case 'fuel':
    case 'transport':
    case 'vehicle':
      return Icons.local_gas_station_rounded;
    case 'shopping':
      return Icons.shopping_bag_rounded;
    case 'housing':
      return Icons.home_rounded;
    case 'connectivity':
      return Icons.wifi_rounded;
    case 'entertainment':
      return Icons.play_circle_fill_rounded;
    case 'health':
    case 'fitness':
      return Icons.favorite_rounded;
    case 'finance':
    case 'taxes':
    case 'invest':
      return Icons.account_balance_rounded;
    case 'edu':
      return Icons.school_rounded;
    default:
      return Icons.autorenew_rounded;
  }
}

// Lowercase + strip Lithuanian diacritics so search matches "ivairus" ↔ "įvairūs".
String _fold(String s) {
  const m = {
    'ą': 'a',
    'č': 'c',
    'ę': 'e',
    'ė': 'e',
    'į': 'i',
    'š': 's',
    'ų': 'u',
    'ū': 'u',
    'ž': 'z'
  };
  final b = StringBuffer();
  for (final ch in s.toLowerCase().split('')) {
    b.write(m[ch] ?? ch);
  }
  return b.toString();
}

// 2026-08-16: merges the SAME merchant even when the bank's own name string
// varies between transactions — "MB Artusgrupė" and "Artus Grupė, MB" showed
// up as two separate top-merchant entries because _fold (case/diacritics
// only) still leaves word order and spacing different. Drops legal-entity
// tokens (MB, UAB, AB...), which move around between statements, then
// collapses everything else down to bare letters/digits — order and
// spacing stop mattering, only the actual name does.
const _legalEntityTokens = {
  'mb', 'uab', 'ab', 'vsi', 'ii', 'oy', 'ltd', 'gmbh', 'inc', 'llc', 'as',
  'sia', 'sp', 'zoo', 'sarl', 'kg', 'plc'
};

// A token carrying a 2+ digit run is a bank-baked store/terminal/card id
// ("X587", "0042"), not part of the brand itself — mirrors the exact same
// gate functions/dashboard.py's _classify uses for the server-side display
// name (see that file's NAME_OVERRIDES branch), so "Maxima Lt X587" (one
// bank) and "Maxima" (another) collapse to the same key here too, not just
// the same server-side display string. Gated at 2+ digits specifically so
// a genuine digit-bearing brand ("7-Eleven") is untouched — its "7" token
// has only one digit and survives.
final _merchantNoiseToken = RegExp(r'\d{2,}');

String _merchantKey(String name) {
  final words = _fold(name)
      .split(RegExp(r'[^a-z0-9]+'))
      .where((w) => w.isNotEmpty)
      .toList();
  final kept = words
      .where((w) =>
          !_legalEntityTokens.contains(w) && !_merchantNoiseToken.hasMatch(w))
      .join();
  return kept.isNotEmpty ? kept : words.join();
}

// 2026-08-16: user-confirmed salary sources (picked "Atlyginimas" once from a
// transaction's category sheet — see _pickCategory) get re-stamped as income
// on EVERY matching row, not just the one that was tapped. A bank that codes
// a recurring salary as a plain top-up/transfer (see _flowOf) hid it from
// every income figure otherwise; the server's own auto-detection
// (functions/dashboard.py _salary_sources) only kicks in once the SAME
// counterparty has posted in >=2 distinct months, so a fresh connection or
// an irregularly-timed payer could stay invisible indefinitely without this.
// Only a POSITIVE amount can be a salary credit (an outgoing payment to the
// same name is never touched), and a row already filed under 'Pajamos' is
// left alone rather than relabelled to the generic "Atlyginimas".
void _applySalaryRefs(List<Map<String, dynamic>> all, Set<String> refs) {
  for (final t in all) {
    if (_secOf(t) == 'Pajamos') continue;
    if (_aOf(t) <= 0) continue;
    if (!refs.contains(_merchantKey(_nmOf(t)))) continue;
    t['sec'] = 'Pajamos';
    t['secc'] = 'amber';
    t['col'] = 'income';
    t['ic'] = 'income';
    t['cat'] = 'Atlyginimas';
  }
}

// 2026-08-16: PHASE 1 of receipt-line-item splitting — turns one purchase
// into several separately-categorised rows sharing its date. Modeled as
// REPLACING the parent row(s) with one new row per item (parent + child
// transactions, the same pattern Copilot Money/Monarch/Lunch Money all use)
// rather than a hidden "splits" field on the original — every existing
// consumer (budgets, the category donut, month totals, search) already sums
// `all` by iterating rows, so nothing else needs to know splits exist.
// Idempotent by construction (removes any of ITS OWN earlier output for the
// same key first, via the 'splitGroup' tag), so it's safe to call more than
// once on the same list.
void _applyTxSplits(
    List<Map<String, dynamic>> all, Map<String, Map<String, dynamic>> splits) {
  if (splits.isEmpty) return;
  final byGroup = <String, List<Map<String, dynamic>>>{};
  for (final r in all) {
    if (r['splitGroup'] != null) continue; // never re-group a split child
    byGroup.putIfAbsent('grp:${r['mkey']}|${r['d']}', () => []).add(r);
  }
  final toRemove = <Map<String, dynamic>>[];
  final toAdd = <Map<String, dynamic>>[];
  splits.forEach((key, entry) {
    final items = (entry['items'] as List?)?.cast<Map>() ?? const [];
    if (items.isEmpty) return;
    toRemove.addAll(all.where((r) => r['splitGroup'] == key));
    final genuine = key.startsWith('grp:')
        ? (byGroup[key] ?? const <Map<String, dynamic>>[])
        : all
            .where((r) =>
                r['splitGroup'] == null && DashboardStore.txIdentity(r) == key)
            .toList();
    toRemove.addAll(genuine);
    final base = genuine.isNotEmpty
        ? genuine.first
        : (entry['parent'] as Map?)?.cast<String, dynamic>();
    if (base == null) return; // nothing to anchor the split's date/mkey to
    for (var i = 0; i < items.length; i++) {
      final it = items[i];
      toAdd.add({
        ...base,
        'mkey': '${base['mkey']}__split$i',
        'nm': it['label'] ?? base['nm'],
        // The merchant name BEFORE the per-item override above — kept so the
        // feed can collapse all of this receipt's children back into one row
        // showing "Rimi -8,51 €" instead of every product as its own row
        // (see _monthFeed's day-merge, keyed by splitGroup for these rows).
        'splitMerchant': base['nm'],
        'a': it['amt'],
        // 'raw'/'cur' are the ORIGINAL (pre-split) bank transaction's own
        // native-currency figure, inherited from `...base` above. _eurTx
        // prefers 'raw'/'cur' over 'a' whenever 'cur' matches the display
        // currency — so left as-is, every split child showed the PARENT's
        // full receipt total instead of its own item price (every row on a
        // split receipt rendering identically, at the pre-split total).
        // Nulled here so _eurTx always falls back to the per-item 'a'.
        'raw': null,
        'cur': null,
        'cat': it['cat'],
        'sec': it['sec'],
        'secc': it['secc'],
        'col': it['col'],
        'ic': it['ic'],
        'splitGroup': key,
        'splitIndex': i,
        'splitCount': items.length,
        'star': false,
      });
    }
  });
  all.removeWhere(toRemove.contains);
  all.addAll(toAdd);
}

// 2026-08-16: shared by both scan entry points — the per-transaction
// "Skenuoti kvitą" button inside _SplitTransactionScreen, and Home's
// standalone _receiptScanBanner (which doesn't know which transaction it
// is yet).
// 2026-08-17: was gallery-only, no camera option. Reversed per request —
// unlike the profile photo (a "photograph yourself" flow, kept gallery-only
// deliberately), photographing a RECEIPT is exactly what NSCameraUsageDescription
// already in Info.plist describes ("kad nufotografuotum kvitą…") and is the
// standard, App-Review-safe pattern every receipt/expense-scanning app uses.
// `source` is chosen up front by _chooseReceiptSource's sheet. Returns null
// on a cancelled/failed picker (not an error, caller shows nothing).
// 2026-08-17: split off from the combined pick+scan function it used to be
// — with ImageSource.camera, calling this WHILE the "Skenuojama…" dialog
// was already on screen (the old order: show dialog, then pick) meant the
// native camera view controller was being presented on top of an active
// Flutter overlay route. On device that suppressed the system camera-
// permission prompt entirely — tapping "Fotografuoti" visibly did nothing
// ("neišmeta prašymo leidimo"). Picking now happens BEFORE any dialog is
// shown; _scanReceiptFlow shows "Skenuojama…" only once a photo already
// exists, wrapping just the backend OCR wait it was always meant for.
Future<XFile?> _pickReceiptFile({required ImageSource source}) async {
  try {
    return await ImagePicker()
        .pickImage(source: source, maxWidth: 1600, imageQuality: 85);
  } catch (_) {
    return null;
  }
}

// The backend half of the old combined function — throws BankingException
// same as every other BankingService call on a real network/server failure.
// Not nullable: unlike the picker, BankingService.scanReceipt() always
// either returns a result or throws.
Future<(List<Map<String, dynamic>>, double, String?)> _scanReceiptFile(
    XFile file) async {
  final bytes = await file.readAsBytes();
  final mediaType =
      file.name.toLowerCase().endsWith('.png') ? 'image/png' : 'image/jpeg';
  return BankingService.instance
      .scanReceipt(imageB64: base64Encode(bytes), mediaType: mediaType);
}

// Shared by every "Kvitas"/receipt-scan entry point (Home, Bill Split) — one
// sheet, same two options everywhere. Returns null if the sheet is
// dismissed without a choice, same "cancelled, not an error" contract as
// _pickReceiptFile itself.
Future<ImageSource?> _chooseReceiptSource(BuildContext context) =>
    showModalBottomSheet<ImageSource>(
      context: context,
      backgroundColor: _card,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(22))),
      builder: (ctx) => SafeArea(
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          const SizedBox(height: 8),
          ListTile(
            leading: Icon(Icons.camera_alt_outlined, color: _purple),
            title: Text(tr('Fotografuoti'), style: TextStyle(color: _ink)),
            onTap: () => Navigator.pop(ctx, ImageSource.camera),
          ),
          ListTile(
            leading: Icon(Icons.photo_outlined, color: _purple),
            title: Text(tr('Pasirinkti iš galerijos'),
                style: TextStyle(color: _ink)),
            onTap: () => Navigator.pop(ctx, ImageSource.gallery),
          ),
          const SizedBox(height: 8),
        ]),
      ),
    );

void _toastAt(BuildContext context, String m) =>
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(SnackBar(
          content: Text(m), duration: const Duration(milliseconds: 3300)));

// 2026-09-01: real design decision — the "Grynieji"/"Kvitas" explainers
// don't gate on a one-time "seen it" flag at all (that flag used to mark
// itself seen the instant the screen was shown, even if the user just
// closed it via X without doing anything — so someone who opened it,
// got confused, and left would never see the explanation again). Instead
// this mirrors exactly how the Investing tab's own empty state already
// works: it shows every time, for as long as the user hasn't actually
// COMPLETED the thing it's explaining, and stops for good the moment they
// have — a real usage milestone, not a "did they glance at this once" flag.
bool get _hasLoggedCashTx =>
    DashboardStore.manualTxs().values.any((tx) => tx['cashSrc'] == true);

// 2026-08-31: real bug, reported — _FeatureIntroScreen's darkening overlay
// used the app's own theme-switchable `_bg`, which in LIGHT mode is a
// near-white colour (0xFFEEF1F7). Since that overlay goes fully OPAQUE for
// the bottom half of the screen (by design — same gradient shape as
// investing_tab.dart's _emptyIntro, so the photo has a solid backdrop for
// the white text), light mode painted a solid white block over most of the
// photo. This screen is always a dark full-bleed photo with light text,
// independent of the app's own theme — same reasoning as investing_tab.dart
// keeping its own _Pal permanently dark regardless of _darkMode — so it
// needs a FIXED dark colour here, never the theme variable.
const Color _kIntroBg = Color(0xFF0A0A0F);

// 2026-08-31: real bug, reported — `_purple` is a theme-switchable variable
// (see _applyTheme) that happens to already BE blue in light mode
// (0xFF2F6BFF) but turns genuinely purple in dark mode (0xFF8B5CF6) — so
// these screens looked fine in light mode purely by coincidence and went
// visibly purple in dark mode. Investing's own welcome screen never has
// this problem because investing_tab.dart's whole _Pal is a fixed, always-
// dark palette with its OWN always-blue accent (p.blue, 0xFF2F7CF6),
// independent of app theme entirely. Matching that exact value here so both
// screens read as the same accent regardless of theme, same reasoning as
// _kIntroBg above.
const Color _kIntroAccent = Color(0xFF2F7CF6);

// Shared full-screen "what does this button do" explainer — same full-bleed
// photo + darkened-bottom-text layout as the Investing tab's own welcome
// screen (investing_tab.dart's _emptyIntro), reused here for the Home hero's
// "Kvitas"/"Grynieji" quick actions so a first-ever tap explains itself
// instead of dropping straight into a picker or a bottom sheet. Pops `true`
// on the CTA (caller proceeds with the real action), `false` if dismissed
// via the close button (caller stops — the user just wanted to read it).
//
// `asset` is allowed to not exist yet on disk: errorBuilder falls back to a
// plain tinted gradient so the flow (and the flags in DashboardStore) can be
// built/tested before the real photo is dropped into assets/onboarding/.
class _FeatureIntroScreen extends StatefulWidget {
  const _FeatureIntroScreen({
    required this.asset,
    required this.accent,
    this.eyebrow = '',
    this.headline = '',
    this.subtitle = '',
    this.trustRows = const [],
    this.ctaLabel = '',
    this.imageShiftFraction = 0,
    this.showText = true,
  });

  final String asset;
  final String eyebrow;
  final Color accent;
  final String headline;
  final String subtitle;
  final List<(IconData, String)> trustRows;
  final String ctaLabel;
  // Fraction of the screen height to shift the photo UP by (crops more off
  // the top, exposes more of the photo's own bottom) — tune per-photo since
  // where the actual subject sits varies image to image.
  final double imageShiftFraction;
  // 2026-08-31: TEMPORARY — while the design is being built up step by step,
  // plain `false` shows just the photo with no text/darkening at all (tap
  // anywhere to continue). Flip back on once there's copy to show again.
  final bool showText;

  @override
  State<_FeatureIntroScreen> createState() => _FeatureIntroScreenState();
}

class _FeatureIntroScreenState extends State<_FeatureIntroScreen> {
  // 2026-08-31: real bug, reported — the CTA button sits close to where the
  // hero button that opened this screen was tapped, and this route replaces
  // the previous one instantly (no async gap). That let the SAME tap the
  // user was still completing land on the new screen's own CTA a frame
  // later, "skipping" the explainer before it was ever actually seen — the
  // user tapped "Grynieji" and landed straight on the chooser sheet with no
  // perceptible pause. Ignoring all input for a short beat after this screen
  // first appears makes that impossible regardless of tap speed or position.
  var _ready = false;

  @override
  void initState() {
    super.initState();
    Future.delayed(const Duration(milliseconds: 500), () {
      if (mounted) setState(() => _ready = true);
    });
  }

  @override
  Widget build(BuildContext context) => Scaffold(
        backgroundColor: _kIntroBg,
        body: IgnorePointer(
          ignoring: !_ready,
          child: LayoutBuilder(
            builder: (context, constraints) {
              final h = constraints.maxHeight;
              return Stack(
                fit: StackFit.expand,
                children: [
                  Positioned(
                    // Bug, reported — a plain `top: -h*shift` with the SAME
                    // height `h` leaves the box's BOTTOM edge short of the
                    // screen's own bottom by exactly the shift amount,
                    // exposing the raw Scaffold background as a solid block
                    // there. Extending the height by the same shift keeps
                    // the bottom pinned to the screen edge while the top
                    // still moves up — the photo now always reaches both
                    // edges regardless of shift.
                    top: -h * widget.imageShiftFraction,
                    left: 0,
                    right: 0,
                    height: h * (1 + widget.imageShiftFraction),
                    child: Image.asset(
                      widget.asset,
                      fit: BoxFit.cover,
                      errorBuilder: (_, __, ___) => DecoratedBox(
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
