                  // backdrop by 0.54, just before the text block starts.
                  if (widget.showText)
                    DecoratedBox(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                          stops: const [0.0, 0.44, 0.54, 1.0],
