// 2026-09-01: real gap, found in audit — a scanned receipt photo is sent to
// Anthropic (functions/receipt_scan.py) to read it, but unlike the app's
// other two uses of the same AI provider (chat, merchant categorisation —
// both gated behind an explicit one-time disclosure dialog, see
// _ensureAiChatConsent-equivalent above / _toggleAiCat), scanning had no
// disclosure at all. Same shape, same one-time dialog pattern, gates every
// scan (not just the first successful one — declining here must actually
// stop the scan from happening).
Future<bool> _ensureReceiptScanConsent(BuildContext context) async {
  if (AppPrefs.receiptScanConsent) return true;
  final ok = await showDialog<bool>(
    context: context,
    barrierDismissible: false,
    builder: (ctx) => AlertDialog(
      backgroundColor: _card,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22)),
      title: Text(tr('Kvito skenavimas'),
          style:
              TextStyle(fontWeight: FontWeight.w800, color: _ink, fontSize: 19)),
      content: Text(
        tr('Kad atpažintų prekes ir sumą, „Vaultie" siunčia NUFOTOGRAFUOTĄ kvitą '
            'mūsų AI tiekėjui (Anthropic).\n\n'
            '• Nuotrauka NIEKUR neišsaugoma — panaudota atpažinimui ir iškart pašalinama.\n'
            '• Siunčiama tik pati kvito nuotrauka, jokių kitų tavo duomenų.'),
        style: TextStyle(color: _muted, height: 1.5, fontSize: 14.5),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(ctx, false),
          child: Text(tr('Atšaukti'), style: TextStyle(color: _muted)),
        ),
        TextButton(
          onPressed: () => Navigator.pop(ctx, true),
          child: Text(tr('Sutinku ir tęsiu'),
              style: TextStyle(color: _purple, fontWeight: FontWeight.w800)),
        ),
      ],
    ),
  );
  if (ok == true) await AppPrefs.setReceiptScanConsent(true);
  return ok == true;
}

// Top-level (not tied to _DashboardPreviewState) so both Home's own
// "Skenuoti kvitą" and Bill Split's entry (_BillSplitHomeScreen, a
// different screen entirely) share ONE implementation of "show the
// scanning dialog, pick+scan a photo, handle every failure the same way".
// Returns null on a cancelled picker or a failure already toasted to the
// user — the caller has nothing further to do in either case.
Future<(List<Map<String, dynamic>>, double, String?)?> _scanReceiptFlow(
    BuildContext context) async {
  if (!await _ensureReceiptScanConsent(context)) return null;
  if (!context.mounted) return null;
  final source = await _chooseReceiptSource(context);
  if (source == null || !context.mounted) return null; // sheet dismissed
  // Pick BEFORE showing the scanning dialog — see _pickReceiptFile's doc for
  // why (a native camera view controller presented over an active Flutter
  // dialog route suppressed iOS's own permission prompt on device).
  final file = await _pickReceiptFile(source: source);
  if (file == null || !context.mounted) return null; // picker cancelled
  // showGeneralDialog with an explicit fade (not plain showDialog) —
  // showDialog's default Material transition scales the card in from a
  // squashed rectangle, which read fine over Home's light backdrop but on
  // Bill Split's pure-black screens (_billBg) that in-between frame showed
  // as a stray white sliver, and the default ~54%-alpha barrier let the
  // screen's own buttons ghost through behind the card instead of the
  // screen just going quietly dark. A near-opaque barrier + a plain fade
  // looks calm and consistent regardless of what screen is behind it.
  showGeneralDialog(
    context: context,
    barrierDismissible: false,
    barrierLabel: '',
    barrierColor: Colors.black.withValues(alpha: 0.82),
    transitionDuration: const Duration(milliseconds: 220),
    pageBuilder: (_, __, ___) => const _ScanningDialog(),
    transitionBuilder: (_, anim, __, child) => FadeTransition(
      opacity: CurvedAnimation(parent: anim, curve: Curves.easeOut),
      child: child,
    ),
  );
  List<Map<String, dynamic>> items = const [];
  double total = 0;
  String? merchant;
  String? error;
  try {
    final res = await _scanReceiptFile(file);
    items = res.$1;
    total = res.$2;
    merchant = res.$3;
  } on BankingException catch (e) {
    error = e.message;
  } catch (_) {
    error = tr('Nepavyko atpažinti kvito — pabandyk kitą nuotrauką');
  }
  if (!context.mounted) return null;
  Navigator.of(context, rootNavigator: true).pop(); // close the spinner
  if (error != null || items.isEmpty) {
    _toastAt(
        context, error ?? tr('Nepavyko atpažinti kvito — pabandyk kitą nuotrauką'));
    return null;
  }
  return (items, total, merchant);
}

// 2026-08-16: was a plain CircularProgressIndicator + "Skenuojama…" —
// looked too basic for a call that can genuinely take up to ~100s (see
// receipt_scan.py's timeouts). A viewfinder frame with a real scanning
// beam sweeping over it reads as "something is actually happening", not
// just a generic spinner shared with every other loading state in the app.
class _ScanningDialog extends StatefulWidget {
  const _ScanningDialog();
  @override
  State<_ScanningDialog> createState() => _ScanningDialogState();
}

class _ScanningDialogState extends State<_ScanningDialog>
    with SingleTickerProviderStateMixin {
  late final AnimationController _ctl = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 1700))
    ..repeat(reverse: true);

  @override
  void dispose() {
    _ctl.dispose();
    super.dispose();
  }

  Widget _corner({required bool top, required bool left}) => Positioned(
        top: top ? -3 : null,
        bottom: top ? null : -3,
        left: left ? -3 : null,
        right: left ? null : -3,
        child: Container(
          width: 18,
          height: 18,
          decoration: BoxDecoration(
            border: Border(
              top: top
                  ? BorderSide(color: _purple, width: 2.5)
                  : BorderSide.none,
              bottom: !top
                  ? BorderSide(color: _purple, width: 2.5)
                  : BorderSide.none,
              left: left
                  ? BorderSide(color: _purple, width: 2.5)
                  : BorderSide.none,
              right: !left
                  ? BorderSide(color: _purple, width: 2.5)
                  : BorderSide.none,
            ),
            borderRadius: BorderRadius.only(
              topLeft: top && left ? const Radius.circular(6) : Radius.zero,
              topRight: top && !left ? const Radius.circular(6) : Radius.zero,
              bottomLeft:
                  !top && left ? const Radius.circular(6) : Radius.zero,
              bottomRight:
                  !top && !left ? const Radius.circular(6) : Radius.zero,
            ),
          ),
        ),
      );

  @override
  Widget build(BuildContext context) {
    const w = 108.0, h = 132.0;
    return Dialog(
      backgroundColor: _card,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(28, 30, 28, 26),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          SizedBox(
            width: w,
            height: h,
            child: Stack(clipBehavior: Clip.none, children: [
              // The "receipt" — a few grey bars standing in for printed
              // lines, just enough to read as a document, not a blank card.
              Container(
                width: w,
                height: h,
                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 16),
                decoration: BoxDecoration(
                  color: _darkMode ? const Color(0xFF20263A) : const Color(0xFFF1F3FA),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  for (final f in [0.85, 0.55, 0.7, 0.4, 0.75, 0.5, 0.65])
                    Padding(
                      padding: const EdgeInsets.only(bottom: 9),
                      child: FractionallySizedBox(
                        widthFactor: f,
                        child: Container(
                          height: 5,
                          decoration: BoxDecoration(
                              color: _faint.withValues(alpha: 0.55),
                              borderRadius: BorderRadius.circular(3)),
                        ),
                      ),
                    ),
                ]),
              ),
              // The scanning beam — sweeps top-to-bottom-to-top forever
              // (the controller repeats with reverse:true) for as long as
              // the dialog is on screen.
              AnimatedBuilder(
                animation: _ctl,
                builder: (_, __) {
                  final y = -4 + _ctl.value * (h + 8);
                  return Positioned(
                    left: -4,
                    right: -4,
                    top: y,
                    child: Container(
                      height: 3,
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(2),
                        gradient: LinearGradient(colors: [
                          _purple.withValues(alpha: 0),
                          _purple,
                          _purple.withValues(alpha: 0),
                        ]),
                        boxShadow: [
                          BoxShadow(
                              color: _purple.withValues(alpha: 0.65),
                              blurRadius: 9),
                        ],
                      ),
                    ),
                  );
                },
              ),
              _corner(top: true, left: true),
              _corner(top: true, left: false),
              _corner(top: false, left: true),
              _corner(top: false, left: false),
            ]),
          ),
          const SizedBox(height: 20),
          Text(tr('Skenuojama…'),
              style: TextStyle(
                  color: _ink, fontWeight: FontWeight.w800, fontSize: 15.5)),
          const SizedBox(height: 4),
          Text(tr('Atpažįstame prekes ir kainas'),
              style: TextStyle(color: _muted, fontSize: 12.5)),
        ]),
      ),
    );
  }
}

String _shortNm(String n) {
  // collapse an exactly-doubled name ("VMI prie LR FM VMI prie LR FM" → "VMI prie LR FM")
  final w = n.trim().split(RegExp(r'\s+'));
  if (w.length >= 2 &&
      w.length.isEven &&
      w.sublist(0, w.length ~/ 2).join(' ') ==
          w.sublist(w.length ~/ 2).join(' ')) {
    n = w.sublist(0, w.length ~/ 2).join(' ');
  }
  n = n.replaceAll(RegExp(r'\s+Lt,?\s+X?-?\d+$', caseSensitive: false),
      ''); // "Maxima Lt X587" / "Maxima Lt, X-603" → "Maxima"
  n = n.replaceAll(RegExp(r'\s+X-?\d{2,}$'), '');
  n = n.replaceAll(RegExp(r' (MB|UAB|AB)$', caseSensitive: false), '');
  n = n.replaceAll(RegExp(r'^Www\.', caseSensitive: false), '');
  n = n.replaceAll(RegExp(r'\.lt$', caseSensitive: false), '');
  final i = n.indexOf('(');
  if (i > 0) n = n.substring(0, i);
  return n.trim();
}

List<String> _ptype(Map t) {
  final badges = ((t['badges'] as List?) ?? const []).cast<String>();
  if (badges.contains('rec')) {
    return ['Sąskaita', 'pasikartoja kas mėnesį · matoma ir „Prenumeratose"'];
  }
  if (t['col'] == 'transfer')
    return ['Pervedimas', 'neįskaičiuojama į išlaidas'];
  if (t['col'] == 'income' || t['pos'] == true) return ['Pajamos', ''];
  if (((t['count'] ?? 0) as num) > 1) {
    return ['Dažnas pirkimas', '${t['count']}× tą pačią dieną'];
  }
  return ['Vienkartinis', ''];
}

// Account avatar built from the backend `icon` field (main.py: 'R' for Revolut,
// 'bank' otherwise, 'cash' for cash) — NEVER a hardcoded bank. 'cash' → wallet
// glyph, 'R' or a revolut-named account → the Revolut letter, otherwise the
// first letter of the account name (SEB → "S"). The connected bank varies per
// user, so every account row must read this, not assume Revolut.
/// Each bank's brand colour, matched loosely on the backend `bank` label so it
/// works whoever the user connected. Used for the account avatar's ring + letter.
/// Falls back to the app accent for an unrecognised bank.
Color _bankColor(String bank) {
  final b = bank.toLowerCase();
  if (b.contains('revolut')) return const Color(0xFF12100E);
  if (b.contains('seb')) return const Color(0xFF5FB130);
  if (b.contains('swedbank') || b.contains('swed'))
    return const Color(0xFFFF5F00);
  if (b.contains('luminor')) return const Color(0xFFE1523D);
  if (b.contains('citadele')) return const Color(0xFF00A0E1);
  if (b.contains('inbank')) return const Color(0xFFE30613);
  if (b.contains('šiaulių') || b.contains('siauliu') || b.contains('artea'))
    return const Color(0xFF0A6BB0);
  return _purple;
}

Widget _acctGlyph(Map a, {double diameter = 40, double fontSize = 18}) {
  final icon = ((a['icon'] as String?) ?? '').trim();
  final name = ((a['name'] as String?) ?? '').trim();
  final isCash = icon == 'cash';
  // The bank's own logo when we SHIP it (SEB, Revolut, Swedbank…), keyed off the
  // backend's `bank` label — never a hardcoded bank, since which one is connected
  // varies per user. Bundled asset only; the letter is the fallback. No network
  // fetch, so an account avatar never discloses the user's bank to a third party.
  final bankName = (a['bank'] as String?) ?? name;
  // Brand-coloured ring (option A): logo/letter stays on white so real logos
  // never clash; only the ring + fallback letter carry the brand colour.
  final ring = isCash ? _purple : _bankColor(bankName);
  Widget child;
  if (isCash) {
    child = Icon(Icons.payments_outlined, size: diameter * 0.5, color: _purple);
  } else if (icon == 'R' || name.toLowerCase().contains('revolut')) {
    child = Text('R',
        style: TextStyle(
            fontSize: fontSize, fontWeight: FontWeight.w800, color: ring));
  } else {
    final letter = name.isNotEmpty ? name.substring(0, 1).toUpperCase() : '•';
    child = Text(letter,
        style: TextStyle(
            fontSize: fontSize, fontWeight: FontWeight.w800, color: ring));
  }
  final asset = isCash ? null : logoAssetForName(bankName);
  if (asset != null) {
    child = Padding(
      padding: EdgeInsets.all(diameter * 0.18),
      child: Image.asset(asset,
          fit: BoxFit.contain,
          errorBuilder: (_, __, ___) => Center(child: child)),
    );
  }
  return Container(
    width: diameter,
    height: diameter,
    alignment: Alignment.center,
    decoration: BoxDecoration(
      shape: BoxShape.circle,
      color: isCash ? _purpleSoft : _card,
      border: Border.all(
          color: ring.withValues(alpha: isCash ? 1 : 0.85), width: 2.2),
    ),
    clipBehavior: Clip.antiAlias,
    child: child,
  );
}

/// The hands-free tours the onboarding demo can run.
enum DemoScript {
  /// Home feed: hide the balance, draw the chart, scroll, open recurring.
  home,

  /// Overview tab: switch to it, then open the savings-rate breakdown.
  overview,

  /// Planning: open the add-budget sheet, then walk into the account settings
  /// and turn the app dark.
  budget,

  /// AI chat: opens straight onto the tab with a conversation already in it,
  /// then types another question and answers it.
  chat,
}

/// Set by the Overview tab while the demo is running, so the director can open
/// the savings-rate screen through the card's own handler rather than a copy of
/// it. The tab lives in its own State class, so this is the seam between them.
VoidCallback? _demoOpenSavings;
final GlobalKey _kSavings = GlobalKey();

/// Set by the AI chat tab while the demo runs: types [q] into the field a
/// character at a time, sends it, and answers with [a] after a pause. The demo
/// must never reach the real assistant — that would ship the viewer's finance
/// summary to Anthropic (and raise a consent dialog) to decorate a marketing
/// page, which is the same mistake the bank sync was.
Future<void> Function(String q, String a)? _demoChatSay;

class DashboardPreview extends StatefulWidget {
  /// [data] is the live dashboard payload from a bank connection. When null the
  /// screen falls back to the baked sample data (standalone design preview).
  /// [deeper] is an optional in-flight fuller (12-month) scan: the screen opens
  /// instantly on the fast (3-month) [data] and quietly swaps in the deeper
  /// result when it arrives (recent-first loading).
  /// [demo] is the onboarding preview: it pins the screen to the baked sample
  /// data and turns off every side effect — no bank sync, no persistence, no
  /// reminder rescheduling. Without it the preview auto-synced the signed-in
  /// user's real banks (and showed their real balance) just to decorate a
  /// marketing page.
  const DashboardPreview({
    super.key,
    this.data,
    this.deeper,
    this.demo = false,
    this.script = DemoScript.home,
  });
  final Map<String, dynamic>? data;
  final Future<Map<String, dynamic>?>? deeper;
  final bool demo;

  /// Which walkthrough the demo runs. One onboarding page shows the home feed,
  /// another the Overview tab — same widget, different tour.
  final DemoScript script;

  /// Parse the demo payload now rather than inside the entry transition of the
  /// page that shows it. Call it from the page before. Safe to call twice.
  static void warmDemo() => _DashboardPreviewState.warmDemo();

  @override
  State<DashboardPreview> createState() => _DashboardPreviewState();
}

/// One side of `_heroSideGlow` — a flat, constant tone. See that getter for
/// why no gradient/fade is needed: the strip is positioned from the hero's
/// own MEASURED height, so it is already the target colour for its entire
/// extent, including the part hidden behind the hero's rounded corner.
class _SideGlowStrip extends StatelessWidget {
  const _SideGlowStrip();

  @override
  Widget build(BuildContext context) =>
      DecoratedBox(decoration: BoxDecoration(color: _previewPageBlue.withValues(alpha: 0.20)));
}

/// 2026-08-14: the hero's bottom edge — rounded top corners as normal, but
/// the bottom is NOT a plain rounded rectangle. The flat "shelf" (where the
/// grabber-style indicator sits) runs across the CENTER, at the height the
/// content naturally ends; the two outer corners keep descending PAST that,
/// all the way down to this widget's full height at x=0 and x=width, then
/// curve back up and inward to meet the shelf. That's the opposite of a
/// normal card corner (which curves up/in as it nears the edge) — here it
/// curves down/out. `legDepth` (the extra height reserved below the
/// content, via the caller's own bottom padding) is how far the corners
/// hang past the shelf; `shelfInset` is how far each end of the flat shelf
/// sits in from the edge.
class _HeroShapeClipper extends CustomClipper<Path> {
  const _HeroShapeClipper({
    required this.legDepth,
    required this.shelfInset,
    this.topRadius = 24,
    this.grooveDepth = 0,
    this.grooveWidth = 64,
  });
  final double legDepth;
  final double shelfInset;
  final double topRadius;

  // 2026-08-14: a shallow SECOND dip, centered on the flat shelf, for the
  // grabber indicator to sit inside — still filled with the hero's own
  // blue, not a cutout revealing the white card below. 0 = no groove (the
  // shelf stays a plain flat line), matching the previous shape exactly.
  final double grooveDepth;
  final double grooveWidth;

  @override
  Path getClip(Size size) {
    final w = size.width;
    final h = size.height;
    final shelfY = h - legDepth;
    final cx = w / 2;
    final gHalf = grooveWidth / 2;
    final path = Path()
      ..moveTo(topRadius, 0)
      ..lineTo(w - topRadius, 0)
      ..quadraticBezierTo(w, 0, w, topRadius)
      ..lineTo(w, h)
      ..quadraticBezierTo(w, shelfY, w - shelfInset, shelfY)
      ..lineTo(cx + gHalf, shelfY);
    if (grooveDepth > 0) {
      // A flat floor, not a round bowl bottom — rounded ONLY at the two
      // transitions (shelf → floor, floor → shelf), each a quarter-ish
      // curve, with a straight run across the middle at the full
      // grooveDepth. floorHalf < gHalf so the transitions have room to
      // curve before the floor starts.
      final floorHalf = gHalf * 0.45;
      path
        ..quadraticBezierTo(
            cx + gHalf, shelfY + grooveDepth, cx + floorHalf, shelfY + grooveDepth)
        ..lineTo(cx - floorHalf, shelfY + grooveDepth)
        ..quadraticBezierTo(cx - gHalf, shelfY + grooveDepth, cx - gHalf, shelfY);
    }
    path
      ..lineTo(shelfInset, shelfY)
      ..quadraticBezierTo(0, shelfY, 0, h)
      ..lineTo(0, topRadius)
      ..quadraticBezierTo(0, 0, topRadius, 0)
      ..close();
    return path;
  }

  @override
  bool shouldReclip(covariant _HeroShapeClipper old) =>
      old.legDepth != legDepth ||
      old.shelfInset != shelfInset ||
      old.topRadius != topRadius ||
      old.grooveDepth != grooveDepth ||
      old.grooveWidth != grooveWidth;
}

/// Traces `clipper`'s own path as a stroke instead of a clip — see the hero's
/// dark-mode build() for why: the fill no longer contrasts against the page
/// behind it, so the spiked-corner/shelf silhouette needs its own visible
/// edge instead of relying on a colour boundary that isn't there anymore.
class _HeroShapeBorderPainter extends CustomPainter {
  _HeroShapeBorderPainter(
      {required this.clipper, required this.color, required this.strokeWidth});
  final _HeroShapeClipper clipper;
  final Color color;
  final double strokeWidth;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawPath(
      clipper.getClip(size),
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = strokeWidth
        ..color = color,
    );
  }

  @override
  bool shouldRepaint(covariant _HeroShapeBorderPainter old) =>
      old.clipper.legDepth != clipper.legDepth ||
      old.clipper.shelfInset != clipper.shelfInset ||
      old.clipper.grooveDepth != clipper.grooveDepth ||
      old.clipper.grooveWidth != clipper.grooveWidth ||
      old.color != color ||
      old.strokeWidth != strokeWidth;
}

/// Two slow, translucent sine bands drifting near a hero's top edge — plain
/// Path fills (no ImageFilter.blur, which produced artifacts in earlier
/// passes). Used on the Finansų Agentas banner so its gradient doesn't read
/// as flat/static.
class _WavePainter extends CustomPainter {
  _WavePainter(this.t);
  final double t;

  void _band(Canvas canvas, Size size, double phase, double baseY, double amp,
      double wavelengths, Color color) {
    final path = Path()..moveTo(0, 0);
    path.lineTo(0, baseY);
    for (double x = 0; x <= size.width; x += 6) {
      final y = baseY + amp * math.sin((x / size.width * wavelengths * 2 * math.pi) + phase);
      path.lineTo(x, y);
    }
    path.lineTo(size.width, 0);
    path.close();
    canvas.drawPath(path, Paint()..color = color);
  }

  @override
  void paint(Canvas canvas, Size size) {
    final phase = t * 2 * math.pi;
    _band(canvas, size, phase, size.height * 0.18, size.height * 0.22, 1.4,
        Colors.white.withValues(alpha: 0.08));
    _band(canvas, size, -phase * 1.3 + math.pi / 3, size.height * 0.12,
        size.height * 0.16, 1.8, Colors.white.withValues(alpha: 0.06));
  }

  @override
  bool shouldRepaint(covariant _WavePainter old) => old.t != t;
}

class _DashboardPreviewState extends State<DashboardPreview>
    with WidgetsBindingObserver, TickerProviderStateMixin {
  // 2026-08-20: _maybePatchPreviewRecurring's own doc comment says it "never
  // touches a real signed-in user's actual synced data" — but that was only
  // true as long as designPreviewFakeRecurring stayed off outside a demo
  // build. main_onboarding_preview.dart's bootstrap sets it for the WHOLE
  // app session (onboarding pages need it live-embedded), and this line
  // used to call the patch unconditionally on whatever _d resolved to —
  // so a REAL user's REAL post-bank-connect dashboard (widget.demo false,
  // widget.data the real synced payload) got the fake Netflix/SEB/Ignitis/
  // Vilniaus vandenys catalogue patched straight into it, and their sids
  // marked "reviewed" in the same real local Hive box. Only ever the demo
  // tour's own live-embedded phone (widget.demo true) should see the fake
  // catalogue — never a real dashboard, real sample, or App Review sample.
  late Map<String, dynamic> _d = widget.demo
      ? _maybePatchPreviewRecurring(_normalizeDash(_demoDash()))
      : _normalizeDash(widget.data ??
          jsonDecode(utf8.decode(base64Decode(_dashB64)))
              as Map<String, dynamic>);

  /// The baked sample data with every date rolled forward by whole weeks, so
  /// the demo reads as current: "this week" is anchored to today's Monday, and
  /// unshifted sample dates left that chart with a single bar (or none). Whole
  /// weeks keep every weekday landing on the same weekday it was authored for.
  /// The views derived from `all` are dropped so they recompute canonically.
  /// Parsed ahead of time by the page before this one. The payload is mutable
  /// and gets one owner: whoever takes it clears the slot, so a second mount
  /// parses its own copy instead of sharing state with the first.
  static Map<String, dynamic>? _warmedDemo;

  /// Build the demo payload now, so the page that shows it doesn't have to do
  /// it inside its entry transition. Safe to call more than once.
  static void warmDemo() => _warmedDemo ??= _buildDemoDash();

  static Map<String, dynamic> _demoDash() {
    final warm = _warmedDemo;
    if (warm != null) {
      _warmedDemo = null;
      // Three onboarding pages each mount their own preview, and each needs its
      // own mutable copy — so consuming the warm one left the NEXT page to parse
      // ~900 transactions inside its entry transition, which is exactly the cost
      // the warming exists to avoid. Refill the slot once this frame is done.
      scheduleMicrotask(() => _warmedDemo ??= _buildDemoDash());
      return warm;
    }
    return _buildDemoDash();
  }

  /// The sample data spends more than it earns in most months, so the Overview
  /// opened on a savings rate of 0% — the rate is clamped at zero, and zero is
  /// a poor thing to put in front of someone deciding whether to subscribe.
  ///
  /// The fix is in the transactions, not on the screen: each month's expenses
  /// are scaled to land its rate on a healthy target. Every view derives from
  /// `all`, so the home feed, the week bars, the category breakdown and the
  /// savings history all move together and keep telling one story. The newest
  /// month lands on 32%; the ones behind it vary a little, so the history reads
  /// as a real person rather than a manufactured line.
  static void _tuneDemoSavings(Map<String, dynamic> dash) {
    final all = (dash['all'] as List).whereType<Map>().toList();
    // Same classification the screens use: transfers are neither, a credit in a
    // spending section is a refund (it nets down what was spent), and only
    // Pajamos / Kita credits count as earned.
    bool isTransfer(Map t) => (t['sec'] ?? '').toString() == 'Pervedimai';
    bool isEarned(Map t) {
      final sec = (t['sec'] ?? '').toString();
      return sec == 'Pajamos' || sec == 'Kita';
    }

    double amt(Map t) => ((t['a'] ?? 0) as num).toDouble();

    final byMonth = <String, List<Map>>{};
    for (final t in all) {
      final d = (t['d'] ?? '').toString();
      if (d.length < 7) continue;
      byMonth.putIfAbsent(d.substring(0, 7), () => <Map>[]).add(t);
    }
    final months = byMonth.keys.toList()..sort();

    // Rolling the dates forward moves a payday across a month boundary, which
    // left five of the twelve months with no income at all — and a month with
    // no income has no savings rate, so the history the demo opens was full of
    // zeros. Give every month one payday, sized to a steady salary, so the
    // history reads like someone who gets paid monthly.
    for (var i = 0; i < months.length; i++) {
      final rows = byMonth[months[i]]!;
      var earned = 0.0;
      for (final t in rows) {
        if (!isTransfer(t) && amt(t) > 0 && isEarned(t)) earned += amt(t);
      }
      final salary = 2400 + ((i % 4) - 1) * 150; // 2250 … 2700
      if (earned >= salary * 0.75) continue;
      final parts = months[i].split('-');
      final y = int.parse(parts[0]), m = int.parse(parts[1]);
      final lastDay = DateTime(y, m + 1, 0).day;
      final payday = DateTime(y, m, lastDay < 25 ? lastDay : 25);
      final row = <String, dynamic>{
        'nm': 'Payroll Inc',
        'mkey': 'payroll',
        'd': _ymd(payday),
        'wd': _wdShort[payday.weekday - 1],
        'md': '${_monGen[payday.month - 1]} ${payday.day}',
        'cat': 'Atlyginimas',
        'col': 'income',
        'ic': 'income',
        'sec': 'Pajamos',
        'secc': 'amber',
        'a': double.parse((salary - earned).toStringAsFixed(2)),
        'amb': false,
        'badges': <String>[],
        'pos': true,
      };
      rows.add(row);
      (dash['all'] as List).add(row);
    }

    for (var i = 0; i < months.length; i++) {
      final rows = byMonth[months[i]]!;
      var earned = 0.0, spent = 0.0;
      for (final t in rows) {
        if (isTransfer(t)) continue;
        final a = amt(t);
        if (a > 0) {
          if (isEarned(t)) {
            earned += a;
          } else {
            spent -= a; // refund
          }
        } else {
          spent += -a;
        }
      }
      if (earned <= 0 || spent <= 0) continue;
      final fromNewest = months.length - 1 - i;
      final target = fromNewest == 0
          ? 0.32
          : (0.32 + ((i % 5) - 2) * 0.025).clamp(0.1, 0.5);
      final factor = earned * (1 - target) / spent;
      if (factor <= 0 || factor > 8) continue; // implausible → leave it alone
      for (final t in rows) {
        if (isTransfer(t) || amt(t) >= 0) continue;
        t['a'] = double.parse((amt(t) * factor).toStringAsFixed(2));
      }
    }
  }

  static Map<String, dynamic> _buildDemoDash() {
    final d =
        jsonDecode(utf8.decode(base64Decode(_dashB64))) as Map<String, dynamic>;
    final all = (d['all'] as List?)?.whereType<Map>().toList() ?? const [];
    DateTime? last;
    for (final t in all) {
      final p = DateTime.tryParse((t['d'] ?? '').toString());
      if (p != null && (last == null || p.isAfter(last))) last = p;
    }
    if (last == null) return d;
    // 2026-08-18: was `floor(diff/7)*7` — a multiple of 7 (required: shifting
    // by anything else would move a payday or a weekly pattern onto the
    // wrong weekday), but rounding DOWN only guarantees landing somewhere in
    // the trailing 6 days before today, which is a rolling window, not the
    // calendar week "Šią savaitę išleista" actually reads (Monday..Sunday).
    // Whenever that trailing window happened to cross back over last
    // Monday, the shifted data landed entirely in LAST week and the chart
    // opened empty — reproducible on some days, not others, which is what
    // made it look broken rather than just occasionally stale. Aligning
    // Monday-to-Monday instead of day-to-day still shifts by a whole number
    // of weeks (same requirement), but guarantees the newest transaction
    // lands inside the CURRENT Monday..Sunday, every day of the week.
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final todayMonday = today.subtract(Duration(days: today.weekday - 1));
    final lastDay = DateTime(last.year, last.month, last.day);
    final lastMonday = lastDay.subtract(Duration(days: lastDay.weekday - 1));
    final shift = todayMonday.difference(lastMonday).inDays;
    if (shift <= 0) return d;
    for (final t in all) {
      final p = DateTime.tryParse((t['d'] ?? '').toString());
      if (p == null) continue;
      final n = p.add(Duration(days: shift));
      t['d'] = _ymd(n);
      t['wd'] = _wdShort[n.weekday - 1];
      t['md'] = '${_monGen[n.month - 1]} ${n.day}';
    }
    for (final s in (((d['balance'] as Map?)?['series'] as List?) ?? const [])
        .whereType<Map>()) {
      final p = DateTime.tryParse((s['d'] ?? '').toString());
      if (p != null) s['d'] = _ymd(p.add(Duration(days: shift)));
    }
    _tuneDemoSavings(d);
    d
      ..remove('totals') // month/day headers recompute canonically from `all`
      ..remove('months')
      ..remove('week');
    return d;
  }

  /// Guarantees the keys the build reads unconditionally (`all`, `balance` +
  /// its `series`, `subs`) exist and are the right type. A payload missing or
  /// mis-shaping any of them — a cache from an older build, a partially-built
  /// dash — would otherwise crash the whole screen on a forced cast at build
  /// time. This turns that into an empty-but-rendering dashboard.
  static Map<String, dynamic> _normalizeDash(Map<String, dynamic> d) {
    if (d['all'] is! List) d['all'] = <Map<String, dynamic>>[];
    if (d['balance'] is! Map) d['balance'] = <String, dynamic>{};
    final bal = d['balance'] as Map;
    if (bal['series'] is! List) bal['series'] = <dynamic>[];
    if (d['subs'] is! Map) d['subs'] = <String, dynamic>{};
    // build() reads d['budgets'] unconditionally too (month-review, tx-detail,
    // overview) — an older cached payload without it would `null as Map` crash the
    // whole dashboard on the first frame, every launch.
    if (d['budgets'] is! Map) d['budgets'] = <String, dynamic>{};
    return d;
  }

  bool _deepening =
      false; // a fuller 12-month scan is still loading in the background
  // True once the OS notification permission has been asked (see
  // AppPrefs.notifIntroShown) AND come back denied — checked once in
  // initState, drives _notifPermissionBanner(). The class this reads,
  // NotificationService.isPermissionDenied(), existed with no consumer at
  // all after the screen that used to show this banner was deleted in the
  // 2026-08 redesign — every reminder scheduled since then has been
  // silently dropped by iOS for anyone who ever tapped "Don't Allow", with
  // nothing in the app ever telling them.
  bool _notifDenied = false;
  // The overview walkthrough opens ON its own tab: that page should show
  // what it's actually about from the first frame, not the home feed
  // switching over to it a moment later. The chat walkthrough opens on
  // Home ON PURPOSE — it wants to show the "Tavo finansų agentas" banner
  // actually being tapped, not skip straight past it.
  late int _tab = !widget.demo
      ? 0
      : switch (widget.script) {
          DemoScript.overview => 1,
          _ => 0,
        };
  bool _hideBal = false;

  /// Whether every connected account is listed in the header, or just the
  /// largest one plus a "+N" chip.
  bool _acctsOpen = false;
  // 2026-08-30: which group the expanded Sąskaitos panel shows — 0 Bankai,
  // 1 Grynieji. Replaced the earlier "Bankai" then "Kita" stacked-sections
  // layout (reported as not distinct enough) with real segmented tabs,
  // picked from an HTML comparison round. Investicijos was tried here too,
  // then dropped per explicit request — it already has its own dedicated
  // tab, so showing its number here just duplicated it.
  int _acctsTab = 0;
  // 2026-08-29: "Kur išleidai daugiausiai" used to always draw from the
  // WHOLE synced history (however many months that happens to be) with no
  // way to narrow it — explicit request to let a specific month be picked
  // instead. null = the original "all history" behaviour, unchanged.
  String? _topMerchantsMonthKey;
  int? _weekSel; // tapped weekday bar
  // 2026-08-15: which week _weekSection shows — 0 = this week, -1 = last
  // week, etc. Never positive: you can't browse into the future.
  int _weekOffset = 0;
  int _shownPast = 2; // how many past months are shown below the current one
  final _txFilter = _TxFilter(); // feed filter (type + sections)

  // The transactions the feed shows — all, or filtered when the filter is active.
  Iterable<Map<String, dynamic>> get _feedAll {
    final all = (_d['all'] as List).cast<Map<String, dynamic>>();
    return _txFilter.active ? all.where(_txFilter.matches) : all;
  }

  Future<void> _openDashFilter() async {
    final avail = (_d['all'] as List)
        .cast<Map<String, dynamic>>()
        .map((t) => _secOf(t))
        .toSet()
        .toList()
      ..sort();
    final res = await _showFilterSheet(context, _txFilter, avail);
    if (res == null) return;
    setState(() {
      _txFilter
        ..type = res.type
        ..secs = res.secs;
    });
  }

  // Cached non-dashboard tabs. They depend only on the immutable `_d` data, so
  // rebuilding them on every tab switch (setState) is wasted work that made tab
  // taps lag — build once and reuse; only a theme flip invalidates them.
  List<Widget>? _otherTabs;

  /// Which of the other tabs a demo script actually shows. IndexedStack lays
  /// out every child it is given, so a page that only ever displays the chat
  /// was still building the Overview (donuts and a category list over ~900
  /// transactions), Planning and Account trees — inside its entry transition.
  /// The ones a script never reaches are replaced with nothing.
  static const _demoTabs = <DemoScript, Set<int>>{
    DemoScript.home: <int>{},
    DemoScript.overview: {0},
    // Chat is reached by tapping the Home banner (a pushed route, its own
    // fresh _AiChatTab) — the IndexedStack's own copy at tabNeeded index 1
    // is never shown, so it doesn't need building either.
    DemoScript.chat: <int>{},
    DemoScript.budget: {2, 3},
  };

  bool _tabNeeded(int i) =>
      !widget.demo ||
      (_demoTabs[widget.script] ?? const {0, 1, 2, 3}).contains(i);

  List<Widget> _buildOtherTabs() => [
        if (!_tabNeeded(0))
          const SizedBox.shrink()
        else
          _OverviewTab(
            all: (_d['all'] as List).cast<Map<String, dynamic>>(),
            balance: _d['balance'] as Map<String, dynamic>,
            budgets: DashboardStore.budgetMap(),
            demo: widget.demo,
          ),
        if (!_tabNeeded(1))
          const SizedBox.shrink()
        else
          _AiChatTab(data: _d, demo: widget.demo),
        if (!_tabNeeded(2))
          const SizedBox.shrink()
        else
          _PlanningTab(
            all: (_d['all'] as List).cast<Map<String, dynamic>>(),
            subs: _d['subs'] as Map<String, dynamic>,
            demo: widget.demo,
            onVerdictChanged: () {
              if (mounted) setState(() {});
            },
          ),
        if (!_tabNeeded(3))
          const SizedBox.shrink()
        else
          _AccountTab(
              balance: _d['balance'] as Map<String, dynamic>,
              allTransactions:
                  (_d['all'] as List?)?.cast<Map<String, dynamic>>()),
        // index 4 — "Transakcijos" (2026-08-14): appended rather than
        // replacing index 1 (_AiChatTab), so the demo-tour's _demoTabs/
        // _tabNeeded indices for the existing four tabs stay exactly as they
        // were. Not gated by _tabNeeded — the auto-demo tour never selects
        // it, so it has nothing to hide during a script run.
        _transactionsTab(),
        // index 5 — "Investavimas" (2026-08-27 prototype, see
        // investing_tab.dart's own doc for isolation/removal). Appended for
        // the same reason as Transakcijos above — never gated by
        // _tabNeeded, the demo tour doesn't know about it.
        InvestingTab(onExit: () => setState(() => _tab = 0), demo: widget.demo),
      ];

  // A theme flip OR a language change must rebuild the cached tabs.
  //
  // Language was missing, and that is the whole "half the app switched" bug:
  // tr() is read at build time, so only widgets that actually rebuild pick up a
  // new language. The nav bar rebuilds with this State; the four other tabs are
  // built once and cached, so they kept whatever language they were first built
  // in — Overview, AI chat and Account stayed English while the bar under them
  // turned Lithuanian. Switching a language must invalidate them exactly as a
  // theme flip does.
  void _onTheme() => setState(() => _otherTabs = null);

  // Controls the home ListView (used for pull-to-refresh).
  final ScrollController _homeScroll = ScrollController();

  // Measures the hero's ACTUAL rendered height (it varies: balance hidden vs
  // shown, +N accounts chip, safe-area insets) so `_heroSideGlow` can start
  // exactly where the hero ends instead of guessing a fraction of the page —
  // a guessed fraction either left a gap of plain backdrop between the hero
  // and the glow (when the guess was too low) or cut across the hero's own
  // rounded corner (when too high). Re-measured after every frame the hero
  // could have changed size; only triggers a rebuild when the number actually
  // moved, so this can't loop.
  final GlobalKey _heroKey = GlobalKey();
  double? _heroHeight;
  void _measureHero() {
    if (!designPreviewPalette) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final box = _heroKey.currentContext?.findRenderObject() as RenderBox?;
      final h = box?.size.height;
      if (h != null && h > 0 && h != _heroHeight) setState(() => _heroHeight = h);
    });
  }

  // Slow ambient wave animation behind the Finansų Agentas banner — a flat
  // solid gradient read as "something missing" on its own; the same slow
  // sine-band treatment used on the onboarding-style heroes elsewhere in
  // this design pass.
  late final AnimationController _agentWaveCtl =
      AnimationController(vsync: this, duration: const Duration(seconds: 8))..repeat();

  // 2026-08-14: the hero collapses like a bottom sheet — drag the grabber up
  // to hide the balance/chart block and let Prenumeratos/Sąskaitos and the
  // rest of Home slide up into its place; drag down to bring it back. 0 =
  // fully open, 1 = fully collapsed. Distance-based drag (not velocity-based
  // fling) for a first pass — every 160px of upward drag is one full
  // collapse, matching a typical bottom-sheet drag feel closely enough
  // without needing a physics simulation yet.
  late final AnimationController _heroCollapseCtl =
      AnimationController(vsync: this, duration: const Duration(milliseconds: 260));

  // ── Onboarding demo (widget.demo only) ────────────────────────────────────
  // A looping, hands-free walkthrough: hide the balance, draw the chart, scroll
  // the payments, open the recurring manager. It drives the real widgets — the
  // same state fields and the same tap handlers a finger would reach — so the
  // demo can't show behaviour the app doesn't have.
  final GlobalKey _kRoot = GlobalKey(); // coordinate space for the pointer
  final GlobalKey _kEye = GlobalKey();
  final GlobalKey _kRec = GlobalKey();
  final GlobalKey _kBills = GlobalKey(); // the Sąskaitos card on Home
  final GlobalKey _kAgentBanner = GlobalKey(); // "Tavo finansų agentas" on Home
  final GlobalKey _kNav0 = GlobalKey(); // the Pradžia tab button
  final GlobalKey _kNav1 = GlobalKey(); // the Apžvalga tab button
  final GlobalKey _kNav3 = GlobalKey(); // Planavimas
  final GlobalKey _kNav4 = GlobalKey(); // Paskyra
  final GlobalKey _kNavTx = GlobalKey(); // the Transakcijos tab button
  final GlobalKey _kShowOlder = GlobalKey(); // "Rodyti senesnius" in Transakcijos
  final GlobalKey _kReview = GlobalKey(); // first month's "X apžvalga" card
  final ScrollController _txScroll = ScrollController();
  // Drives the pushed _MonthReviewScreen's own list during the home demo
  // tour — only ever attached when widget.demo is true (see _openReviewFor).
  final ScrollController _reviewScroll = ScrollController();
  AnimationController? _chartDraw;
  // 2026-08-18: the week bars' entrance — 0 = flat, 1 = fully risen. Set to
  // 1 (pre-risen) in initState, same as _chartDraw — see there for why.
  AnimationController? _barsRise;
  VoidCallback? _demoOpenReview; // set by the first review card during build
  VoidCallback? _demoOpenSubs; // set by the Prenumeratos card during build
  VoidCallback? _demoOpenBills; // set by the Sąskaitos card during build
  VoidCallback? _demoOpenChat; // set by the Finansų agentas banner during build
  bool _demoOn = false;
  Offset? _demoPointer; // null = pointer off screen
  Duration _demoGlide = const Duration(milliseconds: 620);
  bool _demoPress = false;

  /// Centre of a keyed widget in [_kRoot]'s coordinates, or null if it isn't
  /// laid out right now (scrolled out of the list, or on another tab).
  Offset? _spotOf(GlobalKey k) {
    final box = k.currentContext?.findRenderObject();
    final root = _kRoot.currentContext?.findRenderObject();
    if (box is! RenderBox || root is! RenderBox || !box.hasSize) return null;
    return root.globalToLocal(box.localToGlobal(box.size.center(Offset.zero)));
  }

  Future<bool> _beat(int ms) async {
    await Future<void>.delayed(Duration(milliseconds: ms));
    return mounted && _demoOn;
  }

  /// Glide the pointer onto [k] and press it. Returns false if the demo was
  /// stopped, or if the target isn't on screen (so the step is skipped rather
  /// than tapping empty space).
  Future<bool> _demoTap(GlobalKey k, VoidCallback act,
      {int settle = 900}) async {
    final spot = _spotOf(k);
    if (spot == null) return mounted && _demoOn;
    setState(() {
      _demoGlide = const Duration(milliseconds: 620);
      _demoPointer = spot;
    });
    if (!await _beat(700)) return false;
    setState(() => _demoPress = true);
    if (!await _beat(180)) return false;
    act();
    // Cleared right away, not held through `settle` — every caller's `act()`
    // either switches tabs or pushes/pops a route, so whatever the pointer
    // was sitting on is gone the instant it runs. A circle left frozen at
    // its old coordinates through the whole settle window then reads as
    // pressing empty space in the NEW screen instead of what was actually
    // just tapped — most visible on a tab switch (an instant IndexedStack
    // swap, no transition to cover it), which is what surfaced this.
    setState(() {
      _demoPress = false;
      _demoPointer = null;
    });
    return _beat(settle);
  }

  /// Overview tour: move to the Apžvalga tab, let its donuts land, open the
  /// savings-rate breakdown (the one number that page is selling) — then
  /// back to Pradžia for Sąskaitos and Prenumeratos, the two card-shaped
  /// managers Home itself sells. Each of the three opens the exact same
  /// real screen a finger-tap would, and each closes again before the
  /// next opens, so nothing is ever left stacked underneath.
  Future<void> _runOverviewDemo() async {
    if (!await _beat(900)) return;
    while (mounted && _demoOn) {
      if (_tab != 1) {
        if (!await _demoTap(_kNav1, () => setState(() => _tab = 1),
            settle: 1900)) {
          return;
        }
      }
      setState(() => _demoPointer = null);
      if (!await _beat(1400)) return;

      final openSavings = _demoOpenSavings;
      if (openSavings != null) {
        if (!await _demoTap(_kSavings, openSavings, settle: 2600)) return;
        setState(() => _demoPointer = null);
        if (!await _popDemoRoute()) return;
        if (!await _beat(900)) return;
      } else {
        // The tab has not built yet on the first pass; come back around.
        if (!await _beat(700)) return;
      }

      // Back to Pradžia, then Sąskaitos, then Prenumeratos.
      if (!await _demoTap(_kNav0, () => setState(() => _tab = 0),
          settle: 1000)) {
        return;
      }
      setState(() => _demoPointer = null);
      if (!await _beat(700)) return;

      final openBills = _demoOpenBills;
      if (openBills != null) {
        if (!await _demoTap(_kBills, openBills, settle: 2400)) return;
        setState(() => _demoPointer = null);
        if (!await _popDemoRoute()) return;
        if (!await _beat(700)) return;
      }

      final openSubs = _demoOpenSubs;
      if (openSubs != null) {
        // Longer settle than Sąskaitos: LiveRecurringScreen itself opens
        // and closes "Rasti naują prenumeratą" inside this window (see its
        // own widget.demo) — needs room for both transitions plus a beat
        // to actually read the candidate list, not just the base screen.
        if (!await _demoTap(_kRec, openSubs, settle: 4200)) return;
        setState(() => _demoPointer = null);
        if (!await _popDemoRoute()) return;
      }
      if (!await _beat(900)) return;
    }
  }

  /// Pops whatever the demo just opened, from [_kRoot]'s own Navigator —
  /// shared by every tour that pushes a real screen and then closes it
  /// again. Returns whether the demo is still meant to be running.
  Future<bool> _popDemoRoute() async {
    final ctx = _kRoot.currentContext;
    final nav = ctx != null && ctx.mounted ? Navigator.maybeOf(ctx) : null;
    if (nav != null && nav.canPop()) nav.pop();
    return mounted && _demoOn;
  }

  /// Chat tour: tap "Tavo finansų agentas" on Home to open the chat (a
  /// pushed route, not a tab — see _financeAgentBanner), let it answer a
  /// starter question, then ask it something specific, then close it and
  /// come back for the next lap. Kept snappy end to end, per request.
  Future<void> _runChatDemo() async {
    const exchanges = [
      [
        'Kur galėčiau sutaupyti?',
        'Prenumeratos kainuoja 106 € per mėnesį, o dvi iš jų nenaudotos '
            'nuo balandžio. Jas atsisakius liktų 68 € kas mėnesį.',
      ],
      [
        'Kokia mano finansinė padėtis šiuo metu?',
        'Šiuo metu esi teigiamoje pusėje: šį mėnesį uždirbai 2 957 €, '
            'išleidai 1 828 €, o santaupų norma — 27 %.',
      ],
    ];
    while (mounted && _demoOn) {
      final openChat = _demoOpenChat;
      if (openChat == null) return;
      if (!await _demoTap(_kAgentBanner, openChat, settle: 900)) return;
      setState(() => _demoPointer = null);

      var say = _demoChatSay;
      var waited = 0;
      while (say == null && waited < 4000) {
        if (!await _beat(200)) return; // route not built yet — wait for it
        say = _demoChatSay;
        waited += 200;
      }
      if (say != null) {
        for (final e in exchanges) {
          await say(tr(e[0]), tr(e[1]));
          if (!await _beat(1400)) return;
        }
      }

      if (!await _popDemoRoute()) return;
      if (!await _beat(900)) return;
    }
  }

  /// Budget tour: open the add-budget sheet, close it, then show the app going
  /// dark from the settings screen.
  ///
  /// The theme is flipped through [AppPrefs.darkMode]'s notifier and
  /// [_applyTheme] — NOT through `AppPrefs.setDarkMode`, which writes to disk.
  /// A marketing page must not leave the viewer's app dark (nor, further down
  /// this screen, set them a PIN or change their currency); whatever the demo
  /// touches is put back when the page is disposed.
  Future<void> _runBudgetDemo() async {
    if (!await _beat(1000)) return;
    while (mounted && _demoOn) {
      if (_tab != 3) {
        if (!await _demoTap(_kNav3, () => setState(() => _tab = 3),
            settle: 1500)) {
          return;
        }
      }
      setState(() => _demoPointer = null);
      if (!await _beat(900)) return;

      // 1 — add a budget: the sheet is the app's own, opened by its own handler.
      final add = _demoAddBudget;
      if (add != null) {
        if (!await _demoTap(_kAddBudget, add, settle: 2600)) return;
        setState(() => _demoPointer = null);
        _demoPopSheet();
        if (!await _beat(1100)) return;
      }

      // 2 — the app goes dark, then comes back.
      if (!await _demoTap(_kNav4, () => setState(() => _tab = 4),
          settle: 1200)) {
        return;
      }
      setState(() => _demoPointer = null);
      if (!await _beat(900)) return;
      _demoSetDark(true);
      if (!await _beat(2600)) return;
      _demoSetDark(false);
      if (!await _beat(1400)) return;

      if (!await _demoTap(_kNav3, () => setState(() => _tab = 3),
          settle: 900)) {
        return;
      }
      setState(() => _demoPointer = null);
      if (!await _beat(900)) return;
    }
  }

  /// Closes whatever the demo opened inside the phone's own navigator.
  void _demoPopSheet() {
    final ctx = _kRoot.currentContext;
    final nav = ctx != null && ctx.mounted ? Navigator.maybeOf(ctx) : null;
    if (nav != null && nav.canPop()) nav.pop();
  }

  /// Flip the palette for show only — no write, so the viewer's own setting is
  /// untouched. [dispose] puts it back to whatever they actually chose.
  void _demoSetDark(bool dark) {
    if (!mounted) return;
    AppPrefs.darkMode.value = dark;
    _applyTheme(dark);
    setState(
        () => _otherTabs = null); // cached tabs must rebuild in the new palette
  }

  Future<void> _runDemo() async {
    if (widget.script == DemoScript.budget) return _runBudgetDemo();
    if (widget.script == DemoScript.chat) return _runChatDemo();
    if (widget.script == DemoScript.overview) return _runOverviewDemo();
    if (!await _beat(700)) return;
    // 2026-08-19: was a 4-step tour — bars, an eye hide/show, the scroll,
    // Transakcijos. The eye step is gone per request ("šito nereikia
    // rodyti") — everything else unchanged.
    while (mounted && _demoOn) {
      // 1 — the week bars rise, one after another.
      setState(() => _demoPointer = null);
      _barsRise?.forward(from: 0);
      if (!await _beat(1500)) return;

      // 2 — Home isn't only the hero and the week chart: scroll all the way
      // down to "Kur išleidai daugiausiai" so that's part of the tour too.
      // 2026-08-18: used to scroll straight back up to the top afterwards —
      // reads as an unwanted bounce (down, then immediately back up) rather
      // than a clean "show the donut, then move on". Home is put back at
      // the top silently instead, with jumpTo while it's off-screen (see
      // "Reset for the next lap" below), so nothing has to be seen twice.
      //
      // 2026-08-19: this used to need a silent jump-to-bottom-and-back
      // "measure" pass first, because ListView(children: […]) only
      // estimates anything below the fold until it's actually been laid
      // out, and animating straight to the estimate overshot into space
      // that didn't exist yet. The Home ListView now sets a generous
      // cacheExtent in demo mode instead (see its own comment), which lays
      // the whole list out up front — so maxScrollExtent is already the
      // true figure here and a single clean scroll is enough. The old
      // measure pass was itself visible as a flicker on a real device
      // ("atrodo bando užkrauti kitą puslapį") — this removes it outright
      // rather than trying to hide it better.
      if (_homeScroll.hasClients) {
        await _homeScroll.animateTo(_homeScroll.position.maxScrollExtent,
            duration: const Duration(milliseconds: 1200),
            curve: Curves.easeInOutCubic);
        if (!await _beat(1300)) return;
      }

      // 4 — Transakcijos: open it already sitting on the first month's own
      // "apžvalga" card (the hop-search itself stays silent/instant — the
      // visible scroll belongs INSIDE the review, after it's tapped, not
      // spent hunting for the card first), tap it, scroll that screen down
      // a little, then go straight back to Pradžia instead of sitting back
      // on Transakcijos first.
      //
      // The search still has to hop rather than jump straight to
      // maxScrollExtent: ListView(children: […]) still virtualises through
      // a sliver, which only keeps elements within ~250px of the viewport.
      // Jumping to the very bottom of a 12–15k px list built the review
      // card in passing and then DISPOSED it again by the time the jump
      // landed, so ensureVisible(key.currentContext) always found nothing.
      // Short, ~700px hops — checking for the card after each one — keep it
      // in the built range the moment it's found rather than jumping past
      // it. _shownPast already defaults to 2, so the card exists from the
      // very first build; no "Rodyti senesnius" tap is needed first.
      if (_txScroll.hasClients) {
        for (var hop = 0; hop < 6; hop++) {
          if (_kReview.currentContext != null) break;
          if (!mounted || !_demoOn) return;
          final max = _txScroll.position.maxScrollExtent;
          final target = (_txScroll.offset + 700).clamp(0.0, max);
          _txScroll.jumpTo(target);
          if (!await _beat(30)) return;
          if (target >= max) break;
        }
        final reviewCtx0 = _kReview.currentContext;
        if (reviewCtx0 != null) {
          await Scrollable.ensureVisible(reviewCtx0,
              duration: Duration.zero, alignment: 0.3);
        }
      }

      if (!await _demoTap(_kNavTx, () => setState(() => _tab = 5),
          settle: 900)) {
        return;
      }
      setState(() => _demoPointer = null);

      final reviewCtx = _kReview.currentContext;
      final openReview = _demoOpenReview;
      if (reviewCtx != null && openReview != null) {
        if (!await _demoTap(_kReview, openReview, settle: 700)) return;
        setState(() => _demoPointer = null);

        // A gentle, smooth scroll down — NOT all the way to the bottom
        // (that needs the silent-stabilise-first trick Home's own scroll
        // uses; this one is short enough not to hit the virtualisation
        // overshoot that trick exists for).
        if (_reviewScroll.hasClients) {
          await _reviewScroll.animateTo(620,
              duration: const Duration(milliseconds: 1400),
              curve: Curves.easeInOutCubic);
          if (!await _beat(700)) return;
        }

        final nav = _kRoot.currentContext != null
            ? Navigator.maybeOf(_kRoot.currentContext!)
            : null;
        if (nav != null && nav.canPop()) nav.pop();
        // Off-screen now — safe to reset silently for the next lap.
        if (_reviewScroll.hasClients) _reviewScroll.jumpTo(0);
      }

      // Straight back to Pradžia — no lingering on Transakcijos first.
      // Home gets put back at the top here too — silently (jumpTo, not
      // animateTo) since it's off-screen right up until the _tab flip
      // below, so the next lap's bars-rise opens on the hero exactly like
      // this one did, with nothing visible in between.
      if (_homeScroll.hasClients) _homeScroll.jumpTo(0);
      if (_txScroll.hasClients) _txScroll.jumpTo(0);
      setState(() {
        _tab = 0;
        _demoPointer = null;
      });
      if (!await _beat(900)) return;
    }
  }

  /// The demo's finger: a soft ring that glides between targets and dips on tap.
  Widget _demoPointerLayer() {
    final p = _demoPointer;
    return AnimatedPositioned(
      duration: _demoGlide,
      curve: Curves.easeInOutCubic,
      left: (p?.dx ?? 0) - 21,
      top: (p?.dy ?? 0) - 21,
      child: AnimatedScale(
        duration: const Duration(milliseconds: 160),
        scale: p == null ? 0.4 : (_demoPress ? 0.78 : 1),
        child: AnimatedOpacity(
          duration: const Duration(milliseconds: 260),
          opacity: p == null ? 0 : 1,
          child: Container(
            width: 42,
            height: 42,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: Colors.white.withValues(alpha: _demoPress ? 0.42 : 0.26),
              border: Border.all(
                  color: Colors.white.withValues(alpha: 0.9), width: 2),
              boxShadow: [
                BoxShadow(
                    color: const Color(0xFF0B1B4A).withValues(alpha: 0.35),
                    blurRadius: 14,
                    offset: const Offset(0, 4)),
              ],
            ),
          ),
        ),
      ),
    );
  }

  @override
  void initState() {
    super.initState();
    // Sync the dashboard's colour tokens to the saved theme on every launch —
    // otherwise they'd sit at their light defaults until the user toggled.
    // 2026-08-20: the onboarding demo (widget.demo) is a fixed presentation,
    // not a live account — it must always show LIGHT, the look every
    // marketing screenshot/photo was designed against, regardless of
    // whatever dark/light mode the real account happens to be left on. This
    // used to read the real AppPrefs.darkMode unconditionally, so testing
    // dark mode in the real app and then reopening onboarding silently
    // carried dark mode into every onboarding page's live-embedded phone too.
    final dark = widget.demo ? false : AppPrefs.darkMode.value;
    _applyTheme(dark);
    // _applyPreviewPalette's OWN doc comment says "never touches dark mode"
    // — it unconditionally overwrites _card/_bg/_hair/_ink/etc with LIGHT-
    // only values, but this call was never actually guarded on `dark`, so a
    // dark-mode launch got _applyTheme(true)'s correct dark tokens
    // immediately clobbered back to light ones by this line — the hero
    // (a separate RadialGradient literal, not one of these tokens) stayed
    // correctly dark, while the cards under it (which DO read _card) came
    // out white-on-dark-page ("balti blokai nesimato užrašų"). Manually
    // flipping the theme toggle afterward "fixed" it only because THAT path
    // calls _applyTheme alone, without this line re-running behind it.
    if (designPreviewPalette && !dark) _applyPreviewPalette();
    WidgetsBinding.instance.addObserver(this); // auto-sync on resume
    _themeVN.addListener(_onTheme); // rebuild the whole tree when theme flips
    AppPrefs.locale.addListener(_onTheme); // ...and when the language changes
    // ...and when the display currency changes. Nothing was listening to this
    // notifier at all — every €/kr/$ figure is computed fresh from Money.rate
    // in each build(), so it was already CORRECT the moment anything rebuilt
    // that widget for any other reason, and stale otherwise. A tab kept alive
    // by the bottom nav's IndexedStack (Account, reached straight from
    // Settings and back) never got that other reason, so it kept showing
    // whichever currency was selected the last time IT happened to rebuild —
    // one step behind, not simply "wrong".
    AppPrefs.currencyCode.addListener(_onTheme);
    // Let any detail/edit screen that mutates `_d['all']` (delete, edit,
    // convert, recategorise) ask the dashboard to recompute + persist.
    // The onboarding demo is decoration: it must not own the global refresh
    // hook, call a bank, or write anything to disk.
    if (widget.demo) {
      _chartDraw = AnimationController(
          vsync: this, duration: const Duration(milliseconds: 1500));
      _chartDraw!.value = 1;
      // 2026-08-18: starts pre-risen (value 1), same as _chartDraw above —
      // any script that shows Home without ever calling forward(from: 0)
      // (overview, budget, chat, if they ever land there) must still show
      // full bars, not a permanently flat chart. Only the home script's own
      // tour explicitly replays the rise from 0 for its showcase moment.
      _barsRise = AnimationController(
          vsync: this, duration: const Duration(milliseconds: 1100));
      _barsRise!.value = 1;
      _demoOn = true;
      WidgetsBinding.instance.addPostFrameCallback((_) => _runDemo());
      return;
    }
    _dashRefresh = _refreshFromAll;
    // Recent-first: the fast 3-month scan is already showing; when the deeper
    // scan lands, swap it in (fuller history + complete recurring), persist it,
    // and refresh reminders. Failures leave the fast scan in place.
    final deeper = widget.deeper;
    if (deeper != null) {
      _deepening = true;
      deeper.then((full) {
        if (!mounted) return;
        // The deeper scan re-fetches EVERY connected bank, so it can come back
        // missing one (a bank that rate-limited us during the connect burst).
        // It gets the same guard as a manual refresh: never trade complete data
        // for a fuller-but-holed one.
        if (_refreshHasStaleBank(full) || _refreshLostABank(full)) {
          setState(() => _deepening = false);
          return;
        }
        setState(() {
          if (full != null) {
            _applyLocalTxEdits(full);
            _d = _normalizeDash(full);
            _otherTabs = null; // Overview/Planning rebuild from the fuller data
          }
          _deepening = false;
        });
        if (full != null) {
          _persist();
          _rescheduleReminders(full);
        }
      }).catchError((_) {
        if (mounted) setState(() => _deepening = false);
      });
    } else {
      // Opened from the persisted dashboard (not a fresh connect) → auto-sync in
      // the background if the data is stale.
      WidgetsBinding.instance.addPostFrameCallback((_) => _maybeAutoSync());
    }
    // Only ever check after the OS has actually been asked once (see
    // AppPrefs.notifIntroShown's own doc comment) — checking earlier would
    // read a brand-new install's "not determined" state as denied.
    if (AppPrefs.notifIntroShown) {
      NotificationService.instance.isPermissionDenied().then((denied) {
        if (mounted) setState(() => _notifDenied = denied);
      });
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) _maybeAutoSync();
  }

  // Auto-sync on open and on resume: re-fetch all connected banks and swap the
  // fresher data in, so a user who just made a purchase sees it without knowing
  // to pull-to-refresh. No-op in the standalone preview (no connected banks).
  //
  // This was 3 minutes. Enable Banking bills per CONNECTED USER PER MONTH, not
  // per call, so syncing often costs nothing there — an earlier version of this
  // comment claimed otherwise and was simply wrong.
  //
  // What a sync does still cost is our own Cloud Functions: each one is a full
  // multi-bank, 6-month scan, invoked and CPU-billed per run, plus the user's
  // battery and mobile data. Every three minutes buys nothing for that — bank
  // feeds update a few times a day, not continuously, so most of those scans
  // returned identical data. Half an hour is also roughly what comparable apps
  // do (Bilance syncs about every 28 minutes).
  //
  // Pull-to-refresh is deliberately NOT throttled by this: when the user
  // explicitly asks for new data, they get it immediately.
  static const _autoSyncEvery = Duration(minutes: 30);
  // Bank names currently represented in a dashboard payload's accounts.
  Set<String> _banksIn(Map<String, dynamic>? d) {
    final accts = ((d?['balance'] as Map?)?['accounts'] as List?) ?? const [];
    return accts
        .map((a) => ((a as Map)['bank'] as String?)?.toLowerCase().trim())
        .whereType<String>()
        .where((b) => b.isNotEmpty)
        .toSet();
  }

  // Per-account diagnostics from the last refresh — says WHY a bank dropped out.
  List<dynamic> _lastDiag = const [];

  // True when the last scan failed to fetch [bank] because the bank was rate-
  // limiting us. That's a "try again in a bit", not a broken connection.
  bool _wasRateLimited(Set<String> banks) => _lastDiag.any((e) =>
      e is Map &&
      e['rateLimited'] == true &&
      banks.contains((e['bank'] as String?)?.toLowerCase().trim()));

  // A refresh must NEVER make a bank silently vanish. If the fresh result lost a
  // bank the current view shows, keep the last-known data and tell the user
  // instead of overwriting with a bank-less result.
  // True when [fresh] carries a bank the user is no longer connected to —
  // this refresh's OWN network request was dispatched with an account list
  // captured before a disconnect that has since completed, so the request
  // that just landed is answering a question nobody is asking anymore.
  //
  // A tester connected Swedbank+DNB, disconnected DNB, and 37 seconds later
  // a `refresh_dashboard` call that had ALREADY been in flight before that
  // disconnect (a slow deep 6-month DNB scan) landed and got applied — DNB's
  // data reappeared on the dashboard for one refresh cycle, indistinguishable
  // from disconnect having silently failed. `_refreshLostABank` already
  // guards the opposite direction (a bank MISSING from a fresh result); nothing
  // guarded this one. Checked against DashboardStore directly, not `_d` — the
  // source of truth a disconnect action writes to immediately, not whatever
  // happens to be on screen.
  bool _refreshHasStaleBank(Map<String, dynamic>? fresh) {
    if (fresh == null) return false;
    final connected = DashboardStore.connections()
        .map((c) => (c['bank'] as String?)?.toLowerCase().trim())
        .whereType<String>()
        .toSet();
    return _banksIn(fresh).any((b) => !connected.contains(b));
  }

  bool _refreshLostABank(Map<String, dynamic>? fresh,
      [Set<String> ignore = const <String>{}]) {
    if (fresh == null) return false;
    // A bank we intentionally dropped this sync (a revoked consent) is legitimately
    // absent from `fresh` — it is NOT "lost". Excluding it lets us save the fresh
    // (revoked-bank-free) payload instead of keeping the stale one forever, which
    // is what left a revoked bank stuck on the dashboard permanently.
    final ignoreLc = ignore.map((b) => b.toLowerCase()).toSet();
    final lost = _banksIn(_d)
        .difference(_banksIn(fresh))
        .where((b) => !ignoreLc.contains(b.toLowerCase()))
        .toSet();
    if (lost.isEmpty) return false;
    final names = lost.map((b) => b.toUpperCase()).join(', ');
    // Reconnecting a rate-limited bank spends more of the quota that ran out —
    // exactly the wrong advice. Nor is it minutes: Enable Banking's guidance for
    // a bank that has cut us off is to come back in ~6 hours, so promising a
    // quick retry would just send the user back to pull again, and again.
    final msg = _wasRateLimited(lost)
        ? '$names ${tr('kol kas neatiduoda naujų duomenų. Rodomi paskutiniai — atsinaujins savaime, kai bankas vėl leis.')}'
        : '${tr('Nepavyko atnaujinti:')} $names. ${tr('Rodomi paskutiniai duomenys — perjunk banką, jei kartojasi.')}';
    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(
          SnackBar(content: Text(msg), duration: const Duration(seconds: 5)));
    return true;
  }

  // Manual pull-to-refresh. A full multi-month, multi-account bank scan is
  // network-bound (~20-30s), so DON'T hold the pull spinner that long — it reads
  // as frozen. Release it quickly and let the scan run in the background, where
  // its progress shows in the 'Sinchronizuojama' card until fresh data lands.
  // Banks rate-limit per hour, and one pull = a full multi-account scan. Pulling
  // again while the last scan is barely cold spends that quota for data that
  // cannot have changed — and a rate-limited bank comes back with no payments at
  // all. Say when the data is already fresh instead of burning the budget.
  static const _minBetweenManualSyncs = Duration(seconds: 15);

  Future<void> _forceSync() async {
    if (DashboardStore.bankCount == 0 || _deepening) return;
    final last = DashboardStore.syncedAt;
    if (last != null &&
        DateTime.now().difference(last) < _minBetweenManualSyncs) {
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(SnackBar(
          content: Text(tr('Duomenys ką tik atnaujinti.')),
          duration: const Duration(seconds: 2),
        ));
      return;
    }
    unawaited(_runSync());
    // A brief, honest beat so the pull gesture feels acknowledged before the
    // spinner closes and the 'Sinchronizuojama' card takes over.
    await Future<void>.delayed(const Duration(milliseconds: 650));
  }

  /// A bank the backend reported as revoked — its consent expired, or the user
  /// withdrew Vaultie's access in their own bank. The server already stopped
  /// serving its cached data; the phone must drop the dead connection and say
  /// so, rather than keep showing it as if it were merely quiet.
  Future<Set<String>> _handleRevokedBanks() async {
    final revoked = <String>{}; // bank names — for the message + lost-guard
    for (final e in _lastDiag) {
      if (e is! Map || e['revoked'] != true) continue;
      if (e['bank'] is String) revoked.add(e['bank'] as String);
    }
    // A bank that answered has clearly not withdrawn anything — wipe its history
    // of refusals so two strikes have to be CONSECUTIVE.
    for (final e in _lastDiag) {
      if (e is! Map || e['revoked'] == true) continue;
      final b = e['bank'];
      if (b is String && b.isNotEmpty) {
        await DashboardStore.clearRevokedStrike(b);
      }
    }
    if (revoked.isEmpty) return const <String>{};

    // One refusal is not proof. A token refresh mid-flight, a bank-side hiccup,
    // an ASPSP wanting a header on that one call — all arrive as 401, and
    // removing the connection on the first one destroys a working setup over a
    // blip, leaving the user to walk the whole consent flow again to undo it.
    // SEB did exactly this: it scanned 150 transactions at midday and refused
    // once four hours later, and the app deleted it.
    final confirmed = <String>{};
    for (final bank in revoked) {
      if (await DashboardStore.bumpRevokedStrike(bank) >= 2)
        confirmed.add(bank);
    }
    if (!mounted) return const <String>{};
    final isLt = Localizations.localeOf(context).languageCode == 'lt';

    if (confirmed.isEmpty) {
      // Still connected, and the next scan may well succeed. Say what happened
      // without sending anyone to reconnect something that is not broken.
      final names = revoked.join(', ');
      ScaffoldMessenger.of(context)
        ..clearSnackBars()
        ..showSnackBar(SnackBar(
          content: Text(isLt
              ? '$names neatsakė šį kartą. Rodomi paskutiniai duomenys — bandysim dar kartą.'
              : "$names didn't answer this time. Showing the latest data — we'll try again."),
          duration: const Duration(seconds: 5),
        ));
      return const <String>{};
    }

    // Refused twice in a row: treat it as genuinely withdrawn and clean up.
    final confirmedKeys = <String>{};
    for (final e in _lastDiag) {
      if (e is! Map || e['revoked'] != true) continue;
      final b = e['bank'];
      if (b is! String || !confirmed.contains(b)) continue;
      final iban = (e['iban'] as String?)?.replaceAll(' ', '').toUpperCase();
      if (iban != null && iban.isNotEmpty) {
        confirmedKeys
            .add('$iban|${(e['currency'] as String?)?.toUpperCase() ?? ''}');
      }
    }
    if (confirmedKeys.isNotEmpty) {
      // Drop only the revoked wallet(s), keeping any still-valid same-bank sibling.
      await DashboardStore.removeRevokedAccounts(confirmedKeys);
    } else {
      for (final bank in confirmed) {
        await DashboardStore.removeConnection(bank);
      }
    }
    for (final bank in confirmed) {
      await DashboardStore.clearRevokedStrike(bank);
    }
    if (!mounted) return confirmed;
    final names = confirmed.join(', ');
    ScaffoldMessenger.of(context)
      ..clearSnackBars()
      ..showSnackBar(SnackBar(
        content: Text(isLt
            ? 'Prieiga prie $names atšaukta. Prijunk banką iš naujo, kad matytum naujus duomenis.'
            : 'Access to $names was revoked. Reconnect the bank to see new data.'),
        duration: const Duration(seconds: 6),
      ));
    return confirmed;
  }

  Future<void> _runSync() async {
    try {
      // Kill-switch also gates manual pull-to-refresh — no bank calls when off.
      if (!FeatureFlags.instance.bankingEnabled.value) return;
      final refs = DashboardStore.accountRefs();
      if (refs.isEmpty) return;
      if (!mounted) return;
      setState(() => _deepening = true);
      final full = _needsFullScan();
      final fresh = await BankingService.instance.refreshDashboard(refs,
          aiEnrichment: AppPrefs.aiEnrichment,
          monthsBack: 6,
          freshDays: full ? null : 21,
          onDiag: (d) => _lastDiag = d);
      if (full) await DashboardStore.markFullScan();
      if (!mounted) return;
      final revoked = await _handleRevokedBanks();
      if (!mounted) return;
      if (_refreshHasStaleBank(fresh) || _refreshLostABank(fresh, revoked)) {
        setState(() => _deepening = false);
        return; // keep the complete last-known data; don't save the partial
      }
      _applyLocalTxEdits(
          fresh); // re-layer local edits/deletions on the sync (H1)
      setState(() {
        if (fresh != null) {
          _d = _normalizeDash(fresh);
          _otherTabs = null;
        }
        _deepening = false;
      });
      // Guard against a disconnect-all that raced this sync: if every bank was
      // removed while the scan was in flight, don't re-persist the stale payload
      // (which would leave a dashboard with data but zero connections).
      if (fresh != null && DashboardStore.bankCount > 0) {
        await DashboardStore.save(fresh);
        _rescheduleReminders(fresh);
      }
    } catch (_) {
      if (mounted) setState(() => _deepening = false);
    }
  }

  /// A refresh normally asks the bank for the last three weeks and reuses the
  /// phone's history for the rest. That is blind to a bank posting a transaction
  /// dated weeks back, so once a week the scan goes full depth and catches it.
  static const _fullScanEvery = Duration(days: 7);

  bool _needsFullScan() {
    final last = DashboardStore.fullScanAt;
    return last == null || DateTime.now().difference(last) >= _fullScanEvery;
  }

  Future<void> _maybeAutoSync() async {
    try {
      // Respect the banking kill-switch: during an Enable Banking outage it must
      // actually stop existing connections from auto-hammering the down provider,
      // not just hide new connections.
      if (!FeatureFlags.instance.bankingEnabled.value) return;
      if (_deepening || DashboardStore.bankCount == 0) return;
      final last = DashboardStore.syncedAt;
      if (last != null && DateTime.now().difference(last) < _autoSyncEvery)
        return;
      final refs = DashboardStore.accountRefs();
      if (refs.isEmpty) return;
      if (!mounted) return;
      setState(() => _deepening = true);
      final full = _needsFullScan();
      final fresh = await BankingService.instance.refreshDashboard(refs,
          aiEnrichment: AppPrefs.aiEnrichment,
          monthsBack: 6,
          freshDays: full ? null : 21,
          onDiag: (d) => _lastDiag = d);
      if (full) await DashboardStore.markFullScan();
      if (!mounted) return;
      final revoked = await _handleRevokedBanks();
      if (!mounted) return;
      if (_refreshHasStaleBank(fresh) || _refreshLostABank(fresh, revoked)) {
        setState(() => _deepening = false);
        return; // keep the complete last-known data; don't save the partial
      }
      _applyLocalTxEdits(
          fresh); // re-layer local edits/deletions on the sync (H1)
      setState(() {
        if (fresh != null) {
          _d = _normalizeDash(fresh);
          _otherTabs = null;
        }
        _deepening = false;
      });
      if (fresh != null && DashboardStore.bankCount > 0) {
        await DashboardStore.save(fresh); // updates syncedAt → resets the timer
        _rescheduleReminders(fresh);
      }
    } catch (_) {
      if (mounted) setState(() => _deepening = false);
    }
  }

  Future<void> _rescheduleReminders(Map<String, dynamic> dash) async {
    try {
      final subs = (dash['subs'] as Map?)?.cast<String, dynamic>();
      final items = ((subs?['items'] as List?) ?? const [])
          .whereType<Map>()
          .map((e) => e.cast<String, dynamic>())
          .toList();
      final isLt = Localizations.localeOf(context).languageCode == 'lt';
      final now = DateTime.now();
      final mk = '${now.year}-${now.month.toString().padLeft(2, '0')}';
      await NotificationService.instance.scheduleFromRecurring(
        items,
        excluded: DashboardStore.recurringExcluded(),
        included: DashboardStore.recurringIncluded(),
        isLithuanian: isLt,
        consentExpiry: DashboardStore.consentExpiry,
        // This month's spending as of right now. It is scheduled against, not
        // read live — see _scheduleBudgetWarning for why the wording says so.
        spent: _monthExpenses(mk),
        budget: AppPrefs.budget.value,
      );
    } catch (_) {/* reminders are best-effort */}
  }

  @override
  void dispose() {
    _demoOn = false; // stops the demo loop at its next beat
    if (widget.demo) {
      // The budget tour flips the palette for show; never leave the viewer's
      // app in a theme they did not choose.
      final real = AppPrefs.darkModeSaved;
      if (AppPrefs.darkMode.value != real) {
        AppPrefs.darkMode.value = real;
        _applyTheme(real);
      }
    }
    _chartDraw?.dispose();
    _barsRise?.dispose();
    _agentWaveCtl.dispose();
    _heroCollapseCtl.dispose();
    WidgetsBinding.instance.removeObserver(this);
    _themeVN.removeListener(_onTheme);
    AppPrefs.locale.removeListener(_onTheme);
    AppPrefs.currencyCode.removeListener(_onTheme);
    _homeScroll.dispose();
    _txScroll.dispose();
    _reviewScroll.dispose();
    if (_dashRefresh == _refreshFromAll) _dashRefresh = null;
    super.dispose();
  }

  // Re-apply the user's local per-transaction edits (recategorise / rename /
  // transfer / star) and deletions onto a freshly-synced payload BEFORE it's
  // shown or saved, so a background sync no longer wipes them (H1). Mutates
  // [fresh] in place; when anything was overridden it also recomputes the views
  // derived from `all` (month/day headers, week bars — the caller nulls
  // `_otherTabs` so Overview/Planning rebuild too), mirroring _refreshFromAll.
  void _applyLocalTxEdits(Map<String, dynamic>? fresh) {
    if (fresh == null) return;
    final edits = DashboardStore.txEdits();
    final deleted = DashboardStore.txDeleted();
    final salaryRefs = DashboardStore.salaryRefs();
    final splits = DashboardStore.txSplits();
    // 2026-08-31: real bug, reported — a manually-logged cash transaction
    // (no corresponding bank row at all) only ever lived in the in-memory
    // `all` list; a fresh sync replaces that list wholesale from the bank's
    // own data, which can never contain a row the bank never saw, so the
    // manual row silently vanished on the very next sync (every app
    // relaunch). Re-applied here exactly like edits/splits already are.
    final manual = DashboardStore.manualTxs();
    if (edits.isEmpty &&
        deleted.isEmpty &&
        salaryRefs.isEmpty &&
        splits.isEmpty &&
        manual.isEmpty) return;
    final rawAll = fresh['all'];
    if (rawAll is! List) return;
    final all =
        rawAll.whereType<Map>().map((e) => e.cast<String, dynamic>()).toList();
    DashboardStore.applyTxOverrides(all, edits, deleted);
    if (salaryRefs.isNotEmpty) _applySalaryRefs(all, salaryRefs);
    if (splits.isNotEmpty) _applyTxSplits(all, splits);
    if (manual.isNotEmpty) {
      final existingKeys = all.map((r) => r['mkey'] as String?).toSet();
      for (final tx in manual.values) {
        final mkey = tx['mkey'] as String?;
        if (mkey != null && !existingKeys.contains(mkey)) {
          all.add(Map<String, dynamic>.from(tx));
        }
      }
    }
    fresh['all'] = all;
    fresh
        .remove('totals'); // month/day headers recompute canonically from `all`
    fresh['week'] = _computeWeek(all);
  }

  // Re-derive everything from `_d['all']` after an external mutation and persist.
  void _refreshFromAll() {
    if (!mounted) return;
    setState(() {
      _d.remove('totals'); // month/day headers recompute canonically from `all`
      _d['week'] =
          _computeWeek((_d['all'] as List).cast<Map<String, dynamic>>());
      _otherTabs = null; // Overview/Planning rebuild
    });
    _persist();
  }

  @override
  Widget build(BuildContext context) {
    // Wrap the whole dashboard in the content theme so every dialog, bottom
    // sheet and text field pushed from here inherits the dark surfaces — without
    // this they fell back to the app's base (light) theme, so an input field
    // stayed white and its text (styled with the now-light ink colour) vanished.
    return Theme(
      data: contentTheme(Theme.of(context)),
      child: Scaffold(
        backgroundColor: _bg,
        // No top SafeArea here: the home banner paints its own dark strip behind
        // the status bar (edge-to-edge, Deriv-style). The other tabs keep their
        // top inset via their own SafeArea below. Outer overlay style = light
        // icons on the dark theme; the home's inner region overrides it while the
        // (dark) banner covers the top in light theme.
        body: AnnotatedRegion<SystemUiOverlayStyle>(
          value: AppPrefs.darkMode.value
              ? SystemUiOverlayStyle.light
              : SystemUiOverlayStyle.dark,
          child: Stack(key: _kRoot, children: [
            Positioned.fill(
              child: IndexedStack(
                index: _tab,
                children: [
                  AnnotatedRegion<SystemUiOverlayStyle>(
                    // Dark theme = light icons (dark banner under the status bar);
                    // Frost = dark icons (the whole top is light).
                    value: AppPrefs.darkMode.value
                        ? SystemUiOverlayStyle.light
                        : SystemUiOverlayStyle.dark,
                    child: _dashboard(),
                  ),
                  // Same backdrop as home, behind each of the other tabs — they paint
                  // no background of their own, so without this they showed the flat
                  // scaffold colour while home had the gradient.
                  for (final w in (_otherTabs ??= _buildOtherTabs()))
                    Stack(
                      children: [
                        Positioned.fill(child: _frostBackdrop()),
                        // Investavimas paints its own full-bleed hero photo behind
                        // the status bar (same edge-to-edge idea as the home banner
                        // above) — an outer top SafeArea would otherwise show this
                        // frost backdrop as a light strip behind the clock/battery
                        // icons instead of the photo. It applies its own top inset
                        // internally where it actually needs one.
                        w is InvestingTab ? w : SafeArea(bottom: false, child: w),
                      ],
                    ),
                ],
              ),
            ),
            if (widget.demo) _demoPointerLayer(),
          ]),
        ),
        // 2026-08-31: the Investing tab's empty welcome screen reads as a
        // full-bleed screen (same idea as the Grynieji/Kvitas intro) — the
        // bottom nav bar underneath it was reported as visual clutter, so
        // it's hidden specifically for that one state. investments() is a
        // synchronous local read (no async gap), safe to call at build time.
        bottomNavigationBar:
            (_tab == 6 && DashboardStore.investments().isEmpty)
                ? null
                : _navBar(),
      ),
    );
  }

  // ── DASHBOARD ──────────────────────────────────────────────────────────────
  Widget _dashboard() {
    _measureHero();
    // A soft backdrop behind the whole feed. Dark = one smooth violet gradient
    // (top darker for the status bar/header, lighter lower). Light ("Frost") = an
    // airy blue-grey base with three faint colour glows (blue/teal/pink) that
    // blend like a fintech mesh — subtle enough that dark ink stays fully legible.
    // The ListView and banner are transparent so nothing shows a hard block edge.
    // The stuff below the hero — same widgets either way, just laid out
    // differently depending on designPreviewPalette (see below).
    // 2026-08-14: the transaction feed (month headers, review cards, day
    // groups) moved out to its own "Transakcijos" tab — see _transactionsTab
    // — now that the bottom nav's old "Agentas" slot is free (the agent is
    // still one tap away via _financeAgentBanner, just not its own tab
    // anymore). Home stays the "at a glance" summary.
    final contentChildren = [
      if (_notifDenied && !AppPrefs.notifBannerDismissed) _notifPermissionBanner(),
      // 2026-08-16: these two used to live here as standalone banners
      // ("žmogui nereikia toli eiti" — shouldn't have to dig into a
      // transaction's own detail screen to discover this exists). Moved
      // INTO the hero as quick-action buttons (_heroQuickActions) per a
      // later request to shorten the page and put them next to the
      // balance/accounts they act on. Kept here, unchanged, for the
      // production (non-preview) layout, which the hero restructure never
      // touched. See _receiptScanBanner / _billSplitBanner /
      // _startReceiptScan / _startBillSplit.
      if (!designPreviewPalette) _receiptScanBanner(),
      if (!designPreviewPalette) _billSplitBanner(),
      // 2026-08-15: moved above Prenumeratos/Sąskaitos per request — the
      // weekly spend chart now leads Home.
      _weekSection(),
      _subsCard(),
      // 2026-08-14: the Filtras chip itself moved to the Transakcijos tab —
      // transactions aren't on Home any more, so a filter control here had
      // nothing of its own left to scope. It still shares the SAME
      // _txFilter state as the week chart above, so setting it from
      // Transakcijos still narrows this chart too; there just isn't a
      // second copy of the control sitting on Home.
      // 2026-08-16: Santaupų norma removed from Home per request — it stays
      // on Apžvalga (_OverviewTabState._savingsCard), just not duplicated
      // here too.
      // 2026-08-14: moved up, right after the summary cards — it had sunk
      // below the weekly chart and read as buried down there.
      _financeAgentBanner(),
      // 2026-08-16: fills out the bottom of Home, which ran out of content
      // right after the banner. Deliberately whole-history, not this-month —
      // Apžvalga already owns "this month".
      if (designPreviewPalette) _topMerchantsSection(),
    ];
    // REVERTED (2026-08-12): the "one continuous white panel on a blue page,
    // fading to white" experiment (v4–v9) kept producing new visual bugs on
    // device each round without ever landing — back to the simple version:
    // plain backdrop, hero renders its own rounded/shadowed card (see
    // _topBanner), everything else is individual cards straight in the
    // ListView, same as the real app.
    return Stack(
      children: [
        Positioned.fill(child: _frostBackdrop()),
        // 2026-08-14: dark/glow backdrop tried and reverted — back to the
        // plain light backdrop above. _homeDarkBackdrop is left defined,
        // unused, in case it's worth revisiting.
        RefreshIndicator(
            onRefresh: _forceSync,
            color: _purple,
            backgroundColor: _card,
            child: ListView(
              controller: _homeScroll,
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.only(bottom: 28),
              // Demo only: lays out the WHOLE list up front instead of just
              // what's near the viewport, so maxScrollExtent is the true
              // content height from the very first frame — see the demo
              // tour's own scroll-to-bottom step for why that matters (it
              // used to need a silent jump-and-measure dance to get an
              // accurate figure, which flickered visibly on a real device).
              cacheExtent: widget.demo ? 6000 : null,
              children: [
                // 2026-08-14: drag-to-collapse hero + grabber tried and
                // reverted — the grabber's own row read as an unwanted gap/
                // missing block between the hero and the cards. Back to the
                // plain hero. _collapsibleHero/_heroGrabber left defined,
                // unused, in case it's worth a different treatment later.
                _topBanner(),
                const SizedBox(height: 12),
                ...contentChildren,
                const SizedBox(height: 16),
              ],
            )),
      ],
    );
  }

  // ── TRANSAKCIJOS tab (2026-08-14) ────────────────────────────────────────
  // The month-header/review-card/day-group feed that used to live at the
  // bottom of Home, now its own tab — reuses the exact same helper methods
  // (_monthHeaderFor, _reviewCardFor, _monthFeed, _dayGroup), just no longer
  // interleaved with the summary cards above it.
  Widget _transactionsTab() {
    final all = _feedAll;
    final keys = <String>{};
    for (final t in all) {
      keys.add(_ymOf(t));
    }
    final monthKeys = keys.toList()..sort((a, b) => b.compareTo(a));
    final shown = monthKeys.take(1 + _shownPast).toList();
    // The demo (widget.demo) stores its own tap handler here the same way
    // the recurring card does with _demoOpenSavings: only shown[1] — the
    // month right after the newest, the first review card it can ever
    // reach — gets the key, so there's exactly one unambiguous target to
    // scroll to and tap. Re-keyed (and re-bound) on every build rather than
    // once, the same as any other GlobalKey attached from a rebuildable list.
    final monthBlocks = <Widget>[];
    for (var i = 0; i < shown.length; i++) {
      monthBlocks.add(_monthHeaderFor(shown[i]));
      if (i > 0) {
        final isDemoTarget = widget.demo && i == 1;
        if (isDemoTarget) _demoOpenReview = () => _openReviewFor(shown[i]);
        monthBlocks.add(
            _reviewCardFor(shown[i], key: isDemoTarget ? _kReview : null));
      }
      monthBlocks.addAll(_monthFeed(shown[i]).map(_dayGroup));
    }
    return ListView(
      controller: widget.demo ? _txScroll : null,
      padding: const EdgeInsets.fromLTRB(0, 8, 0, 28),
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(18, 8, 18, 4),
          child: Row(children: [
            Text(tr('Transakcijos'),
                style: TextStyle(
                    fontSize: 26,
                    fontWeight: FontWeight.w800,
                    color: _ink,
                    letterSpacing: -0.4)),
            const Spacer(),
            // Moved here from Home's hero (2026-08-14) — searching FOR a
            // transaction only makes sense where transactions actually are.
            GestureDetector(
              onTap: () => Navigator.of(context).push(MaterialPageRoute(
                  builder: (_) => _SearchScreen(
                        all: (_d['all'] as List).cast<Map<String, dynamic>>(),
                        budgets: DashboardStore.budgetMap(),
                      ))),
              child: Icon(Icons.search_rounded, size: 24, color: _ink),
            ),
          ]),
        ),
        _filters(),
        ...monthBlocks,
        if (monthKeys.length > shown.length)
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 4),
            child: GestureDetector(
              key: widget.demo ? _kShowOlder : null,
              onTap: () => setState(() => _shownPast += 2),
              child: Container(
                padding: const EdgeInsets.symmetric(vertical: 14),
                alignment: Alignment.center,
                decoration: BoxDecoration(
                    color: _card,
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(color: _hair)),
                child: Text('Rodyti senesnius (${monthKeys.length - shown.length})',
                    style: TextStyle(
                        fontSize: 15, fontWeight: FontWeight.w700, color: _purple)),
              ),
            ),
          ),
      ],
    );
  }

  /// The hero's blue carried down BOTH page margins — the 16dp gutter between
  /// the screen edge and every card below it — for the whole scrollable
  /// height, not just the sliver the hero's own drop shadow used to bleed a
  /// few pixels past its rounded bottom corners. Deliberately only the two
  /// side strips: full-width bands (behind the hero itself, and in the gaps
  /// BETWEEN stacked cards) would tint the cards' own background, which is
  /// exactly what was rejected in the "one continuous panel" experiment
  /// above. Fixed in the Stack (not inside the ListView), so it doesn't
  /// scroll away under the cards.
  ///
  /// A FULL-WIDTH continuation of the hero's own blue, sitting behind the
  /// ListView in this Stack. Not narrow side strips — those had their own
  /// width (however wide) and the hero had its full width, so at the exact
  /// row where the hero ended, the blue visibly stepped from "the whole
  /// screen" down to "a thin strip" in one hard horizontal line: still a cut,
  /// no matter how well the colour lined up. A full-width rectangle has
  /// nothing to step FROM — the hero is the same width as this the whole
  /// way, so there's no edge to see. The white cards below (each own its
  /// opaque, on top of this in z-order) are what carve the "sides only" look
  /// out of it, simply by covering the middle; the margins and the gaps
  /// between cards show through everywhere they don't.
  ///
  /// Starts ABOVE the hero's REAL measured bottom by more than its rounded
  /// corner's own radius (32 — see _topBanner) — this layer is what shows
  /// through that rounded corner, so it has to already be back there,
  /// solid, for the corner's entire curve, or the corner reveals a sliver of
  /// plain backdrop instead of blue (the original "gap in the corner" bug).
  /// Solid for a stretch after that, then fades to nothing well clear of the
  /// Prenumeratos/Sąskaitos cards rather than ending in a visible line right
  /// above them.
  static const double _heroSideGlowOverlap = 40;

  // How far the hero's outer bottom corners hang below its flat center
  // "shelf" — see _HeroShapeClipper and _topBanner.
  static const double _heroLegDepth = 28;
  // 2026-08-16: was 16 — a centered dip in the shelf with a white pull-tab
  // pill sitting inside it. Removed per request ("nebereikia to burbuliuko,
  // padaryk tiesiai") — 0 keeps the clipper's flat-shelf path (see
  // _HeroShapeClipper's own "0 = no groove" branch).
  static const double _heroGrooveDepth = 0;
  // solidRun covers the 40px overlap PLUS ~20px genuinely below the hero's
  // true bottom, so the fade's own top stop can't land inside the rounded
  // corner's arc (which would show as the corner fading instead of solid).
  // Fade then runs long enough to reach white by around "Šią savaitę
  // išėjo", well short of the weekly bar chart.
  static const double _heroSideGlowSolidRun = 60;
  static const double _heroSideGlowFade = 170;
  List<Widget> get _heroSideGlow {
    final h = _heroHeight;
    if (h == null) return const [];
    final top = h - _heroSideGlowOverlap;
    return [
      Positioned(
        top: top,
        left: 0,
        right: 0,
        height: _heroSideGlowSolidRun + _heroSideGlowFade,
        child: Column(children: [
          SizedBox(height: _heroSideGlowSolidRun, child: const _SideGlowStrip()),
          SizedBox(
            height: _heroSideGlowFade,
            child: DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [
                    _previewPageBlue.withValues(alpha: 0.20),
                    _previewPageBlue.withValues(alpha: 0),
                  ],
                ),
              ),
            ),
          ),
        ]),
      ),
    ];
  }

  /// 2026-08-14: a near-black, Revolut-style ambient backdrop for the rest of
  /// Home, below the (still blue) hero — replaces `_heroSideGlow`'s blue
  /// continuation for now. Starts _heroSideGlowOverlap px above the hero's
  /// REAL measured bottom for the same reason that constant exists: the
  /// hero's own bottom corners are rounded (see _topBanner), so this has to
  /// already be painted back there, or the corner's curve reveals a sliver
  /// of the plain light backdrop instead.
  ///
  /// Deliberately does NOT try to avoid the Prenumeratos/Sąskaitos cards, the
  /// weekly chart, or the Finansų Agentas banner — it doesn't need to. Those
  /// are opaque cards drawn ON TOP of this in the Stack (same pattern as the
  /// hero's own side glow), so they simply cover whatever's behind them;
  /// this shows through only in the margins and the gaps between cards,
  /// which is the same as "not behind the cards" from the user's side.
  Widget _homeDarkBackdrop() {
    final h = _heroHeight;
    if (h == null) return const SizedBox.shrink();
    return Positioned(
      top: h - _heroSideGlowOverlap,
      left: 0,
      right: 0,
      bottom: 0,
      child: Stack(children: [
        const Positioned.fill(child: DecoratedBox(decoration: BoxDecoration(color: Color(0xFF0A0A10)))),
        Positioned.fill(
          child: DecoratedBox(
            decoration: BoxDecoration(
              gradient: RadialGradient(
                center: const Alignment(-0.7, -0.25),
                radius: 0.9,
                colors: [const Color(0xFF2F6BFF).withValues(alpha: 0.20), const Color(0xFF2F6BFF).withValues(alpha: 0)],
              ),
            ),
          ),
        ),
        Positioned.fill(
          child: DecoratedBox(
            decoration: BoxDecoration(
              gradient: RadialGradient(
                center: const Alignment(0.9, 0.55),
                radius: 0.9,
                colors: [const Color(0xFF7C5CD6).withValues(alpha: 0.16), const Color(0xFF7C5CD6).withValues(alpha: 0)],
              ),
            ),
          ),
        ),
      ]),
    );
  }

  /// The app's shared backdrop: a soft gradient, plus (in light "Frost") three
  /// faint colour glows. Painted behind every tab so the whole app stands on the
  /// same ground — the home tab used to have this while Overview, AI chat,
  /// Planning and Account were flat white.
  // Shared by EVERY tab (Home, Overview, Agent, Planning, Account) — the
  // preview palette experiment is scoped to Home only, so this stays exactly
  // as it always was. (2026-08-12: briefly made this blue too, which leaked
  // the hero's colour into every other tab — reverted.)
  Widget _frostBackdrop() => Stack(
        children: [
          Positioned.fill(
            child: DecoratedBox(
              decoration: _darkMode
                  ? const BoxDecoration(
                      gradient: LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        colors: [
                          Color(0xFF07060E),
                          Color(0xFF0A0910),
                          Color(0xFF141220)
                        ],
                        stops: [0.0, 0.5, 1.0],
                      ),
                    )
                  // 2026-08-17 v3: v1 (off-center corner glow) and v2 (top
                  // vignette) were both too subtle to register against a
                  // busy real screen — "niekas nepasikeitė". Flat base again
                  // (matches [[vaultie-keep-light-mode-restrained]]); the
                  // dot-grid painter below carries the "more interesting"
                  // part now, texture rather than a colour gradient.
                  : const BoxDecoration(color: Color(0xFFF4F5FA)),
            ),
          ),
          if (!_darkMode)
            const Positioned.fill(
              child: IgnorePointer(
                child: CustomPaint(painter: _DotGridPainter(alpha: 0.09)),
              ),
            ),
          if (!_darkMode) ..._frostMesh,
        ],
      );

  /// Light "Frost" mesh: three faint colour glows over the base gradient, kept
  /// low-alpha so cards and dark ink stay perfectly legible on top.
  static const List<Widget> _frostMesh = [
    Positioned.fill(
      child: DecoratedBox(
        decoration: BoxDecoration(
          gradient: RadialGradient(
            center: Alignment(-0.85, -1.0),
            radius: 1.15,
            colors: [Color(0x1A2F6BFF), Color(0x002F6BFF)],
            stops: [0.0, 1.0],
          ),
        ),
      ),
    ),
    Positioned.fill(
      child: DecoratedBox(
        decoration: BoxDecoration(
          gradient: RadialGradient(
            center: Alignment(1.0, -0.85),
            radius: 1.05,
            colors: [Color(0x1714B8A6), Color(0x0014B8A6)],
            stops: [0.0, 1.0],
          ),
        ),
      ),
    ),
    // Bottom glow: blue (was pink) so the page reads all-blue top-to-bottom
    // instead of cooling to a warm/red tint at the fold.
    Positioned.fill(
      child: DecoratedBox(
        decoration: BoxDecoration(
          gradient: RadialGradient(
            center: Alignment(0.3, 1.15),
            radius: 1.2,
            colors: [Color(0x142F6BFF), Color(0x002F6BFF)],
            stops: [0.0, 1.0],
          ),
        ),
      ),
    ),
