  int _monthCount(String mk) =>
      _feedAll.where((t) => _dOf(t).startsWith(mk)).length;

  // ── Canonical month figures — the SINGLE source of truth so the same concept
  // shows the same number everywhere. Prefer the backend `totals` block; fall
  // back to the shared top-level _flowOf/_spendOf rule.
  Map<String, dynamic>? get _totalsBlock =>
      _d['totals'] as Map<String, dynamic>?;

  Map<String, dynamic>? _monthTotals(String mk) =>
      (_totalsBlock?['months'] as Map?)?[mk] as Map<String, dynamic>?;

  Iterable<Map<String, dynamic>> _rowsForMonth(String mk) =>
      _feedAll.where((t) => _dOf(t).startsWith(mk));

  double _monthExpenses(String mk) {
    // Backend totals cover the whole month; when a filter is active they don't
    // match the shown rows, so compute from the filtered rows instead.
    if (!_txFilter.active) {
      final m = _monthTotals(mk);
      if (m != null) return (m['expenses'] as num).toDouble();
    }
    return _sumExpenses(_rowsForMonth(mk));
  }

  double _monthIncome(String mk) {
    if (!_txFilter.active) {
      final m = _monthTotals(mk);
      if (m != null) return (m['income'] as num).toDouble();
    }
    return _sumIncome(_rowsForMonth(mk));
  }

  // Canonical month net = income − expenses (NOT a raw sum of amounts, which
  // double-counts transfers between the user's own accounts).
  double _monthNet(String mk) => _monthIncome(mk) - _monthExpenses(mk);

  Widget _monthHeaderFor(String mk) {
    // mk can be a padded/odd key from a malformed row; parse the month safely so
    // a bad date never crashes the header (int.parse("  ") threw).
    final mi = (mk.length >= 7 ? int.tryParse(mk.substring(5, 7)) : null) ?? 1;
    return _monthHeader(
        _monNom[(mi - 1).clamp(0, 11)], _monthExpenses(mk), _monthIncome(mk));
  }

  // Build a day-by-day feed for a month from the flat `all` list (merging same
  // merchant on the same day into an N× row, like the current-month feed).
  List<Map<String, dynamic>> _monthFeed(String mk) {
    final rows = _feedAll.where((t) => _dOf(t).startsWith(mk)).toList();
    final byDate = <String, List<Map<String, dynamic>>>{};
    for (final t in rows) {
      byDate.putIfAbsent(_dOf(t), () => []).add(t);
    }
    final days = byDate.keys.toList()..sort((a, b) => b.compareTo(a));
    final out = <Map<String, dynamic>>[];
    for (final d in days) {
      final dayTx = byDate[d]!;
      final merged = <String, Map<String, dynamic>>{};
      for (final t in dayTx) {
        // A split receipt's children (Rimi maišas, Atvirukas, ...) each get a
        // UNIQUE mkey (see _applyTxSplits) so they'd never merge under the
        // usual same-mkey rule — every product would flood the feed as its
        // own row. 2026-08-21 per request ("pasiklys tarp transakciju"):
        // group them by their shared splitGroup instead, back into ONE row
        // showing the merchant + full total, same as before the split. The
        // itemised breakdown moves into _TxDetailScreen (_splitItemsCard),
        // reached by tapping this row — _underlying resolves it back to the
        // real per-item rows via splitGroup.
        final isSplit = t['splitGroup'] != null;
        final k = isSplit ? t['splitGroup'] as String : t['mkey'] as String;
        final m = merged.putIfAbsent(
            k,
            () => {
                  'nm': isSplit ? (t['splitMerchant'] ?? t['nm']) : t['nm'],
                  'cat': t['cat'],
                  'ic': isSplit ? 'doc' : t['ic'],
                  'col': isSplit ? 'other' : t['col'],
                  'a': 0.0, 'count': 0, 'badges': t['badges'], 'amb': t['amb'],
                  'pos': t['pos'],
                  // identity + fields so the detail screen can find/edit/delete the
                  // underlying row(s): a group shares (mkey, date).
                  'mkey': k, 'd': d, 'sec': t['sec'], 'secc': t['secc'],
                  'star': t['star'] == true,
                  // 2026-08-31: real bug, reported — this reconstruction
                  // whitelist dropped 'cashSrc' entirely, so the cash badge
                  // (_txRow) never showed here even for a single, un-merged
                  // manual cash row — every row in the Transactions feed
                  // goes through this same putIfAbsent regardless of
                  // whether it ends up merging with anything else.
                  'cashSrc': t['cashSrc'] == true,
                  'ts': t['ts'],
                  // raw/cur (the bank's own pre-conversion figure) — dropped here
                  // before, so every merged row (even a "merge" of one) lost them
                  // and _eurTx always fell back to the EUR round-trip, ~6% off.
                  'raw': 0.0, 'cur': t['cur'],
                  'splitGroup': isSplit ? k : null,
                  'isSplitGroup': isSplit,
                });
        if (t['star'] == true) m['star'] = true;
        m['a'] = (m['a'] as double) + _aOf(t).toDouble();
        m['count'] = (m['count'] as int) + 1;
        if ((m['count'] as int) > 1) m['ts'] = null; // merged → no single time
        // A merged row's raw sum is only meaningful when every leg shares ONE
        // currency — same rule the server's own day-merge uses. Mixed legs fall
        // back to the EUR-derived 'a' rather than summing unlike currencies.
        final legRaw = t['raw'];
        final legCur = (t['cur'] as String?)?.toUpperCase();
        if (m['cur'] != null && legCur != null && m['cur'] == legCur && legRaw is num) {
          m['raw'] = (m['raw'] as double) + legRaw.toDouble();
        } else {
          m['cur'] = null;
        }
      }
      // `pos` drives the GREEN amount, and the group inherited it from whichever
      // row happened to create the entry. Two APPLE.COM/BILL rows on one day —
      // a charge and a smaller refund — merged to −117,46 € but kept the refund's
      // pos:true and rendered green, i.e. money spent shown as money received.
      // Once rows are summed, only the sum can say which direction the group went.
      final tx = merged.values.map((m) {
        final n = m['count'] as int;
        return {
          ...m,
          if (n > 1) 'pos': (m['a'] as double) > 0,
          'count': n > 1 ? n : 0,
        };
      }).toList();
      // Day "spent" uses the canonical rule (expenses only) so it stays
      // consistent with the month header and category totals.
      final total = dayTx.fold(0.0, (s, t) => s + _spendOf(t));
      // What the header actually shows: the sum of the rows printed underneath
      // it, signed the way those rows are signed. `total` above is NET SPENDING
      // — positive means money left — which is the opposite convention to every
      // row in the list, so a day on which more money arrived than left was
      // headed "−76,74 €" and read as a day of spending. The one property that
      // makes this number checkable is that adding up the visible rows gives it.
      final netFlow = dayTx.fold(0.0, (s, t) => s + _aOf(t).toDouble());
      final dt = DateTime.tryParse(d);
      if (dt == null)
        continue; // skip a day with an unparseable date, don't crash
      out.add({
        'date': d,
        'wd': _wdFull[dt.weekday - 1],
        'day': dt.day,
        'total': total,
        'net': netFlow,
        'tx': tx
      });
    }
    return out;
  }

  Widget _filters() {
    // "Visas laikas" removed: the feed is already all-time (scroll → past months,
    // each with its own total), and period-scoped analysis lives in the Apžvalga
    // / Planavimas tabs — a placeholder chip here only duplicated that.
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          GestureDetector(
            onTap: _openDashFilter,
            child: _Chip(
              icon: Icons.tune_rounded,
              label: _txFilter.active
                  ? '${tr('Filtras')} · ${_txFilter.count}'
                  : tr('Filtras'),
              active: _txFilter.active,
            ),
          ),
          // 2026-08-30: instant clear right next to the chip — the sheet's
          // own "Išvalyti" link already did this, but required opening the
          // whole sheet first just to turn the filter back off.
          if (_txFilter.active) ...[
            const SizedBox(width: 8),
            GestureDetector(
              onTap: _clearTxFilter,
              child: Icon(Icons.close_rounded, size: 20, color: _muted),
            ),
          ],
          const SizedBox(width: 8),
          // 2026-08-30: was a bare, unlabelled icon up in the header —
          // reported real gap: nothing told a new user it existed, let alone
          // what it did. A labelled chip, right next to Filtras (a pattern
          // this screen already teaches — "chips here are tappable
          // controls"), reads immediately as its own action instead of
          // decoration. `active: true` gives it a permanent accent tint
          // (unlike Filtras, which is only tinted when a filter is ON) —
          // this one is always "ready to tap", not a state to toggle.
          GestureDetector(
            onTap: _openCashExpense,
            child: _Chip(
              icon: Icons.payments_outlined,
              label: tr('Mokėjau grynais'),
              active: true,
            ),
          ),
        ]),
        if (_txFilter.active)
          Padding(
