  /// Three overlapping, ACTUALLY-blurred blobs — a hard-edged RadialGradient
  /// falloff reads as a flat smudge no matter how saturated its colour is;
  /// real Gaussian blur (ImageFiltered) plus higher alpha is most of what
  /// separates "faded" from the reference deck's own luminous glow.
  // v5 (2026-08-12): dropped ImageFiltered/blur entirely — even with a large
  // transparent margin and TileMode.decal it still produced a visible
  // rounded-rectangle "block" on device (Impeller compositing the blur's own
  // layer bounds, most visible where it overlapped the chart's end labels).
  // A plain multi-stop RadialGradient has no layer edge to show at all: it
  // fades to fully transparent by construction, not by post-processing.
  Widget _previewGlow() => Positioned.fill(
        child: IgnorePointer(
          child: Stack(children: [
            _glowBlob(top: -160, left: -80, size: 420,
                color: const Color(0xFFA9C4FF), alpha: 0.10),
            _glowBlob(top: -90, left: 80, size: 260,
                color: const Color(0xFF6E9BFF), alpha: 0.40),
            _glowBlob(top: -70, right: 10, size: 200,
                color: const Color(0xFF2F6BFF), alpha: 0.30),
          ]),
        ),
      );

  Widget _glowBlob({
    double? top,
    double? left,
    double? right,
    double? bottom,
    required double size,
    required Color color,
    required double alpha,
  }) {
    return Positioned(
      top: top,
      left: left,
      right: right,
      bottom: bottom,
      child: IgnorePointer(
        child: Container(
          width: size,
          height: size,
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            gradient: RadialGradient(
              colors: [
                color.withValues(alpha: alpha),
                color.withValues(alpha: alpha * 0.5),
                color.withValues(alpha: 0),
              ],
              stops: const [0.0, 0.5, 1.0],
            ),
          ),
        ),
      ),
    );
  }

  /// Balance change vs ~a month ago (the last dated point ≥30 days back, else the
  /// series start): returns (absolute €, percent). Nulls when there isn't data.
  (double?, double?) _balanceDelta(List<Map> series, double? cur) {
    if (cur == null || series.length < 2) return (null, null);
    double? prev;
    final lastD = DateTime.tryParse((series.last['d'] ?? '').toString());
    if (lastD != null) {
      final target = lastD.subtract(const Duration(days: 30));
      for (final p in series) {
        final d = DateTime.tryParse((p['d'] ?? '').toString());
        if (d != null && !d.isAfter(target))
          prev = (p['v'] as num?)?.toDouble();
      }
    }
    prev ??= (series.first['v'] as num?)?.toDouble();
    if (prev == null) return (null, null);
    final delta = cur - prev;
    final pct = prev.abs() > 1e-6 ? delta / prev.abs() * 100 : null;
    // The balance history is RECONSTRUCTED by walking backwards over transactions,
    // so far-back points drift toward ~0 — and a change measured against a near-zero
    // baseline is meaningless (a €495 balance was showing "+6016 %" because the
    // reconstructed month-ago value was ~€8). When the baseline is unreliable — no
    // usable %, or an implausible month-over-month swing (>300 %) — suppress the
    // WHOLE "vs last month" comparison rather than show a nonsense figure (both the
    // % and the € delta derive from that same bad baseline).
    if (pct == null || pct.abs() > 300) return (null, null);
    return (delta, pct);
  }

  // 2026-08-15: PREVIEW-ONLY — "if the last ~14 days' rate holds, here's the
  // balance at month-end." A straight-line extrapolation, not a forecast —
  // deliberately simple so it's easy to reason about what it's actually
  // saying. Null when there's under 2 days of recent data to draw a rate
  // from, rather than guess off a single point.
  double? _projectedMonthEnd(List<Map> series, double? cur) {
    if (cur == null || series.isEmpty) return null;
    final now = DateTime.now();
    final monthEnd = DateTime(now.year, now.month + 1, 0);
    final today = DateTime(now.year, now.month, now.day);
    final daysLeft = monthEnd.difference(today).inDays;
    if (daysLeft <= 0) return cur;
    final cutoff = today.subtract(const Duration(days: 14));
    final recent = <(DateTime, double)>[];
    for (final p in series) {
      final d = DateTime.tryParse((p['d'] ?? '').toString());
      final v = (p['v'] as num?)?.toDouble();
      if (d != null && v != null && !d.isBefore(cutoff)) recent.add((d, v));
    }
    if (recent.length < 2) return null;
    recent.sort((a, b) => a.$1.compareTo(b.$1));
    final spanDays = recent.last.$1.difference(recent.first.$1).inDays;
    if (spanDays <= 0) return null;
    final dailyRate = (recent.last.$2 - recent.first.$2) / spanDays;
    return cur + dailyRate * daysLeft;
  }

  /// ~5 evenly-spaced "dd-MM" labels spanning the balance series, for the chart's
  /// x-axis. Empty when there aren't enough dated points.
  List<String> _sparkDateLabels(List<Map> series) {
    final dates = series
        .map((p) => (p['d'] ?? '').toString())
        .where((s) => s.length >= 10)
        .toList();
    if (dates.length < 2) return const [];
    const n = 5;
    final out = <String>[];
    for (var i = 0; i < n; i++) {
      final idx = ((dates.length - 1) * i / (n - 1)).round();
      final s = dates[idx];
      out.add('${s.substring(8, 10)}-${s.substring(5, 7)}');
    }
    return out;
  }

  // [account] scopes the sheet to ONE bank — its own series (see
  // functions/dashboard.py's _balance_block), its own current amount, no
  // combined household total. Null (the hero's own balance tap) shows the
  // combined view exactly as before.
  void _showBalance([Map<String, dynamic>? account]) {
    final bal = account == null
        ? _d['balance'] as Map<String, dynamic>
        : {
            'current': account['amount'],
            // Old cached accounts (synced before this existed) or one with
            // no transactions yet carry no series — _BalanceSheet already
            // shows its own "Balanso istorijos dar nėra" empty state for
            // that, same as it always has for a brand-new connection.
            'series': account['series'] ?? const [],
            'accounts': [account],
          };
    showModalBottomSheet(
      context: context,
      backgroundColor: _card,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (_) => _BalanceSheet(
          bal: bal,
          title: account == null
              ? null
              : (account['bank'] ?? account['name'] ?? acctFallbackName()).toString()),
    );
  }

  // Dashboard recurring block (Bilance-style, calm): ONE card, but the top
  // row is two INDEPENDENT tap targets — Prenumeratos opens the manager
  // filtered to subscriptions, Sąskaitos opens it filtered to bills, so one
  // tap never lands you on the other pool. Below it, a PERMANENT "review
  // recurring payments" row opens the ＋/✗ sheet — amber with a count when the
  // engine is unsure, calm otherwise. No outer title: the halves label it.
  Widget _subsCard() {
    final subs = _d['subs'] as Map<String, dynamic>;
    final hidden = DashboardStore.recurringHidden();
    // allItems (incl. hidden + manual) go to the manager so it can restore hidden
    // ones; items (hidden dropped) drive the totals/split.
    final allItems = _recItemsFull(subs);
    final items = allItems.where((it) => !_recHasVerdict(hidden, it)).toList();
    final excl = DashboardStore.recurringExcluded();
    final incl = DashboardStore.recurringIncluded();
    final counted = items.where((it) => _recCounted(it, excl, incl)).toList();
    double subsSum = 0, billsSum = 0;
    int subsN = 0, billsN = 0;
    for (final it in counted) {
      final m = ((it['monthly'] ?? 0) as num).toDouble();
      if (_recType(it) == 'subscription') {
        subsSum += m;
        subsN++;
      } else {
        billsSum += m;
        billsN++;
      }
    }

    // Each card is its own destination — 'subscription'/'bill' — using the
    // 2026-08-13 redesign (hero + ranked candidate sort, real logos) instead
    // of the old toggle-switch manager, so a tap on "Prenumeratos" can never
    // land the user on a Sąskaitos row (and vice versa). The candidate review
    // this used to need a SEPARATE "Patikrink pasikartojančius mokėjimus" row
    // for now lives inside each card's own hero ("Peržiūrėti mokėjimus") —
    // that row would only have duplicated it.
    Future<void> openManager(String typeFilter) async {
      await Navigator.of(context).push(MaterialPageRoute(
          builder: (_) => LiveRecurringScreen(
                wantType: typeFilter,
                title: typeFilter == 'subscription' ? tr('Prenumeratos') : tr('Sąskaitos'),
                itemsOverride: allItems,
                allTransactions: (_d['all'] as List?)?.cast<Map>(),
                demo: widget.demo,
                // 2026-08-21: a due-day correction made inside the manager
                // (LiveRecurringScreen._editDueDay) used to only update the
                // calendar/list there — the actual local reminder kept
                // firing off the OLD predicted date until the next
                // auto-sync happened to call _rescheduleReminders on its
                // own, which could be hours away. Rebuild it immediately.
                onDueDateChanged: () => _rescheduleReminders(_d),
              )));
      // Toggling a payment off in the manager has to reach Planning's copy of
      // the list too — it lives in the CACHED tab list, not this tab's state.
      if (mounted) setState(() => _otherTabs = null);
    }

    // The demo taps these cards by calling the very handler each card's own
    // GestureDetector uses, so it can never drift from what a real tap does.
    if (widget.demo) {
      _demoOpenSubs = () => openManager('subscription');
      _demoOpenBills = () => openManager('bill');
    }

    Widget card(GlobalKey? key, String label, double sum, int n, Color dot,
            String typeFilter) =>
        Expanded(
          child: GestureDetector(
            key: key,
            onTap: () => openManager(typeFilter),
            behavior: HitTestBehavior.opaque,
            child: Container(
              decoration: BoxDecoration(
                color: _card,
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: _hair),
                boxShadow: _darkMode
                    ? null
                    : [
                        BoxShadow(
                            color: const Color(0xFF1E284A).withValues(alpha: 0.05),
                            blurRadius: 16,
                            offset: const Offset(0, 6))
                      ],
              ),
              padding: const EdgeInsets.fromLTRB(16, 15, 14, 15),
              child: Row(children: [
                Expanded(child: _recHalf(label, sum, n, dot)),
                Icon(Icons.chevron_right_rounded, size: 18, color: _faint),
              ]),
            ),
          ),
        );

    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
        card(_kRec, tr('Prenumeratos'), subsSum, subsN,
            _catColors['entertainment']!, 'subscription'),
        const SizedBox(width: 12),
        card(_kBills, tr('Sąskaitos'), billsSum, billsN,
            _catColors['housing']!, 'bill'),
      ]),
    );
  }

  // 2026-08-14: a "Santaupų norma" (savings rate) card for Home, matching
  // the reference — right below Prenumeratos/Sąskaitos. Overview already has
  // a fuller version of this same card (_savingsCard in _OverviewTabState),
  // but that class computes it from ITS OWN filtered-rows/month-key state,
  // which Home doesn't share — this is a lighter, Home-scoped version off
  // the SAME _monthIncome/_monthExpenses this class already uses for the
  // month headers in _transactionsTab, tapping through to Apžvalga (index 1)
  // for the full breakdown rather than duplicating it here.
  // Savings % for a month, or null if it had no income to divide by (the
  // same "no income → undefined, not 0%" rule _OverviewTabState's _savingsOf
  // uses).
  // 2026-08-14: was `.clamp(0, 100)` — a month where you spent more than you
  // earned rounded to a flat "0%", indistinguishable from a month you broke
  // even on. The gauge below exists specifically to show that difference
  // (red, below the zero tick), so the number behind it has to be honest too.
  // 2026-08-16: a month with a tiny stray "income" row (a few € refund,
  // say) technically satisfies earned > 0 but isn't a real income month —
  // dividing by it produces a mathematically-correct but absurd number
  // (-2000%+), which then blows out the 6-month chart's whole scale.
  // Clamped to ±100 — past that point the sign and "you way overspent" is
  // already the whole story; more precision isn't more useful.
  int? _savingsPctFor(String mk) {
    final earned = _monthIncome(mk);
    if (earned <= 0) return null;
    final spent = _monthExpenses(mk);
    return (((earned - spent) / earned) * 100).round().clamp(-100, 100);
  }

  // 2026-08-14: a "Santaupų norma" (savings rate) card for Home, matching
  // the reference — right below Prenumeratos/Sąskaitos. Overview already has
  // a fuller version of this same card (_savingsCard in _OverviewTabState),
  // but that class computes it from ITS OWN filtered-rows/month-key state,
  // which Home doesn't share — this is a lighter, Home-scoped version off
  // the SAME _monthIncome/_monthExpenses this class already uses for the
  // month headers in _transactionsTab, tapping through to the real detail
  // screen (_SavingsRateScreen — see 2026-08-15 note there) rather than
  // duplicating it here. 2026-08-15: the bigger unboxed half-donut gauge
  // tried here didn't read well sitting on Home among the other boxed
  // cards — that treatment moved into the detail screen itself instead;
  // this stayed the small boxed ring, just with the clamp removed so a
  // month you overspent shows its real negative number, not a flat "0%".
  Widget _savingsRateCard() {
    final keys = (_feedAll.map((t) => _ymOf(t)).toSet().toList()..sort()); // ascending
    final now = DateTime.now();
    final curMk = '${now.year}-${now.month.toString().padLeft(2, '0')}';

    // Most of any given month has no salary landed yet — showing a blank
    // "šį mėn. dar nėra" for most of the month made the card read as
    // permanently empty on Home (a glance-y summary, unlike the Overview
    // detail screen where drilling into an empty month is expected). Falls
    // back to the most recent month that DID have income, labelled as such,
    // so the card almost always has a real number on it.
    var shownMk = curMk;
    var pct = _savingsPctFor(curMk);
    var isCurrent = true;
    if (pct == null) {
      for (final mk in keys.reversed) {
        if (mk == curMk) continue;
        final p = _savingsPctFor(mk);
        if (p != null) {
          shownMk = mk;
          pct = p;
          isCurrent = false;
          break;
        }
      }
    }
    final net = _monthIncome(curMk) - _monthExpenses(curMk);

    return GestureDetector(
      // The real detail screen (_SavingsRateScreen) — same one Overview's
      // own savings card opens (see _openSavings) — not a stand-in. Built
      // from Home's OWN data (_feedAll/_monthIncome/_monthExpenses) since
      // this class doesn't share _OverviewTabState's filtered-rows state.
      onTap: () => Navigator.of(context).push(MaterialPageRoute(
          builder: (_) => _SavingsRateScreen(
                monthKeys: keys,
                savingsOf: (rows) {
                  final e = _sumIncome(rows);
                  if (e <= 0) return 0;
                  final s = _sumExpenses(rows);
                  return (((e - s) / e) * 100).round().clamp(-100, 100);
                },
                earnedOf: _sumIncome,
                rowsOf: (mk) => _rowsForMonth(mk).toList(),
                initialKey: shownMk,
                all: _feedAll.toList(),
              ))),
      behavior: HitTestBehavior.opaque,
      child: Container(
        margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 16),
        decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: _hair),
          boxShadow: _darkMode
              ? null
              : [
                  BoxShadow(
                      color: const Color(0xFF1E284A).withValues(alpha: 0.05),
                      blurRadius: 16,
                      offset: const Offset(0, 6))
                ],
        ),
        child: Row(children: [
          SizedBox(
            width: 44,
            height: 44,
            child: Stack(alignment: Alignment.center, children: [
              CircularProgressIndicator(
                value: pct == null ? 0 : (pct / 100).clamp(0.0, 1.0),
                backgroundColor: _hair,
                color: pct != null && pct < 0 ? DS.danger : _purple,
                strokeWidth: 4,
              ),
              if (pct != null)
                Text('$pct%',
                    style: TextStyle(fontSize: 11, fontWeight: FontWeight.w800, color: _ink)),
            ]),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(tr('Santaupų norma'),
                    style: TextStyle(fontSize: 15.5, fontWeight: FontWeight.w700, color: _ink)),
                const SizedBox(height: 2),
                Text(
                    pct == null
                        ? tr('Dar nėra pajamų duomenų')
                        : (isCurrent
                            ? (net >= 0
                                ? '${tr('Sutaupei')} ${_eur0(net)}'
                                : '${tr('Viršyta')} ${_eur0(-net)}')
                            : '$pct% · ${tr('praėjusio mėn.')}'),
                    style: TextStyle(
                        fontSize: 12.5,
                        color: (pct != null && pct < 0) ? DS.danger : _muted)),
              ],
            ),
          ),
          Icon(Icons.chevron_right_rounded, size: 20, color: _faint),
        ]),
      ),
    );
  }

  // 2026-08-14: a Bilance-style "Finance Agent" promo card — sits right below
  // the weekly spend chart. 2026-08-14: the AI chat no longer has its own
  // bottom-nav row (that slot now opens Transakcijos — see _navBar) — this
  // banner is the one remaining doorway to it, so it PUSHES the chat as its
  // own screen rather than switching tabs (there's no nav row left that
  // would highlight for it). The robot art is a true transparent cutout
  // (see assets/images/finance_agent_robot.png) so it blends straight into
  // this gradient with no background rectangle of its own.
  // 2026-08-16: PREVIEW-ONLY — top merchants by total spend, across ALL
  // synced history (not the current month — Apžvalga already answers "this
  // month", so this answers "overall, where does my money really go"). Uses
  // the canonical _spendOf rule (refunds net down, transfers excluded), same
  // as every other spend figure in the app.
  List<({String name, double amt, int count, String? cat})> _topMerchants(
      {int limit = 6, String? monthKey}) {
    final allRows = (_d['all'] as List?)?.cast<Map>() ?? const [];
    // monthKey == null keeps the original "whole synced history" behaviour;
    // a specific 'YYYY-MM' narrows to just that month.
    final rows = monthKey == null
        ? allRows
        : allRows.where((t) => _ymOf(t) == monthKey).toList();
    final byKey = <String, ({String name, double amt, int count, String? cat})>{};
    for (final t in rows) {
      final spend = _spendOf(t);
      if (spend <= 0) continue;
      final nm = _nmOf(t).trim();
      if (nm.isEmpty) continue;
      final key = _merchantKey(nm);
      final ex = byKey[key];
      // Prefer the longer of the name variants seen — usually the more
      // legible one ("ARTUS GRUPĖ, MB" over "Mb artusgrupe").
      final name = ex == null || nm.length > ex.name.length ? nm : ex.name;
      byKey[key] = (
        name: name,
        amt: (ex?.amt ?? 0) + spend,
        count: (ex?.count ?? 0) + 1,
        cat: ex?.cat ?? (t['cat'] as String?),
      );
    }
    final list = byKey.values.toList()..sort((a, b) => b.amt.compareTo(a.amt));
    return list.take(limit).toList();
  }

  // The real earliest→latest dated row in the whole synced history, so the
  // section can say exactly what it's drawn from instead of a vague "all
  // time" — however many months the bank connection actually has (3? 6?)
  // varies per person, so this is computed, never a guessed constant.
  String _historySpanLabel() {
    final rows = (_d['all'] as List?)?.cast<Map>() ?? const [];
    DateTime? earliest, latest;
    for (final t in rows) {
      final d = DateTime.tryParse(_dOf(t));
      if (d == null) continue;
      if (earliest == null || d.isBefore(earliest)) earliest = d;
      if (latest == null || d.isAfter(latest)) latest = d;
    }
    if (earliest == null || latest == null) return tr('Visos operacijos');
    final months =
        (latest.year - earliest.year) * 12 + (latest.month - earliest.month) + 1;
    if (months <= 1) return tr('Šio mėnesio operacijos');
    return '${tr('Paskutinių')} $months ${tr('mėn.')} '
        '(${_monNom[earliest.month - 1]}–${_monNom[latest.month - 1]})';
  }

  /// Distinct 'YYYY-MM' keys present in the whole synced history, newest
  /// first — the list _pickTopMerchantsMonth's sheet offers alongside "Visi".
  List<String> get _topMerchantsMonthKeys {
    final rows = (_d['all'] as List?)?.cast<Map>() ?? const [];
    final keys = <String>{for (final t in rows) _ymOf(t)};
    return keys.toList()..sort((a, b) => b.compareTo(a));
  }

