  Widget _topMerchantsSection() {
    final top = _topMerchants(limit: 6, monthKey: _topMerchantsMonthKey);
    // A month with zero spend still shows the header + filter chip, so the
    // user can switch back to "Visas laikotarpis" without the whole section
    // disappearing out from under them.
    if (top.isEmpty) {
      return Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Expanded(
              child: Text(tr('Kur išleidai daugiausiai'),
                  style: TextStyle(
                      fontSize: 17, fontWeight: FontWeight.w800, color: _ink)),
            ),
            _topMerchantsFilterChip(),
          ]),
          const SizedBox(height: 14),
          Text(tr('Šiuo laikotarpiu operacijų nerasta.'),
              style: TextStyle(fontSize: 13, color: _faint)),
        ]),
      );
    }
    final total = top.fold(0.0, (s, m) => s + m.amt);
    const size = 208.0, stroke = 24.0, r = (size - stroke) / 2;
    final segments = [for (final m in top) [m.amt, SubscriptionAvatar.colorFor(m.name)]];

    // Same angle walk as _DonutPainter (start at 12 o'clock, sweep clockwise,
    // proportional to spend) so each logo sits exactly on its own segment.
    final logos = <Widget>[];
    var start = -math.pi / 2;
    const gap = 0.06;
    for (final m in top) {
      final frac = m.amt / total;
      final sweep = top.length == 1 ? 2 * math.pi : 2 * math.pi * frac - gap;
      final mid = top.length == 1 ? 0.0 : start + gap / 2 + sweep / 2;
      final dx = size / 2 + r * math.cos(mid);
      final dy = size / 2 + r * math.sin(mid);
      logos.add(Positioned(
        left: dx - 16,
        top: dy - 16,
        child: Container(
          padding: const EdgeInsets.all(2.5),
          decoration:
              BoxDecoration(color: _bg, shape: BoxShape.circle, boxShadow: DS.e1),
          // category left null on purpose: SubscriptionAvatar only guesses a
          // brand logo from the NAME when category is null or 'entertainment'
          // — passing the real spend category (groceries, transport…) would
          // have blocked every real logo (Maxima, Circle K, ...) in favour of
          // a generic category-tinted icon.
          child: ClipOval(
              child: SubscriptionAvatar(name: m.name, category: null, size: 27)),
        ),
      ));
      start += 2 * math.pi * frac;
    }

    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Expanded(
            child: Text(tr('Kur išleidai daugiausiai'),
                style: TextStyle(
                    fontSize: 17, fontWeight: FontWeight.w800, color: _ink)),
          ),
          // 2026-08-29: explicit request — this used to always draw from the
          // WHOLE synced history with no way to narrow it to one month.
          _topMerchantsFilterChip(),
        ]),
        const SizedBox(height: 2),
        // Only the "whole history" label needs computing (earliest→latest
        // span) — a specific month already names itself in the chip above,
        // so no second, redundant caption is shown for that case.
        if (_topMerchantsMonthKey == null)
          Text(_historySpanLabel(), style: TextStyle(fontSize: 12, color: _faint)),
        const SizedBox(height: 18),
        Center(
          child: SizedBox(
            width: size,
            height: size,
            child: Stack(children: [
              CustomPaint(size: const Size(size, size), painter: _DonutPainter(segments)),
              Positioned.fill(
                child: Center(
                  child: Column(mainAxisSize: MainAxisSize.min, children: [
                    Text(_eur0(total),
                        style: TextStyle(
                            fontSize: 24,
                            fontWeight: FontWeight.w800,
                            color: _ink)),
                    Text(tr('iš viso'),
                        style: TextStyle(fontSize: 11, color: _faint)),
                  ]),
                ),
              ),
              ...logos,
            ]),
          ),
        ),
        const SizedBox(height: 20),
        Wrap(
          spacing: 18,
          runSpacing: 8,
          children: [
            for (final m in top)
              SizedBox(
                width: (MediaQuery.of(context).size.width - 32 - 18) / 2,
                child: Row(children: [
                  Container(
                      width: 8,
                      height: 8,
                      margin: const EdgeInsets.only(right: 7),
                      decoration: BoxDecoration(
                          color: SubscriptionAvatar.colorFor(m.name),
                          shape: BoxShape.circle)),
                  Expanded(
                    child: Text(m.name,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                            fontSize: 12.5,
                            fontWeight: FontWeight.w600,
                            color: _ink)),
                  ),
                  Text(_eur0(m.amt),
                      style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w700,
                          color: _faint)),
                ]),
              ),
          ],
        ),
      ]),
    );
  }

