  Widget _weekSection() {
    // When a filter is active, or a past week is being browsed, recompute
    // the chart instead of using the cached current-week map — the cache
    // only ever holds THIS week. `_d['week']` is null when the account has
    // no transactions in the window — fall back to computing an (empty)
    // week so the home never crashes.
    final week = (_txFilter.active || _weekOffset != 0)
        ? _computeWeek(_feedAll.toList(), weekOffset: _weekOffset)
        : (_d['week'] as Map<String, dynamic>?) ??
            _computeWeek(_feedAll.toList());
    final days = (week['days'] as List).cast<Map<String, dynamic>>();
    // 2026-08-15: was spending + "gone" money (transfers to people, cash
    // withdrawals) — a big transfer inflated this into looking like a huge
    // spending week. Pure spending now, same figure as everywhere else in
    // the app (_sumExpenses).
    double outOf(Map<String, dynamic> d) => (d['total'] as num).toDouble();
    final total = (week['total'] as num).toDouble();
    double maxV = 1;
    for (final d in days) {
      final t = outOf(d);
      if (t > maxV) maxV = t;
    }
    // Average per ELAPSED day: the week is usually still in progress, so dividing
    // by 7 would understate it. Find this week's Monday (from the range the
    // computed week carries, else the current week) and divide by the days that
    // have actually happened — "your typical day so far". A fully past week
    // divides by 7.
    final n = DateTime.now();
    final today = DateTime(n.year, n.month, n.day);
    DateTime? monday;
    final range = week['range'] as String?;
    if (range != null && range.contains('..')) {
      monday = DateTime.tryParse(range.split('..').first);
    }
    monday ??= today.subtract(Duration(days: today.weekday - 1));
    final sunday = monday.add(const Duration(days: 6));
    // 2026-08-18: the demo dataset is a complete, already-happened week —
    // every day already has a bar — just relabelled onto the current
    // calendar dates for freshness (see _buildDemoDash's shift). Dividing
    // by "days elapsed so far" assumes a week still in progress, which is
    // the right question for a REAL account (most of whose future days
    // genuinely have no transactions yet) but wrong here: with all 7 days
    // already populated, "elapsed" could be as low as 1–2, inflating the
    // average far above every individual bar and pinning the dashed line
    // above all of them instead of through their middle.
    final int elapsed = widget.demo
        ? 7
        : today.isAfter(sunday)
            ? 7
            : today.isBefore(monday)
                ? 1
                : today.difference(monday).inDays + 1;
    final avg = total / elapsed;
    // 2026-08-15: browsable, same idea as the savings-rate month switcher —
    // 0 = this week, -1 = last week, older weeks get a "4–10 rugp." range
    // label since "praėjusią" only reads right one week back.
    final weekTitle = _weekOffset == 0
        ? tr('Šią savaitę išleista')
        : _weekOffset == -1
            ? tr('Praėjusią savaitę išleista')
            : '${monday.day}–${sunday.day} ${_monGen[monday.month - 1]} ${tr('išleista')}';
    return Column(
      children: [
        _activeFilterBanner(),
        Padding(
          padding: const EdgeInsets.fromLTRB(20, 6, 20, 8),
          child: Row(crossAxisAlignment: CrossAxisAlignment.end, children: [
            Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Text(weekTitle,
                    style: TextStyle(
                        fontSize: 14.5,
                        color: _ink,
                        fontWeight: FontWeight.w700)),
                const SizedBox(width: 4),
                _weekNavBtn(
                    icon: Icons.chevron_left_rounded,
                    onTap: () => setState(() {
                          _weekOffset--;
                          _weekSel = null;
                        })),
                _weekNavBtn(
                    icon: Icons.chevron_right_rounded,
                    enabled: _weekOffset < 0,
                    onTap: () => setState(() {
                          _weekOffset++;
                          _weekSel = null;
                        })),
              ]),
              // Average lives in the header (never on top of a bar or its number).
              if (avg > 0)
                Padding(
                  padding: const EdgeInsets.only(top: 2),
                  child: Text('${tr('vidurkis')} ${_eur0(avg)}/d.',
                      style: TextStyle(
                          fontSize: 12,
                          color: _faint,
                          fontWeight: FontWeight.w600)),
                ),
            ]),
            const Spacer(),
            // Positive amount — consistent with the month header's "Išleista X".
            Text(_eur(total),
                style: TextStyle(
                    fontSize: 15, fontWeight: FontWeight.w700, color: _ink)),
          ]),
        ),
        Container(
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 16),
          padding: const EdgeInsets.fromLTRB(10, 16, 10, 10),
          decoration: BoxDecoration(
            // 2026-08-29: was `_soft` — a shade meant to look "recessed"
            // against a white PARENT card that this section never actually
            // renders (no visible outer card here, just this one panel), so
            // it just read as a different tone from the Prenumeratos/
            // Sąskaitos cards right below it (reported, real — most visible
            // in dark mode where _soft/_card are further apart). Matches
            // those cards' own `_card` now.
            color: designPreviewPalette ? _card : _bg,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: _hair),
          ),
          child: LayoutBuilder(
            builder: (context, c) {
              final w = c.maxWidth;
              final sel = _weekSel;
              return Stack(
                clipBehavior: Clip.none,
                children: [
                  // € gridlines + average line, BEHIND the bars.
                  Positioned.fill(
                    child: IgnorePointer(
                      child: CustomPaint(
                        painter: _WeekAvgPainter(
                          avg: avg,
                          maxV: maxV,
                          barMax: 118,
                          label: 'vidurkis ${_eur0(avg)}/d.',
                          dark: _darkMode,
                        ),
                      ),
                    ),
                  ),
                  SizedBox(
                    height: 168,
                    child: AnimatedBuilder(
                      animation: _barsRise ?? kAlwaysCompleteAnimation,
                      builder: (_, __) => Row(
                        crossAxisAlignment: CrossAxisAlignment.end,
                        children: [
                          for (var i = 0; i < days.length; i++)
                            _bar(days[i], maxV, i, days.length,
                                _barsRise?.value ?? 1),
                        ],
                      ),
                    ),
                  ),
                  if (sel != null)
                    Positioned(
                      left: ((sel + 0.5) / days.length * w - 110)
                          .clamp(0.0, (w - 220).clamp(0.0, double.infinity)),
                      top: -102,
                      child: _weekTip(days[sel]),
                    ),
                ],
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _weekNavBtn(
          {required IconData icon,
          bool enabled = true,
          required VoidCallback onTap}) =>
      GestureDetector(
        onTap: enabled ? onTap : null,
        behavior: HitTestBehavior.opaque,
