  Widget _dayGroup(Map<String, dynamic> dd) {
    final tx = (dd['tx'] as List).cast<Map<String, dynamic>>();
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(20, 14, 20, 8),
          child: Row(children: [
            Text('${dd['wd']}, ${dd['day']} d.',
                style: TextStyle(
                    fontSize: 13.5,
                    color: _muted,
                    fontWeight: FontWeight.w600)),
            const Spacer(),
            // The day's net, signed like the rows below it: negative = money
            // left. Older cached days carry no 'net', so fall back to negating
            // the spend-positive 'total' rather than showing a wrong sign.
            Builder(builder: (_) {
              final n = (dd['net'] as num?)?.toDouble() ??
                  -((dd['total'] as num?)?.toDouble() ?? 0);
              return Text(_eur(n, signed: true),
                  style:
                      TextStyle(fontSize: 13.5, color: n > 0 ? _good : _muted));
            }),
          ]),
        ),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16),
          child: AppCard(
            color: _card,
            border: _hair,
            child: Column(children: [
              for (var i = 0; i < tx.length; i++) ...[
                _txRow(tx[i], dd),
                if (i != tx.length - 1) const RowDivider(indent: 57),
              ],
            ]),
          ),
        ),
      ],
    );
  }

  Widget _txRow(Map<String, dynamic> t, Map<String, dynamic> dd) {
    final amb = t['amb'] == true;
    final pos = t['pos'] == true;
    final count = (t['count'] ?? 0) as int;
    final badges = ((t['badges'] as List?) ?? const []).cast<String>();
    return InkWell(
      onTap: () => _openTx(t, dd),
      child: Padding(
        // Tighter than before: smaller icon + less row height + snugger gaps,
        // so more transactions fit a screen and the feed reads calmer. The
        // amount stays full-size and bright — that's the part worth glancing at.
        padding: const EdgeInsets.symmetric(horizontal: 15, vertical: 7),
        child: Row(
          children: [
            Stack(
              clipBehavior: Clip.none,
              children: [
                CategoryIcon(
                    icon: _iconOf(t['ic'] as String?),
                    color: _colOf(t['col'] as String?),
                    size: 32,
                    circle: false,
                    merchant: _logoOf(t),
                    domain: _domOf(t)),
                if (count > 1)
                  Positioned(
                    top: -6,
                    left: -6,
                    child: Container(
                      constraints: const BoxConstraints(minWidth: 19),
                      height: 19,
                      alignment: Alignment.center,
                      padding: const EdgeInsets.symmetric(horizontal: 3),
                      decoration: BoxDecoration(
                        color: _purple,
                        borderRadius: BorderRadius.circular(7),
                        border: Border.all(color: Colors.white, width: 2),
                      ),
                      child: Text('$count×',
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 11,
                              fontWeight: FontWeight.w800)),
                    ),
                  ),
              ],
            ),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(children: [
                    Flexible(
                      child: Text(_txDisplayName(t),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.w700,
                              color: _ink,
                              letterSpacing: -0.2)),
                    ),
                    if (t['star'] == true) ...[
                      const SizedBox(width: 5),
                      const Icon(Icons.star_rounded,
                          size: 14, color: Color(0xFFF5B301)),
                    ],
                  ]),
                  const SizedBox(height: 1),
                  Row(children: [
                    Container(
                      width: 6,
                      height: 6,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color: amb ? Colors.transparent : _purple,
                        border:
                            amb ? Border.all(color: _faint, width: 1.5) : null,
                      ),
                    ),
                    const SizedBox(width: 6),
                    Flexible(
                      child: Text(tr(t['cat'] as String),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(fontSize: 12.5, color: _muted)),
                    ),
                    for (final b in badges) ...[
                      const SizedBox(width: 6),
                      _badge(b),
                    ],
                  ]),
                ],
              ),
            ),
            const SizedBox(width: 10),
            // 2026-08-31: moved here from the category row, right before
            // the amount — see the doc that used to sit here: a manually-
            // logged cash expense otherwise looks identical to a bank row
            // in the feed. Purple, not the green used for income, since
            // this is usually a negative/expense amount — a green mark next
            // to it would read as "this is money coming in", which it isn't.
            if (t['cashSrc'] == true) ...[
              Icon(Icons.payments_rounded, size: 13, color: _purple),
              const SizedBox(width: 4),
            ],
            Text(_eurTx(t, signed: true),
                style: TextStyle(
                    fontSize: 15,
                    fontWeight: FontWeight.w700,
                    letterSpacing: -0.3,
                    color: pos ? _good : _ink,
                    fontFeatures: const [FontFeature.tabularFigures()])),
          ],
        ),
      ),
    );
  }

