  // ── PLACEHOLDER ──────────────────────────────────────────────────────────────

  Widget _navBar() {
    const items = [
      ['Pradžia', Icons.dashboard_rounded],
      ['Apžvalga', Icons.donut_large_rounded],
      ['Transakcijos', Icons.receipt_long_rounded],
      ['Planavimas', Icons.event_note_rounded],
      ['Paskyra', Icons.person_outline_rounded],
    ];
    // Row position 2 used to be "Agentas" (AI chat, IndexedStack index 2).
    // 2026-08-14: the agent is reachable from _financeAgentBanner on Home
    // instead (so it's not lost), freeing this row for the transaction feed
    // that moved out of Home — the feed lives at IndexedStack index 5
    // (appended, not swapped in — see _buildOtherTabs), so this row's real
    // target differs from its on-screen position; every other row still
    // targets its own index. Investavimas (IndexedStack index 6) is NOT in
    // this bar at all — 2026-08-28 per request, it moved to the Home hero's
    // own quick-action row instead (_heroQuickActions), so it isn't offered
    // in two places.
    int navTarget(int i) => i == 2 ? 5 : i;
    final bottomPad = MediaQuery.of(context).padding.bottom;
    // The 10 fallback (no system inset reported — gesture-nav devices that
    // return 0, or a handful of OEM skins) reads fine against iOS's ~34pt home
    // indicator inset, which almost always makes bottomPad > 0 true anyway. On
    // Android the same fallback made the row read as sitting flush against the
    // edge with no breathing room, so it gets a taller floor there specifically.
    final minBottom = Platform.isAndroid ? 16.0 : 10.0;
    return Container(
      decoration: BoxDecoration(
        color: _card,
        border: Border(top: BorderSide(color: _hair)),
      ),
      padding: EdgeInsets.only(top: 8, bottom: bottomPad > 0 ? bottomPad : minBottom),
      child: Row(
        children: [
          for (var i = 0; i < items.length; i++)
            Expanded(
              child: GestureDetector(
                key: !widget.demo
                    ? null
                    : i == 0
                        ? _kNav0
                        : i == 1
                            ? _kNav1
                            : i == 2
                                ? _kNavTx
                                : i == 3
                                    ? _kNav3
                                    : i == 4
                                        ? _kNav4
                                        : null,
                behavior: HitTestBehavior.opaque,
                // Re-tapping the ALREADY-active tab scrolls it back to the top
                // (the iOS convention), so you don't have to scroll up by hand.
                onTap: () {
                  final target = navTarget(i);
                  if (_tab == target) {
                    if (i == 0 && _homeScroll.hasClients) {
                      _homeScroll.animateTo(0,
                          duration: const Duration(milliseconds: 300),
                          curve: Curves.easeOut);
                    }
                  } else {
                    setState(() => _tab = target);
                  }
                },
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(items[i][1] as IconData,
                        size: 24, color: _tab == navTarget(i) ? _purple : _navOff),
                    const SizedBox(height: 4),
                    // Five labels share the width, and the longest of them
                    // ("AI pokalbis", "Planavimas") runs out of room as soon as
                    // text is scaled up — by the onboarding demo, or by anyone
                    // who raised the system text size. Shrink to fit rather
                    // than overflow, which skewed the whole row.
                    FittedBox(
                      fit: BoxFit.scaleDown,
                      child: Text(tr(items[i][0] as String),
                          maxLines: 1,
                          style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.w600,
                              color: _tab == navTarget(i) ? _purple : _navOff)),
                    ),
                  ],
                ),
              ),
            ),
        ],
      ),
    );
  }

  Future<void> _persist() async {
    if (widget.demo) return; // onboarding demo never writes
    // Real app: the payload came from a bank scan and is stored on-device, so
    // manual edits survive restart. Preview harness has no open Hive box —
    // swallow that so the in-memory add still works for design testing.
    try {
      await DashboardStore.persist(_d);
    } catch (_) {/* no store in preview */}
  }

  static String _ymd(DateTime d) =>
      '${d.year.toString().padLeft(4, '0')}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

  // Rebuild the "this week" bar chart from `all` (Mon..Sun of the latest date)
  // so a manual entry in the current week shows up there too — same expenses-
  // only rule as the day/month headers.
  Map<String, dynamic> _computeWeek(List<Map<String, dynamic>> all,
      {int weekOffset = 0}) {
    // Anchor to the CURRENT calendar week (today's Monday) so "Šios savaitės
    // išlaidos" is genuinely this week — even if there's been no spending yet —
    // rather than the week of the most recent transaction. weekOffset shifts
    // that anchor back N weeks so the same chart can browse history.
    final now = DateTime.now();
    final monday = DateTime(now.year, now.month, now.day)
        .subtract(Duration(days: now.weekday - 1))
        .add(Duration(days: 7 * weekOffset));
    final wdShort = _wdShort;
    final days = <Map<String, dynamic>>[];
    var weekTotal = 0.0;
    var weekGone = 0.0;
    for (var i = 0; i < 7; i++) {
      final day = monday.add(Duration(days: i));
      final ds = _ymd(day);
      final rows = all.where((t) => t['d'] == ds);
      final total = _sumExpenses(rows);
      final gone = rows.fold(0.0, (double s, t) => s + _goneOf(t as Map));
      weekTotal += total;
      weekGone += gone;
      final bySec = <String, double>{};
      final secColor = <String, String>{};
      for (final t in rows) {
        final s = _spendOf(t);
        if (s <= 0) continue;
        final sec = _secOf(t);
        bySec[sec] = (bySec[sec] ?? 0) + s;
        secColor[sec] = _seccOf(t);
      }
      final cats = bySec.entries
          .map((e) => {
                'label': e.key,
                'color': secColor[e.key],
                'icon': _secToIcon[e.key] ?? 'transfer',
                'amount': e.value,
              })
          .toList()
        ..sort(
            (a, b) => (b['amount'] as double).compareTo(a['amount'] as double));
      days.add({
        // 'lbl'/'dlabel' are the language the week happened to be COMPUTED in,
        // and this map is persisted to Hive — so after a language switch the
        // bar-chart weekday letters and the tooltip date stayed Lithuanian, and
        // survived a restart until the next bank sync. The numbers below are
        // locale-neutral; the labels are built at render time from them, and the
        // two strings stay only as a fallback for data persisted by older builds.
        'lbl': wdShort[i],
        'total': total,
        'gone': gone,
        'cats': cats,
        'dlabel': '${_monGen[day.month - 1]} ${day.day}',
        'wdi': day.weekday, // 1..7, Monday-first — matches wdShort's order
        'mo': day.month,
        'dd': day.day,
      });
    }
    return {
      'total': weekTotal,
      'gone': weekGone,
      'days': days,
      'range': '${_ymd(monday)}..${_ymd(monday.add(const Duration(days: 6)))}',
    };
  }
}

