  _ManualCat('Bankas, komisiniai', 'Finansai', 'red', 'finance', 'money'),
  _ManualCat('Investicijos', 'Finansai', 'red', 'finance', 'doc'),
  _ManualCat('Paskola, lizingas', 'Finansai', 'red', 'finance', 'money'),
  _ManualCat('Mokslas', 'Švietimas', 'purple', 'edu', 'edu'),
  _ManualCat('Kursai, knygos', 'Švietimas', 'purple', 'edu', 'edu'),
  _ManualCat('Vaikai, ugdymas', 'Švietimas', 'purple', 'edu', 'edu'),
  _ManualCat('Kita', 'Kita', 'indigo', 'other', 'swap'),
];
const _incomeCats = <_ManualCat>[
  _ManualCat('Atlyginimas', 'Pajamos', 'amber', 'income', 'income'),
  _ManualCat('Pajamos', 'Pajamos', 'amber', 'income', 'income'),
  _ManualCat('Dovana', 'Pajamos', 'amber', 'income', 'income'),
  // _flowOf checks this EXACT string directly — a manual pick here really
  // does reclassify the row as a refund, not just relabel it.
  _ManualCat('Grąžinimas', 'Pajamos', 'amber', 'income', 'income'),
];
const _transferCats = <_ManualCat>[
  _ManualCat('Pervedimas', 'Pervedimai', 'indigo', 'transfer', 'swap'),
  _ManualCat('Grynieji', 'Pervedimai', 'indigo', 'transfer', 'swap'),
  _ManualCat(
      'Asmeninis pervedimas', 'Pervedimai', 'indigo', 'transfer', 'person'),
  _ManualCat(
      'Sąskaitos papildymas', 'Pervedimai', 'indigo', 'transfer', 'swap'),
  // _receivedOf checks this EXACT string directly too — picking it excludes
  // the row from "Gauta", same as a bank-detected own-account transfer.
  _ManualCat(
      'Savas pervedimas', 'Pervedimai', 'indigo', 'transfer', 'swap'),
  _ManualCat(
      'Valiutos keitimas', 'Pervedimai', 'indigo', 'transfer', 'swap'),
];
List<_ManualCat> _catsFor(String kind) => kind == 'income'
    ? _incomeCats
    : kind == 'transfer'
        ? _transferCats
        : _expenseCats;

// Look up full row metadata (sec/secc/col/ic) for a category label — used when
// recategorising an existing transaction so it gets consistent colours/section.
_ManualCat? _catMetaFor(String cat) {
  for (final list in [_expenseCats, _incomeCats, _transferCats]) {
    for (final c in list) {
      if (c.cat == cat) return c;
    }
  }
  return null;
}

/// The month chronologically right before [key], or null if [key] is the
/// first one (or isn't in the list at all).
///
/// Shared by the Overview savings badge and _SavingsRateScreen — both need
/// "the month before whichever one is currently on screen". Both used to
/// compute this as `monthKeys[monthKeys.length - 2]`, a fixed "second-to-last
/// in the whole dataset" that was only ever correct when the month on screen
/// happened to be the newest one: browsing April still showed May as "last
/// month" (the actual second-to-last month while June exists), and tapping
/// into the savings-rate screen from ANY month but the newest dropped the
/// user onto June's figures regardless of what they'd tapped from.
@visibleForTesting
String? prevMonthKey(List<String> monthKeys, String key) {
  final i = monthKeys.indexOf(key);
  return i > 0 ? monthKeys[i - 1] : null;
}

String? nextMonthKey(List<String> monthKeys, String key) {
  final i = monthKeys.indexOf(key);
  return (i >= 0 && i < monthKeys.length - 1) ? monthKeys[i + 1] : null;
}

// Saving streak: consecutive COMPLETED months (excluding the latest/current,
// which may be partial) with a positive savings rate. Shared by the Overview
// card and the savings-rate detail screen so both show the same number.
int _streakOf(
    List<String> monthKeys,
    List<Map<String, dynamic>> Function(String) rowsOf,
    int Function(List<Map<String, dynamic>>) savingsOf) {
  var streak = 0;
  for (var i = monthKeys.length - 2; i >= 0; i--) {
    if (savingsOf(rowsOf(monthKeys[i])) > 0) {
      streak++;
    } else {
      break;
    }
  }
  return streak;
}

// ── Transaction filter (shared by Overview + Dashboard) ─────────────────────────
class _TxFilter {
  _TxFilter({this.type = 'all', Set<String>? secs}) : secs = secs ?? <String>{};
  String type; // 'all' | 'expense' | 'income' | 'transfer'
  Set<String> secs; // selected section labels; empty = all

  bool get active => type != 'all' || secs.isNotEmpty;
  int get count => (type != 'all' ? 1 : 0) + secs.length;

  bool matches(Map t) {
    if (type != 'all') {
      final f = _flowOf(t);
      if (type == 'expense' && !(f == 'expense' || f == 'refund')) return false;
      if (type == 'income' && f != 'income') return false;
      if (type == 'transfer' && f != 'transfer') return false;
    }
    if (secs.isNotEmpty && !secs.contains(t['sec'])) return false;
    return true;
  }

  List<Map<String, dynamic>> apply(Iterable rows) => rows
      .where((t) => matches(t as Map))
      .cast<Map<String, dynamic>>()
      .toList();

  _TxFilter copy() => _TxFilter(type: type, secs: {...secs});
}

// Bottom-sheet filter editor. Returns the applied filter, or null if dismissed.
Future<_TxFilter?> _showFilterSheet(
    BuildContext context, _TxFilter current, List<String> availableSecs) {
  var type = current.type;
  final secs = <String>{...current.secs};
  const types = [
    ['all', 'Visi'],
    ['expense', 'Išlaidos'],
    ['income', 'Pajamos'],
    ['transfer', 'Pervedimai'],
  ];
  return showModalBottomSheet<_TxFilter>(
    context: context,
    backgroundColor: _card,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(22))),
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, setSheet) => SafeArea(
        child: ConstrainedBox(
          constraints:
              BoxConstraints(maxHeight: MediaQuery.of(ctx).size.height * 0.8),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const SizedBox(height: 12),
              Container(
                  width: 40,
                  height: 4,
                  decoration: BoxDecoration(
                      color: _faint, borderRadius: BorderRadius.circular(2))),
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 14, 20, 4),
                child: Row(children: [
                  Text(tr('Filtras'),
                      style: TextStyle(
                          fontSize: 20,
                          fontWeight: FontWeight.w800,
                          color: _ink)),
                  const Spacer(),
                  GestureDetector(
                    onTap: () => setSheet(() {
                      type = 'all';
                      secs.clear();
                    }),
                    child: Text(tr('Išvalyti'),
                        style: TextStyle(
                            fontSize: 14.5,
                            fontWeight: FontWeight.w700,
                            color: _purple)),
                  ),
                ]),
              ),
              Flexible(
                child: ListView(
                  shrinkWrap: true,
                  padding: const EdgeInsets.fromLTRB(20, 8, 20, 8),
                  children: [
                    Text(tr('TIPAS'),
                        style: TextStyle(
                            fontSize: 11.5,
                            fontWeight: FontWeight.w800,
                            color: _muted,
                            letterSpacing: 0.6)),
                    const SizedBox(height: 10),
                    Wrap(spacing: 8, runSpacing: 8, children: [
                      for (final tp in types)
                        GestureDetector(
                          onTap: () => setSheet(() => type = tp[0]),
                          child: Container(
                            padding: const EdgeInsets.symmetric(
                                horizontal: 15, vertical: 9),
                            decoration: BoxDecoration(
                              color: type == tp[0] ? _purple : _soft,
                              borderRadius: BorderRadius.circular(11),
                            ),
                            child: Text(tr(tp[1]),
                                style: TextStyle(
                                    fontSize: 14,
                                    fontWeight: FontWeight.w700,
                                    color:
                                        type == tp[0] ? Colors.white : _ink)),
                          ),
                        ),
                    ]),
                    if (availableSecs.isNotEmpty) ...[
                      const SizedBox(height: 20),
                      Text(tr('KATEGORIJOS'),
                          style: TextStyle(
                              fontSize: 11.5,
                              fontWeight: FontWeight.w800,
                              color: _muted,
                              letterSpacing: 0.6)),
                      const SizedBox(height: 4),
                      for (final s in availableSecs)
                        InkWell(
                          onTap: () => setSheet(() =>
                              secs.contains(s) ? secs.remove(s) : secs.add(s)),
                          child: Padding(
                            padding: const EdgeInsets.symmetric(vertical: 11),
                            child: Row(children: [
                              CategoryIcon(
                                  icon: _secIcon[_secToIcon[s]] ?? Icons.circle,
                                  color:
                                      _secColor[_secToIconColor(s)] ?? _muted,
                                  size: 34),
                              const SizedBox(width: 12),
                              Expanded(
                                  child: Text(tr(s),
                                      style: TextStyle(
                                          fontSize: 15,
                                          fontWeight: FontWeight.w600,
                                          color: _ink))),
                              Icon(
                                  secs.contains(s)
                                      ? Icons.check_circle_rounded
                                      : Icons.circle_outlined,
                                  size: 24,
                                  color: secs.contains(s) ? _purple : _faint),
                            ]),
                          ),
                        ),
                    ],
                  ],
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 8, 20, 12),
                child: GestureDetector(
                  onTap: () =>
                      Navigator.pop(ctx, _TxFilter(type: type, secs: secs)),
                  child: Container(
                    height: 52,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                        color: _purple,
                        borderRadius: BorderRadius.circular(15)),
                    child: Text(tr('Taikyti'),
                        style: const TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w800,
                            color: Colors.white)),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    ),
  );
}

// Section label → its colour key (for the filter sheet icon tint).
String _secToIconColor(String sec) {
  for (final t in _taxonomy) {
    if (t['sec'] == sec) return t['c'] as String;
  }
  // data sections not in the picker taxonomy
  if (sec == 'Pajamos') return 'amber';
  if (sec == 'Pervedimai' || sec == 'Kita') return 'indigo';
  return 'indigo';
}

String _kindTitle(String kind) => kind == 'income'
    ? 'Naujos pajamos'
    : kind == 'transfer'
        ? 'Vidinis pervedimas'
        : 'Nauja išlaida';
Color _kindColor(String kind) => kind == 'income'
    ? _good
    : kind == 'transfer'
        ? const Color(0xFF6E6E86)
        : const Color(0xFFE0574F);

// The manual-entry form (amount + category + date + note). Also used to EDIT an
// existing transaction when [initial] is passed (prefills the fields).
class _ManualTxScreen extends StatefulWidget {
  const _ManualTxScreen({required this.kind, this.initial, this.cash = false});
  final String kind; // 'expense' | 'income' | 'transfer'
  final Map<String, dynamic>? initial; // when set → edit mode
  // 2026-08-30: "Išleidau grynais" (see _DashboardPreviewState._openCashExpense)
  // reuses this exact screen — same amount/category/date/note fields a bank
  // transaction's own edit screen already has — instead of building a second,
  // near-identical form. Only changes the title and stamps the saved row with
  // 'cashSrc': true (see _save) so it can be told apart from a bank row later.
  final bool cash;
  @override
  State<_ManualTxScreen> createState() => _ManualTxScreenState();
}

class _ManualTxScreenState extends State<_ManualTxScreen> {
  final _amountCtl = TextEditingController();
  final _noteCtl = TextEditingController();
  late _ManualCat _cat = _catsFor(widget.kind).first;
  late DateTime _date = _today();
  bool get _isEdit => widget.initial != null;

  @override
  void initState() {
    super.initState();
    final init = widget.initial;
    if (init == null) return;
    final a = (init['a'] as num?)?.toDouble() ?? 0;
    if (a != 0) {
      // Stored EUR → show in the display currency the user edits in.
      final abs = a.abs() * Money.rate;
      _amountCtl.text = abs == abs.roundToDouble()
          ? abs.toStringAsFixed(0)
          : abs.toStringAsFixed(2);
    }
    final cats = _catsFor(widget.kind);
    _cat =
        cats.firstWhere((c) => c.cat == init['cat'], orElse: () => cats.first);
    final d = init['d'] as String?;
    if (d != null) {
      final dt = DateTime.tryParse(d);
      if (dt != null) _date = DateTime(dt.year, dt.month, dt.day);
    }
    // Prefill the note with the merchant name unless it's just the category label.
    final nm = init['nm'] as String?;
    if (nm != null && nm.trim().isNotEmpty && nm != init['cat'])
      _noteCtl.text = nm;
  }

  static DateTime _today() {
    final n = DateTime.now();
    return DateTime(n.year, n.month, n.day);
  }

  double get _amount {
    final raw = _amountCtl.text
        .trim()
        .replaceAll(',', '.')
        .replaceAll('€', '')
        .replaceAll(Money.symbol, '')
        .replaceAll(' ', '');
    return double.tryParse(raw) ?? 0;
  }

  bool get _valid => _amount > 0;

  @override
  void dispose() {
    _amountCtl.dispose();
    _noteCtl.dispose();
    super.dispose();
  }

  Future<void> _pickCat() async {
    final cats = _catsFor(widget.kind);
    final picked = await showModalBottomSheet<_ManualCat>(
      context: context,
      backgroundColor: _card,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(20))),
      builder: (_) => SafeArea(
        child: ConstrainedBox(
          constraints: BoxConstraints(
              maxHeight: MediaQuery.of(context).size.height * 0.7),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const SizedBox(height: 10),
              Container(
                  width: 40,
                  height: 4,
                  decoration: BoxDecoration(
                      color: _faint, borderRadius: BorderRadius.circular(2))),
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 14, 20, 6),
                child: Align(
                    alignment: Alignment.centerLeft,
                    child: Text(tr('Kategorija'),
                        style: TextStyle(
                            fontSize: 18,
                            fontWeight: FontWeight.w800,
                            color: _ink))),
              ),
              Flexible(
                child: ListView.builder(
                  shrinkWrap: true,
                  itemCount: cats.length,
                  itemBuilder: (_, i) {
                    final c = cats[i];
                    final sel = c.cat == _cat.cat;
                    return InkWell(
                      onTap: () => Navigator.of(context).pop(c),
                      child: Padding(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 18, vertical: 9),
                        child: Row(children: [
                          CategoryIcon(
                              icon: _iconOf(c.ic),
                              color: _colOf(c.col),
                              size: 40,
                              circle: false),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(tr(c.cat),
                                      style: TextStyle(
                                          fontSize: 15,
                                          fontWeight: FontWeight.w700,
                                          color: _ink)),
                                  const SizedBox(height: 1),
                                  Text(tr(c.sec),
                                      style: TextStyle(
                                          fontSize: 12, color: _muted)),
                                ]),
                          ),
                          if (sel)
                            Icon(Icons.check_circle_rounded,
                                color: _purple, size: 22),
                        ]),
                      ),
                    );
                  },
                ),
              ),
              const SizedBox(height: 8),
            ],
          ),
        ),
      ),
    );
    if (picked != null) setState(() => _cat = picked);
  }

  Future<void> _pickDate() async {
    final now = _today();
    final picked = await showDatePicker(
      context: context,
      initialDate: _date,
      firstDate: DateTime(now.year - 3),
      lastDate: now,
      helpText: tr('Data'),
    );
    if (picked != null)
      setState(() => _date = DateTime(picked.year, picked.month, picked.day));
  }

  void _save() {
    final signed = widget.kind == 'income' ? _amount.abs() : -_amount.abs();
    final note = _noteCtl.text.trim();
    final nm = note.isNotEmpty ? note : _cat.cat;
    final tx = <String, dynamic>{
      'nm': nm,
      'mkey': 'manual-${DateTime.now().microsecondsSinceEpoch}',
      'd': _DashboardPreviewState._ymd(_date),
      // Same date fields bank rows carry, so search/detail don't show "· null".
      // Written in whatever language the app is in at save time, and then
      // persisted — so these are a fallback only. Everything that shows a date
      // goes through _mdOf, which rebuilds it from 'd' in the CURRENT language.
      'md': '${_monGen[_date.month - 1]} ${_date.day}',
      'wd': _wdShort[_date.weekday - 1],
      'cat': _cat.cat,
      'col': _cat.col,
      'ic': _cat.ic,
      'sec': _cat.sec,
      'secc': _cat.secc,
      // The user typed in the DISPLAY currency; all stored amounts are EUR (every
      // screen multiplies by Money.rate to display), so convert back before saving
      // — otherwise a 50 kr entry was stored as 50 EUR and shown as ~580 kr.
      'a': double.parse(
          (Money.rate > 0 ? signed / Money.rate : signed).toStringAsFixed(2)),
      'amb': false,
      'badges': <String>[],
      'pos': signed > 0,
      'count': 0,
      'manual': true,
      if (widget.cash) 'cashSrc': true,
    };
    Navigator.of(context).pop(tx);
  }

  String get _dateLabel {
    final t = _today();
    if (_date == t) return tr('Šiandien');
    if (_date == t.subtract(const Duration(days: 1))) return tr('Vakar');
    return '${_date.day} ${_monGen[_date.month - 1].toLowerCase()} ${_date.year}';
  }

  @override
  Widget build(BuildContext context) {
    final tint = _kindColor(widget.kind);
    return Scaffold(
      backgroundColor: _bg,
      body: SafeArea(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // header
            Padding(
              padding: const EdgeInsets.fromLTRB(8, 6, 16, 6),
              child: Row(children: [
                IconButton(
                    icon: Icon(Icons.arrow_back_rounded, color: _ink),
                    onPressed: () => Navigator.of(context).pop()),
                Expanded(
                    child: Text(
                        widget.cash
                            ? tr('Išleidau grynais')
                            : _isEdit
                                ? tr('Redaguoti')
                                : tr(_kindTitle(widget.kind)),
                        style: TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.w800,
                            color: _ink))),
              ]),
            ),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
                children: [
                  // amount
                  Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 18, vertical: 22),
                    decoration: BoxDecoration(
                        color: _card,
                        borderRadius: BorderRadius.circular(18),
                        border: Border.all(color: _hair)),
                    child: Row(children: [
                      Text(widget.kind == 'income' ? '+' : '−',
                          style: TextStyle(
                              fontSize: 34,
                              fontWeight: FontWeight.w800,
                              color: tint)),
                      const SizedBox(width: 6),
                      Expanded(
                        child: TextField(
                          controller: _amountCtl,
                          autofocus: true,
                          keyboardType: const TextInputType.numberWithOptions(
                              decimal: true),
                          inputFormatters: [
                            FilteringTextInputFormatter.allow(
                                RegExp(r'[0-9.,]'))
                          ],
                          onChanged: (_) => setState(() {}),
                          style: TextStyle(
                              fontSize: 40,
                              fontWeight: FontWeight.w800,
                              color: _ink,
                              letterSpacing: -1),
                          decoration: InputDecoration(
                            isCollapsed: true,
                            border: InputBorder.none,
                            hintText: '0',
                            hintStyle: TextStyle(
                                fontSize: 40,
                                fontWeight: FontWeight.w800,
                                color: _faint),
                          ),
                        ),
                      ),
                      Text(Money.symbol,
                          style: TextStyle(
                              fontSize: 30,
                              fontWeight: FontWeight.w700,
                              color: _muted)),
                    ]),
                  ),
                  const SizedBox(height: 12),
                  // category
                  _row(
                    onTap: _pickCat,
                    leading: CategoryIcon(
                        icon: _iconOf(_cat.ic),
                        color: _colOf(_cat.col),
                        size: 40,
                        circle: false),
                    label: tr('Kategorija'),
                    value: tr(_cat.cat),
                  ),
                  const SizedBox(height: 10),
                  // date
                  _row(
                    onTap: _pickDate,
                    leading: Container(
                      width: 40,
                      height: 40,
                      decoration: BoxDecoration(
                          color: _soft,
                          borderRadius: BorderRadius.circular(11)),
                      child: Icon(Icons.event_rounded, color: _muted, size: 21),
                    ),
                    label: tr('Data'),
                    value: _dateLabel,
                  ),
                  const SizedBox(height: 10),
                  // note
                  Container(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
                    decoration: BoxDecoration(
                        color: _card,
                        borderRadius: BorderRadius.circular(16),
                        border: Border.all(color: _hair)),
                    child: Row(children: [
                      Container(
                        width: 40,
                        height: 40,
                        decoration: BoxDecoration(
                            color: _soft,
                            borderRadius: BorderRadius.circular(11)),
                        child:
                            Icon(Icons.notes_rounded, color: _muted, size: 21),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: TextField(
                          controller: _noteCtl,
                          textCapitalization: TextCapitalization.sentences,
                          style: TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.w600,
                              color: _ink),
                          decoration: InputDecoration(
                            border: InputBorder.none,
                            hintText: widget.kind == 'transfer'
                                ? tr('Pavadinimas (nebūtina)')
                                : tr('Pastaba (nebūtina)'),
                            hintStyle: TextStyle(fontSize: 15, color: _faint),
                          ),
                        ),
                      ),
                    ]),
                  ),
                  if (widget.kind == 'transfer')
                    Padding(
                      padding: const EdgeInsets.fromLTRB(4, 14, 4, 0),
                      child: Text(
                          tr(
                              'Vidiniai pervedimai neįskaičiuojami į išlaidas ar pajamas.'),
                          style: TextStyle(
                              fontSize: 12.5, color: _muted, height: 1.3)),
                    ),
                ],
              ),
            ),
            // save
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
              child: GestureDetector(
                onTap: _valid ? _save : null,
                child: Container(
                  height: 54,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: _valid ? _purple : _faint,
                    borderRadius: BorderRadius.circular(16),
                  ),
                  child: Text(tr('Išsaugoti'),
                      style: const TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.w800,
                          color: Colors.white)),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _row(
      {required VoidCallback onTap,
      required Widget leading,
      required String label,
      required String value}) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(16),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
        decoration: BoxDecoration(
            color: _card,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: _hair)),
        child: Row(children: [
          leading,
          const SizedBox(width: 12),
          Expanded(
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(label,
                  style: TextStyle(
                      fontSize: 12,
                      color: _muted,
                      fontWeight: FontWeight.w600)),
              const SizedBox(height: 2),
              Text(value,
                  style: TextStyle(
                      fontSize: 15.5,
                      fontWeight: FontWeight.w700,
                      color: _ink)),
            ]),
          ),
          Icon(Icons.chevron_right_rounded, color: _faint, size: 22),
        ]),
      ),
    );
  }
}

// ── PAINTERS ──────────────────────────────────────────────────────────────────
class _SparkPainter extends CustomPainter {
  _SparkPainter(this.pts);
  final List<double> pts;
  @override
  void paint(Canvas canvas, Size size) {
    if (pts.length < 2) return;
    final mn = pts.reduce((a, b) => a < b ? a : b);
    final mx = pts.reduce((a, b) => a > b ? a : b);
    final range = (mx - mn).abs() < 1e-6 ? 1.0 : (mx - mn);
    final path = Path();
    for (var i = 0; i < pts.length; i++) {
      final x = i / (pts.length - 1) * size.width;
      final y = size.height - (pts[i] - mn) / range * size.height;
      i == 0 ? path.moveTo(x, y) : path.lineTo(x, y);
    }
    canvas.drawPath(
      path,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = _purple,
    );
  }

  @override
  bool shouldRepaint(_SparkPainter old) => false;
}

/// Balance flow chart: a single crisp line (no gradient, no blur haze behind it —
/// the user found those distracting) with a gently pulsing endpoint dot so it
/// still feels "live". Two faint gridlines give the € labels something to sit
/// against. Leaves right padding so the overlaid value labels don't collide with
/// the line's endpoint. [pulse] is a 0→1 animation value from the host widget.
class _NeonSparkPainter extends CustomPainter {
  _NeonSparkPainter(this.pts,
      {this.dark = true, this.endLabel, this.progress = 1, this.projectedValue});
  final List<double> pts;
  final bool dark;
  // 2026-08-15: PREVIEW-ONLY — when set, the real line stops short (leaving
  // room on the right) and a dashed segment + hollow dot continue on to this
  // value, read as "if this rate holds, here's where you land."
  final double? projectedValue;

  /// How much of the line is drawn, 0→1. Always 1 in the app; the onboarding
  /// demo runs it up from 0 so the balance draws itself across the chart.
  final double progress;
  // Current balance, shown in a coloured pill at the line's endpoint (null hides it).
  final String? endLabel;
  // Room on the right so the endpoint pill + € labels don't touch the line.
  static const double rightPad = 66;

  // One solid line colour (violet on dark, Frost blue on light) — the app's
  // usual dark-mode accent. A blue variant was tried here and reverted on the
  // device: it read as out of place next to the rest of the dark palette.
  // PREVIEW-ONLY: white reads as "part of the gradient" on the vivid blue
  // hero; the old fixed violet/blue swatches sat on top of it as a visibly
  // foreign, flat-coloured patch ("looks cut out") no matter which one ran.
  Color get _line =>
      designPreviewPalette
          ? Colors.white
          : dark ? const Color(0xFF8B5CF6) : const Color(0xFF2F6BFF);
  Color get _gridColor =>
      (designPreviewPalette ? Colors.white : dark ? const Color(0xFFFFFFFF) : const Color(0xFF14203A))
          .withValues(alpha: designPreviewPalette ? 0.32 : 0.07);

  @override
  void paint(Canvas canvas, Size size) {
    final w = (size.width - rightPad).clamp(1.0, size.width);
    // Two faint reference lines (top = max, bottom = min).
    final grid = Paint()
      ..color = _gridColor
      ..strokeWidth = 1;
    canvas.drawLine(const Offset(0, 1), Offset(size.width, 1), grid);
    canvas.drawLine(
        Offset(0, size.height - 1), Offset(size.width, size.height - 1), grid);
    if (pts.length < 2) return;

    // The real line stops at histW, leaving room for the dashed projection —
    // full width when there's nothing to project.
    final hasProj = projectedValue != null;
    final histW = hasProj ? w * 0.74 : w;

    final mn0 = pts.reduce((a, b) => a < b ? a : b);
    final mx0 = pts.reduce((a, b) => a > b ? a : b);
    final mn = hasProj && projectedValue! < mn0 ? projectedValue! : mn0;
    final mx = hasProj && projectedValue! > mx0 ? projectedValue! : mx0;
    final range = (mx - mn).abs() < 1e-6 ? 1.0 : (mx - mn);
    double yOf(double v) =>
        (size.height - 8) - (v - mn) / range * (size.height - 16) + 4;
    Offset at(int i) => Offset(i / (pts.length - 1) * histW, yOf(pts[i]));

    final line = Path()..moveTo(at(0).dx, at(0).dy);
    for (var i = 1; i < pts.length; i++) {
      line.lineTo(at(i).dx, at(i).dy);
    }

    // While the demo draws the line, clip everything to how far it has got, so
    // the stroke and its fill sweep in together from the left.
    final t = progress.clamp(0.0, 1.0);
    if (t < 1) {
      canvas.save();
      canvas.clipRect(Rect.fromLTWH(0, 0, histW * t + 0.5, size.height));
    }

    // Soft area fill under the line — a clean colour tint (no blur haze).
    final area = Path.from(line)
      ..lineTo(at(pts.length - 1).dx, size.height)
      ..lineTo(0, size.height)
      ..close();
    canvas.drawPath(
      area,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            _line.withValues(alpha: designPreviewPalette ? 0.22 : (dark ? 0.26 : 0.16)),
            _line.withValues(alpha: 0.0)
          ],
        ).createShader(Rect.fromLTWH(0, 0, size.width, size.height)),
    );

    canvas.drawPath(
      line,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = _line,
    );

    if (t < 1) canvas.restore();

    // PREVIEW-ONLY: dashed continuation out to the projected value — "if
    // this rate holds, here's where you land" — only once the real line has
    // fully drawn in (matches the endLabel pill's own t >= 0.995 gate).
    if (hasProj && t >= 0.995) {
      final from = at(pts.length - 1);
      final to = Offset(w, yOf(projectedValue!));
      final dashPaint = Paint()
        ..color = Colors.white.withValues(alpha: 0.55)
        ..strokeWidth = 2
        ..strokeCap = StrokeCap.round;
      const dashLen = 5.0, gapLen = 4.5;
      final total = (to - from).distance;
      if (total > 0) {
        final dir = Offset((to.dx - from.dx) / total, (to.dy - from.dy) / total);
        var dist = 0.0;
        while (dist < total) {
          final segEnd = (dist + dashLen).clamp(0.0, total);
          canvas.drawLine(
              from + dir * dist, from + dir * segEnd, dashPaint);
          dist += dashLen + gapLen;
        }
      }
      canvas.drawCircle(to, 4, Paint()..color = const Color(0xFF1557E8));
      canvas.drawCircle(
          to,
          4,
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.6
            ..color = Colors.white);
    }

    // Endpoint dot (white halo for contrast against the fill), then the balance
    // pill. Mid-draw the dot rides the tip of the line instead.
    final Offset end;
    if (t >= 1) {
      end = at(pts.length - 1);
    } else {
      final seg = t * (pts.length - 1);
      final i = seg.floor().clamp(0, pts.length - 2);
      final a = at(i), b = at(i + 1);
      end = Offset(histW * t, a.dy + (b.dy - a.dy) * (seg - i));
    }
    // PREVIEW-ONLY: a translucent white halo works on any patch of the blue
    // gradient it happens to land on; the old fixed grey/dark-violet halo
    // was a flat swatch that didn't track the gradient underneath it.
    canvas.drawCircle(
        end,
        5,
        Paint()
          ..color = designPreviewPalette
              ? Colors.white.withValues(alpha: 0.28)
              : (dark ? const Color(0xFF201545) : const Color(0xFFEEF1F7)));
    canvas.drawCircle(end, 3.4, Paint()..color = _line);

    if (endLabel != null && endLabel!.isNotEmpty && t >= 0.995) {
      // PREVIEW-ONLY: the pill needs its OWN colours, not _line (now white
      // for the stroke/dot) — white text on a white pill is invisible.
      // Matches the "Revolut EUR" chip elsewhere on this hero: white pill,
      // dark ink text.
      final pillBg = designPreviewPalette ? Colors.white : _line;
      final pillTextColor =
          designPreviewPalette ? const Color(0xFF0B1533) : Colors.white;
      final tp = TextPainter(
        text: TextSpan(
            text: endLabel,
            style: TextStyle(
                fontSize: 11.5,
                fontWeight: FontWeight.w800,
                color: pillTextColor)),
        textDirection: TextDirection.ltr,
      )..layout();
      const padH = 8.0, padV = 4.0;
      final pillW = tp.width + padH * 2;
      final pillH = tp.height + padV * 2;
      final px = (end.dx + 8).clamp(0.0, size.width - pillW);
      final py = (end.dy - pillH / 2).clamp(0.0, size.height - pillH);
      final rr = RRect.fromRectAndRadius(
          Rect.fromLTWH(px, py, pillW, pillH), const Radius.circular(8));
      canvas.drawRRect(rr, Paint()..color = pillBg);
      tp.paint(canvas, Offset(px + padH, py + padV));
    }
  }

  @override
  bool shouldRepaint(_NeonSparkPainter old) =>
      old.pts != pts ||
      old.dark != dark ||
      old.endLabel != endLabel ||
      old.progress != progress ||
      old.projectedValue != projectedValue;
}

/// The weekly chart's background: faint € gridlines (so a bar's height reads as
/// a real amount) plus a dashed "average per day" reference line, so the space
/// behind the bars carries information instead of being empty.
///
/// Geometry matches `_bar`: each bar's Column is bottom-aligned inside the box
/// with a ~26px day-label strip beneath it, so the bars stand on a baseline that
/// far above the box bottom, and grow up to [barMax] px scaled by [maxV].
class _WeekAvgPainter extends CustomPainter {
  _WeekAvgPainter(
      {required this.avg,
      required this.maxV,
      required this.barMax,
      required this.label,
      this.dark = true});
  final double avg, maxV, barMax;
  final String label;
  final bool dark;

  static const double _bottomInset = 26; // day-label strip + gap under the bars

  Color get _avgColor =>
      dark ? const Color(0xFF6EE7FF) : const Color(0xFF2F6BFF);

  @override
  void paint(Canvas canvas, Size size) {
    if (maxV <= 0) return;
    final baseY = size.height - _bottomInset;
    double yFor(double v) => baseY - (_weekBarFrac(v, maxV) * barMax);

    final gridPaint = Paint()
      ..color = (dark ? const Color(0xFFFFFFFF) : const Color(0xFF14203A))
          .withValues(alpha: dark ? 0.06 : 0.07)
      ..strokeWidth = 1;
    final labelStyle = TextStyle(
        fontSize: 9,
        color: dark ? const Color(0xFF6E6790) : const Color(0xFF5C6A85),
        fontWeight: FontWeight.w600);

    // Faint horizontal gridlines at "nice" euro steps, each labelled on the right.
    final step = _niceStep(maxV / 3);
    for (double v = step; v <= maxV * 1.001; v += step) {
      final y = yFor(v);
      canvas.drawLine(Offset(0, y), Offset(size.width, y), gridPaint);
      final tp = TextPainter(
        text: TextSpan(text: _eur0(v), style: labelStyle),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(size.width - tp.width - 1, y - tp.height - 1));
    }
    // Baseline the bars sit on.
    canvas.drawLine(
        Offset(0, baseY + 0.5),
        Offset(size.width, baseY + 0.5),
        Paint()
          ..color = (dark ? const Color(0xFFFFFFFF) : const Color(0xFF14203A))
              .withValues(alpha: dark ? 0.08 : 0.10)
          ..strokeWidth = 1);

    // Dashed average line only (the "vidurkis X €/d." label now lives in the
    // section header, so it can never overlap a bar or its number).
    if (avg > 0) {
      final y = yFor(avg).clamp(8.0, baseY);
      const dash = 5.0, gap = 4.0;
      final avgPaint = Paint()
        ..color = _avgColor.withValues(alpha: dark ? 0.7 : 0.85)
        ..strokeWidth = 1.3;
      for (double x = 0; x < size.width; x += dash + gap) {
        canvas.drawLine(
            Offset(x, y), Offset((x + dash).clamp(0, size.width), y), avgPaint);
      }
    }
  }

  double _niceStep(double raw) {
    if (raw <= 0) return 1;
    final mag = math.pow(10, (math.log(raw) / math.ln10).floor()).toDouble();
    for (final f in [1, 2, 2.5, 5, 10]) {
      if (f * mag >= raw) return f * mag;
    }
    return 10 * mag;
  }

  @override
  bool shouldRepaint(_WeekAvgPainter old) =>
      old.avg != avg ||
      old.maxV != maxV ||
      old.label != label ||
      old.dark != dark;
}

