// Locale-aware name arrays — one switch localizes every month/weekday usage.
bool get _enUi => effectiveLocale().languageCode == 'en';

/// Lithuanian number agreement. "1 tuščia", "2 tuščios", "11 tuščių" — the app
/// printed "1 tuščios" everywhere a count met a noun, which reads as broken
/// Lithuanian to every native speaker on the first screen they see it.
///   ends in 1 (but not 11)        → [one]
///   ends in 2–9 (but not 12–19)   → [few]
///   everything else (0, 10–19, …) → [many]
@visibleForTesting
String ltPlural(int n, String one, String few, String many) {
  final t = n % 10, h = n % 100;
  if (t == 1 && h != 11) return one;
  if (t >= 2 && t <= 9 && (h < 11 || h > 19)) return few;
  return many;
}

List<String> get _monAbbr => _enUi ? _monAbbrEn : _monAbbrLt;
List<String> get _monNom => _enUi ? _monNomEn : _monNomLt;
List<String> get _monGen => _enUi ? _monNomEn : _monGenLt;
List<String> get _wdFull => _enUi ? _wdFullEn : _wdFullLt;
List<String> get _wdShort => _enUi ? _wdShortEn : _wdShortLt;
String _dateLabel(DateTime t) => '${_monAbbr[t.month - 1]} ${t.day}';

/// The greyed "money moved, but it is not income or spending" line in a calendar
/// cell. Deliberately NOT green/red and deliberately unsigned: the direction of a
/// transfer is the part the app can't vouch for.
Widget _calXfer(double x) => Text(
      '↔ ${_eur0(x.abs())}',
      style:
          TextStyle(fontSize: 9.5, fontWeight: FontWeight.w600, color: _faint),
    );

// Week-chart labels, built at render time so they follow the UI language.
// `_computeWeek` persists 'wdi'/'mo'/'dd' (numbers); the older 'lbl'/'dlabel'
// strings are the fallback for a week still sitting in Hive from a build that
// predates those keys — stale in language, but better than a crash or a blank.
String _weekDayLbl(Map<String, dynamic> d) {
  final wdi = d['wdi'];
  if (wdi is int && wdi >= 1 && wdi <= 7) return _wdShort[wdi - 1];
  return (d['lbl'] as String?) ?? '';
}

/// A transaction's "Liepos 14" / "July 14" label, rebuilt from its ISO 'd' so it
/// follows the UI language. The stored 'md' is frozen in the language the row
/// was created in — the server writes it in the language it was asked for, and a
/// manually added transaction keeps it forever — so it is only the fallback for
/// a row whose date won't parse.
String _mdOf(Map<String, dynamic> t) {
  final d = t['d'];
  if (d is String && d.length >= 10) {
    final mo = int.tryParse(d.substring(5, 7));
    final dd = int.tryParse(d.substring(8, 10));
    if (mo != null && dd != null && mo >= 1 && mo <= 12) {
      return '${_monGen[mo - 1]} $dd';
    }
  }
  return (t['md'] as String?) ?? '';
}

String _weekDateLbl(Map<String, dynamic> d) {
  final mo = d['mo'], dd = d['dd'];
  if (mo is int && mo >= 1 && mo <= 12 && dd is int) {
    return '${_monGen[mo - 1]} $dd';
  }
  return (d['dlabel'] as String?) ?? '';
}

// Compact chart-axis amount, currency-aware (stored EUR → display currency).
String _kEur(double v) {
  final c = v * Money.rate;
  final s = Money.symbol;
  return c.abs() >= 1000
      ? '${(c / 1000).toStringAsFixed(1)}K$s'
      : '${c.toStringAsFixed(0)}$s';
}

String _eurRound(double v) {
  final s = Money.format(v.roundToDouble());
  final c = s.indexOf(',');
  return c > 0 ? '${s.substring(0, c)} ${Money.symbol}' : s;
}

/// Total-balance detail sheet: reconstructed balance-over-time area chart with a
/// 1M/3M/YTD/1Y/Max range selector, plus the synced-accounts breakdown.
///
/// LOGIC: balance history is not stored by the bank — it's reconstructed by
/// walking backwards from the current balance over available transactions. Long
/// ranges therefore clamp to the earliest data we have (a freshly-connected
/// account only has ~90d under PSD2, so 1Y/Max == 3M until history accrues).
class _BalanceSheet extends StatefulWidget {
  const _BalanceSheet({required this.bal, this.title});
  final Map<String, dynamic> bal;
  // 2026-08-16: null → "Bendras likutis" (combined). Set to a bank's own
  // name when this sheet is scoped to ONE account (see _showBalance) —
  // tapping the SEB chip used to open the exact same combined chart a tap
  // on Revolut did, which read as broken with two real banks connected.
  final String? title;
  @override
  State<_BalanceSheet> createState() => _BalanceSheetState();
}

class _BalanceSheetState extends State<_BalanceSheet> {
  String _range = '3M';
  int? _scrubI; // finger-scrub index into the filtered series
  static const _ranges = ['1M', '3M', 'YTD', '1Y', 'Max'];

  late final List<Map<String, dynamic>> _all =
      _cleanSeries(widget.bal['series']);
  late final DateTime _last = _pDate(_all.last['d']);
  late final DateTime _first = _pDate(_all.first['d']);

  DateTime _cutoffFor(String r) {
    switch (r) {
      case '1M':
        return _last.subtract(const Duration(days: 30));
      case '3M':
        return _last.subtract(const Duration(days: 90));
      case 'YTD':
        return DateTime(_last.year, 1, 1);
      case '1Y':
        return _last.subtract(const Duration(days: 365));
      default:
        return _first;
    }
  }

  bool get _clamped => _range != 'Max' && _cutoffFor(_range).isBefore(_first);

  List<Map<String, dynamic>> get _filtered {
    var cutoff = _cutoffFor(_range);
    if (cutoff.isBefore(_first)) cutoff = _first;
    return _all.where((p) => !_pDate(p['d']).isBefore(cutoff)).toList();
  }

  @override
  Widget build(BuildContext context) {
    // No balance history yet (e.g. a connected account with no transactions) —
    // show a gentle empty sheet instead of reducing/indexing an empty series.
    if (_all.length < 2) {
      return Padding(
        padding: const EdgeInsets.fromLTRB(24, 28, 24, 40),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Icon(Icons.show_chart_rounded, size: 34, color: _faint),
          const SizedBox(height: 12),
          Text(tr('Balanso istorijos dar nėra'),
              style: TextStyle(
                  fontSize: 16.5, fontWeight: FontWeight.w800, color: _ink)),
          const SizedBox(height: 6),
          Text(
              tr('Kai atsiras operacijų, čia matysi kaip keitėsi tavo likutis.'),
              textAlign: TextAlign.center,
              style: TextStyle(fontSize: 13.5, color: _muted, height: 1.4)),
        ]),
      );
    }
    final pts = _filtered;
    final vals = pts.map((p) => _vOf(p)).toList();
    final mn = vals.reduce((a, b) => a < b ? a : b);
    final mx = vals.reduce((a, b) => a > b ? a : b);
    final startD = _pDate(pts.first['d']);
    final endD = _pDate(pts.last['d']);
    final accounts = ((widget.bal['accounts'] as List?) ?? const [])
        .cast<Map<String, dynamic>>();

    return DraggableScrollableSheet(
      initialChildSize: 0.82,
      minChildSize: 0.5,
      maxChildSize: 0.94,
      expand: false,
      builder: (_, controller) => ListView(
        controller: controller,
        padding: const EdgeInsets.only(bottom: 30),
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 16, 20, 8),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                GestureDetector(
                  onTap: () => Navigator.pop(context),
                  child: Padding(
                    padding: const EdgeInsets.only(right: 14, top: 2),
                    child: Icon(Icons.close_rounded, size: 24, color: _ink),
                  ),
                ),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(widget.title ?? tr('Bendras likutis'),
                        style: TextStyle(
                            fontSize: 15,
                            color: _muted,
                            fontWeight: FontWeight.w500)),
                    const SizedBox(height: 2),
                    Text(_eur(((widget.bal['current'] ?? 0) as num).toDouble()),
                        style: TextStyle(
                            fontSize: 27,
                            fontWeight: FontWeight.w800,
                            color: _ink,
                            letterSpacing: -0.5)),
                  ],
                ),
              ],
            ),
          ),
          // chart with axis labels + finger scrub
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 8, 20, 6),
            child: LayoutBuilder(
              builder: (context, c) {
                const yW = 46.0, xH = 26.0;
                const totalH = 210.0;
                final plotW = c.maxWidth - yW;
                const plotH = totalH - xH;
                final n = vals.length;
                final si = _scrubI?.clamp(0, n - 1);
                double sx = 0, sy = 0;
                if (si != null) {
                  final range = (mx - mn).abs() < 1e-6 ? 1.0 : (mx - mn);
                  sx = n <= 1 ? 0 : si / (n - 1) * plotW;
                  sy = plotH - (vals[si] - mn) / range * (plotH - 6) - 3;
                }
                return SizedBox(
                  height: totalH,
                  child: Stack(
                    clipBehavior: Clip.none,
                    children: [
                      Positioned(
                        left: 0,
                        top: 0,
                        right: yW,
                        bottom: xH,
                        child: GestureDetector(
                          behavior: HitTestBehavior.opaque,
                          onTapDown: (d) =>
                              _scrub(d.localPosition.dx, plotW, n),
                          onTapUp: (_) => setState(() => _scrubI = null),
                          onTapCancel: () => setState(() => _scrubI = null),
                          onHorizontalDragStart: (d) =>
                              _scrub(d.localPosition.dx, plotW, n),
                          onHorizontalDragUpdate: (d) =>
                              _scrub(d.localPosition.dx, plotW, n),
                          onHorizontalDragEnd: (_) =>
                              setState(() => _scrubI = null),
                          onHorizontalDragCancel: () =>
                              setState(() => _scrubI = null),
                          child: CustomPaint(
                              painter: _AreaChartPainter(vals, mn, mx, si),
                              size: Size.infinite),
                        ),
                      ),
                      Positioned(
                        right: 0,
                        top: 0,
                        bottom: xH,
                        width: yW,
                        child: Padding(
                          padding: const EdgeInsets.only(left: 6),
                          child: Column(
                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(_kEur(mx),
                                  style: TextStyle(
                                      fontSize: 12,
                                      color: _muted,
                                      fontWeight: FontWeight.w600)),
                              Text(_kEur((mx + mn) / 2),
                                  style: TextStyle(
                                      fontSize: 12,
                                      color: _muted,
                                      fontWeight: FontWeight.w600)),
                              Text(_kEur(mn),
                                  style: TextStyle(
                                      fontSize: 12,
                                      color: _muted,
                                      fontWeight: FontWeight.w600)),
                            ],
                          ),
                        ),
                      ),
                      Positioned(
                        left: 0,
                        right: yW,
                        bottom: 0,
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.spaceBetween,
                          children: [
                            Text(_dateLabel(startD),
                                style:
                                    TextStyle(fontSize: 12.5, color: _muted)),
                            Text(_dateLabel(endD),
                                style:
                                    TextStyle(fontSize: 12.5, color: _muted)),
                          ],
                        ),
                      ),
                      if (si != null)
                        Positioned(
                          left: (sx - 52).clamp(
                              0.0, (plotW - 104).clamp(0.0, double.infinity)),
                          top: (sy - 58).clamp(-34.0, plotH - 40),
                          child: _tip(vals[si], _pDate(pts[si]['d'])),
                        ),
                    ],
                  ),
                );
              },
            ),
          ),
          // range selector
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 10, 20, 8),
            child: Container(
              padding: const EdgeInsets.all(4),
              decoration: BoxDecoration(
                  color: _soft, borderRadius: BorderRadius.circular(14)),
              child: Row(
                children: [
                  for (final r in _ranges)
                    Expanded(
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onTap: () => setState(() => _range = r),
                        child: Container(
                          alignment: Alignment.center,
                          padding: const EdgeInsets.symmetric(vertical: 10),
                          decoration: BoxDecoration(
                            color: _range == r ? _card : Colors.transparent,
                            borderRadius: BorderRadius.circular(11),
                            boxShadow: _range == r
                                ? [
                                    BoxShadow(
                                        color: Colors.black
                                            .withValues(alpha: 0.06),
                                        blurRadius: 6,
                                        offset: const Offset(0, 2))
                                  ]
                                : null,
                          ),
                          child: Text(r,
                              style: TextStyle(
                                  fontSize: 14,
                                  fontWeight: FontWeight.w700,
                                  color: _range == r ? _purple : _muted)),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
          if (_clamped)
            Container(
              margin: const EdgeInsets.fromLTRB(20, 4, 20, 4),
              padding: const EdgeInsets.all(11),
              decoration: BoxDecoration(
                color: _soft,
                borderRadius: BorderRadius.circular(12),
              ),
              child: Row(
                children: [
                  Icon(Icons.info_outline_rounded, size: 16, color: _purple),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      '${tr('Rodoma')} ${_monthsAvail()} ${tr('mėn. — tiek istorijos grąžino bankas. Daugiau prisipildys laikui bėgant.')}',
                      style: TextStyle(fontSize: 12, color: _ink, height: 1.35),
                    ),
                  ),
                ],
              ),
            ),
          // Per-account sheet (widget.title set) already IS this one
          // account's own chart — repeating it as a one-row list below
          // would just be the same account shown twice.
          if (widget.title == null) ...[
            Divider(height: 24, thickness: 1, color: _hair),
            for (var i = 0; i < accounts.length; i++) ...[
              _accountRow(accounts[i]),
              if (i != accounts.length - 1) const RowDivider(indent: 68),
            ],
          ],
        ],
      ),
    );
  }

  int _monthsAvail() => ((_last.difference(_first).inDays) / 30).round();

  void _scrub(double dx, double plotW, int n) {
    if (n <= 1) {
      setState(() => _scrubI = 0);
      return;
    }
    var i = (dx / plotW * (n - 1)).round();
    if (i < 0) i = 0;
    if (i > n - 1) i = n - 1;
    setState(() => _scrubI = i);
  }

  Widget _tip(double v, DateTime d) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
      decoration: BoxDecoration(
        color: _card,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: _hair),
        boxShadow: [
          BoxShadow(
              color: Colors.black.withValues(alpha: 0.10),
              blurRadius: 12,
              offset: const Offset(0, 4))
        ],
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(_eurRound(v),
              style: TextStyle(
                  fontSize: 16, fontWeight: FontWeight.w800, color: _ink)),
          Text(_dateLabel(d), style: TextStyle(fontSize: 13, color: _muted)),
        ],
      ),
    );
  }

  Widget _accountRow(Map<String, dynamic> a) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 14),
      child: Row(
        children: [
          _acctGlyph(a),
          const SizedBox(width: 12),
          Expanded(
            child: Text(a['name'] as String,
                style: TextStyle(
                    fontSize: 16, fontWeight: FontWeight.w700, color: _ink)),
          ),
          Column(
            crossAxisAlignment: CrossAxisAlignment.end,
            children: [
              Text(
                  a['sub'] != null ? '${a['sub']}' : _eurAcct(a),
                  style: TextStyle(
                      fontSize: 16, fontWeight: FontWeight.w700, color: _ink)),
              if (a['sub'] != null)
                Text(_eurAcct(a),
                    style: TextStyle(fontSize: 12.5, color: _muted)),
            ],
          ),
        ],
      ),
    );
  }
}

class _AreaChartPainter extends CustomPainter {
  _AreaChartPainter(this.vals, this.mn, this.mx, [this.scrubIndex]);
  final List<double> vals;
  final double mn, mx;
  final int? scrubIndex;

  @override
  void paint(Canvas canvas, Size size) {
    if (vals.length < 2) return;
    final range = (mx - mn).abs() < 1e-6 ? 1.0 : (mx - mn);
    Offset at(int i) {
      final x = i / (vals.length - 1) * size.width;
      final y = size.height - (vals[i] - mn) / range * (size.height - 6) - 3;
      return Offset(x, y);
    }

    // dashed gridlines (3)
    final grid = Paint()
      ..color = const Color(0xFFE6E6EC)
      ..strokeWidth = 1;
    for (final f in [0.0, 0.5, 1.0]) {
      final y = 3 + f * (size.height - 6);
      double x = 0;
      while (x < size.width) {
        canvas.drawLine(Offset(x, y), Offset(x + 4, y), grid);
        x += 9;
      }
    }

    final line = Path()..moveTo(at(0).dx, at(0).dy);
    for (var i = 1; i < vals.length; i++) {
      line.lineTo(at(i).dx, at(i).dy);
    }

    final area = Path.from(line)
      ..lineTo(size.width, size.height)
      ..lineTo(0, size.height)
      ..close();
    canvas.drawPath(
      area,
      Paint()
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0x336D28D9), Color(0x066D28D9)],
        ).createShader(Offset.zero & size),
    );
    canvas.drawPath(
      line,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..color = _purple,
    );

    // finger-scrub crosshair + dot
    if (scrubIndex != null && scrubIndex! >= 0 && scrubIndex! < vals.length) {
      final p = at(scrubIndex!);
      canvas.drawLine(
        Offset(p.dx, 0),
        Offset(p.dx, size.height),
        Paint()
          ..color = _purple.withValues(alpha: 0.40)
          ..strokeWidth = 1.5,
      );
      canvas.drawCircle(p, 6.5, Paint()..color = Colors.white);
      canvas.drawCircle(
        p,
        6.5,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 2.5
          ..color = _purple,
      );
      canvas.drawCircle(p, 3, Paint()..color = _purple);
    }
  }

  @override
  bool shouldRepaint(_AreaChartPainter old) =>
      old.vals != vals ||
      old.mn != mn ||
      old.mx != mx ||
      old.scrubIndex != scrubIndex;
}

// ══════════════════════════════════════════════════════════════════════════════
// TRANSACTION DETAIL — full screen
// ══════════════════════════════════════════════════════════════════════════════
class _TxDetailScreen extends StatefulWidget {
  const _TxDetailScreen(
      {required this.tx,
      required this.day,
      required this.all,
      required this.budgets,
      this.accounts = const [],
      this.single = false});
  final Map<String, dynamic> tx;
  final Map<String, dynamic> day;
  final List<Map<String, dynamic>> all;
  final Map<String, dynamic> budgets;
  // The connected account(s) so the detail can name the real bank instead of a
  // hardcoded one. When there isn't exactly one account we can't map a tx to a
  // specific account, so the card is hidden rather than guessing.
  final List<Map<String, dynamic>> accounts;
  // Opened for ONE specific row (e.g. from search) → actions must not affect
  // the whole merchant+day group. From the feed a row represents the group.
  final bool single;
  @override
  State<_TxDetailScreen> createState() => _TxDetailScreenState();
}

class _TxDetailScreenState extends State<_TxDetailScreen> {
  late String _cat = widget.tx['cat'] as String;
  late Color _catColor = _colOf(widget.tx['col'] as String?);
  late IconData _catIcon = _iconOf(widget.tx['ic'] as String?);
  late bool _isTransfer =
      widget.tx['sec'] == 'Pervedimai' || widget.tx['col'] == 'transfer';
  late bool _starred = widget.tx['star'] == true;

  Map<String, dynamic> get tx => widget.tx;
  double get amount => _aOf(tx).toDouble();
  bool get isPos => tx['pos'] == true;
  String get merchant => _txDisplayName(tx);

  // True for the single collapsed feed row standing in for a whole split
  // receipt (see _monthFeed's day-merge) — its own 'ic'/'col' are the
  // generic 'doc'/'other' set there, never a real category.
  bool get _isSplitGroup => tx['isSplitGroup'] == true;

  // The row(s) in `_d['all']` this detail represents. A merged N× feed row
  // shares (mkey, date); a split-group row shares splitGroup instead (each
  // child has its OWN unique mkey, by design — see _applyTxSplits); a
  // single/manual/search row is itself.
  List<Map<String, dynamic>> get _underlying {
    // Single-row mode (search): the tapped `tx` IS a real `all` element, so act
    // only on that exact instance — never the whole (mkey, date) group.
    if (widget.single) return [tx];
    final splitGroup = tx['splitGroup'];
    if (splitGroup != null) {
      final rows =
          widget.all.where((r) => r['splitGroup'] == splitGroup).toList();
      return rows.isEmpty ? [tx] : rows;
    }
    final mkey = tx['mkey'];
    final d = tx['d'];
    if (mkey == null || d == null) return [tx];
    final rows =
        widget.all.where((r) => r['mkey'] == mkey && r['d'] == d).toList();
    return rows.isEmpty ? [tx] : rows;
  }

  String get _kind {
    if (_isTransfer) return 'transfer';
    return amount > 0 ? 'income' : 'expense';
  }

  // ── Real actions (persist via the dashboard's _dashRefresh) ─────────────────
  Future<void> _delete() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: _card,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
        title: Text(tr('Ištrinti sandorį?'),
            style: TextStyle(fontWeight: FontWeight.w800, color: _ink)),
        content: Text(
            '„$merchant" (${_eurTx(tx, signed: true)}) ${tr('bus pašalintas. Šio veiksmo anuliuoti negalima.')}',
            style: TextStyle(color: _muted, height: 1.4)),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: Text(tr('Atšaukti'), style: TextStyle(color: _muted))),
          TextButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: Text(tr('Ištrinti'),
                  style: const TextStyle(
                      color: Color(0xFFE0574F), fontWeight: FontWeight.w800))),
        ],
      ),
    );
    if (ok != true) return;
    final targets = _underlying;
    // 2026-08-31: real bug, found in audit — deleting a SPLIT transaction
    // (or one of its line items) via this generic "Ištrinti" button only
    // tombstoned the synthetic split-child identities (mkey__split0|...).
    // Those identities never match the RAW, unsplit bank row that comes
    // back from the next sync — so _applyTxSplits (see its own doc)
    // regenerated the exact same "deleted" children right back from the
    // split record still sitting in DashboardStore.txSplits(), which this
    // never removed. The visible rows vanished for one screen, then came
    // back on the next background sync — a zombie delete. Splitting has
    // its own explicit undo ("Anuliuoti skaidymą", _undoSplit) that already
    // calls removeTxSplit correctly; this generic delete just never mirrored
    // that when the thing being deleted HAPPENED to be a split.
    final splitGroups = <String>{
      for (final r in targets)
        if (r['splitGroup'] is String) r['splitGroup'] as String,
    };
    for (final g in splitGroups) {
      await DashboardStore.removeTxSplit(g);
    }
    // Tombstone each deleted transaction so a background sync re-removes it.
    for (final r in targets) {
      DashboardStore.addTxDeleted(DashboardStore.txIdentity(r));
    }
    // removeTxSplit alone stops the SPLIT CHILDREN from regenerating, but
    // the RAW, pre-split bank row (one lump sum, e.g. "Rimi -8,51 €") no
    // longer exists anywhere in `all` to tombstone directly either — split
    // children replace it entirely (see _applyTxSplits' own toRemove/toAdd).
    // Reconstruct its real identity from a child's own mkey (always
    // '<raw mkey>__split<i>', see _applyTxSplits) and the sum of every
    // child's amount (== the original total by construction — _canSave
    // enforces lines sum to the full amount before a split can even be
    // saved), so the raw transaction is ALSO tombstoned — otherwise the next
    // sync would still bring it back as one un-split row, which is not what
    // "Ištrinti" on a split transaction means to a user.
    for (final g in splitGroups) {
      final children = targets.where((r) => r['splitGroup'] == g).toList();
      if (children.isEmpty) continue;
      final childMkey = children.first['mkey'] as String;
      final cut = childMkey.lastIndexOf('__split');
      final rawMkey = cut >= 0 ? childMkey.substring(0, cut) : childMkey;
      final rawAmount =
          children.fold(0.0, (s, r) => s + ((r['a'] as num?)?.toDouble() ?? 0));
      DashboardStore.addTxDeleted(DashboardStore.txIdentity({
        'mkey': rawMkey,
        'd': children.first['d'],
        'a': rawAmount,
      }));
      // 2026-08-31: same zombie-row failure mode as splits themselves, for
      // the same reason — a cash-receipt-split's PARENT row is a manual
      // entry (see DashboardStore.manualTxs' own doc), and children inherit
      // 'manual': true from it via _applyTxSplits' `...base` spread. Without
      // this, the parent would reappear from manualTxs() on the next sync
      // and get re-split right back into the "deleted" children.
      if (children.first['manual'] == true) {
        await DashboardStore.removeManualTx(rawMkey);
      }
    }
    // 2026-08-31: same audit finding as the edit-time reconciliation above
    // (_edit) — deleting a cash-sourced expense never gave the deducted
    // amount back to the tracked "Grynieji" balance, permanently
    // understating it by however much was ever deleted. Give it back
    // whenever a deleted row (or, for a split receipt, its raw total) was
    // cash-sourced.
    for (final r in targets) {
      if (r['cashSrc'] == true) {
        await _addToCashAsset(_aOf(r).abs().toDouble());
      }
      // A plain (non-split) manual row, e.g. a cash expense logged via
      // _openCashExpense — same reasoning as the split parent above: leaving
      // it in DashboardStore.manualTxs() would bring it right back on the
      // next sync even though "Ištrinti" was tapped.
      if (r['splitGroup'] == null && r['manual'] == true) {
        final mkey = r['mkey'] as String?;
        if (mkey != null) await DashboardStore.removeManualTx(mkey);
      }
    }
    widget.all.removeWhere(targets.contains);
    _dashRefresh?.call();
    if (mounted) Navigator.pop(context);
  }

  Future<void> _edit() async {
    final rows = _underlying;
    if (rows.length > 1) {
      _toast('Sujungtos operacijos — keisis pavadinimas ir kategorija visoms');
    }
    final edited = await Navigator.of(context).push<Map<String, dynamic>>(
      MaterialPageRoute(
          builder: (_) => _ManualTxScreen(kind: _kind, initial: tx)),
    );
    if (edited == null || !mounted) return;
    // A merged N× row can't take a single amount; keep per-row amounts and only
    // apply the shared fields (name/category/date). A single row takes all.
    final single = rows.length == 1;
    // Capture each row's identity BEFORE mutating — a single-row edit can change
    // the amount/date (part of the identity); the override is stored under the
    // ORIGINAL identity (what the next sync will present) with the NEW values.
    final ids = [for (final r in rows) DashboardStore.txIdentity(r)];
    final shared = <String, dynamic>{
      'nm': edited['nm'],
      'cat': edited['cat'],
      'col': edited['col'],
      'ic': edited['ic'],
      'sec': edited['sec'],
      'secc': edited['secc'],
      'pos': edited['pos'],
    };
    // 2026-08-31: real bug, found in audit — a cash-sourced expense
    // (_openCashExpense/_createCashReceiptSplit) deducts from the tracked
    // "Grynieji" balance exactly ONCE, at creation. Editing its amount
    // afterward (e.g. fixing a typo) updated the category totals correctly
    // but left the cash balance silently wrong forever after — it never
    // re-deducted the difference. Captured BEFORE `tx['a']` is overwritten
    // below, so the reconciliation always compares the true old vs new
    // amount regardless of the amount widget's own current display state.
    final cashAdjust =
        (single && tx['cashSrc'] == true) ? _aOf(tx).abs().toDouble() : null;
    for (var i = 0; i < rows.length; i++) {
      final r = rows[i];
      shared.forEach((k, v) => r[k] = v);
      final ov = {...shared};
      if (single) {
        r['a'] = edited['a'];
        r['d'] = edited['d'];
        ov['a'] = edited['a'];
        ov['d'] = edited['d'];
      }
      // Persist the edit so a background sync re-applies it instead of wiping it.
      DashboardStore.setTxEdit(ids[i], ov);
    }
    if (cashAdjust != null) {
      final newAbs = ((edited['a'] as num).toDouble()).abs();
      final delta = newAbs - cashAdjust; // >0 spent MORE now, <0 spent LESS
      if (delta > 0) {
        await _deductFromCashAsset(delta);
      } else if (delta < 0) {
        await _addToCashAsset(-delta);
      }
    }
    // Reflect on the display object too.
    tx['nm'] = edited['nm'];
    tx['cat'] = edited['cat'];
    tx['col'] = edited['col'];
    tx['ic'] = edited['ic'];
    tx['sec'] = edited['sec'];
    tx['secc'] = edited['secc'];
    tx['pos'] = edited['pos'];
    if (single) {
      tx['a'] = edited['a'];
      tx['d'] = edited['d'];
    }
    setState(() {
      _cat = edited['cat'] as String;
      _catColor = _colOf(edited['col'] as String?);
      _catIcon = _iconOf(edited['ic'] as String?);
      _isTransfer = edited['sec'] == 'Pervedimai';
    });
    _dashRefresh?.call();
    _toast(tr('Pakeitimai išsaugoti'));
  }

  /// For a bill/subscription the bank data hasn't repeated yet (a first rent
  /// payment, a card the app isn't linked to): let the user say so from a
  /// single transaction, instead of waiting for a second occurrence the
  /// engine needs before it will trust the pattern. Once the engine DOES
  /// confirm the same merchant later, it takes over and keeps this choice —
  /// see `_recItemsFull`.
  Future<void> _addToRecurring() async {
    final type = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: _card,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (ctx) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(20, 22, 20, 22),
          child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(tr('Pridėti prie pasikartojančių'),
                    style: TextStyle(
                        fontSize: 17,
                        fontWeight: FontWeight.w800,
                        color: _ink)),
                const SizedBox(height: 3),
                Text(tr('Ar tai prenumerata, ar sąskaita?'),
                    style: TextStyle(fontSize: 13.5, color: _muted)),
                const SizedBox(height: 10),
                ListTile(
                  contentPadding: EdgeInsets.zero,
                  onTap: () => Navigator.pop(ctx, 'subscription'),
                  leading: Icon(Icons.autorenew_rounded, color: _purple),
                  title: Text(tr('Prenumerata'),
                      style:
                          TextStyle(color: _ink, fontWeight: FontWeight.w700)),
                  subtitle: Text(
                      tr('Reguliarios paslaugos — Netflix, sporto salė, programėlės.'),
                      style: TextStyle(color: _muted, fontSize: 12.5)),
                ),
                ListTile(
                  contentPadding: EdgeInsets.zero,
                  onTap: () => Navigator.pop(ctx, 'bill'),
                  leading: Icon(Icons.home_outlined, color: _purple),
                  title: Text(tr('Sąskaita'),
                      style:
                          TextStyle(color: _ink, fontWeight: FontWeight.w700)),
                  subtitle: Text(
                      tr('Nuoma, komunaliniai, telefonas, paskolos, draudimas.'),
                      style: TextStyle(color: _muted, fontSize: 12.5)),
                ),
              ]),
        ),
      ),
    );
    if (type == null || !mounted) return;
    final name = merchant;
    await DashboardStore.addManualRecurring({
      'sid': 'manual:${_fold(name.trim())}',
      'name': name,
      'monthly': amount.abs(),
      'cost': amount.abs(),
      'cycle': 'monthly',
      'status': 'active',
      'active': true,
      'type': type,
      'occ': 1,
      'lastCharge': tx['d'],
      'category': tx['cat'],
      'manual': true,
    });
    _dashRefresh?.call();
    if (!mounted) return;
    _toast(type == 'subscription'
        ? tr('Pridėta prie prenumeratų')
        : tr('Pridėta prie sąskaitų'));
  }

  void _toggleStar() {
    setState(() => _starred = !_starred);
    for (final r in _underlying) {
      r['star'] = _starred;
      DashboardStore.setTxEdit(
          DashboardStore.txIdentity(r), {'star': _starred});
    }
    tx['star'] = _starred;
    _dashRefresh?.call();
  }

  void _convertTransfer() {
    final toTransfer = !_isTransfer;
    // → transfer: mark as internal (excluded from spent/earned).
    // → normal: fall back to uncategorised spending ("Kita"); the user can then
    //   pick a real category. There's no original category to restore.
    final fields = toTransfer
        ? {
            'sec': 'Pervedimai',
            'secc': 'indigo',
            'col': 'transfer',
            'cat': 'Pervedimas',
            'ic': 'swap'
          }
        : {
            'sec': 'Kita',
            'secc': 'indigo',
            'col': 'other',
            'cat': 'Kita',
            'ic': 'swap'
          };
    for (final r in [..._underlying, tx]) {
      fields.forEach((k, v) => r[k] = v);
    }
    // Transfer-convert doesn't touch amount/date, so the identity is stable.
    for (final r in _underlying) {
      DashboardStore.setTxEdit(DashboardStore.txIdentity(r), fields);
    }
    setState(() {
      _isTransfer = toTransfer;
      _cat = fields['cat']!;
      _catColor = _colOf(fields['col']);
      _catIcon = _iconOf(fields['ic']);
    });
    _dashRefresh?.call();
    _toast(toTransfer
        ? tr('Pažymėta kaip vidinis pervedimas')
        : tr('Grąžinta į įprastą (kategorija „Kita")'));
  }

  // 2026-08-16: PHASE 1 of receipt-line-item splitting (manual only — no
  // OCR yet). Keyed by the (mkey, date) group _underlying already groups
  // this card by, so a merged N× row and a single search-opened row (see
  // widget.single) split consistently with how every other action here
  // already scopes itself.
  String get _splitKey => widget.single
      ? DashboardStore.txIdentity(tx)
      : 'grp:${tx['mkey']}|${tx['d']}';

  bool get _isSplitChild => tx['splitGroup'] != null;

  Future<void> _openSplit() async {
    final saved = await Navigator.of(context).push<bool>(
      MaterialPageRoute(
        builder: (_) => _SplitTransactionScreen(
          splitKey: _splitKey,
          merchant: merchant,
          total: amount.abs(),
          initialCat: _cat,
          initialMeta: _catMetaFor(_cat),
          parentSnapshot: Map<String, dynamic>.from(tx),
        ),
      ),
    );
    if (saved != true || !mounted) return;
    _dashRefresh?.call();
    // The row this screen was showing no longer exists as ONE transaction —
    // it's now several line items back in the feed, same as after a delete.
    Navigator.pop(context);
  }

  Future<void> _undoSplit() async {
    final key = tx['splitGroup'] as String;
    final entry = DashboardStore.txSplits()[key];
    await DashboardStore.removeTxSplit(key);
    // Reconstructed immediately from the stashed snapshot, rather than
    // waiting on the next background sync to re-derive it.
    final children = widget.all.where((r) => r['splitGroup'] == key).toList();
    widget.all.removeWhere(children.contains);
    final parent = (entry?['parent'] as Map?)?.cast<String, dynamic>();
    if (parent != null) widget.all.add(Map<String, dynamic>.from(parent));
    _dashRefresh?.call();
    if (mounted) Navigator.pop(context);
  }

  String get _dateFull {
    final d = _pDate(widget.day['date']);
    String two(int n) => n.toString().padLeft(2, '0');
    return '${widget.day['wd']}, ${two(d.day)}.${two(d.month)}.${d.year}';
  }

  /// Local HH:MM from the backend's epoch (Revolut only; null otherwise).
  String? get _txTime => _hm(widget.tx['ts']);

  List<Map<String, dynamic>> get _similar {
    // Group by the transaction's OWN merge key (set by the backend / feed), not
    // a client-recomputed brand key — the two formulas don't agree on real data,
    // which left "Similar" empty in production. Siblings share this key.
    final key = tx['mkey'];
    if (key == null) return const [];
    return widget.all.where((t) => t['mkey'] == key).toList();
  }

  double _secSpentThisMonth() {
    // Spend in THIS transaction's SECTION this month — matches the per-section
    // budget shown in the card (budgets are keyed by section, not category).
    final month = ((tx['d'] ?? widget.day['date']) as String?)?.substring(0, 7);
    if (month == null) return 0;
    final sec = _secOf(tx);
    return widget.all
        .where((t) =>
            _secOf(t) == sec && t['pos'] != true && _dOf(t).startsWith(month))
        .fold(0.0, (s, t) => s + _aOf(t).toDouble().abs());
  }

  // The genitive month name of this transaction (for the budget card header).
  String get _txMonthGen {
    final d = (tx['d'] ?? widget.day['date']) as String?;
    if (d == null) return '';
    final m = int.tryParse(d.substring(5, 7));
    return (m != null && m >= 1 && m <= 12) ? _monGen[m - 1] : '';
  }

  void _toast(String m) => ScaffoldMessenger.of(context)
    ..hideCurrentSnackBar()
    ..showSnackBar(SnackBar(
        content: Text(m), duration: const Duration(milliseconds: 3300)));

  void _pickCategory() {
    showModalBottomSheet<Map<String, dynamic>>(
      context: context,
      isScrollControlled: true,
      backgroundColor: _card,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (_) => _SelectCategorySheet(current: _cat),
    ).then((res) {
      if (res == null || !mounted) return;
      final cat = res['cat'] as String;
      final meta = _catMetaFor(cat);
      // Prefer the full metadata table (consistent per-tx col/ic + section);
      // fall back to the sheet's section-level keys for any uncovered label.
      final col = meta?.col;
      final ic = meta?.ic;
      final sec = meta?.sec;
      final secc = meta?.secc ?? res['c'] as String?;
      setState(() {
        _cat = cat;
        _catColor =
            meta != null ? _colOf(col) : (_secColor[res['c']] ?? _catColor);
        _catIcon =
            meta != null ? _iconOf(ic) : (_secIcon[res['i']] ?? _catIcon);
        _isTransfer = sec == 'Pervedimai';
      });
      // 2026-08-16: a manual pick used to only mutate the in-memory rows —
      // nothing recorded it in DashboardStore, so a background sync (which
      // rebuilds `all` straight from the bank feed) silently reverted it,
      // same class of bug _convertTransfer/_toggleStar already guard
      // against. 'manual': true also matches the "Įvesta ranka" vs
      // "Kategorizuota automatiškai" badge _categoryCard already shows.
      final fields = <String, dynamic>{'cat': cat, 'manual': true};
      if (sec != null) fields['sec'] = sec;
      if (secc != null) fields['secc'] = secc;
      if (col != null) fields['col'] = col;
      if (ic != null) fields['ic'] = ic;
      for (final r in [..._underlying, tx]) {
        fields.forEach((k, v) => r[k] = v);
      }
      for (final r in _underlying) {
        DashboardStore.setTxEdit(DashboardStore.txIdentity(r), fields);
      }
      // "Atlyginimas" picked once → remember this counterparty as a salary
      // source (DashboardStore.salaryRefs) and re-stamp every OTHER credit
      // from them already in view right now — not just the row that was
      // tapped. _applySalaryRefs re-applies the same rule to every future
      // sync, for payments that haven't arrived yet.
      if (cat == 'Atlyginimas') {
        final key = _merchantKey(_nmOf(tx));
        if (key.isNotEmpty) {
          DashboardStore.addSalaryRef(key);
          _applySalaryRefs(widget.all, {key});
        }
      }
      _dashRefresh?.call();
      _toast('${tr('Kategorija pakeista į')} „$cat"');
    });
  }

  @override
  Widget build(BuildContext context) {
    final similar = _similar;
    // Budgets are per SECTION, so look up by this transaction's section (not its
    // category — a category name is never a budget key, so this always missed).
    final budgetLimit = (widget.budgets[_secOf(tx)] as num?)?.toDouble();
    return Scaffold(
      backgroundColor: _bg,
      body: SafeArea(
        bottom: false,
        child: Column(
          children: [
            Container(
              color: _card,
              child: Column(children: [
                _topBar(),
                const SizedBox(height: 6),
                _hero(),
                const SizedBox(height: 18),
                _dateRow(),
                const SizedBox(height: 14)
              ]),
            ),
            Expanded(
              child: ListView(
                padding: const EdgeInsets.only(top: 14, bottom: 30),
                children: [
                  _isSplitGroup ? _splitItemsCard() : _categoryCard(),
                  _cashWithdrawalCard(),
                  _detailsBox(),
                  _actions(),
                  if (budgetLimit != null) _budgetCard(budgetLimit),
                  _accountCard(),
                  if (similar.length > 1) _similarSection(similar),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _topBar() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(6, 4, 10, 4),
      child: Row(
        children: [
          IconButton(
              onPressed: () => Navigator.pop(context),
              icon: Icon(Icons.arrow_back_ios_new_rounded,
                  size: 20, color: _ink)),
          Expanded(
            child: Text(
                _isSplitGroup
                    ? tr('Išskaidytas sandoris')
                    : (_isTransfer
                        ? tr('Vidinis pervedimas')
                        : tr('Įprastas sandoris')),
                style: TextStyle(
                    fontSize: 18, fontWeight: FontWeight.w700, color: _ink)),
          ),
          IconButton(
              onPressed: _delete,
              icon:
                  Icon(Icons.delete_outline_rounded, size: 22, color: _muted)),
          IconButton(
              onPressed: _toggleStar,
              icon: Icon(
                  _starred ? Icons.star_rounded : Icons.star_border_rounded,
                  size: 24,
                  color: _starred ? const Color(0xFFF5B301) : _muted)),
