  Widget _hero() {
    return Padding(
      // A short merchant name is one line, so Column's own centering was
      // enough and this never showed up in testing with real (short) names.
      // A long one (e.g. "Overføring Innland Bonprix Handelsgesellschaft
      // Mb") wraps to 2+ lines — each wrapped line is independently
      // left-aligned by Text's own default TextAlign.start, block-centering
      // (what Column's crossAxisAlignment does) only centers the block as a
      // whole, not the text within it. No horizontal padding either, so a
      // wrapped line could reach the literal screen edge.
      padding: const EdgeInsets.symmetric(horizontal: 24),
      child: Column(
        children: [
          CategoryIcon(
            icon: _isTransfer ? Icons.swap_horiz_rounded : _catIcon,
            color: _isTransfer ? const Color(0xFF3E3B54) : _catColor,
            size: 76,
            circle: false,
            // A transfer is a movement, not a merchant — a brand logo on it
            // would be claiming the money went somewhere it didn't.
            merchant: _isTransfer ? null : _logoOf(widget.tx),
            domain: _isTransfer ? null : _domOf(widget.tx),
          ),
          const SizedBox(height: 14),
          Text(merchant,
              textAlign: TextAlign.center,
              style: TextStyle(
                  fontSize: 27,
                  fontWeight: FontWeight.w800,
                  color: _ink,
                  letterSpacing: -0.4)),
          const SizedBox(height: 4),
          Text(_eurTx(tx, signed: true),
              textAlign: TextAlign.center,
              style: TextStyle(
                  fontSize: 20,
                  fontWeight: FontWeight.w700,
                  color: isPos ? _good : _ink)),
        ],
      ),
    );
  }

  // The itemised breakdown of a collapsed split-receipt row — replaces
  // _categoryCard() (a single category/amount doesn't apply to a purchase
  // spanning several). Each row is one real underlying `all` entry, so its
  // own 'col'/'ic'/'cat' and (post-2026-08-21 fix) correctly individualised
  // 'a' render exactly as they do everywhere else split items appear.
  Widget _splitItemsCard() {
    final items = _underlying
      ..sort((a, b) => ((a['splitIndex'] as int?) ?? 0)
          .compareTo((b['splitIndex'] as int?) ?? 0));
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      child: AppCard(
        color: _card,
        border: _hair,
        padding: const EdgeInsets.fromLTRB(14, 12, 14, 2),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('${tr('Išskaidyta į')} ${items.length}',
                style: TextStyle(
                    fontSize: 12.5, color: _muted, fontWeight: FontWeight.w600)),
            const SizedBox(height: 10),
            for (final it in items) ...[
              Row(
                children: [
                  CategoryIcon(
                      icon: _iconOf(it['ic'] as String?),
                      color: _colOf(it['col'] as String?),
                      size: 34),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text((it['nm'] as String?) ?? '',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                fontSize: 14.5,
                                fontWeight: FontWeight.w600,
                                color: _ink)),
                        Text(tr((it['cat'] as String?) ?? ''),
                            style: TextStyle(fontSize: 12, color: _muted)),
                      ],
                    ),
                  ),
                  Text(_eurTx(it, signed: true),
                      style: TextStyle(
                          fontSize: 14.5,
                          fontWeight: FontWeight.w700,
                          color: _ink)),
                ],
              ),
              if (it != items.last)
                Divider(height: 20, color: _hair)
              else
                const SizedBox(height: 10),
            ],
          ],
        ),
      ),
    );
  }

  Widget _dateRow() {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 20),
      child: Row(
        children: [
          Text(tr('Data'), style: TextStyle(fontSize: 15, color: _muted)),
          const Spacer(),
