  Widget _actions() {
    final chips = <List<dynamic>>[
      // A split group has no single name/category/flow to rename or convert —
      // _edit/_convertTransfer/_addToRecurring all act on the WHOLE group via
      // _underlying, which would silently overwrite every item's own category.
      if (!_isSplitGroup) [Icons.edit_outlined, tr('Redaguoti'), _edit],
      // 2026-08-16: removed — the star icon in the AppBar (onPressed:
      // _toggleStar, ~line 8649) already does this exact thing; having it
      // twice (icon up top, "Žyma" text button down here) was one control
      // shown in two places for no reason.
      if (!_isSplitGroup)
        [
          Icons.swap_horiz_rounded,
          _isTransfer ? tr('Į įprastą') : tr('Į vidinį pervedimą'),
          _convertTransfer
        ],
      if (!_isSplitGroup && !_isTransfer && !isPos)
        [
          Icons.repeat_rounded,
          tr('Pridėti prie pasikartojančių'),
          _addToRecurring
        ],
      // A single bank charge (Maxima receipt, etc.) covering several real
      // categories — turn it into separate categorised line items. Not
      // offered for transfers/income: splitting only makes sense for a
      // purchase covering several spending categories.
      if (_isSplitChild)
        [Icons.call_split_rounded, tr('Anuliuoti skaidymą'), _undoSplit]
      else if (!_isTransfer && !isPos)
        [Icons.call_split_rounded, tr('Skaidyti'), _openSplit],
      [Icons.delete_outline_rounded, tr('Ištrinti'), _delete],
    ];
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
      child: Wrap(
        spacing: 8,
        runSpacing: 8,
        children: [
          for (final c in chips)
            InkWell(
              onTap: c[2] as VoidCallback,
              borderRadius: BorderRadius.circular(12),
              child: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 13, vertical: 10),
                decoration: BoxDecoration(
                  color: _card,
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: _ink, width: 1.5),
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  Icon(c[0] as IconData, size: 16, color: _purple),
                  const SizedBox(width: 6),
                  Text(c[1] as String,
                      style: TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w700,
                          color: _ink)),
                ]),
              ),
            ),
        ],
      ),
    );
  }

  Widget _budgetCard(double limit) {
    final spent = _secSpentThisMonth();
    final left = limit - spent;
    final ratio = (spent / limit).clamp(0.0, 1.0);
    final over = left < 0;
    return Padding(
      padding: const EdgeInsets.fromLTRB(20, 0, 20, 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('$_txMonthGen ${tr('biudžetas')}',
              style: TextStyle(
                  fontSize: 12.5, color: _muted, fontWeight: FontWeight.w600)),
          const SizedBox(height: 8),
          AppCard(
            color: _card,
            border: _hair,
            padding: const EdgeInsets.all(15),
            child: Column(
              children: [
                Row(children: [
                  CategoryIcon(icon: _catIcon, color: _catColor, size: 36),
                  const SizedBox(width: 10),
                  // The section this transaction belongs to — the budget is
                  // per-section, so name the section, not the category.
                  Expanded(
                      child: Text(tr(_secOf(tx)),
                          style: TextStyle(
                              fontSize: 15.5,
                              fontWeight: FontWeight.w700,
                              color: _ink))),
                  Text(_eur(limit).replaceAll(',00', ''),
                      style: TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.w800,
                          color: _ink)),
                ]),
                const SizedBox(height: 12),
                Row(children: [
                  Text('${_eur(spent)} ${tr('išleista')}',
                      style: TextStyle(fontSize: 12.5, color: _muted)),
                  const Spacer(),
                  Text(
                      over
                          ? '${_eur(-left)} ${tr('viršyta')}'
                          : '${_eur(left)} ${tr('liko')}',
                      style: TextStyle(
                          fontSize: 12.5,
                          fontWeight: FontWeight.w700,
                          color: over ? DS.danger : _good)),
                ]),
                const SizedBox(height: 8),
                ClipRRect(
                  borderRadius: BorderRadius.circular(5),
                  child: LinearProgressIndicator(
                    value: ratio,
                    minHeight: 8,
                    backgroundColor: _soft,
                    valueColor:
                        AlwaysStoppedAnimation(over ? DS.danger : _good),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _accountCard() {
    // Only name an account when the scan has exactly one — otherwise we can't
    // tell which account this transaction belongs to (rows carry no account id),
    // so showing any single bank would be a guess. Hide it instead of lying.
    if (widget.accounts.length != 1) return const SizedBox.shrink();
    final a = widget.accounts.first;
    final label = (a['name'] as String?)?.trim();
    if (label == null || label.isEmpty) return const SizedBox.shrink();
    return Padding(
      padding: const EdgeInsets.fromLTRB(20, 0, 20, 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(acctFallbackName(),
              style: TextStyle(
                  fontSize: 12.5, color: _muted, fontWeight: FontWeight.w600)),
          const SizedBox(height: 8),
          AppCard(
            color: _card,
            border: _hair,
            padding: const EdgeInsets.all(14),
            child: Row(children: [
              _acctGlyph(a, diameter: 38, fontSize: 17),
              const SizedBox(width: 12),
              Text(label,
                  style: TextStyle(
                      fontSize: 15.5,
                      fontWeight: FontWeight.w700,
                      color: _ink)),
            ]),
          ),
        ],
      ),
    );
  }

  Widget _similarSection(List<Map<String, dynamic>> items) {
    final show = items.take(15).toList();
    return Padding(
      padding: const EdgeInsets.fromLTRB(20, 4, 20, 0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(children: [
            Text(tr('Panašūs sandoriai'),
                style: TextStyle(
                    fontSize: 20,
                    fontWeight: FontWeight.w800,
                    color: _ink,
                    letterSpacing: -0.3)),
            const SizedBox(width: 8),
            Text('${items.length}',
                style: TextStyle(
                    fontSize: 14, fontWeight: FontWeight.w700, color: _muted)),
          ]),
          const SizedBox(height: 10),
          for (final s in show)
            Container(
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 11),
              decoration: BoxDecoration(
                  color: _card,
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: _hair)),
              child: Row(children: [
                CategoryIcon(
                    icon: _iconOf(s['ic'] as String?),
                    color: _colOf(s['col'] as String?),
                    size: 40,
                    circle: false,
                    merchant: _logoOf(s),
                    domain: _domOf(s)),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(_shortNm(_nmOf(s)),
                          style: TextStyle(
                              fontSize: 15.5,
                              fontWeight: FontWeight.w700,
                              color: _ink)),
                      const SizedBox(height: 2),
                      Row(children: [
                        Container(
                            width: 5,
                            height: 5,
                            decoration: BoxDecoration(
                                shape: BoxShape.circle, color: _purple)),
                        const SizedBox(width: 6),
                        Flexible(
                            child: Text(
                                '${_mdOf(s)}; ${tr((s['cat'] ?? '').toString())}',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style:
                                    TextStyle(fontSize: 12.5, color: _muted))),
                      ]),
                    ],
                  ),
                ),
                const SizedBox(width: 8),
                Text(_eurTx(s, signed: true),
                    style: TextStyle(
                        fontSize: 15.5,
                        fontWeight: FontWeight.w700,
                        color: s['pos'] == true ? _good : _ink,
                        fontFeatures: const [FontFeature.tabularFigures()])),
              ]),
            ),
          if (items.length > show.length)
            Padding(
              padding: const EdgeInsets.only(top: 4),
              child: Text('… ${tr('ir dar')} ${items.length - show.length}',
                  style: TextStyle(fontSize: 13, color: _muted)),
            ),
        ],
      ),
    );
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// SELECT CATEGORY sheet — Vaultie taxonomy
// ══════════════════════════════════════════════════════════════════════════════
class _SelectCategorySheet extends StatefulWidget {
  const _SelectCategorySheet({required this.current});
  final String current;
  @override
  State<_SelectCategorySheet> createState() => _SelectCategorySheetState();
}

class _SelectCategorySheetState extends State<_SelectCategorySheet> {
  String _q = '';

  @override
  Widget build(BuildContext context) {
    return DraggableScrollableSheet(
      initialChildSize: 0.88,
      minChildSize: 0.5,
      maxChildSize: 0.95,
      expand: false,
      builder: (_, ctrl) => Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 14, 20, 6),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                GestureDetector(
                    onTap: () => Navigator.pop(context),
                    child: Padding(
                        padding: const EdgeInsets.only(right: 14, top: 4),
                        child:
                            Icon(Icons.close_rounded, size: 24, color: _ink))),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(tr('SANDORIS'),
                        style: TextStyle(
                            fontSize: 11,
                            color: _muted,
                            fontWeight: FontWeight.w700,
                            letterSpacing: 0.8)),
                    Text(tr('Pasirinkti kategoriją'),
                        style: TextStyle(
                            fontSize: 24,
                            fontWeight: FontWeight.w800,
                            color: _ink,
                            letterSpacing: -0.4)),
                  ],
                ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 8, 20, 8),
            child: TextField(
              onChanged: (v) => setState(() => _q = v.toLowerCase()),
              cursorColor: _purple,
              style: TextStyle(color: _ink),
              decoration: InputDecoration(
                hintText: tr('Ieškoti'),
                hintStyle: TextStyle(color: _faint),
                suffixIcon: Icon(Icons.search_rounded, color: _muted),
                isDense: true,
                contentPadding:
                    const EdgeInsets.symmetric(horizontal: 4, vertical: 12),
                enabledBorder:
                    UnderlineInputBorder(borderSide: BorderSide(color: _hair)),
                focusedBorder: UnderlineInputBorder(
                    borderSide: BorderSide(color: _purple)),
              ),
            ),
          ),
          Expanded(
            child: ListView(
              controller: ctrl,
              padding: const EdgeInsets.only(bottom: 24),
              children: [
                for (final sec in _taxonomy) ..._section(sec),
              ],
            ),
          ),
        ],
      ),
    );
  }

  List<Widget> _section(Map sec) {
    final subs = (sec['subs'] as List)
        .cast<String>()
        .where((s) => _q.isEmpty || s.toLowerCase().contains(_q))
        .toList();
    if (subs.isEmpty) return [];
    final color = _secColor[sec['c']] ?? _muted;
    return [
      Padding(
        padding: const EdgeInsets.fromLTRB(20, 14, 20, 6),
        child: Row(children: [
          CategoryIcon(
              icon: _secIcon[sec['i']] ?? Icons.circle, color: color, size: 30),
          const SizedBox(width: 10),
          Text(tr(sec['sec'] as String),
              style: TextStyle(
                  fontSize: 15, fontWeight: FontWeight.w800, color: _ink)),
        ]),
      ),
      for (final sub in subs)
        InkWell(
          onTap: () => Navigator.pop(
              context, {'cat': sub, 'c': sec['c'], 'i': sec['i']}),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(60, 11, 20, 11),
            child: Row(children: [
              Expanded(
                  child: Text(tr(sub),
                      style: TextStyle(fontSize: 15, color: _ink))),
              if (sub == widget.current)
                Icon(Icons.check_rounded, size: 20, color: _purple),
            ]),
          ),
        ),
    ];
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// SPLIT TRANSACTION (PHASE 1 — manual only, no receipt scan yet)
// One purchase (a Maxima receipt covering groceries + alcohol + household)
// becomes several separately-categorised line items. Modeled as REPLACING
// the original row with one new row per item (see _applyTxSplits) rather
// than a hidden field on it — every existing consumer already sums `all` by
// iterating rows, so nothing else in the app needs to know splits exist.
// Matches how Copilot Money / Monarch / Lunch Money all model this
// (parent + child transactions), not a bespoke scheme invented here.
// ══════════════════════════════════════════════════════════════════════════════
class _SplitLine {
  _SplitLine(
      {required this.cat,
      required this.sec,
      required this.secc,
      required this.col,
      required this.ic,
      this.name = '',
      double amt = 0})
      : amtCtrl = TextEditingController(
            text: amt > 0 ? amt.toStringAsFixed(2).replaceAll('.', ',') : '');
  String cat, sec, secc, col, ic;
  // The actual product name from a receipt scan ("Duona tostinė", "Šampūnas
  // Head & Shoulders") — empty for a manually-added line. 2026-08-16: this
  // was captured from the scan but never stored anywhere or shown — the
  // split screen showed only a category icon + price per line, so there
  // was no way to check the scan actually put the RIGHT product under the
  // right category, only that the numbers summed correctly.
  String name;
  final TextEditingController amtCtrl;
  double get amt =>
      double.tryParse(amtCtrl.text.replaceAll(',', '.').trim()) ??
      double.nan;
  void dispose() => amtCtrl.dispose();
}

class _SplitTransactionScreen extends StatefulWidget {
  const _SplitTransactionScreen({
    required this.splitKey,
    required this.merchant,
    required this.total, // magnitude — always positive
    required this.initialCat,
    required this.initialMeta,
    required this.parentSnapshot,
    this.prefilledItems,
  });
  final String splitKey;
  final String merchant;
  final double total;
  final String initialCat;
  final _ManualCat? initialMeta;
  final Map<String, dynamic> parentSnapshot;
  // Set when a receipt was already scanned BEFORE this transaction was
  // picked (the Home "Skenuoti kvitą" entry — see _startReceiptScan) —
  // skips straight to these line items instead of the empty/full-amount
  // starting state, and skips a second, redundant scan.
  final List<Map<String, dynamic>>? prefilledItems;

  @override
  State<_SplitTransactionScreen> createState() =>
      _SplitTransactionScreenState();
}

class _SplitTransactionScreenState extends State<_SplitTransactionScreen> {
  late List<_SplitLine> _lines;
  bool _scanning = false;

  @override
  void initState() {
    super.initState();
    final pre = widget.prefilledItems;
    final existing = DashboardStore.txSplits()[widget.splitKey];
    final items = (existing?['items'] as List?)?.cast<Map>();
    if (pre != null && pre.isNotEmpty) {
      // Scanned BEFORE the transaction was even picked (Home's "Skenuoti
      // kvitą" entry) — go straight to these, no second scan.
      _lines = [
        for (final it in pre)
          () {
            final m = _matchScanCat(it['category'] as String?);
            return _SplitLine(
                cat: m.cat,
                sec: m.sec,
                secc: m.secc,
                col: m.col,
                ic: m.ic,
                name: (it['name'] as String?) ?? '',
                amt: ((it['price'] as num?) ?? 0).toDouble());
          }(),
      ];
    } else if (items != null && items.isNotEmpty) {
      _lines = [
        for (final it in items)
          _SplitLine(
              cat: it['cat'] as String,
              sec: it['sec'] as String,
              secc: it['secc'] as String,
              col: it['col'] as String,
              ic: it['ic'] as String,
              name: (it['label'] as String?) ?? '',
              amt: (it['amt'] as num).toDouble())
      ];
    } else {
      final meta = widget.initialMeta;
      // Row 1 starts holding the FULL amount under the original category —
      // splitting is "peel a piece off the bucket", not "type every line
      // from zero". Row 2 starts empty so there's always ≥2 rows to edit.
      _lines = [
        _SplitLine(
            cat: widget.initialCat,
            sec: meta?.sec ?? 'Kita',
            secc: meta?.secc ?? 'indigo',
            col: meta?.col ?? 'other',
            ic: meta?.ic ?? 'swap',
            amt: widget.total),
        _SplitLine(cat: tr('Pasirink kategoriją'), sec: '', secc: '',
            col: 'other', ic: 'swap'),
      ];
    }
    for (final l in _lines) l.amtCtrl.addListener(() => setState(() {}));
  }

  @override
  void dispose() {
    for (final l in _lines) l.dispose();
    super.dispose();
  }

  double get _allocated =>
      _lines.fold(0.0, (s, l) => s + (l.amt.isNaN ? 0 : l.amt));
  double get _remaining => widget.total - _allocated;
  bool get _canSave =>
      _lines.length >= 2 &&
      _remaining.abs() < 0.01 &&
      _lines.every((l) => !l.amt.isNaN && l.amt > 0 && l.sec.isNotEmpty);

  Future<void> _pickLineCategory(_SplitLine line) async {
    final res = await showModalBottomSheet<Map<String, dynamic>>(
      context: context,
      isScrollControlled: true,
      backgroundColor: _card,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (_) => _SelectCategorySheet(current: line.cat),
    );
    if (res == null) return;
    final cat = res['cat'] as String;
    final meta = _catMetaFor(cat);
    setState(() {
      line.cat = cat;
      line.sec = meta?.sec ?? res['c'] as String? ?? 'Kita';
      line.secc = meta?.secc ?? res['c'] as String? ?? 'indigo';
      line.col = meta?.col ?? 'other';
      line.ic = meta?.ic ?? 'swap';
    });
  }

  void _addLine() => setState(() => _lines.add(
      _SplitLine(cat: tr('Pasirink kategoriją'), sec: '', secc: '',
          col: 'other', ic: 'swap')));

  void _toast(String m) => ScaffoldMessenger.of(context)
    ..hideCurrentSnackBar()
    ..showSnackBar(SnackBar(
        content: Text(m), duration: const Duration(milliseconds: 3300)));

  // PHASE 2 — the actual "scan it for me" the manual editor above exists to
  // correct, not replace. A photo goes to scan_receipt (Cloud Function →
  // vision LLM call, see functions/receipt_scan.py), which returns line
  // items with a category from the SAME taxonomy _SelectCategorySheet uses.
  // The scanned total is deliberately NOT trusted as the target — _remaining
  // stays computed against widget.total (the real bank amount), so a missed
  // item or a misread price just shows up as a nonzero remainder the user
  // fixes with the exact same tools (add a line, "Priskirti likutį") as any
  // manual edit — never a silent, possibly-wrong auto-save.
  Future<void> _pickAndScan() async {
    if (!await _ensureReceiptScanConsent(context)) return;
    if (!mounted) return;
    final source = await _chooseReceiptSource(context);
    if (source == null || !mounted) return; // sheet dismissed
    // Pick before the spinner goes up — same order as _scanReceiptFlow, see
    // _pickReceiptFile's doc for why that matters for ImageSource.camera.
    final file = await _pickReceiptFile(source: source);
    if (file == null || !mounted) return; // picker cancelled — not an error
    setState(() => _scanning = true);
    try {
      final res = await _scanReceiptFile(file);
      final (items, _, _) = res;
      if (items.isEmpty) {
        _toast(tr('Nepavyko atpažinti kvito — pabandyk dar kartą arba įvesk rankiniu būdu'));
        return;
      }
      // 2026-09-01: this rescan button is reachable from BOTH the bank-
      // matched split (widget.total is a real bank amount, already EUR —
      // items must stay as the OCR returned them) and the cash-only split
      // opened from _createCashReceiptSplit (widget.total was pre-converted
      // to EUR there, via Money.rate, same reasoning as that function's own
      // doc). Freshly-scanned prices here are raw/unconverted either way, so
      // the cash case needs the identical conversion applied a second time,
      // or a rescan would silently reintroduce the exact bug just fixed at
      // the entry point. cashSrc on the parent snapshot is what tells the
      // two cases apart.
      final isCash = widget.parentSnapshot['cashSrc'] == true;
      setState(() {
        for (final l in _lines) l.dispose();
        _lines = [
          for (final it in items)
            () {
              final m = _matchScanCat(it['category'] as String?);
              final rawPrice = ((it['price'] as num?) ?? 0).toDouble();
              return _SplitLine(
                  cat: m.cat,
                  sec: m.sec,
                  secc: m.secc,
                  col: m.col,
                  ic: m.ic,
                  name: (it['name'] as String?) ?? '',
                  amt: (isCash && Money.rate > 0)
                      ? rawPrice / Money.rate
                      : rawPrice);
            }(),
        ];
        for (final l in _lines) l.amtCtrl.addListener(() => setState(() {}));
      });
    } on BankingException catch (e) {
      if (mounted) _toast(e.message);
    } catch (_) {
      if (mounted) {
        _toast(tr('Nepavyko atpažinti kvito — pabandyk dar kartą arba įvesk rankiniu būdu'));
      }
    } finally {
      if (mounted) setState(() => _scanning = false);
    }
  }

  // The server already constrains its reply to this exact taxonomy (see
  // receipt_scan._CATEGORIES, kept in sync by hand), so this only guards
  // against a genuinely unrecognised string reaching the UI unstyled.
  ({String cat, String sec, String secc, String col, String ic}) _matchScanCat(
      String? raw) {
    final cat = (raw != null && raw.isNotEmpty) ? raw : 'Kita';
    final meta = _catMetaFor(cat) ?? _catMetaFor('Kita')!;
    return (cat: cat, sec: meta.sec, secc: meta.secc, col: meta.col, ic: meta.ic);
  }

  void _removeLine(_SplitLine line) {
    if (_lines.length <= 2) return; // a "split" needs at least 2 parts
    setState(() {
      _lines.remove(line);
      line.dispose();
    });
  }

  // One-tap fix for the common case — the last line takes whatever's left.
  void _fillRemainder() {
    if (_lines.isEmpty || _remaining.abs() < 0.005) return;
    final l = _lines.last;
    final cur = l.amt.isNaN ? 0 : l.amt;
    l.amtCtrl.text =
        (cur + _remaining).toStringAsFixed(2).replaceAll('.', ',');
  }

  Future<void> _save() async {
    if (!_canSave) return;
    final parentAmt = (widget.parentSnapshot['a'] as num?)?.toDouble() ?? 0;
    final negative = parentAmt < 0;
    final items = [
      for (final l in _lines)
        {
          'cat': l.cat,
          'sec': l.sec,
          'secc': l.secc,
          'col': l.col,
          'ic': l.ic,
          'amt': negative ? -l.amt : l.amt,
          // The scanned product name ("Duona tostinė") — _applyTxSplits
          // uses this as the split child row's OWN name in the feed
          // (falling back to the merchant name when empty, e.g. for a
          // manually-added line with no product name).
          if (l.name.isNotEmpty) 'label': l.name,
        }
    ];
    await DashboardStore.setTxSplit(
        widget.splitKey, widget.parentSnapshot, items);
    if (mounted) Navigator.pop(context, true);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _bg,
      appBar: AppBar(
        backgroundColor: _bg,
        elevation: 0,
        foregroundColor: _ink,
        title: Text(tr('Skaidyti operaciją'),
            style: TextStyle(fontWeight: FontWeight.w800, color: _ink)),
      ),
      body: SafeArea(
        child: Column(children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 4, 20, 12),
            child: Row(children: [
              Expanded(
                  child: Text(widget.merchant,
                      style: TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.w800,
                          color: _ink))),
              Text(_eur0(widget.total),
                  style: TextStyle(
                      fontSize: 18, fontWeight: FontWeight.w800, color: _ink)),
            ]),
          ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
              children: [
                InkWell(
                  onTap: _scanning ? null : _pickAndScan,
                  borderRadius: BorderRadius.circular(14),
                  child: Container(
                    margin: const EdgeInsets.only(bottom: 12),
                    padding: const EdgeInsets.symmetric(
                        horizontal: 14, vertical: 13),
                    decoration: BoxDecoration(
                        color: _purpleSoft,
                        borderRadius: BorderRadius.circular(14)),
                    child: Row(children: [
                      if (_scanning)
                        SizedBox(
                            width: 20,
                            height: 20,
                            child: CircularProgressIndicator(
                                strokeWidth: 2.4, color: _purple))
                      else
                        Icon(Icons.document_scanner_outlined,
                            size: 22, color: _purple),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                            _scanning
                                ? tr('Skenuojama…')
                                : tr('Skenuoti kvitą'),
                            style: TextStyle(
                                fontSize: 15,
                                fontWeight: FontWeight.w800,
                                color: _purple)),
                      ),
                      if (!_scanning)
                        Icon(Icons.chevron_right_rounded, color: _purple),
                    ]),
                  ),
                ),
                for (final l in _lines) _lineRow(l),
                const SizedBox(height: 4),
                InkWell(
                  onTap: _addLine,
                  borderRadius: BorderRadius.circular(12),
                  child: Padding(
                    padding: const EdgeInsets.symmetric(vertical: 12),
                    child: Row(children: [
                      Icon(Icons.add_rounded, size: 18, color: _purple),
                      const SizedBox(width: 6),
                      Text(tr('Pridėti eilutę'),
                          style: TextStyle(
                              color: _purple, fontWeight: FontWeight.w700)),
                    ]),
                  ),
                ),
              ],
            ),
          ),
          _summaryBar(),
        ]),
      ),
    );
  }

  // 2026-08-16: a scanned product name ("Duona tostinė", "Šampūnas Head &
  // Shoulders") is now its own row up top — before this the line showed
  // ONLY a category icon + price, so there was no way to check the scan
  // actually put the right PRODUCT under the right category, only that the
  // numbers happened to sum correctly. A manually-added line has no name
  // (l.name is empty) and keeps the original single-row layout.
  Widget _lineRow(_SplitLine line) {
    final catRow = Row(children: [
      InkWell(
        onTap: () => _pickLineCategory(line),
        borderRadius: BorderRadius.circular(10),
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 4),
          child: Row(children: [
            CategoryIcon(
                icon: _iconOf(line.ic), color: _colOf(line.col), size: 32),
            const SizedBox(width: 8),
            ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 110),
              child: Text(tr(line.cat),
                  maxLines: 2,
                  style: TextStyle(
                      fontSize: 13, fontWeight: FontWeight.w700, color: _ink)),
            ),
            Icon(Icons.expand_more_rounded, size: 16, color: _muted),
          ]),
        ),
      ),
      const Spacer(),
      if (line.name.isEmpty)
        SizedBox(
          // 2026-08-30: widened to match the other amount field's fix (see
          // its own doc) — same clipped-last-digit risk, same box-plus-
          // suffix width problem.
          width: 100,
          child: TextField(
            controller: line.amtCtrl,
            keyboardType:
                const TextInputType.numberWithOptions(decimal: true),
            textAlign: TextAlign.right,
            style: TextStyle(
                fontSize: 15,
                fontWeight: FontWeight.w800,
                color: _ink,
                fontFeatures: const [FontFeature.tabularFigures()]),
            decoration: InputDecoration(
              isDense: true,
              suffixText: ' €',
              suffixStyle: TextStyle(color: _muted, fontSize: 13),
              border: InputBorder.none,
              hintText: '0,00',
              hintStyle: TextStyle(color: _faint),
            ),
          ),
        ),
      if (_lines.length > 2)
        IconButton(
          onPressed: () => _removeLine(line),
          icon: Icon(Icons.close_rounded, size: 18, color: _faint),
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(),
          visualDensity: VisualDensity.compact,
        )
      else if (line.name.isEmpty)
        const SizedBox(width: 24),
    ]);
    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: _hair)),
      child: line.name.isEmpty
          ? catRow
          : Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Expanded(
                  child: Text(line.name,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                          fontSize: 14.5,
                          fontWeight: FontWeight.w800,
                          color: _ink)),
                ),
                SizedBox(
                  // 2026-08-30: was 84 — reported real bug, the number's
                  // own last digit was cut off/hidden behind the "€" suffix
                  // (e.g. "0,55" rendered as "0,5€"). 84px fit a plain 4-char
                  // amount at this font size but not that PLUS the suffix
                  // text in the same box — widened enough for both, matching
                  // the OTHER amount field a few lines up (the no-name/
                  // catRow variant), which already used 90.
                  width: 100,
                  child: TextField(
                    controller: line.amtCtrl,
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    textAlign: TextAlign.right,
                    style: TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.w800,
                        color: _ink,
                        fontFeatures: const [FontFeature.tabularFigures()]),
                    decoration: InputDecoration(
                      isDense: true,
                      suffixText: ' €',
                      suffixStyle: TextStyle(color: _muted, fontSize: 13),
                      border: InputBorder.none,
                      hintText: '0,00',
                      hintStyle: TextStyle(color: _faint),
                    ),
                  ),
                ),
              ]),
              const SizedBox(height: 2),
              catRow,
            ]),
    );
  }

  Widget _summaryBar() {
    final ok = _remaining.abs() < 0.01;
    // 2026-08-16: was always "Liko paskirstyti: X€" — the same neutral text
    // whether the lines summed to LESS than the real bank amount or MORE
    // than it (only the red/green colour differed). Comparing a scanned
    // receipt's own total against a real transaction it doesn't actually
    // belong to made an over-allocation common enough during testing that
    // the ambiguity itself was the confusing part — spelling out the
    // direction removes the need to do that arithmetic in your head.
    final over = _remaining < -0.01;
    return Container(
      padding: const EdgeInsets.fromLTRB(20, 12, 20, 16),
      decoration: BoxDecoration(
          color: _card,
          border: Border(top: BorderSide(color: _hair)),
          boxShadow: DS.e1),
      child: SafeArea(
        top: false,
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Row(children: [
            Text(
                ok
                    ? tr('Paskirstyta viskas')
                    : over
                        ? '${tr('Priskirta per daug')}: ${_eur0(_remaining.abs())}'
                        : '${tr('Trūksta')}: ${_eur0(_remaining.abs())}',
                style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w700,
                    color: ok ? _good : DS.danger)),
            const Spacer(),
            if (!ok)
              TextButton(
                onPressed: _fillRemainder,
                // Same underlying fix either direction (adds the signed
                // remainder — positive or negative — to the last line), so
                // one label that doesn't imply a direction, unlike
                // "Priskirti likutį" (assign the LEFTOVER), which reads
                // oddly when there's an excess to remove instead.
                child: Text(tr('Pataisyti paskutinę eilutę'),
                    style:
                        TextStyle(color: _purple, fontWeight: FontWeight.w700)),
              ),
          ]),
          const SizedBox(height: 8),
          SizedBox(
            width: double.infinity,
            child: ElevatedButton(
              onPressed: _canSave ? _save : null,
              style: ElevatedButton.styleFrom(
                  backgroundColor: _purple,
                  disabledBackgroundColor: _faint,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                  shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14))),
              child: Text(tr('Išsaugoti skaidymą'),
                  style: const TextStyle(fontWeight: FontWeight.w800)),
            ),
          ),
        ]),
      ),
    );
  }
}

// Picks WHICH recent bank transaction a just-scanned receipt belongs to
// (see _DashboardPreviewState._startReceiptScan) — the standalone Home
// scan entry has a photo and a total before it has a transaction, unlike
// the per-transaction "Skaidyti" flow which already knows. A plain list,
// closest-amount first; tapping one returns it to the caller, which then
// opens _SplitTransactionScreen for it with the scan already attached.
class _ReceiptMatchScreen extends StatelessWidget {
  const _ReceiptMatchScreen(
      {required this.candidates, required this.scannedTotal});
  final List<Map<String, dynamic>> candidates;
  final double scannedTotal;

  // 2026-08-30: real risk, reported — this screen used to ALWAYS assume the
  // scanned receipt belongs to some real bank transaction, with no way out
  // if none of the offered candidates actually match (or worse, if the user
  // wasn't sure and just picked the closest-looking one). A cash purchase
  // has no bank transaction at all — this tile makes "it wasn't from my
  // bank" a first-class, always-visible choice instead of an unhandled gap.
  Widget _cashOnlyTile(BuildContext context) => InkWell(
        onTap: () => Navigator.pop(context, {'cashOnly': true}),
        borderRadius: BorderRadius.circular(14),
        child: Container(
          margin: const EdgeInsets.only(bottom: 14),
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
              color: _purpleSoft,
              borderRadius: BorderRadius.circular(14),
              border: Border.all(color: _purple.withValues(alpha: 0.4))),
          child: Row(children: [
            Icon(Icons.payments_outlined, color: _purple, size: 24),
            const SizedBox(width: 12),
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(tr('Apmokėta grynais'),
                    style: TextStyle(fontWeight: FontWeight.w800, color: _ink)),
                const SizedBox(height: 2),
                Text(tr('Tai ne banko operacija — pridėsime kaip naują grynųjų įrašą.'),
                    style: TextStyle(fontSize: 12, color: _muted, height: 1.3)),
              ]),
            ),
            Icon(Icons.chevron_right_rounded, color: _faint),
          ]),
        ),
      );

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _bg,
      appBar: AppBar(
        backgroundColor: _bg,
        elevation: 0,
        foregroundColor: _ink,
        title: Text(tr('Su kuria operacija susieti?'),
            style: TextStyle(fontWeight: FontWeight.w800, color: _ink)),
      ),
      body: SafeArea(
        child: candidates.isEmpty
            ? Padding(
                padding: const EdgeInsets.all(20),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    Icon(Icons.search_off_rounded, size: 40, color: _faint),
                    const SizedBox(height: 12),
                    Text(
                        tr('Nerasta panašios banko operacijos per pastarąsias dienas.'),
                        textAlign: TextAlign.center,
                        style: TextStyle(color: _muted, height: 1.4)),
                    const SizedBox(height: 20),
                    _cashOnlyTile(context),
                  ],
                ),
              )
            : ListView(
                padding: const EdgeInsets.fromLTRB(16, 12, 16, 16),
                children: [
                  Padding(
                    padding: const EdgeInsets.only(bottom: 10),
                    child: Text(
                        '${tr('Atpažinta suma')}: ${_eur0(scannedTotal)} — ${tr('pasirink, kuri banko operacija tai yra')}',
                        style: TextStyle(color: _muted, fontSize: 13)),
                  ),
                  _cashOnlyTile(context),
                  for (final t in candidates)
                    InkWell(
                      onTap: () => Navigator.pop(context, t),
                      borderRadius: BorderRadius.circular(14),
                      child: Container(
                        margin: const EdgeInsets.only(bottom: 8),
                        padding: const EdgeInsets.all(12),
                        decoration: BoxDecoration(
                            color: _card,
                            borderRadius: BorderRadius.circular(14),
                            border: Border.all(color: _hair)),
                        child: Row(children: [
                          CategoryIcon(
                              icon: _iconOf(t['ic'] as String?),
                              color: _colOf(t['col'] as String?),
                              size: 38),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(_txDisplayName(t),
                                    style: TextStyle(
                                        fontWeight: FontWeight.w700,
                                        color: _ink)),
                                Text(t['d'] as String? ?? '',
                                    style: TextStyle(
                                        fontSize: 12, color: _muted)),
                              ],
                            ),
                          ),
                          Text(_eur0(_aOf(t).abs().toDouble()),
                              style: TextStyle(
                                  fontWeight: FontWeight.w800, color: _ink)),
                        ]),
                      ),
                    ),
                ],
              ),
      ),
    );
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// BILL SPLIT — split a scanned receipt between PEOPLE, not categories.
// 2026-08-16, explicitly requested as a SEPARATE concept from the category
// split feature above, with one rule that never changed across every
// revision of this section: nothing here ever touches DashboardStore's
// txSplits/txEdits, the bank feed, budgets, or categories — a Bill Split can
// only ever affect DashboardStore.billSplits(), its own private list, never
// anything a real transaction/expense screen reads.
//
// Rewritten 2026-08-16 (second pass) from a single screen into the
// step-by-step flow requested against a reference design: scan -> review
// receipt -> add people -> assign items -> review split -> saved. Saved
// results now DO persist (in billSplits() only, per the request that a
// completed split doesn't have to be thrown away) with an explicit
// delete option — the "nothing is ever saved" rule from the FIRST pass
// was specifically about never reaching the app's real financial data, not
// about Bill Split remembering nothing of its own.
//
// Fixed true-black identity, independent of the app's own light/dark theme
// toggle — explicitly requested after seeing the reference design ("gali
// foną juodą daryti istikro"). None of the app-wide theme getters
// (_ink/_card/_bg/etc., used everywhere else in this file) appear anywhere
// in this section on purpose.
// ══════════════════════════════════════════════════════════════════════════════

const _billBg = Color(0xFF07070B);
const _billCard = Color(0xFF17181F);
const _billCard2 = Color(0xFF1E202A);
const _billInk = Color(0xFFFFFFFF);
const _billMuted = Color(0xFFA7A8B8);
const _billFaint = Color(0xFF64657A);
const _billAccent = Color(0xFF5B62F0);
const _billGood = Color(0xFF34C77B);
const _billHair = Color(0xFF23242E);

// Every "leave the wizard" action (Atmesti / Uždaryti after saving) jumps
// straight back to the Bill Split list via this route name, no matter how
// many steps deep it's called from — simpler and more robust than relaying
// a result back up through every intermediate screen's own push/await.
const _kBillSplitHomeRoute = 'billSplitHome';

// 2026-08-30: real bug, reported — deleting a saved split (or closing the
// wizard right after saving a new one) left the list screen showing its OLD
// content until the user left the Dalybos tab entirely and came back.
// `Navigator.popUntil` only uncovers the list route's ALREADY-BUILT widget
// tree; it doesn't rebuild it just because it becomes visible again (that
// old assumption was wrong — see _BillSplitHomeScreenState's own doc). Every
// wizard exit funnels through this one function, so the fix belongs here
// once, not patched into every individual "Atmesti"/"Uždaryti"/delete call
// site separately.
void _exitBillSplitWizard(BuildContext context) {
  Navigator.of(context).popUntil((r) => r.settings.name == _kBillSplitHomeRoute);
  _billSplitHomeRefresh?.call();
}

/// Set by _BillSplitHomeScreenState while it's the current route; see
/// _exitBillSplitWizard's own doc for why this exists.
void Function()? _billSplitHomeRefresh;

String _billYmd(DateTime d) =>
    '${d.year.toString().padLeft(4, '0')}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

class _BillPerson {
  _BillPerson(this.name, this.color);
  final String name;
  final Color color;
  Map<String, dynamic> toJson() => {'name': name, 'color': color.toARGB32()};
  static _BillPerson fromJson(Map m) =>
      _BillPerson(m['name'] as String, Color(m['color'] as int));
}

const _billPalette = [
  Color(0xFF5866F0),
  Color(0xFF46AE4B),
  Color(0xFFE0574F),
  Color(0xFFF0A322),
  Color(0xFF7C5CD6),
  Color(0xFF2E9BE6),
  Color(0xFF00897B),
  Color(0xFFEE7A3A),
];

Widget _billAvatar(_BillPerson p, {double radius = 15, double fontSize = 13}) =>
    CircleAvatar(
      radius: radius,
      backgroundColor: p.color,
      child: Text(
          p.name.trim().isEmpty ? '?' : p.name.trim()[0].toUpperCase(),
          style: TextStyle(
              color: Colors.white, fontWeight: FontWeight.w800, fontSize: fontSize)),
    );

// ── STEP 0: Bill Split's own section — past saves + start a new one ────────
class _BillSplitHomeScreen extends StatefulWidget {
  const _BillSplitHomeScreen();
  @override
  State<_BillSplitHomeScreen> createState() => _BillSplitHomeScreenState();
}

class _BillSplitHomeScreenState extends State<_BillSplitHomeScreen> {
  // 2026-08-30: was a StatelessWidget with a comment claiming
  // "Navigator.popUntil back to it triggers a rebuild" — false; popping
  // routes uncovers this screen's ALREADY-BUILT widget tree, it doesn't
  // re-invoke build() just because it becomes visible again. That's exactly
  // why a deleted (or freshly saved) split kept showing stale until the
  // whole Dalybos tab was left and re-entered (reported, real). Registering
  // this instance's own setState as the shared _billSplitHomeRefresh hook —
  // called once from _exitBillSplitWizard, so every wizard exit path
  // refreshes this list the same way, not patched per call site.
  @override
  void initState() {
    super.initState();
    _billSplitHomeRefresh = () {
      if (mounted) setState(() {});
    };
  }

  @override
  void dispose() {
    _billSplitHomeRefresh = null;
    super.dispose();
  }

  Future<void> _startNew(BuildContext context) async {
    final res = await _scanReceiptFlow(context);
    if (res == null || !context.mounted) return;
    final (items, total, merchant) = res;
    await Navigator.of(context).push(MaterialPageRoute(
      builder: (_) =>
          _BillReviewReceiptScreen(items: items, total: total, merchant: merchant),
    ));
  }

  Future<void> _openSaved(BuildContext context, Map<String, dynamic> s) async {
    final people = (s['people'] as List)
        .map((e) => _BillPerson.fromJson(e as Map))
        .toList();
    final totals = (s['personTotals'] as List)
        .map((e) => (e as num).toDouble())
        .toList();
    await Navigator.of(context).push(MaterialPageRoute(
      builder: (_) => _BillSplitSavedScreen(
        id: s['id'] as String,
        merchant: s['merchant'] as String?,
        date: s['date'] as String,
        total: (s['total'] as num).toDouble(),
        people: people,
        personTotals: totals,
        justSaved: false,
      ),
    ));
  }

  @override
  Widget build(BuildContext context) {
    // Read fresh on every build — deliberately no cached field. This screen
    // stays alive underneath the whole wizard while it's pushed on top, and
    // a plain Navigator.popUntil back to it (see _exitBillSplitWizard)
    // triggers a rebuild but would never re-run a one-shot field
    // initializer, so a save made mid-wizard would otherwise still be
    // missing from this list the moment the user lands back on it.
    final saved = DashboardStore.billSplits();
    return Scaffold(
      backgroundColor: _billBg,
      appBar: AppBar(
        backgroundColor: _billBg,
        elevation: 0,
        foregroundColor: _billInk,
        title: Text(tr('Dalybos'),
            style: const TextStyle(fontWeight: FontWeight.w800, color: _billInk)),
      ),
      body: SafeArea(
        child: saved.isEmpty
            ? Center(
                child: Padding(
                  padding: const EdgeInsets.all(28),
                  child: Column(mainAxisSize: MainAxisSize.min, children: [
                    Icon(Icons.groups_rounded, size: 46, color: _billFaint),
                    const SizedBox(height: 14),
                    Text(tr('Dar nėra išsaugotų skaidymų.'),
                        style: TextStyle(color: _billMuted, fontSize: 14),
                        textAlign: TextAlign.center),
                    const SizedBox(height: 24),
                    _newSplitButton(context),
                  ]),
                ),
              )
            : ListView(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 16),
                children: [
                  _newSplitButton(context),
                  const SizedBox(height: 18),
                  Text(tr('Anksčiau išsaugoti'),
                      style: TextStyle(
                          color: _billMuted,
                          fontSize: 12.5,
                          fontWeight: FontWeight.w700)),
                  const SizedBox(height: 8),
                  for (final s in saved) _savedCard(context, s),
                ],
              ),
      ),
    );
  }

  Widget _newSplitButton(BuildContext context) => SizedBox(
        width: double.infinity,
        child: ElevatedButton.icon(
          onPressed: () => _startNew(context),
          icon: const Icon(Icons.add_rounded),
          label: Text(tr('Naujas skaidymas'),
              style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 15)),
          style: ElevatedButton.styleFrom(
              backgroundColor: _billAccent,
              foregroundColor: Colors.white,
              padding: const EdgeInsets.symmetric(vertical: 15),
              shape:
                  RoundedRectangleBorder(borderRadius: BorderRadius.circular(14))),
        ),
      );

  Widget _savedCard(BuildContext context, Map<String, dynamic> s) {
    final people = (s['people'] as List).cast<Map>();
    final peopleLabel =
        people.length == 1 ? tr('1 žmogus') : '${people.length} ${tr('žmonės')}';
    return InkWell(
      onTap: () => _openSaved(context, s),
      // 2026-08-16: was 16 here, 14 on every other _billCard in this wizard
      // — matched for consistency (audit finding).
      borderRadius: BorderRadius.circular(14),
      child: Container(
        margin: const EdgeInsets.only(bottom: 10),
        padding: const EdgeInsets.all(14),
        decoration:
            BoxDecoration(color: _billCard, borderRadius: BorderRadius.circular(14)),
        child: Row(children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text((s['merchant'] as String?) ?? tr('Kvitas'),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: _billInk, fontWeight: FontWeight.w800, fontSize: 15)),
                const SizedBox(height: 3),
                Text('${s['date']} · $peopleLabel',
                    style: TextStyle(color: _billMuted, fontSize: 12)),
              ],
            ),
          ),
          Text(_eur0((s['total'] as num).toDouble()),
              style: const TextStyle(
                  color: _billInk, fontWeight: FontWeight.w800, fontSize: 15)),
        ]),
      ),
    );
  }
}

// ── STEP 1: Review receipt ──────────────────────────────────────────────────
class _BillReviewReceiptScreen extends StatelessWidget {
  const _BillReviewReceiptScreen(
      {required this.items, required this.total, required this.merchant});
  final List<Map<String, dynamic>> items;
  final double total;
  final String? merchant;

  double get _itemSum =>
      items.fold(0.0, (s, it) => s + ((it['price'] as num?) ?? 0).toDouble());
  double get _extra => total - _itemSum;

  @override
  Widget build(BuildContext context) {
    final extra = _extra;
    return Scaffold(
      backgroundColor: _billBg,
      appBar: AppBar(
        backgroundColor: _billBg,
        elevation: 0,
        foregroundColor: _billInk,
        title: Text(tr('Peržiūrėti kvitą'),
            style: const TextStyle(fontWeight: FontWeight.w800, color: _billInk)),
      ),
      body: SafeArea(
        child: Column(children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 6, 20, 0),
            child: Row(children: [
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                decoration: BoxDecoration(
                    color: _billGood.withValues(alpha: 0.16),
                    borderRadius: BorderRadius.circular(20)),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  Icon(Icons.check_circle_rounded, size: 15, color: _billGood),
                  const SizedBox(width: 5),
                  Text('${items.length} ${tr('prekės rasta')}',
                      style: const TextStyle(
                          color: _billGood,
                          fontWeight: FontWeight.w700,
                          fontSize: 12.5)),
                ]),
              ),
            ]),
          ),
          if (merchant != null)
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 12, 20, 0),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(merchant!,
                    style: const TextStyle(
                        color: _billInk, fontWeight: FontWeight.w800, fontSize: 21)),
              ),
            ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(20, 16, 20, 16),
              children: [
                for (final it in items)
                  _priceRow((it['name'] as String?) ?? '',
                      ((it['price'] as num?) ?? 0).toDouble()),
                if (extra > 0.01) ...[
                  const SizedBox(height: 4),
                  _priceRow(tr('Kiti mokesčiai'), extra, muted: true),
                ],
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 12),
                  child: Divider(color: _billHair, height: 1),
                ),
                _priceRow(tr('Iš viso'), total, big: true),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
            child: SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                onPressed: () => Navigator.of(context).push(MaterialPageRoute(
                    builder: (_) => _BillAddPeopleScreen(
                        items: items, total: total, merchant: merchant))),
                style: ElevatedButton.styleFrom(
                    backgroundColor: _billAccent,
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(vertical: 15),
                    shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(14))),
                child: Text(tr('Tęsti'),
                    style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 15)),
              ),
            ),
          ),
        ]),
      ),
    );
  }

  Widget _priceRow(String name, double price, {bool muted = false, bool big = false}) =>
      Padding(
        padding: const EdgeInsets.symmetric(vertical: 8),
        child: Row(children: [
          Expanded(
              child: Text(name,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                      color: muted ? _billMuted : _billInk,
                      fontWeight: big ? FontWeight.w800 : FontWeight.w600,
                      fontSize: big ? 17 : 14.5))),
          const SizedBox(width: 10),
          Text(_eur0(price),
              style: TextStyle(
                  color: muted ? _billMuted : _billInk,
                  fontWeight: FontWeight.w800,
                  fontSize: big ? 17 : 14.5)),
        ]),
      );
}

// ── STEP 2: Add people ──────────────────────────────────────────────────────
class _BillAddPeopleScreen extends StatefulWidget {
  const _BillAddPeopleScreen(
      {required this.items, required this.total, required this.merchant});
  final List<Map<String, dynamic>> items;
  final double total;
  final String? merchant;
  @override
  State<_BillAddPeopleScreen> createState() => _BillAddPeopleScreenState();
}

class _BillAddPeopleScreenState extends State<_BillAddPeopleScreen> {
  final List<_BillPerson> _people = [];
  final _nameCtrl = TextEditingController();

  @override
  void dispose() {
    _nameCtrl.dispose();
    super.dispose();
  }

  void _add() {
    final name = _nameCtrl.text.trim();
    if (name.isEmpty) return;
    setState(() {
      _people.add(_BillPerson(name, _billPalette[_people.length % _billPalette.length]));
      _nameCtrl.clear();
    });
  }

  void _remove(int i) => setState(() => _people.removeAt(i));

  void _showAddSheet() {
    showModalBottomSheet(
      context: context,
      backgroundColor: _billCard,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (ctx) => Padding(
        padding: EdgeInsets.fromLTRB(
            20, 20, 20, MediaQuery.of(ctx).viewInsets.bottom + 20),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Text(tr('Vardas'),
              style: const TextStyle(
                  color: _billInk, fontWeight: FontWeight.w800, fontSize: 17)),
          const SizedBox(height: 14),
          TextField(
            controller: _nameCtrl,
            autofocus: true,
            textCapitalization: TextCapitalization.words,
            style: const TextStyle(color: _billInk, fontSize: 16),
            onSubmitted: (_) {
              _add();
              Navigator.pop(ctx);
            },
            decoration: InputDecoration(
              filled: true,
              fillColor: _billCard2,
              hintText: tr('Vardas…'),
              hintStyle: TextStyle(color: _billFaint),
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(14), borderSide: BorderSide.none),
              contentPadding:
                  const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
            ),
          ),
          const SizedBox(height: 14),
          SizedBox(
            width: double.infinity,
            child: ElevatedButton(
              onPressed: () {
                _add();
                Navigator.pop(ctx);
              },
              style: ElevatedButton.styleFrom(
                  backgroundColor: _billAccent,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                  shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14))),
              child: Text(tr('Pridėti'),
                  style: const TextStyle(fontWeight: FontWeight.w800)),
            ),
          ),
        ]),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _billBg,
      appBar: AppBar(
        backgroundColor: _billBg,
        elevation: 0,
        foregroundColor: _billInk,
        title: Text(tr('Pridėti žmones'),
            style: const TextStyle(fontWeight: FontWeight.w800, color: _billInk)),
      ),
      body: SafeArea(
        child: Column(children: [
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(20, 12, 20, 16),
              children: [
                for (var i = 0; i < _people.length; i++) _personRow(i),
                InkWell(
                  onTap: _showAddSheet,
                  borderRadius: BorderRadius.circular(14),
                  child: Padding(
                    padding: const EdgeInsets.symmetric(vertical: 14),
                    child: Row(children: [
                      Icon(Icons.add_rounded, color: _billAccent),
                      const SizedBox(width: 10),
                      Text(tr('Pridėti žmogų'),
                          style: const TextStyle(
                              color: _billAccent,
                              fontWeight: FontWeight.w700,
                              fontSize: 15)),
                    ]),
                  ),
                ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
            child: SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                onPressed: _people.isEmpty
                    ? null
                    : () => Navigator.of(context).push(MaterialPageRoute(
                        builder: (_) => _BillAssignItemsScreen(
                            items: widget.items,
                            total: widget.total,
                            merchant: widget.merchant,
                            people: _people))),
                style: ElevatedButton.styleFrom(
                    backgroundColor: _billAccent,
                    disabledBackgroundColor: _billCard2,
                    disabledForegroundColor: _billFaint,
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(vertical: 15),
                    shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(14))),
                child: Text(tr('Tęsti'),
                    style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 15)),
              ),
            ),
          ),
        ]),
      ),
    );
  }

  Widget _personRow(int i) {
    final p = _people[i];
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      decoration:
          BoxDecoration(color: _billCard, borderRadius: BorderRadius.circular(14)),
