// ══════════════════════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════════════════
// MONTH IN REVIEW — full screen (opened from the dashboard review card)
// ══════════════════════════════════════════════════════════════════════════════
class _SecAgg {
  _SecAgg(this.label, this.colorKey);
  final String label;
  final String colorKey;
  double net = 0;
  Color get color => _secColor[colorKey] ?? _muted;
  IconData get icon => _secIcon[_secToIcon[label]] ?? Icons.circle;
}

class _MonthReviewScreen extends StatefulWidget {
  const _MonthReviewScreen(
      {required this.all,
      required this.balance,
      required this.budgets,
      required this.subs,
      required this.month,
      required this.monthNom,
      required this.monthGen,
      required this.onGoToBudgets,
      this.demoScrollController});
  final List<Map<String, dynamic>> all;
  final Map<String, dynamic> balance;
  final Map<String, dynamic> budgets;
  final Map<String, dynamic> subs;
  final String month, monthNom, monthGen;
  final VoidCallback onGoToBudgets;
  // Non-null only for the onboarding demo — lets its own tour drive this
  // screen's list the same way it drives Home's and Transakcijos'.
  final ScrollController? demoScrollController;
  @override
  State<_MonthReviewScreen> createState() => _MonthReviewScreenState();
}

// Session cache for AI month summaries, keyed by month (e.g. "2026-06"), so
// re-opening the same review doesn't pay for another AI call.
final Map<String, String> _monthAiCache = {};

class _MonthReviewScreenState extends State<_MonthReviewScreen> {
  List<Map<String, dynamic>> get _rows =>
      widget.all.where((t) => _dOf(t).startsWith(widget.month)).toList();

  // Category-list sort: 0 = amount (€), 1 = share (% of total), 2 = change (vs
  // previous month). Mirrors Bilance's "⟳% / ↕% / Amount" toggles.
  int _catSort = 0;
  bool _merchantsOpen = false;
  bool _recOpen = false;

  /// The previous month key ("2026-05") if it has any data, else null.
  String? get _prevMonthKey {
    final y = _yInt(widget.month);
    final mo = _moInt(widget.month);
    final p = DateTime(y, mo - 1, 1);
    final k = '${p.year}-${p.month.toString().padLeft(2, '0')}';
    return widget.all.any((t) => _dOf(t).startsWith(k)) ? k : null;
  }

  Map<String, double> _netByLabelFor(String mk) {
    final m = <String, double>{};
    for (final t in widget.all) {
      if (!_dOf(t).startsWith(mk)) continue;
      m[_secOf(t)] = (m[_secOf(t)] ?? 0) + _aOf(t).toDouble();
    }
    return m;
  }

  // AI-written month narrative: null until it arrives; falls back to a templated
  // summary if the AI is unavailable.
  String? _aiText;
  bool _aiLoading = false;

  @override
  void initState() {
    super.initState();
    _fetchAiSummary();
  }

  Future<void> _fetchAiSummary() async {
    // Sending the month's figures to the AI provider needs the SAME consent the
    // chat asks for. A user who never accepted it must not have their finances sent
    // off-device; the templated fallback summary still renders (_aiText stays null).
    if (!AppPrefs.aiChatConsent) return;
    // Keyed by month AND language: the summary comes back written in the UI
    // language, so a month cached in Lithuanian was replayed verbatim after the
    // user switched to English — the one paragraph on the screen stayed
    // Lithuanian for the rest of the session.
    final lang = effectiveLocale().languageCode;
    final cacheKey = '${widget.month}|$lang';
    final cached = _monthAiCache[cacheKey];
    if (cached != null && cached.isNotEmpty) {
      setState(() => _aiText = cached);
      return;
    }
    setState(() => _aiLoading = true);
    try {
      final text = await BankingService.instance
          .monthSummary(stats: _buildStats(), lang: lang);
      if (!mounted) return;
      if (text.isNotEmpty) _monthAiCache[cacheKey] = text;
      setState(() {
        _aiText = text.isNotEmpty ? text : null;
        _aiLoading = false;
      });
    } catch (_) {
      if (mounted) setState(() => _aiLoading = false);
    }
  }

  /// A compact, PII-free block of this month's figures for the AI to narrate —
  /// only aggregates and category labels, never merchant names or single txns.
  ///
  /// Fixed labels ("Mėnuo:", "Pajamos:", …) switch with `_enUi`, same as
  /// [buildFinanceSummary]: sending an English-mode narrative a 100%
  /// Lithuanian-scaffolded stats block, every single time, is exactly the kind
  /// of pressure that pulls a longer AI reply back into Lithuanian mid-way —
  /// see that function's docstring for the full story. Category labels
  /// (`s.label`) and month names (`widget.monthNom`, already `_enUi`-aware via
  /// `_monNom`) are left as the data already resolves them to.
  String _buildStats() {
    final spent = _sumExpenses(_rows);
    final earned = _sumIncome(_rows);
    final net = earned - spent;
    final secs = _sections();
    final expenseSecs = secs
        .where((s) => !_isIncome(s.label) && !_isTransfer(s.label) && s.net < 0)
        .toList();
    final b = StringBuffer()
      ..writeln('${_enUi ? 'Month' : 'Mėnuo'}: ${widget.monthNom}')
      ..writeln('${_enUi ? 'Income' : 'Pajamos'}: ${earned.round()} €')
      ..writeln('${_enUi ? 'Spending' : 'Išlaidos'}: ${spent.round()} €')
      ..writeln(
          '${_enUi ? 'Net result' : 'Grynasis rezultatas'}: ${net.round()} €');
    if (earned > 0) {
      b.writeln('${_enUi ? 'Savings rate' : 'Santaupų norma'}: '
          '${((earned - spent) / earned * 100).round().clamp(0, 100)} %');
    } else {
      b.writeln(_enUi
          ? 'No income detected this month.'
          : 'Pajamų šį mėnesį neaptikta.');
    }
    if (expenseSecs.isNotEmpty) {
      b.writeln(_enUi
          ? 'Biggest spending categories:'
          : 'Didžiausios išlaidų kategorijos:');
      for (final s in expenseSecs.take(4)) {
        b.writeln('- ${s.label}: ${(-s.net).round()} €');
      }
    }
    final prevRows =
        widget.all.where((t) => _dOf(t).startsWith(_prevMonth)).toList();
    if (prevRows.isNotEmpty) {
      b.writeln(_enUi
          ? 'Previous month ($_prevMonthNom): income ${_sumIncome(prevRows).round()} €, '
              'spending ${_sumExpenses(prevRows).round()} €.'
          : 'Praėjęs mėnuo ($_prevMonthNom): pajamos ${_sumIncome(prevRows).round()} €, '
              'išlaidos ${_sumExpenses(prevRows).round()} €.');
    }
    // Same end-of-block reminder as buildFinanceSummary, for the same reason:
    // recency in context matters more than a system prompt read once at the
    // very start of it.
    if (_enUi) {
      b.writeln('\n(Category labels above are in Lithuanian — this is the '
          'source data. Write the narrative entirely in English regardless.)');
    }
    return b.toString();
  }

  String get _prevMonth {
    final y = _yInt(widget.month);
    final m = _moInt(widget.month);
    return m == 1 ? '${y - 1}-12' : '$y-${(m - 1).toString().padLeft(2, '0')}';
  }

  String get _prevMonthNom => _monNom[(_moInt(widget.month) + 10) % 12];

  bool _isIncome(String l) => l == 'Pajamos';
  bool _isTransfer(String l) =>
      l == 'Pervedimai'; // 'Kita' = uncategorised spending, counts as expense

  List<_SecAgg> _sections() {
    final m = <String, _SecAgg>{};
    for (final t in _rows) {
      final label = _secOf(t);
      final a = m.putIfAbsent(label, () => _SecAgg(label, _seccOf(t)));
      a.net += _aOf(t).toDouble();
    }
    final list = m.values.toList()
      ..sort((x, y) => y.net.abs().compareTo(x.net.abs()));
    return list;
  }

  @override
  Widget build(BuildContext context) {
    final secs = _sections();
    final expenseSecs = secs
        .where((s) => !_isIncome(s.label) && !_isTransfer(s.label) && s.net < 0)
        .toList();
    // Headline figures use the canonical rule (transfers excluded, refunds net
    // spending down) so grynasis == earned − spent and matches the dashboard +
    // review card exactly — never the raw sum-of-amounts that inflated it before.
    final spent = _sumExpenses(_rows);
    final earned = _sumIncome(_rows);
    // "Gauta" = all money that landed from outside (income + incoming transfers).
    // Display-only — net/savings below still use `earned` (canonical income).
    final received = _sumReceived(_rows);
    final net = earned - spent;
    final savings = earned > 0
        ? ((earned - spent) / earned * 100).round().clamp(0, 100)
        : 0;
    // Real saving streak (was hardcoded "2 mėn."), derived from all months.
    final mkeys = (widget.all.map((t) => _ymOf(t)).toSet().toList()..sort());
    int savOf(List<Map<String, dynamic>> r) {
      final e = _sumIncome(r);
      return e > 0
          ? ((e - _sumExpenses(r)) / e * 100).round().clamp(0, 100)
          : 0;
    }

    final streak = _streakOf(
        mkeys,
        (mk) => widget.all.where((t) => _dOf(t).startsWith(mk)).toList(),
        savOf);

    return Scaffold(
      backgroundColor: _bg,
      body: Column(
        children: [
          _header(),
          Expanded(
            child: ListView(
              controller: widget.demoScrollController,
              padding: const EdgeInsets.only(bottom: 56),
              children: [
                const SizedBox(height: 14),
                _filters(),
                _donuts(spent, earned, received, expenseSecs),
                _totalCard(net),
                _statsRow(spent, earned, savings, net),
                _currencyNote(),
                _aiReport(spent, earned, expenseSecs, net),
                _balanceChart(),
                _calendar(),
                _savingsClub(savings, earned, streak),
                _categoryList(secs),
                _budgets(),
                _recurringSection(),
                _insights(),
                _avgDaily(expenseSecs),
                _merchants(),
                _largest(),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _header() {
    // 2026-08-29: was a flat _purpleDeep bar in both themes — one more
    // purple block on a screen that's otherwise gone dark (reported, real —
    // applies to ANY month's review, not just July's). Dark mode matches
    // the Scaffold's own `_bg` instead, so the header melts into the page
    // with no visible bar at all. Light mode keeps its original purple bar.
    return Container(
      color: _darkMode ? _bg : _purpleDeep,
      child: SafeArea(
        bottom: false,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(6, 6, 14, 14),
          child: Row(
            children: [
              IconButton(
                  onPressed: () => Navigator.pop(context),
                  icon: Icon(Icons.arrow_back_ios_new_rounded,
                      size: 20, color: _darkMode ? _ink : Colors.white)),
              Expanded(
                  child: Text('${widget.monthGen} ${tr('apžvalga')}',
                      style: TextStyle(
                          fontSize: 20,
                          fontWeight: FontWeight.w700,
                          color: _darkMode ? _ink : Colors.white))),
            ],
          ),
        ),
      ),
    );
  }

  Widget _filters() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
      child: Row(children: [
        _Chip(icon: Icons.calendar_today_rounded, label: widget.monthNom),
        const SizedBox(width: 9),
        _Chip(icon: Icons.tune_rounded, label: tr('Filtras')),
      ]),
    );
  }

  Widget _donuts(
      double spent, double earned, double received, List<_SecAgg> expenseSecs) {
    // Right donut = "Gauta" (all inflows), split into recognised income (amber)
    // and other inflows/transfers (indigo). Tappable → breakdown. Value/segments
    // are display-only; the canonical income (`earned`) still drives net/savings.
    final other = (received - earned).clamp(0.0, double.infinity);
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
      child: Row(
        children: [
          Expanded(
              child: _donut(
                  spent,
                  [
                    for (final s in expenseSecs) [-s.net, s.color]
                  ],
                  '−',
                  'Išleista')),
          Expanded(
            child: GestureDetector(
              onTap: () => _showReceivedBreakdown(context, earned, other,
                  rows: _rows, monthName: widget.monthNom),
              child: _donut(
                  received,
                  [
                    if (earned > 0) [earned, _secColor['amber']!],
                    if (other > 0) [other, _secColor['indigo']!]
                  ],
                  '+',
                  'Gauta',
                  tappable: true),
            ),
          ),
        ],
      ),
    );
  }

  // [tappable] draws a small ⓘ next to the label. "Gauta" can genuinely be
  // bigger than "Pajamos" the category list shows below — it also counts
  // incoming transfers, per _receivedOf's own doc comment — and that gap sat
  // fully explained in _showReceivedBreakdown, but nothing on screen said the
  // circle could be tapped. Reported live as "neatitikimu" (a mismatch) —
  // the numbers were never wrong, the explanation was just unreachable.
  Widget _donut(
      double value, List<List<dynamic>> segs, String sign, String label,
      {bool tappable = false}) {
    return AspectRatio(
      aspectRatio: 1,
      child: Stack(
        alignment: Alignment.center,
        children: [
          CustomPaint(size: Size.infinite, painter: _DonutPainter(segs)),
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(sign,
                  style: TextStyle(
                      fontSize: 20,
                      fontWeight: FontWeight.w400,
                      color: _muted,
                      height: 1)),
              const SizedBox(height: 2),
              Text(_eur0(value),
                  style: TextStyle(
                      fontSize: 24,
                      fontWeight: FontWeight.w800,
                      color: _ink,
                      letterSpacing: -0.5)),
              Row(mainAxisSize: MainAxisSize.min, children: [
                Text(tr(label), style: TextStyle(fontSize: 13, color: _muted)),
                if (tappable) ...[
                  const SizedBox(width: 3),
                  Icon(Icons.info_outline_rounded, size: 12, color: _faint),
                ],
              ]),
            ],
          ),
        ],
      ),
    );
  }

  Widget _totalCard(double net) {
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 10, 16, 10),
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 15),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: _hair)),
      child: Row(children: [
        Text('${widget.monthGen} ${tr('suma')}',
            style: TextStyle(
                fontSize: 17, fontWeight: FontWeight.w700, color: _ink)),
        const Spacer(),
        Text(_eur(net, signed: true),
            style: TextStyle(
                fontSize: 17,
                fontWeight: FontWeight.w800,
                color: net >= 0 ? _good : _ink)),
      ]),
    );
  }

  Widget _statsRow(double spent, double earned, int savings, double net) {
    Widget stat(String v, String l) => Expanded(
          child: Column(children: [
            Text(v,
                style: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.w800,
                    color: _ink,
                    letterSpacing: -0.3)),
            const SizedBox(height: 2),
            Text(l,
                style: TextStyle(fontSize: 11.5, color: _muted),
                textAlign: TextAlign.center),
          ]),
        );
    Widget div() => Container(width: 1, height: 34, color: _hair);
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      padding: const EdgeInsets.symmetric(vertical: 14),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: _hair)),
      child: Row(children: [
        stat(_eur0(spent), tr('išleista')),
        div(),
        stat(_eur0(earned), tr('uždirbta')),
        div(),
        stat('${net >= 0 ? '+' : '−'}${_eur0(net.abs())}', tr('grynasis')),
        div(),
        stat(earned > 0 ? '$savings %' : '—', tr('santaupų')),
      ]),
    );
  }

  Widget _currencyNote() {
    final sal = _rows
        .where((t) => t['cat'] == 'Atlyginimas (iš NOK)')
        .fold(0.0, (s, t) => s + _aOf(t).toDouble());
    if (sal < 100) return const SizedBox.shrink();
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      padding: const EdgeInsets.all(13),
      decoration:
          BoxDecoration(color: _soft, borderRadius: BorderRadius.circular(14)),
      child: Row(children: [
        Icon(Icons.currency_exchange_rounded, size: 18, color: _purple),
        const SizedBox(width: 10),
        Expanded(
          child: Text(
            '${tr('Atlyginimas')} (${_eur0(sal)}) ${tr('gaunamas NOK (Nergard) ir automatiškai konvertuojamas į EUR. Rodoma bazine valiuta — EUR.')}',
            style: TextStyle(fontSize: 12.5, color: _ink, height: 1.35),
          ),
        ),
      ]),
    );
  }

  Widget _aiReport(
      double spent, double earned, List<_SecAgg> expenseSecs, double net) {
    final savings = earned > 0
        ? ((earned - spent) / earned * 100).round().clamp(0, 100)
        : 0;
    final top = expenseSecs.isNotEmpty ? expenseSecs.first : null;
    // Templated fallback used while the AI writes, or if it's unavailable.
    final fallback =
        '${widget.monthGen} ${tr('mėnesį uždirbai')} ${_eur0(earned)}, ${tr('o išleidai')} ${_eur0(spent)}. ${tr('Grynasis rezultatas')} ${_eur(net, signed: true)}. '
        '${top != null ? '${tr('Daugiausia išleidai kategorijoje')} „${tr(top.label).split(',').first}" (${_eur0(-top.net)}). ' : ''}'
        '${earned > 0 ? '${tr('Santaupų norma šį mėnesį —')} $savings %.' : tr('Šį mėnesį pajamų nebuvo, tad santaupų norma neskaičiuojama.')}';
    final isAi = _aiText != null && _aiText!.isNotEmpty;
    final body = isAi ? _aiText! : fallback;
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(18),
          boxShadow: DS.e1),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(children: [
            Text(tr('SANTRAUKA'),
                style: TextStyle(
                    fontSize: 11.5,
                    fontWeight: FontWeight.w800,
                    color: _purple,
                    letterSpacing: 0.8)),
            const SizedBox(width: 8),
            if (isAi)
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 1),
                decoration: BoxDecoration(
                    color: _purpleSoft, borderRadius: BorderRadius.circular(5)),
                child: Text('AI',
                    style: TextStyle(
                        fontSize: 10,
                        fontWeight: FontWeight.w800,
                        color: _purple,
                        letterSpacing: 0.5)),
              ),
            const Spacer(),
            Icon(Icons.auto_awesome_rounded, size: 20, color: _purple),
          ]),
          const SizedBox(height: 12),
          Text('${widget.monthGen} ${tr('finansų momentas 📸')}',
              style: TextStyle(
                  fontSize: 22,
                  fontWeight: FontWeight.w800,
                  color: _ink,
                  letterSpacing: -0.4)),
          const SizedBox(height: 10),
          if (_aiLoading && !isAi)
            Row(children: [
              SizedBox(
                  width: 15,
                  height: 15,
                  child: CircularProgressIndicator(
                      strokeWidth: 2, color: _purple)),
              const SizedBox(width: 10),
              Text(tr('AI rašo santrauką…'),
                  style: TextStyle(fontSize: 14.5, color: _muted)),
            ])
          else
            Text(body,
                style: TextStyle(fontSize: 15.5, color: _ink, height: 1.45)),
        ],
      ),
    );
  }

  Widget _balanceChart() {
    final series = _cleanSeries(widget.balance['series'])
        .where((p) => _dOf(p).startsWith(widget.month))
        .toList();
    if (series.length < 2) return const SizedBox.shrink();
    final vals = series.map((p) => _vOf(p)).toList();
    final mn = vals.reduce((a, b) => a < b ? a : b);
    final mx = vals.reduce((a, b) => a > b ? a : b);
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 12),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: _hair)),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('${widget.monthGen} ${tr('balansas')}',
              style: TextStyle(
                  fontSize: 13.5, color: _muted, fontWeight: FontWeight.w600)),
          const SizedBox(height: 10),
          SizedBox(
            height: 130,
            child: Row(
              children: [
                Expanded(
                    child: CustomPaint(
                        painter: _AreaChartPainter(vals, mn, mx),
                        size: Size.infinite)),
                const SizedBox(width: 8),
                SizedBox(
                  width: 46,
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(_kEur(mx),
                          style: TextStyle(
                              fontSize: 11.5,
                              color: _muted,
                              fontWeight: FontWeight.w600)),
                      Text(_kEur(mn),
                          style: TextStyle(
                              fontSize: 11.5,
                              color: _muted,
                              fontWeight: FontWeight.w600)),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _savingsClub(int savings, double earned, int streak) {
    final noInc = earned <= 0;
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(18),
          boxShadow: DS.e1),
      child: Row(
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('${widget.monthGen} ${tr('santaupų klubas')}',
                    style: TextStyle(
                        fontSize: 17,
                        fontWeight: FontWeight.w800,
                        color: _ink)),
                const SizedBox(height: 10),
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                      color: _purpleSoft,
                      borderRadius: BorderRadius.circular(20)),
                  child: Row(mainAxisSize: MainAxisSize.min, children: [
                    Icon(Icons.military_tech_rounded, size: 16, color: _purple),
                    const SizedBox(width: 6),
                    Text(noInc ? '—' : '$savings %',
                        style: TextStyle(
                            fontSize: 14,
                            fontWeight: FontWeight.w800,
                            color: _purple)),
                    if (streak >= 2) ...[
                      const SizedBox(width: 10),
                      Icon(Icons.local_fire_department_rounded,
                          size: 16, color: _purple),
                      const SizedBox(width: 4),
                      Text('$streak ${tr('mėn. iš eilės')}',
                          style: TextStyle(
                              fontSize: 13,
                              fontWeight: FontWeight.w600,
                              color: _purple)),
                    ],
                  ]),
                ),
              ],
            ),
          ),
          _clubBadge(savings, earned),
        ],
      ),
    );
  }

  Widget _clubBadge(int savings, double earned) {
    return Container(
      width: 76,
      height: 76,
      decoration: BoxDecoration(color: _purple, shape: BoxShape.circle),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text(earned > 0 ? '$savings' : '—',
              style: const TextStyle(
                  fontSize: 26,
                  fontWeight: FontWeight.w800,
                  color: Colors.white,
                  height: 1)),
          const Text('% klubas',
              style: TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w600,
                  color: Colors.white)),
        ],
      ),
    );
  }

  Widget _catSortToggle(int mode, String label) {
    final on = _catSort == mode;
    return GestureDetector(
      onTap: () => setState(() => _catSort = mode),
      behavior: HitTestBehavior.opaque,
      child: Container(
        margin: const EdgeInsets.only(right: 8),
        padding: const EdgeInsets.symmetric(horizontal: 13, vertical: 6),
        decoration: BoxDecoration(
          color: on ? _purple : _card,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color: on ? _purple : _hair),
        ),
        child: Text(label,
            style: TextStyle(
                fontSize: 12.5,
                fontWeight: FontWeight.w700,
                color: on ? Colors.white : _muted)),
      ),
    );
  }

  Widget _categoryList(List<_SecAgg> secs) {
    // Spending only in the divisor.
    //
    // This used to sum |net| across EVERY section, income and transfers
    // included, so each category was measured against a total it is not part of:
    // 400 € of food out of 1 000 € spent showed as 12% once a 2 000 € salary and
    // a 1 000 € transfer sat in the denominator. Every share was quietly wrong,
    // and they never added up to 100%.
    final total = secs
        .where((s) => !_isIncome(s.label) && !_isTransfer(s.label))
        .fold(0.0, (s, x) => s + x.net.abs());
    final prevMk = _prevMonthKey;
    final prev =
        prevMk != null ? _netByLabelFor(prevMk) : const <String, double>{};
    double changePct(_SecAgg s) {
      final p = prev[s.label];
      if (p == null || p == 0) return s.net == 0 ? 0 : double.infinity;
      return ((s.net - p) / p.abs()) * 100;
    }

    final sorted = [...secs];
    if (_catSort == 2) {
      sorted.sort((a, b) {
        final ca = changePct(a).abs(), cb = changePct(b).abs();
        return (cb.isFinite ? cb : 1e9).compareTo(ca.isFinite ? ca : 1e9);
      });
    } else {
      sorted.sort((a, b) => b.net.abs().compareTo(a.net.abs()));
    }

    String valueOf(_SecAgg s) {
      if (_catSort == 1) {
        // Income and transfers are not part of spending, so a "share of
        // spending" for them is not a small number — it is a meaningless one.
        // Salary against a spending total reads as 214%.
        if (_isIncome(s.label) || _isTransfer(s.label)) return '—';
        final pct = total > 0 ? s.net.abs() / total * 100 : 0;
        return '${pct.toStringAsFixed(0)}%';
      }
      if (_catSort == 2) {
        final c = changePct(s);
        if (!c.isFinite) return tr('nauja');
        return '${c > 0 ? '+' : ''}${c.toStringAsFixed(0)}%';
      }
      return _eur(s.net, signed: true);
    }

    Color colorOf(_SecAgg s) {
      if (_catSort == 0) return s.net >= 0 ? _good : _ink;
      if (_catSort == 2) {
        final c = changePct(s);
        if (!c.isFinite) return _purple;
        // For SPENDING sections, spending more is up (red), less is down (green).
        final expense = !_isIncome(s.label) && !_isTransfer(s.label);
        if (!expense || c == 0) return _ink;
        return c > 0 ? const Color(0xFFD9534F) : _good;
      }
      return _ink;
    }

    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 4, 16, 0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(4, 0, 4, 10),
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(tr('Rūšiuoti pagal'),
                  style: TextStyle(
                      fontSize: 13,
                      color: _muted,
                      fontWeight: FontWeight.w600)),
              const SizedBox(height: 8),
              Row(children: [
                _catSortToggle(0, tr('Suma')),
                _catSortToggle(1, tr('Procentai')),
                _catSortToggle(2, tr('Pokytis')),
              ]),
            ]),
          ),
          AppCard(
            color: _card,
            border: _hair,
            child: Column(children: [
              for (var i = 0; i < sorted.length; i++) ...[
                InkWell(
                  onTap: () => Navigator.of(context).push(MaterialPageRoute(
                    builder: (_) => _CategoryDetailScreen(
                        section: sorted[i],
                        rows: _rows
                            .where((t) => t['sec'] == sorted[i].label)
                            .toList(),
                        monthName: widget.monthGen),
                  )),
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 14, vertical: 13),
                    child: Row(children: [
                      CategoryIcon(
                          icon: sorted[i].icon,
                          color: sorted[i].color,
                          size: 40),
                      const SizedBox(width: 13),
                      Expanded(
                          child: Text(tr(sorted[i].label),
                              style: TextStyle(
                                  fontSize: 16,
                                  fontWeight: FontWeight.w600,
                                  color: _ink))),
                      Text(valueOf(sorted[i]),
                          style: TextStyle(
                              fontSize: 16,
                              fontWeight: FontWeight.w700,
                              color: colorOf(sorted[i]),
                              fontFeatures: const [
                                FontFeature.tabularFigures()
                              ])),
                      const SizedBox(width: 4),
                      Icon(Icons.chevron_right_rounded,
                          size: 20, color: _faint),
                    ]),
                  ),
                ),
                if (i != sorted.length - 1) const RowDivider(indent: 66),
              ],
            ]),
          ),
        ],
      ),
    );
  }

  // ── helpers ──
  Map<String, double> _sectionSpend(String month) {
    final m = <String, double>{};
    for (final t in widget.all) {
      if (!_dOf(t).startsWith(month)) continue;
      final label = _secOf(t);
      if (_isIncome(label) || _isTransfer(label)) continue;
      final a = _aOf(t).toDouble();
      if (a < 0) m[label] = (m[label] ?? 0) - a;
    }
    return m;
  }

  Color _labelColor(String label) {
    final t =
        widget.all.firstWhere((t) => t['sec'] == label, orElse: () => const {});
    return _secColor[t['secc']] ?? _muted;
  }

  IconData _labelIcon(String label) =>
      _secIcon[_secToIcon[label]] ?? Icons.circle;

  int get _daysInMonth {
    final y = _yInt(widget.month);
    final mo = _moInt(widget.month);
    return DateTime(y, mo + 1, 0).day;
  }

  Widget _sectionLabel(String s) => Padding(
        padding: const EdgeInsets.fromLTRB(20, 22, 20, 8),
        child: Text(tr(s),
            style: TextStyle(
                fontSize: 22,
                fontWeight: FontWeight.w800,
                color: _ink,
                letterSpacing: -0.4)),
      );

  // ── CALENDAR heatmap ──
  Widget _calendar() {
    final y = _yInt(widget.month);
    final mo = _moInt(widget.month);
    final lead = DateTime(y, mo, 1).weekday - 1; // Mon=0
    final net = <int, double>{};
    final spend =
        <int, double>{}; // expenses only — drives the "heavy day" amber
    final daySec = <int, Map<String, double>>{};
    // Transfers stay OUT of `net`: the app cannot tell a person paying you from
    // money you moved between your own accounts, so counting them would invent
    // income. But dropping them entirely left a day on which money genuinely
    // arrived looking completely EMPTY, while the category panel right above the
    // calendar showed the same movement as "Pervedimai +977 €". Collected
    // separately and drawn greyed, so the day reads as "something moved here"
    // without touching the day's spend/income figure.
    final xfer = <int, double>{};
    for (final t in _rows) {
      final label = _secOf(t);
      final d = _dayOf(t);
      if (_isTransfer(label)) {
        xfer[d] = (xfer[d] ?? 0) + _aOf(t).toDouble();
        continue;
      }
      final a = _aOf(t).toDouble();
      net[d] = (net[d] ?? 0) + a;
      if (!_isIncome(label) && a < 0) {
        spend[d] = (spend[d] ?? 0) + (-a);
        final sm = daySec.putIfAbsent(d, () => {});
        sm[_seccOf(t)] = (sm[_seccOf(t)] ?? 0) - a;
      }
    }
    Color? dom(int d) {
      final sm = daySec[d];
      if (sm == null || sm.isEmpty) return null;
      return _secColor[
          sm.entries.reduce((a, b) => a.value >= b.value ? a : b).key];
    }

    final wd = _wdShort;
    final cells = <Widget>[];
    for (var i = 0; i < lead; i++) {
      cells.add(const SizedBox());
    }
    for (var d = 1; d <= _daysInMonth; d++) {
      // Highlight a day amber only for heavy SPENDING — never for a payday or a
      // big own-account transfer (those used to trip the "heavy spend" alarm).
      final c = ((spend[d] ?? 0) > 500) ? _secColor['amber'] : dom(d);
      cells.add(_calCell(d, net[d], c, xfer[d]));
    }
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: _hair)),
      child: Column(
        children: [
          Row(children: [
            for (final w in wd)
              Expanded(
                  child: Center(
                      child: Text(w,
                          style: TextStyle(
                              fontSize: 12,
                              color: _muted,
                              fontWeight: FontWeight.w600))))
          ]),
          const SizedBox(height: 6),
          GridView.count(
            crossAxisCount: 7,
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            childAspectRatio: 0.82,
            children: cells,
          ),
        ],
      ),
    );
  }

  Widget _calCell(int d, double? n, Color? c, [double? x]) {
    return Container(
      margin: const EdgeInsets.all(2),
      decoration: BoxDecoration(
        color: c?.withValues(alpha: 0.10) ?? Colors.transparent,
        borderRadius: BorderRadius.circular(8),
        border:
            Border.all(color: c?.withValues(alpha: 0.55) ?? _hair, width: 1.1),
      ),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text('$d',
              style: TextStyle(
                  fontSize: 12, fontWeight: FontWeight.w700, color: _ink)),
          if (n != null)
            Text(_eur0(n),
                style: TextStyle(
                    fontSize: 9.5,
                    fontWeight: FontWeight.w600,
                    color: n >= 0 ? _good : _muted))
          else if (x != null)
            _calXfer(x),
        ],
      ),
    );
  }

  // ── BUDGETS ──
  Widget _budgets() {
    final b = widget.budgets;
    // Budgets are keyed by SECTION (`sec`), so match spending by section too —
    // keying by category here left every budget showing €0 spent (SB-M3).
    final spentBySec = <String, double>{};
    for (final t in _rows) {
      final a = _aOf(t).toDouble();
      if (a < 0) spentBySec[_secOf(t)] = (spentBySec[_secOf(t)] ?? 0) - a;
    }
    final cats = b.keys.toList();
    // No user budgets → don't show a budget section at all (it was showing fake
    // hardcoded example limits that confused people — "where did 880 € come from?").
    if (cats.isEmpty) return const SizedBox.shrink();
    final totalBudget = cats.fold(0.0, (s, c) => s + (b[c] as num).toDouble());
    final totalSpent = cats.fold(0.0, (s, c) => s + (spentBySec[c] ?? 0));
    final under = totalBudget - totalSpent;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _sectionLabel('Biudžetai'),
        Container(
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 12),
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(16),
            gradient: LinearGradient(
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
                colors: [_purpleDeep, _purple]),
          ),
          child: Text(
            // Honest scope: these are example limits covering only a few
            // categories, so never claim overall savings — state what was spent
            // in the tracked categories out of their (placeholder) limit.
            under >= 0
                ? '${tr('Sekamose kategorijose išleidai')} ${_eur0(totalSpent)} ${tr('iš')} ${_eur0(totalBudget)}.'
                : '${tr('Viršijai sekamų kategorijų limitą')} ${_eur0(-under)}.',
            style: const TextStyle(
                fontSize: 17,
                fontWeight: FontWeight.w800,
                color: Colors.white,
                height: 1.3),
          ),
        ),
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 0, 16, 6),
          child: AppCard(
            color: _card,
            border: _hair,
            padding: const EdgeInsets.all(15),
            child: Column(children: [
              Row(children: [
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(_eur0(totalSpent),
                      style: TextStyle(
                          fontSize: 21,
                          fontWeight: FontWeight.w800,
                          color: _ink)),
                  Text(tr('išleista'),
                      style: TextStyle(fontSize: 12.5, color: _muted)),
                ]),
                const Spacer(),
                Builder(builder: (ctx) {
                  // Same reason as the planning card's ring: scale with the
                  // amounts it sits between, or they swallow it.
                  final d =
                      MediaQuery.textScalerOf(ctx).scale(56).clamp(56.0, 94.0);
                  return SizedBox(
                    width: d,
                    height: d,
                    child: Stack(alignment: Alignment.center, children: [
                      CustomPaint(
                          size: Size(d, d),
                          painter: _RingProgressPainter(totalBudget > 0
                              ? (totalSpent / totalBudget).clamp(0.0, 1.0)
                              : 0.0)),
                      Text(
                          '${totalBudget > 0 ? (totalSpent / totalBudget * 100).round() : 0}%',
                          style: TextStyle(
                              fontSize: 13,
                              fontWeight: FontWeight.w800,
                              color: _ink)),
                    ]),
                  );
                }),
                const Spacer(),
                Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
                  Text(_eur0(totalBudget),
                      style: TextStyle(
                          fontSize: 21,
                          fontWeight: FontWeight.w800,
                          color: _ink)),
                  Text(tr('biudžetas*'),
                      style: TextStyle(fontSize: 12.5, color: _muted)),
                ]),
              ]),
              const SizedBox(height: 6),
              Align(
                  alignment: Alignment.centerRight,
                  child: Text(tr('* pavyzdiniai limitai'),
                      style: TextStyle(fontSize: 10.5, color: _faint))),
            ]),
          ),
        ),
        for (final c in cats)
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
            child: AppCard(
              color: _card,
              border: _hair,
              padding: const EdgeInsets.all(14),
              child:
                  _budgetBar(c, spentBySec[c] ?? 0, (b[c] as num).toDouble()),
            ),
          ),
        const SizedBox(height: 4),
      ],
    );
  }

  Widget _budgetBar(String cat, double spent, double limit) {
    final left = limit - spent;
    final over = left < 0;
    return Column(children: [
      Row(children: [
        Expanded(
            child: Text(tr(cat),
                style: TextStyle(
                    fontSize: 15.5, fontWeight: FontWeight.w700, color: _ink))),
        Text(_eur0(limit),
            style: TextStyle(
                fontSize: 16, fontWeight: FontWeight.w800, color: _ink)),
      ]),
      const SizedBox(height: 8),
      Row(children: [
        Text('${_eur(spent)} ${tr('išleista')}',
            style: TextStyle(fontSize: 12.5, color: _muted)),
        const Spacer(),
        Text(
            over
                ? '${_eur(-left)} ${tr('viršyta')}'
                : '${_eur(left)} ${tr('liko')}',
            style: TextStyle(
                fontSize: 12.5,
                fontWeight: FontWeight.w700,
                color: over ? DS.danger : _good)),
      ]),
      const SizedBox(height: 8),
      ClipRRect(
        borderRadius: BorderRadius.circular(5),
        child: LinearProgressIndicator(
            value: (spent / limit).clamp(0.0, 1.0),
            minHeight: 8,
            backgroundColor: _soft,
            valueColor: AlwaysStoppedAnimation(over ? DS.danger : _good)),
      ),
    ]);
  }

  // ── INSIGHTS (June vs May) ──
  Widget _insights() {
    final cur = _sectionSpend(widget.month);
    final prev = _sectionSpend(_prevMonth);
    final labels = cur.keys.toList()
      ..sort((a, b) => cur[b]!.compareTo(cur[a]!));
    final top = labels.take(3).toList();
    if (top.isEmpty) return const SizedBox.shrink();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _sectionLabel('Įžvalgos'),
        for (final l in top) _insightCard(l, prev[l] ?? 0, cur[l] ?? 0),
        const SizedBox(height: 4),
      ],
    );
  }

