                    children: [
                      TextSpan(
                          text:
                              '${tr('Kategorijai')} „${tr(label).split(',').first}" ${tr('išleidai')} '),
                      TextSpan(
                          text: _eur0(diff.abs()),
                          style: TextStyle(
                              fontWeight: FontWeight.w800, color: diffColor)),
                      TextSpan(
                          text:
                              ' ${more ? tr('daugiau') : tr('mažiau')} ${tr('nei praėjusį mėnesį.')}'),
                    ],
                  ),
                ),
              ),
            ]),
            const SizedBox(height: 14),
            Row(children: [
              Expanded(child: _insightBox(color, mayV, _prevMonthNom)),
              const SizedBox(width: 10),
