  // ── AVERAGE DAILY SPENDING ──
  int get _elapsedDays {
    final now = DateTime.now();
    final curCal = '${now.year}-${now.month.toString().padLeft(2, '0')}';
    // Current calendar month → days elapsed so far (today's day); any earlier
    // month is complete → full month. (Was latest-tx-day + 1, off by one.)
    if (widget.month == curCal) return now.day.clamp(1, _daysInMonth);
    return _daysInMonth;
  }

  Widget _avgDaily(List<_SecAgg> expenseSecs) {
    final days = _elapsedDays;
    final totalAvg = expenseSecs.fold(0.0, (s, x) => s - x.net) / days;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _sectionLabel('Vidutinės dienos išlaidos'),
        Container(
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
              color: _card,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: _hair)),
          child: Column(children: [
            Row(children: [
              Text(widget.monthNom,
                  style: TextStyle(
                      fontSize: 17, fontWeight: FontWeight.w800, color: _ink)),
              const Spacer(),
              Text('−${_eur(totalAvg)}',
                  style: TextStyle(
                      fontSize: 17, fontWeight: FontWeight.w800, color: _ink)),
            ]),
            const SizedBox(height: 12),
            for (final s in expenseSecs)
              Padding(
                padding: const EdgeInsets.only(bottom: 9),
                child: Row(children: [
                  CategoryIcon(icon: s.icon, color: s.color, size: 26),
                  const SizedBox(width: 10),
                  Expanded(
                      child: Text(tr(s.label),
                          style: TextStyle(fontSize: 14.5, color: _ink))),
                  Text('−${_eur((-s.net) / days)}',
                      style: TextStyle(
                          fontSize: 14.5,
                          fontWeight: FontWeight.w700,
                          color: _ink,
                          fontFeatures: const [FontFeature.tabularFigures()])),
                ]),
              ),
          ]),
        ),
      ],
    );
  }

  // ── MERCHANTS ──
  // ── RECURRING spent this month (collapsible) ──
  // Shows what recurring merchants actually COST this month — grouped by merchant
  // (no per-item "pending", which made no sense for a finished month). A charge
  // counts as recurring when its merchant matches one of the detected recurring
  // streams by normalized name. Collapsed by default; tap to expand.
  Widget _recurringSection() {
    final recNames = <String>{};
    for (final it in _recItems(widget.subs)) {
      final f = _fold((it['name'] as String?) ?? '');
      if (f.length >= 4) recNames.add(f);
    }
    if (recNames.isEmpty) return const SizedBox.shrink();
    final byMerch = <String, Map<String, dynamic>>{};
    for (final t in _rows) {
      if (_aOf(t) >= 0) continue;
      final rn = _fold((t['nm'] as String?) ?? '');
      if (rn.length < 4) continue;
      final isRec =
          recNames.any((n) => rn == n || rn.contains(n) || n.contains(rn));
      if (!isRec) continue;
      final k = t['mkey'] as String;
      final m = byMerch.putIfAbsent(
          k,
          () => {
                'nm': t['nm'],
                'a': 0.0,
                'ic': t['ic'],
                'col': t['col'],
                'row': t
              });
      m['a'] = (m['a'] as double) + _aOf(t).toDouble();
    }
    if (byMerch.isEmpty) return const SizedBox.shrink();
    final list = byMerch.values.toList()
      ..sort((a, b) => (a['a'] as double).compareTo(b['a'] as double));
    final total = list.fold(0.0, (s, m) => s + (m['a'] as double).abs());
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      _sectionLabel('Pasikartojantys'),
      Padding(
