  Widget _merchants() {
    // Group this month's spending by merchant (mkey), most spent first.
    final byMerch = <String, Map<String, dynamic>>{};
    for (final t in _rows) {
      if (_isIncome(_secOf(t)) || _isTransfer(_secOf(t)) || _aOf(t) >= 0) {
        continue;
      }
      final k = t['mkey'] as String;
      final m = byMerch.putIfAbsent(
          k,
          () => {
                'nm': t['nm'],
                'a': 0.0,
                'n': 0,
                'ic': t['ic'],
                'col': t['col'],
                'row': t
              });
      m['a'] = (m['a'] as double) + _aOf(t).toDouble();
      m['n'] = (m['n'] as int) + 1;
    }
    final list = byMerch.values.toList()
      ..sort((a, b) => (a['a'] as double).compareTo(b['a'] as double));
    final count = list.length;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _sectionLabel('Prekybininkai'),
        Container(
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 4),
          decoration: BoxDecoration(
              color: _card,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: _hair)),
          child: Column(children: [
            InkWell(
              borderRadius: BorderRadius.circular(16),
              onTap: () => setState(() => _merchantsOpen = !_merchantsOpen),
              child: Padding(
                padding:
                    const EdgeInsets.symmetric(horizontal: 16, vertical: 18),
                child: Row(children: [
                  Text('$count ${tr('prekybininkai')}',
                      style: TextStyle(
                          fontSize: 17,
                          fontWeight: FontWeight.w700,
                          color: _ink)),
                  const Spacer(),
                  AnimatedRotation(
                    turns: _merchantsOpen ? 0.5 : 0,
                    duration: const Duration(milliseconds: 180),
                    child:
                        Icon(Icons.keyboard_arrow_down_rounded, color: _purple),
                  ),
                ]),
              ),
            ),
            if (_merchantsOpen)
              for (var i = 0; i < list.length; i++) ...[
                const RowDivider(indent: 16),
                Padding(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 14, vertical: 11),
                  child: Row(children: [
                    CategoryIcon(
                        icon: _iconOf(list[i]['ic'] as String?),
                        color: _colOf(list[i]['col'] as String?),
                        size: 34,
                        circle: false,
                        merchant:
                            _logoOf(list[i]['row'] as Map<String, dynamic>),
                        domain: _domOf(list[i]['row'] as Map<String, dynamic>)),
                    const SizedBox(width: 12),
                    Expanded(
                        child: Text(_shortNm(list[i]['nm'] as String),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                fontSize: 15,
                                fontWeight: FontWeight.w600,
                                color: _ink))),
                    Text('${list[i]['n']}×',
                        style: TextStyle(fontSize: 12.5, color: _faint)),
                    const SizedBox(width: 10),
                    Text(_eur((list[i]['a'] as double), signed: true),
                        style: TextStyle(
                            fontSize: 15,
                            fontWeight: FontWeight.w700,
                            color: _ink,
                            fontFeatures: const [
                              FontFeature.tabularFigures()
                            ])),
                  ]),
                ),
              ],
          ]),
        ),
      ],
    );
  }

  // ── LARGEST EXPENSES ──
  Widget _largest() {
    final exp = _rows.where((t) => _aOf(t) < 0).toList()
      ..sort((a, b) => _aOf(a).compareTo(_aOf(b)));
    final top = exp.take(5).toList();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
