                  child: Row(children: [
                    CategoryIcon(
                        icon: _iconOf(top[i]['ic'] as String?),
                        color: _colOf(top[i]['col'] as String?),
                        size: 40,
                        circle: false,
                        merchant: _logoOf(top[i]),
                        domain: _domOf(top[i])),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
