                            Text(_shortNm(top[i]['nm'] as String),
                                style: TextStyle(
                                    fontSize: 15.5,
                                    fontWeight: FontWeight.w700,
                                    color: _ink)),
                            const SizedBox(height: 2),
                            Text(
                                '${_mdOf(top[i])}${_hm(top[i]['ts']) != null ? ', ${_hm(top[i]['ts'])}' : ''}; ${tr((top[i]['cat'] ?? '').toString())}',
