// CATEGORY DETAIL — colored section screen with subcategory breakdown
// ══════════════════════════════════════════════════════════════════════════════
class _CategoryDetailScreen extends StatelessWidget {
  const _CategoryDetailScreen(
      {required this.section, required this.rows, required this.monthName});
  final _SecAgg section;
  final List<Map<String, dynamic>> rows;
  final String monthName;

  @override
  Widget build(BuildContext context) {
    // group by subcategory (cat)
    final subs = <String, List<dynamic>>{}; // cat -> [sum, iconKey]
    for (final t in rows) {
      final c = t['cat'] as String;
      final e = subs.putIfAbsent(c, () => [0.0, t['ic']]);
      e[0] = (e[0] as double) + _aOf(t).toDouble();
    }
    final subList = subs.entries.toList()
      ..sort((a, b) => (a.value[0] as double).compareTo(b.value[0] as double));
    final neg = rows
        .where((t) => _aOf(t) < 0)
        .fold(0.0, (s, t) => s + _aOf(t).toDouble());
    final pos = rows
        .where((t) => _aOf(t) > 0)
        .fold(0.0, (s, t) => s + _aOf(t).toDouble());

    return Scaffold(
      backgroundColor: _bg,
      body: Column(
        children: [
          // coloured header
          Container(
            color: section.color,
            child: SafeArea(
              bottom: false,
              child: Column(
                children: [
                  Padding(
                    padding: const EdgeInsets.fromLTRB(6, 6, 14, 0),
                    child: Row(children: [
                      IconButton(
                          onPressed: () => Navigator.pop(context),
                          icon: const Icon(Icons.arrow_back_ios_new_rounded,
                              size: 20, color: Colors.white)),
                      Expanded(
                          child: Text(section.label,
                              style: const TextStyle(
                                  fontSize: 20,
                                  fontWeight: FontWeight.w700,
                                  color: Colors.white))),
                      const Icon(Icons.search_rounded,
                          size: 24, color: Colors.white),
                    ]),
                  ),
                  const SizedBox(height: 8),
                  Icon(section.icon, size: 64, color: Colors.white),
                  const SizedBox(height: 10),
                  Text(section.label,
                      style: const TextStyle(
                          fontSize: 26,
                          fontWeight: FontWeight.w800,
                          color: Colors.white)),
                  const SizedBox(height: 2),
                  Text(_eur(section.net, signed: true),
                      style: const TextStyle(
                          fontSize: 20,
                          fontWeight: FontWeight.w700,
                          color: Colors.white)),
                  const SizedBox(height: 20),
                ],
              ),
            ),
          ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 30),
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(4, 0, 4, 8),
                  child: Row(children: [
                    Text(tr('Kategorija'),
                        style: TextStyle(fontSize: 13, color: _muted)),
                    const Spacer(),
                    Text(tr('Suma'),
                        style: TextStyle(fontSize: 13, color: _muted))
                  ]),
                ),
                AppCard(
                  color: _card,
                  border: _hair,
                  child: Column(children: [
                    for (var i = 0; i < subList.length; i++) ...[
                      InkWell(
                        onTap: () => Navigator.of(context).push(MaterialPageRoute(
                          builder: (_) => _SubcategoryDetailScreen(
                            label: tr(subList[i].key),
                            color: section.color,
                            icon: _iconOf(subList[i].value[1] as String?),
                            rows: rows
                                .where((t) => t['cat'] == subList[i].key)
                                .toList(),
                          ),
                        )),
                        child: Padding(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 14, vertical: 13),
                          child: Row(children: [
                            CategoryIcon(
                                icon: _iconOf(subList[i].value[1] as String?),
                                color: section.color,
                                size: 40),
                            const SizedBox(width: 13),
                            Expanded(
                                child: Text(tr(subList[i].key),
                                    style: TextStyle(
                                        fontSize: 16,
                                        fontWeight: FontWeight.w600,
                                        color: _ink))),
                            Text(
                                _eur(subList[i].value[0] as double,
                                    signed: true),
                                style: TextStyle(
                                    fontSize: 16,
                                    fontWeight: FontWeight.w700,
                                    color: (subList[i].value[0] as double) >= 0
                                        ? _good
                                        : _ink,
                                    fontFeatures: const [
                                      FontFeature.tabularFigures()
                                    ])),
                            const SizedBox(width: 4),
                            Icon(Icons.chevron_right_rounded,
                                size: 18, color: _faint),
                          ]),
                        ),
                      ),
                      if (i != subList.length - 1) const RowDivider(indent: 66),
                    ],
                  ]),
