/// "21 rugpjūčio" / "Aug 21" — a short, locale-aware date for a line-item row.
String _shortDate(String iso) {
  final d = DateTime.tryParse(iso);
  if (d == null) return iso;
  final mon = _monGen[d.month - 1];
  return _enUi ? '${mon.substring(0, 3)} ${d.day}' : '${d.day} ${mon.toLowerCase()}';
}

/// The actual line-item list behind one subcategory's total — the drill-down
/// that used to be missing. _CategoryDetailScreen showed subcategory SUMS
/// with no way to see which real charges (including individual receipt-split
/// items, which each carry their own 'cat') made up that number; a person
/// wanting to know exactly where a euro went inside e.g. "Namų prekės →
/// Kvapai" had nowhere to look. `rows` is already filtered to this one
/// subcategory by the caller — every row here genuinely belongs to it.
class _SubcategoryDetailScreen extends StatelessWidget {
  const _SubcategoryDetailScreen(
      {required this.label,
      required this.color,
      required this.icon,
      required this.rows});
  final String label;
  final Color color;
  final IconData icon;
  final List<Map<String, dynamic>> rows;

  @override
  Widget build(BuildContext context) {
    final sorted = [...rows]..sort((a, b) => _dOf(b).compareTo(_dOf(a)));
    final total = rows.fold(0.0, (s, t) => s + _aOf(t).toDouble());
    return Scaffold(
      backgroundColor: _bg,
      appBar: AppBar(
        backgroundColor: _bg,
        surfaceTintColor: _bg,
        elevation: 0,
        title: Text(label, style: TextStyle(color: _ink, fontWeight: FontWeight.w700)),
      ),
      body: SafeArea(
        top: false,
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 8, 16, 30),
          children: [
            Row(children: [
              CategoryIcon(icon: icon, color: color, size: 44),
              const SizedBox(width: 12),
              Expanded(
                child: Text(
                    _enUi
                        ? '${sorted.length} ${sorted.length == 1 ? 'transaction' : 'transactions'}'
                        : '${sorted.length} ${sorted.length == 1 ? 'operacija' : 'operacijos'}',
                    style: TextStyle(fontSize: 14, color: _muted)),
              ),
              Text(_eur(total, signed: true),
                  style: TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.w800,
                      color: total >= 0 ? _good : _ink,
                      fontFeatures: const [FontFeature.tabularFigures()])),
            ]),
            const SizedBox(height: 14),
            AppCard(
              color: _card,
              border: _hair,
              child: Column(children: [
                for (var i = 0; i < sorted.length; i++) ...[
                  Padding(
                    padding:
                        const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
                    child: Row(children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(_txDisplayName(sorted[i]),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: TextStyle(
                                    fontSize: 15,
                                    fontWeight: FontWeight.w600,
                                    color: _ink)),
                            const SizedBox(height: 2),
                            Text(_shortDate(_dOf(sorted[i])),
                                style: TextStyle(fontSize: 12.5, color: _muted)),
                          ],
                        ),
                      ),
                      const SizedBox(width: 10),
                      Text(_eurTx(sorted[i], signed: true),
                          style: TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.w700,
                              color: _aOf(sorted[i]) >= 0 ? _good : _ink,
                              fontFeatures: const [
                                FontFeature.tabularFigures()
                              ])),
                    ]),
                  ),
                  if (i != sorted.length - 1) const RowDivider(indent: 14),
                ],
              ]),
            ),
          ],
        ),
      ),
    );
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// OVERVIEW TAB — analytics for the selected period (defaults to current month)
// ══════════════════════════════════════════════════════════════════════════════
class _OverviewTab extends StatefulWidget {
  const _OverviewTab(
      {required this.all,
      required this.balance,
      required this.budgets,
      this.demo = false});
  final List<Map<String, dynamic>> all;
  final Map<String, dynamic> balance;
  final Map<String, dynamic> budgets;

  /// Running inside the onboarding walkthrough: publish the savings card so the
  /// director can open it, and let it be found by key.
  final bool demo;
  @override
  State<_OverviewTab> createState() => _OverviewTabState();
}

class _OverviewTabState extends State<_OverviewTab> {
  bool _merchantsOpen = false;
  String? _selKey; // chosen month (null = latest / "Šis mėnuo")
  bool _hide = false; // eye toggle → mask the headline amounts
  final _filter = _TxFilter();

  Future<void> _openFilter() async {
    final avail = _rows.map((t) => _secOf(t)).toSet().toList()..sort();
    final res = await _showFilterSheet(context, _filter, avail);
    if (res == null) return;
    setState(() {
      _filter
        ..type = res.type
        ..secs = res.secs;
    });
  }

  List<String> get _monthKeys {
    final s = widget.all.map((t) => _ymOf(t)).toSet().toList()..sort();
    return s; // ascending
  }

  String get _curKey {
    final keys = _monthKeys;
    if (_selKey != null && keys.contains(_selKey)) return _selKey!;
    if (keys.isNotEmpty) return keys.last;
    final n = DateTime.now();
    return '${n.year}-${n.month.toString().padLeft(2, '0')}';
  }

  String get _monthLabel {
    final keys = _monthKeys;
    if (_selKey == null || keys.isEmpty || _selKey == keys.last)
      return tr('Šis mėnuo');
    return _monNom[_moInt(_selKey!) - 1];
  }

  void _pickMonth() {
    final keys = _monthKeys.reversed.toList(); // newest first
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: _card,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(22))),
      builder: (ctx) => SafeArea(
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          const SizedBox(height: 12),
          Container(
              width: 40,
              height: 4,
              decoration: BoxDecoration(
                  color: _faint, borderRadius: BorderRadius.circular(2))),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 14, 20, 6),
            child: Align(
                alignment: Alignment.centerLeft,
                child: Text(tr('Laikotarpis'),
                    style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.w800,
                        color: _ink))),
          ),
          Flexible(
            child: ListView(shrinkWrap: true, children: [
              for (final k in keys)
                InkWell(
                  onTap: () {
                    setState(() => _selKey = k);
                    Navigator.pop(ctx);
                  },
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 20, vertical: 14),
                    child: Row(children: [
                      Expanded(
                        child: Text(
                          k == _monthKeys.last
                              ? tr('Šis mėnuo')
                              : '${_monNom[_moInt(k) - 1]} ${k.substring(0, 4)}',
                          style: TextStyle(
                              fontSize: 16,
                              fontWeight: FontWeight.w600,
                              color: _ink),
                        ),
                      ),
                      if (k == _curKey)
                        Icon(Icons.check_rounded, size: 22, color: _purple),
                    ]),
                  ),
                ),
            ]),
          ),
          const SizedBox(height: 10),
        ]),
      ),
    );
  }

  int get _curMon => _moInt(_curKey);
  List<Map<String, dynamic>> _rowsOf(String mk) =>
      widget.all.where((t) => _dOf(t).startsWith(mk)).toList();
  List<Map<String, dynamic>> get _rows => _rowsOf(_curKey);

  bool _isIncome(String l) => l == 'Pajamos';
  bool _isTransfer(String l) => l == 'Pervedimai';

  List<_SecAgg> _sections(List<Map<String, dynamic>> rows) {
    final m = <String, _SecAgg>{};
    for (final t in rows) {
      final a = m.putIfAbsent(_secOf(t), () => _SecAgg(_secOf(t), _seccOf(t)));
      a.net += _aOf(t).toDouble();
    }
    return m.values.toList()
      ..sort((x, y) => y.net.abs().compareTo(x.net.abs()));
  }

  // Canonical rule (shared with the dashboard + review) so every Overview figure
  // matches: transfers/exchange excluded, refunds net spending down, and net =
  // income − expenses (never the raw sum that double-counts transfers).
  double _spentOf(List<Map<String, dynamic>> rows) => _sumExpenses(rows);
  double _earnedOf(List<Map<String, dynamic>> rows) => _sumIncome(rows);
  double _netOf(List<Map<String, dynamic>> rows) =>
      _sumIncome(rows) - _sumExpenses(rows);
  // savings rate = share of income you didn't spend. Uses classified income
  // (salary incl. currency-converted salary + refunds), NOT all inflows —
  // account top-ups / transfers between your own accounts are not income and
  // would otherwise distort the rate.
  /// The savings card's own tap handler, shared with the demo director so the
  /// walkthrough opens exactly what a finger would.
  void _openSavings() => Navigator.of(context).push(MaterialPageRoute(
        builder: (_) => _SavingsRateScreen(
            monthKeys: _monthKeys,
            savingsOf: _savingsOf,
            earnedOf: _earnedOf,
            rowsOf: _rowsOf,
            initialKey: _curKey,
            all: widget.all),
      ));

  // 2026-08-15: was `.clamp(0, 100)` — a month you overspent rounded to a
  // flat "0%", indistinguishable from breaking even. 2026-08-16: re-added a
  // ±100 clamp (not 0–100) after a near-zero-income month produced a
  // -2275% that blew out the whole 6-month chart's scale — past ±100 the
  // sign is already the whole story. See _savingsPctFor's own note (Home's
  // equivalent).
  int _savingsOf(List<Map<String, dynamic>> rows) {
    final earned = _earnedOf(rows);
    final spent = _spentOf(rows);
    return earned > 0
        ? ((earned - spent) / earned * 100).round().clamp(-100, 100)
        : 0;
  }

  // Consecutive COMPLETED months (excluding the current, possibly-partial one)
  // where you actually saved (rate > 0). Unfiltered — the streak reflects your
  // saving history, not the on-screen filter, and a fresh month with no income
  // yet shouldn't reset it.
  int get _savingStreak => _streakOf(_monthKeys, _rowsOf, _savingsOf);

  @override
  Widget build(BuildContext context) {
    // Hand the demo director the card's own handler; it is rebuilt with this
    // State's context, so it can never go stale on it.
    if (widget.demo) _demoOpenSavings = _openSavings;
    // No transactions at all (a freshly-connected bank with no activity yet):
    // the donuts, calendar and category list would render as empty/zero shells.
    // Show a single friendly empty state instead of a screen of blank cards (E1).
    if (widget.all.isEmpty) {
      return SafeArea(
        bottom: false,
        child: ListView(
          padding: const EdgeInsets.only(bottom: 28),
          children: [_header(), _overviewEmpty()],
        ),
      );
    }
    final rows = _filter.apply(_rows);
    final secs = _sections(rows);
    final expenseSecs = secs
        .where((s) => !_isIncome(s.label) && !_isTransfer(s.label) && s.net < 0)
        .toList();
    final spent = _spentOf(rows);
    final earned = _earnedOf(rows);
    // "Gauta" = all inflows (income + incoming transfers); display-only, does not
    // touch net/savings which stay on canonical income (`earned`).
    final received = _sumReceived(rows);
    final net = _netOf(rows);
    final savings = _savingsOf(rows);
    // No income that month → a savings rate is undefined, so show "—" not "0 %".
    final savStr = earned > 0 ? '$savings %' : '—';
    final prevKey = prevMonthKey(_monthKeys, _curKey);
    final prevRows = prevKey != null
        ? _filter.apply(_rowsOf(prevKey))
        : <Map<String, dynamic>>[];
    final prevStr = _earnedOf(prevRows) > 0 ? '${_savingsOf(prevRows)} %' : '—';

    return SafeArea(
      bottom: false,
      child: ListView(
        padding: const EdgeInsets.only(bottom: 28),
        children: [
          _header(),
          _filters(),
          _donuts(spent, earned, received, expenseSecs),
          _totalCard(net),
          _savingsCard(savStr, prevStr, _savingStreak),
          _categoryList(secs),
          _analyticsLabel(),
          _calendar(),
          _merchants(),
          _last6(),
          _avgDaily(expenseSecs),
        ],
      ),
    );
  }

