  // ── calendar ──
  Widget _calendar() {
    final y = int.parse(_curKey.substring(0, 4));
    final lead = DateTime(y, _curMon, 1).weekday - 1;
    final daysIn = DateTime(y, _curMon + 1, 0).day;
    final net = <int, double>{};
    final spend =
        <int, double>{}; // expenses only — drives the "heavy day" amber
    final daySec = <int, Map<String, double>>{};
    // Transfers stay OUT of `net`: the app cannot tell a person paying you from
    // money you moved between your own accounts, so counting them would invent
    // income. But dropping them entirely left a day on which money genuinely
    // arrived looking completely EMPTY, while the category panel right above the
    // calendar showed the same movement as "Pervedimai +977 €". Collected
    // separately and drawn greyed, so the day reads as "something moved here"
    // without touching the day's spend/income figure.
    final xfer = <int, double>{};
    for (final t in _rows) {
      final label = _secOf(t);
      final d = _dayOf(t);
      if (_isTransfer(label)) {
        xfer[d] = (xfer[d] ?? 0) + _aOf(t).toDouble();
        continue;
      }
      final a = _aOf(t).toDouble();
      net[d] = (net[d] ?? 0) + a;
      if (!_isIncome(label) && a < 0) {
        spend[d] = (spend[d] ?? 0) + (-a);
        (daySec.putIfAbsent(d, () => {}))[_seccOf(t)] =
            ((daySec[d]![_seccOf(t)]) ?? 0) - a;
      }
    }
    Color? dom(int d) {
      final sm = daySec[d];
      if (sm == null || sm.isEmpty) return null;
      return _secColor[
          sm.entries.reduce((a, b) => a.value >= b.value ? a : b).key];
    }

    final wd = _wdShort;
    final cells = <Widget>[];
    for (var i = 0; i < lead; i++) {
      cells.add(const SizedBox());
    }
    for (var d = 1; d <= daysIn; d++) {
      final n = net[d];
      final c = ((spend[d] ?? 0) > 500) ? _secColor['amber'] : dom(d);
      cells.add(Container(
        margin: const EdgeInsets.all(2),
        decoration: BoxDecoration(
          color: c?.withValues(alpha: 0.10) ?? Colors.transparent,
          borderRadius: BorderRadius.circular(8),
          border: Border.all(
              color: c?.withValues(alpha: 0.55) ?? _hair, width: 1.1),
        ),
        child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
          Text('$d',
              style: TextStyle(
                  fontSize: 12, fontWeight: FontWeight.w700, color: _ink)),
          if (n != null)
            Text(_eur0(n),
                style: TextStyle(
                    fontSize: 9.5,
                    fontWeight: FontWeight.w600,
                    color: n >= 0 ? _good : _muted))
          else if (xfer[d] != null)
            _calXfer(xfer[d]!),
        ]),
      ));
    }
    return Container(
      margin: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: _hair)),
      child: Column(children: [
        Row(children: [
          for (final w in wd)
            Expanded(
                child: Center(
                    child: Text(w,
                        style: TextStyle(
                            fontSize: 12,
                            color: _muted,
                            fontWeight: FontWeight.w600))))
        ]),
        const SizedBox(height: 6),
        GridView.count(
            crossAxisCount: 7,
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            childAspectRatio: 0.82,
            children: cells),
      ]),
    );
  }

  // ── merchants ──
  Widget _merchants() {
    final m = <String, List<dynamic>>{}; // mkey -> [name, sum, count]
    for (final t in _rows) {
      // merchants = places you spent; skip income + internal transfers
      if (_isIncome(_secOf(t)) || _isTransfer(_secOf(t)) || _aOf(t) >= 0)
        continue;
      final k = t['mkey'] as String;
      final e = m.putIfAbsent(k, () => [t['nm'], 0.0, 0]);
      e[1] = (e[1] as double) + _aOf(t).toDouble();
      e[2] = (e[2] as int) + 1;
    }
    final list = m.values.toList()
      ..sort((a, b) =>
          (a[1] as double).abs().compareTo((b[1] as double).abs()) * -1);
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Padding(
            padding: const EdgeInsets.only(left: 4, bottom: 8),
            child: Text(tr('Prekybininkai'),
                style: TextStyle(fontSize: 13.5, color: _muted))),
        Container(
          decoration: BoxDecoration(
              color: _card,
              borderRadius: BorderRadius.circular(14),
              border: Border.all(color: _hair)),
          child: Column(children: [
            InkWell(
              onTap: () => setState(() => _merchantsOpen = !_merchantsOpen),
              child: Padding(
                padding:
                    const EdgeInsets.symmetric(horizontal: 16, vertical: 16),
                child: Row(children: [
                  Text('${list.length} ${tr('prekybininkai')}',
                      style: TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.w700,
                          color: _ink)),
                  const Spacer(),
                  Icon(
                      _merchantsOpen
                          ? Icons.keyboard_arrow_up_rounded
                          : Icons.keyboard_arrow_down_rounded,
                      color: _purple),
                ]),
              ),
            ),
            if (_merchantsOpen)
              for (final e in list) ...[
                Divider(height: 1, thickness: 1, color: _hair),
                Padding(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 16, vertical: 13),
                  child: Row(children: [
                    if ((e[2] as int) > 1) ...[
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 6, vertical: 2),
                        decoration: BoxDecoration(
                            color: _purple,
                            borderRadius: BorderRadius.circular(6)),
                        child: Text('${e[2]}×',
                            style: const TextStyle(
                                fontSize: 11,
                                fontWeight: FontWeight.w800,
                                color: Colors.white)),
                      ),
                      const SizedBox(width: 10),
                    ],
                    Expanded(
                        child: Text(_shortNm(e[0] as String),
                            style: TextStyle(
                                fontSize: 15.5,
                                fontWeight: FontWeight.w600,
                                color: _ink))),
                    Text(_eur(e[1] as double, signed: true),
                        style: TextStyle(
                            fontSize: 15.5,
                            fontWeight: FontWeight.w700,
                            color: _ink,
                            fontFeatures: const [
                              FontFeature.tabularFigures()
                            ])),
                  ]),
                ),
              ],
          ]),
        ),
      ]),
    );
  }

  // ── last 6 months (income up / spending down) ──
  Widget _last6() {
    final keys = _monthKeys.length > 6
        ? _monthKeys.sublist(_monthKeys.length - 6)
        : _monthKeys;
    final inc = <double>[], spd = <double>[];
    for (final k in keys) {
      final r = _rowsOf(k);
      inc.add(_earnedOf(r));
      spd.add(_spentOf(r));
    }
    final total = keys.fold(0.0, (s, k) => s + _netOf(_rowsOf(k)));
    final maxUp = (inc.isEmpty ? 1.0 : inc.reduce((a, b) => a > b ? a : b))
        .clamp(1.0, double.infinity);
    final maxDn = (spd.isEmpty ? 1.0 : spd.reduce((a, b) => a > b ? a : b))
        .clamp(1.0, double.infinity);
    const upH = 150.0, dnH = 90.0;
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(4, 0, 4, 10),
          child: Row(children: [
            Text(tr('Paskutiniai 6 mėn.'),
                style: TextStyle(
                    fontSize: 14.5,
                    color: _muted,
                    fontWeight: FontWeight.w500)),
            const Spacer(),
            Text(_eur(total, signed: true),
                style: TextStyle(
                    fontSize: 15,
                    fontWeight: FontWeight.w700,
                    color: total >= 0 ? _good : _ink)),
          ]),
        ),
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 10),
          decoration: BoxDecoration(
              color: _card,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: _hair)),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              for (var i = 0; i < keys.length; i++)
                Expanded(
                  child: Column(children: [
                    Text(inc[i] >= 1 ? '+${_kEur(inc[i])}' : '',
                        style: TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.w700,
                            color: _muted)),
                    // The grid line sits INSIDE each column rather than being
                    // painted behind the row: the columns already own these
                    // heights, so the line lands exactly on the scale's edge
                    // instead of on a guess about the layout. Column by column
                    // they read as one continuous line.
                    //
                    // Without a scale the bars said nothing: +4,7K and +2,0K
                    // looked much the same, because the tallest bar always fills
                    // the box whatever it holds. These two lines are the scale,
                    // and the figure at the end of each says what they are worth.
                    SizedBox(
                      height: upH,
                      child: Stack(children: [
                        Positioned(
                            top: 0,
                            left: 0,
                            right: 0,
                            child: Container(height: 1, color: _hair)),
                        if (i == keys.length - 1 && maxUp >= 1)
                          Positioned(
                            top: 2,
                            right: 0,
                            child: Text('+${_kEur(maxUp)}',
                                style: TextStyle(
                                    fontSize: 8.5,
                                    fontWeight: FontWeight.w700,
                                    color: _faint)),
                          ),
                        Align(
                          alignment: Alignment.bottomCenter,
                          child: Container(
                              width: 16,
                              height: (inc[i] / maxUp * upH).clamp(0.0, upH),
                              decoration: BoxDecoration(
                                  color: _secColor['green'],
                                  borderRadius: const BorderRadius.vertical(
                                      top: Radius.circular(8)))),
                        ),
                      ]),
                    ),
                    Container(height: 1, color: _hair),
                    SizedBox(
                      height: dnH,
                      child: Stack(children: [
                        Positioned(
                            bottom: 0,
                            left: 0,
                            right: 0,
                            child: Container(height: 1, color: _hair)),
                        if (i == keys.length - 1 && maxDn >= 1)
                          Positioned(
                            bottom: 2,
                            right: 0,
                            child: Text('−${_kEur(maxDn)}',
                                style: TextStyle(
                                    fontSize: 8.5,
                                    fontWeight: FontWeight.w700,
                                    color: _faint)),
                          ),
                        Align(
                          alignment: Alignment.topCenter,
                          child: Container(
                              width: 16,
                              height: (spd[i] / maxDn * dnH).clamp(0.0, dnH),
                              decoration: BoxDecoration(
                                  color: _secColor['red'],
                                  borderRadius: const BorderRadius.vertical(
                                      bottom: Radius.circular(8)))),
                        ),
                      ]),
                    ),
                    Text(spd[i] >= 1 ? '−${_kEur(spd[i])}' : '',
                        style: TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.w600,
                            color: _muted)),
                    const SizedBox(height: 4),
                    Text(_monNom[_moInt(keys[i]) - 1].substring(0, 3),
                        style: TextStyle(
                            fontSize: 11.5,
                            color: _muted,
                            fontWeight: FontWeight.w500)),
                  ]),
                ),
            ],
          ),
        ),
      ]),
    );
  }

  // ── average daily spending (current month → per days ELAPSED, not full month) ──
  Widget _avgDaily(List<_SecAgg> exp) {
    final y = int.parse(_curKey.substring(0, 4));
    final daysInMonth = DateTime(y, _curMon + 1, 0).day;
    final now = DateTime.now();
    final curCal = '${now.year}-${now.month.toString().padLeft(2, '0')}';
    // Current month → days elapsed so far; earlier month → full month.
    final days =
        (_curKey == curCal ? now.day : daysInMonth).clamp(1, daysInMonth);
    final totalAvg = exp.fold(0.0, (s, x) => s - x.net) / days;
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Padding(
            padding: const EdgeInsets.only(left: 4, bottom: 8),
            child: Text(tr('Vidutinės dienos išlaidos'),
                style: TextStyle(fontSize: 13.5, color: _muted))),
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
              color: _card,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: _hair)),
          child: Column(children: [
            Row(children: [
              Text(tr('Šį mėnesį'),
                  style: TextStyle(
                      fontSize: 17, fontWeight: FontWeight.w800, color: _ink)),
              const Spacer(),
              Text('−${_eur(totalAvg)}',
                  style: TextStyle(
                      fontSize: 17, fontWeight: FontWeight.w800, color: _ink)),
            ]),
            const SizedBox(height: 12),
            for (final s in exp)
              Padding(
                padding: const EdgeInsets.only(bottom: 9),
                child: Row(children: [
                  CategoryIcon(icon: s.icon, color: s.color, size: 26),
                  const SizedBox(width: 10),
                  Expanded(
                      child: Text(tr(s.label),
                          style: TextStyle(fontSize: 14.5, color: _ink))),
                  Text('−${_eur((-s.net) / days)}',
                      style: TextStyle(
                          fontSize: 14.5,
                          fontWeight: FontWeight.w700,
                          color: _ink,
                          fontFeatures: const [FontFeature.tabularFigures()])),
                ]),
              ),
          ]),
        ),
      ]),
    );
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// SAVINGS RATE — detail screen
// ══════════════════════════════════════════════════════════════════════════════
class _SavingsRateScreen extends StatefulWidget {
  const _SavingsRateScreen(
      {required this.monthKeys,
      required this.savingsOf,
      required this.earnedOf,
      required this.rowsOf,
      required this.initialKey,
      required this.all});
  final List<String> monthKeys;
  final int Function(List<Map<String, dynamic>>) savingsOf;
  final double Function(List<Map<String, dynamic>>) earnedOf;
  final List<Map<String, dynamic>> Function(String) rowsOf;
  // The month Overview was browsing when this was opened. Without it this
  // screen always showed the dataset's LATEST month — so tapping the savings
  // row while looking at April, or May, or any month but the newest one,
  // dropped you onto June's figures every time, no matter which month you'd
  // actually tapped from.
  final String initialKey;
  // 2026-08-27: the flat, unfiltered feed — the goal tracker below the rate
  // chart (Taupymo tikslas) needs raw dated rows for its own exact-date math,
  // which the rate chart's own month-bucketed callbacks above don't give it.
  final List<Map<String, dynamic>> all;

  @override
  State<_SavingsRateScreen> createState() => _SavingsRateScreenState();
}

class _SavingsRateScreenState extends State<_SavingsRateScreen> {
  // 2026-08-15: browsable — a left/right month switcher so "what was my
  // savings rate two months ago" doesn't require re-tapping in from a
  // different screen. Starts on the key the caller opened us with; moving
  // from there is purely local state, same pattern as the 6-month trend
  // chart below it.
  late String _curKey;

  @override
  void initState() {
    super.initState();
    // Falls back to the latest month only if the tapped-from key somehow
    // isn't in this list (stale data mid-refresh) — never silently defaults
    // to it otherwise, which is the bug this field exists to fix.
    _curKey = widget.monthKeys.contains(widget.initialKey)
        ? widget.initialKey
        : (widget.monthKeys.isNotEmpty
            ? widget.monthKeys.last
            : widget.initialKey);
    _savingsGoal = DashboardStore.savingsGoal();
  }

  // ── savings goal tracker ────────────────────────────────────────────────
  //
  // 2026-08-27: lives here (not a separate tab) per explicit request — this
  // screen already IS "where savings live" (the % club/streak card above),
  // so a goal-with-a-target belongs beside it rather than off in Planavimas
  // where nothing else about it connects. Does not touch monthKeys/savingsOf/
  // earnedOf/rowsOf or the chart built from them above — this section reads
  // widget.all directly and keeps its own entirely separate date math.
  //
  // Rework, per explicit correction: the first version bucketed by CALENDAR
  // month, so picking "today" as the start still summed the whole month —
  // including days of spending that happened BEFORE the goal existed.
  // Everything below filters by the exact start DATE (like a budget's own
  // "Nuo šiandien"), and buckets progress into rolling 30-day periods
  // anchored to that date, so day 1 already counts and the first period
  // completes ~30 days after starting — not at the next calendar 1st.
  Map<String, dynamic>? _savingsGoal;

  DateTime get _goalStart {
    final raw = _savingsGoal?['startDate'] as String?;
    return (raw != null ? DateTime.tryParse(raw) : null) ?? DateTime.now();
  }

  DateTime? _rowDate(Map t) => DateTime.tryParse(_dOf(t));

  /// Every real row dated on/after the goal's start — the ONLY rows any
  /// savings figure below is allowed to touch.
  List<Map<String, dynamic>> get _savingsRows {
    final start = DateTime(_goalStart.year, _goalStart.month, _goalStart.day);
    return widget.all.where((t) {
      final d = _rowDate(t);
      return d != null && !d.isBefore(start);
    }).toList();
  }

  /// Total saved from the exact start date through now.
  double get _totalSaved {
    final rows = _savingsRows;
    return _sumIncome(rows) - _sumExpenses(rows);
  }

  int get _daysSinceStart =>
      DateTime.now().difference(_goalStart).inDays.clamp(0, 1 << 30);

  static const _periodDays = 30;
  int get _completedPeriods => _daysSinceStart ~/ _periodDays;

  /// Net saved in one completed 30-day period since start (index 0 = the
  /// first 30 days). Only ever called for i < _completedPeriods.
  double _periodNet(int i) {
    final from = _goalStart.add(Duration(days: i * _periodDays));
    final to = _goalStart.add(Duration(days: (i + 1) * _periodDays));
    final rows = widget.all.where((t) {
      final d = _rowDate(t);
      return d != null && !d.isBefore(from) && d.isBefore(to);
    }).toList();
    return _sumIncome(rows) - _sumExpenses(rows);
  }

  /// Net saved so far in the CURRENT, still-running period — what the
  /// monthly-goal progress bar shows, so it moves from day 1 of that period
  /// rather than sitting at 0 until the period finishes.
  double get _currentPeriodNet {
    final from = _goalStart.add(Duration(days: _completedPeriods * _periodDays));
    final rows = widget.all.where((t) {
      final d = _rowDate(t);
      return d != null && !d.isBefore(from);
    }).toList();
    return _sumIncome(rows) - _sumExpenses(rows);
  }

  DateTime get _nextPeriodEnd =>
      _goalStart.add(Duration(days: (_completedPeriods + 1) * _periodDays));

  /// % of income saved, over completed periods (up to the last 6).
  double get _savingsGoalRate6mo {
    final n = _completedPeriods;
    if (n == 0) return 0;
    final from = n >= 6 ? n - 6 : 0;
    var income = 0.0, net = 0.0;
    for (var i = from; i < n; i++) {
      final periodFrom = _goalStart.add(Duration(days: i * _periodDays));
      final periodTo = _goalStart.add(Duration(days: (i + 1) * _periodDays));
      final rows = widget.all.where((t) {
        final d = _rowDate(t);
        return d != null && !d.isBefore(periodFrom) && d.isBefore(periodTo);
      }).toList();
      income += _sumIncome(rows);
      net += _sumIncome(rows) - _sumExpenses(rows);
    }
    return income > 0 ? (net / income * 100) : 0;
  }

  Future<void> _editSavingsGoal() async {
    final result = await showModalBottomSheet<Map<String, dynamic>>(
      context: context,
      isScrollControlled: true,
      backgroundColor: _card,
      shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
      builder: (_) => _SavingsGoalSheet(existing: _savingsGoal),
    );
    if (result == null) return;
    setState(() => _savingsGoal = result);
    await DashboardStore.setSavingsGoal(result);
  }

  Widget _savingsGoalSection() {
    if (_savingsGoal == null) return _savingsGoalEmpty();
    return Column(children: [
      _savingsGoalHero(),
      const SizedBox(height: 12),
      _savingsGoalTrendCard(),
      const SizedBox(height: 12),
      _savingsGoalCard(),
    ]);
  }

  Widget _savingsGoalEmpty() => Container(
        decoration: BoxDecoration(
            color: _card,
            borderRadius: BorderRadius.circular(18),
            border: Border.all(color: _hair),
            boxShadow: DS.e1),
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(18, 18, 18, 16),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(tr('Matyk, kiek realiai sutaupai'),
                  style: TextStyle(
                      fontSize: 17,
                      fontWeight: FontWeight.w800,
                      color: _ink,
                      height: 1.25)),
              const SizedBox(height: 8),
              Text(
                  tr('Nustatyk mėnesio ir bendrą taupymo tikslą — skaičiuosime iš tavo realių pajamų ir išlaidų.'),
                  style: TextStyle(fontSize: 14, color: _muted, height: 1.4)),
            ]),
          ),
          Divider(height: 1, thickness: 1, color: _hair),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 22),
            child: Column(children: [
              Container(
                width: 52,
                height: 52,
                alignment: Alignment.center,
                decoration:
                    BoxDecoration(color: _purpleSoft, shape: BoxShape.circle),
                child: Icon(Icons.savings_outlined, size: 26, color: _purple),
              ),
              const SizedBox(height: 12),
              Text(tr('Dar neturi taupymo tikslo'),
                  style: TextStyle(
                      fontSize: 16, fontWeight: FontWeight.w700, color: _ink)),
              const SizedBox(height: 16),
              GestureDetector(
                onTap: _editSavingsGoal,
                child: Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 20, vertical: 13),
                  decoration: BoxDecoration(
                      color: _purple, borderRadius: BorderRadius.circular(14)),
                  child: Text(tr('Nustatyti tikslą'),
                      style: const TextStyle(
                          fontSize: 15,
                          fontWeight: FontWeight.w800,
                          color: Colors.white)),
                ),
              ),
            ]),
          ),
        ]),
      );

  // Same off-center RadialGradient the Home hero and the agent banner use
  // (built from _purple/_purpleDeep, so it tracks dark mode automatically —
  // see _topBanner's own doc) so this reads as the same app, not a bolted-on
  // feature with its own colour language.
  //
  // 2026-08-27: the headline number used to be the LIVE running total from
  // day 1 — right after setting a goal it often read as a scary negative
  // (today's coffee already logged, no salary landed yet), which looks like
  // a verdict but isn't one; a single day is never representative. Per
  // explicit correction: this is a look-BACK number, not something to
  // watch tick during the day, so it only appears once the first 30-day
  // period has actually closed. The goal progress bars below stay live —
  // those are framed as "how far in", not "the result".
  Widget _savingsGoalHero() {
    final hasResult = _completedPeriods > 0;
    return Container(
      margin: const EdgeInsets.fromLTRB(0, 0, 0, 0),
      padding: const EdgeInsets.fromLTRB(20, 20, 20, 18),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(20),
        // 2026-08-29: same dark-mode treatment as the Home hero/agent
        // banner — a dark, faintly purple-tinted card instead of the full
        // gradient (one purple block too many, reported). Light mode keeps
        // its original gradient.
        color: _darkMode ? Color.lerp(_card, _purple, 0.07) : null,
        gradient: _darkMode
            ? null
            : RadialGradient(
                center: const Alignment(-0.7, -0.6),
                radius: 1.5,
                colors: [
                  _purple,
                  Color.lerp(_purpleDeep, const Color(0xFF05050A), 0.4)!,
                ],
                stops: const [0.0, 0.75],
              ),
        border: _darkMode
            ? Border.all(color: _purple.withValues(alpha: 0.35))
            : null,
        boxShadow: [
          BoxShadow(
              color: _purple.withValues(alpha: _darkMode ? 0.20 : 0.28),
              blurRadius: 20,
              offset: const Offset(0, 10)),
        ],
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Icon(Icons.savings_rounded,
              size: 18, color: Colors.white.withValues(alpha: 0.85)),
          const SizedBox(width: 7),
          Text(
              '${tr('Sutaupei nuo')} ${_shortDate(_goalStart.toIso8601String())}',
              style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                  color: Colors.white.withValues(alpha: 0.85))),
        ]),
        const SizedBox(height: 10),
        if (hasResult) ...[
          Text(_eur(_totalSaved),
              style: const TextStyle(
                  fontSize: 34,
                  fontWeight: FontWeight.w800,
                  color: Colors.white,
                  letterSpacing: -0.6)),
          const SizedBox(height: 6),
          Text(
              '${tr('Taupai')} ${_savingsGoalRate6mo.clamp(-999, 999).toStringAsFixed(1)}% ${tr('pajamų per pastaruosius 6 mėn.')}',
              style: TextStyle(
                  fontSize: 13.5,
                  fontWeight: FontWeight.w600,
                  color: Colors.white.withValues(alpha: 0.85))),
        ] else ...[
          Text(tr('Kaupiame pirmuosius duomenis'),
              style: const TextStyle(
                  fontSize: 22,
                  fontWeight: FontWeight.w800,
                  color: Colors.white,
                  letterSpacing: -0.3)),
          const SizedBox(height: 6),
          Text(
              '${tr('Pirmas rezultatas')} ${_shortDate(_nextPeriodEnd.toIso8601String())}',
              style: TextStyle(
                  fontSize: 13.5,
                  fontWeight: FontWeight.w600,
                  color: Colors.white.withValues(alpha: 0.85))),
        ],
      ]),
    );
  }

  Widget _savingsGoalTrendCard() {
    final n = _completedPeriods;
    // Up to the last 8 completed 30-day periods since the goal's own start —
    // never calendar months, so a chart legitimately appears the day the
    // FIRST period closes (~30 days in), not "whenever the next 1st is".
    final from = n > 8 ? n - 8 : 0;
    final points = [for (var i = from; i < n; i++) _periodNet(i)];
    return Container(
      padding: const EdgeInsets.fromLTRB(16, 16, 16, 12),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(16),
          boxShadow: DS.e1),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(tr('Taupymo tendencija'),
            style: TextStyle(
                fontSize: 14.5, fontWeight: FontWeight.w700, color: _ink)),
        const SizedBox(height: 12),
        SizedBox(
          height: 100,
          child: points.isEmpty
              ? Center(
                  child: Text(
                      '${tr('Pirmas laikotarpis baigsis')} ${_shortDate(_nextPeriodEnd.toIso8601String())} — ${tr('tada atsiras grafikas')}',
                      textAlign: TextAlign.center,
                      style: TextStyle(fontSize: 12.5, color: _muted)))
              : CustomPaint(
                  size: Size.infinite,
                  painter: _SavingsGoalTrendPainter(points, _purple)),
        ),
      ]),
    );
  }

  Widget _savingsGoalRowUi(
      {required String label, required double current, required double goal}) {
    final frac = goal > 0 ? (current / goal).clamp(0.0, 1.0) : 0.0;
    // 2026-09-01: real bug, found in audit — `frac` (the progress BAR) was
    // already floored at 0, but `pct` (the TEXT next to it) was not, so a
    // goal with negative net-since-start (spent more than earned) could
    // show e.g. "Įvykdyta -15%" next to a bar sitting visibly at 0% — text
    // and bar disagreeing. No upper clamp: exceeding the goal legitimately
    // shows e.g. 120%, which `over` already highlights in green below.
    final pct = goal > 0 ? math.max(0, (current / goal * 100).round()) : 0;
    final over = goal > 0 && current >= goal;
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [
        Text(label,
            style: TextStyle(
                fontSize: 13.5, fontWeight: FontWeight.w600, color: _muted)),
        const Spacer(),
        Text('${tr('Įvykdyta')} $pct%',
            style: TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w800,
                color: over ? _good : _purple)),
      ]),
      const SizedBox(height: 8),
      ClipRRect(
        borderRadius: BorderRadius.circular(6),
        child: LinearProgressIndicator(
          value: frac,
          minHeight: 8,
          backgroundColor: _hair,
          valueColor: AlwaysStoppedAnimation(over ? _good : _purple),
        ),
      ),
      const SizedBox(height: 6),
      Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
        Text(_eur0(current), style: TextStyle(fontSize: 13, color: _ink)),
        Text('${tr('Tikslas')} ${_eur0(goal)}',
            style: TextStyle(fontSize: 12.5, color: _muted)),
      ]),
    ]);
  }

  Widget _savingsGoalCard() {
    final goal = _savingsGoal!;
    final monthlyGoal = (goal['monthlyGoal'] as num?)?.toDouble() ?? 0;
    final totalGoal = (goal['totalGoal'] as num?)?.toDouble() ?? 0;
    final thisPeriod = _currentPeriodNet.clamp(0, double.infinity).toDouble();
    return Container(
      padding: const EdgeInsets.fromLTRB(16, 16, 16, 16),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(16),
          boxShadow: DS.e1),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Text(tr('Taupymo tikslas'),
              style: TextStyle(
                  fontSize: 14.5, fontWeight: FontWeight.w700, color: _ink)),
          const Spacer(),
          GestureDetector(
            onTap: _editSavingsGoal,
            child: Icon(Icons.edit_outlined, size: 18, color: _purple),
          ),
        ]),
        const SizedBox(height: 16),
        if (monthlyGoal > 0) ...[
          _savingsGoalRowUi(
              label: tr('Mėnesio tikslas'), current: thisPeriod, goal: monthlyGoal),
          const SizedBox(height: 18),
        ],
        if (totalGoal > 0)
          _savingsGoalRowUi(
              label: tr('Bendras tikslas'), current: _totalSaved, goal: totalGoal),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    final monthKeys = widget.monthKeys;
    final savingsOf = widget.savingsOf;
    final earnedOf = widget.earnedOf;
    final rowsOf = widget.rowsOf;
    if (monthKeys.isEmpty) {
      // A freshly-connected / empty account has no months yet — don't `.last` on
      // an empty list (StateError → red screen); show a neutral empty state.
      return Scaffold(
        backgroundColor: _bg,
        appBar:
            AppBar(backgroundColor: _bg, elevation: 0, foregroundColor: _ink),
        body: Center(
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Text(tr('Dar nėra duomenų.'),
                textAlign: TextAlign.center, style: TextStyle(color: _muted)),
          ),
        ),
      );
    }
    final curKey = _curKey;
    final curMon = _moInt(curKey);
    final rows = rowsOf(curKey);
    final earned = earnedOf(rows); // canonical income (matches Overview)
    final savings = savingsOf(rows);
    final prevKey = prevMonthKey(monthKeys, curKey);
    final prevMon = prevKey != null ? _moInt(prevKey) : 0;
    final prevRows =
        prevKey != null ? rowsOf(prevKey) : <Map<String, dynamic>>[];
    // 2026-09-01: real bug, found in audit — savingsOf (aka _savingsOf)
    // deliberately allows a NEGATIVE rate (an overspending month shouldn't
    // hide behind a flat 0%), but this value feeds the "santaupų klubas"
    // badge below — a gamification/achievement pill, same shape as
    // _clubBadge's own already-correct (0, 100) clamp elsewhere in this
    // file. Un-clamped here, an overspending previous month could show
    // "−45 % klubas", which reads as broken rather than "you overspent".
    final prevSavings = savingsOf(prevRows).clamp(0, 100);
    final prevStr = earnedOf(prevRows) > 0 ? '$prevSavings %' : '—';
    // Deliberately NOT relative to curKey: this is the user's overall
    // saving streak (consecutive completed months with a positive rate,
