/// Six months of savings rate as a line with an area under it.
///
/// It was six bars floating in an empty card: no zero line, no target, nothing
/// to say whether 28% is good. The lines here are the point — a baseline, and
/// the 20% target the explainer above already names as "a decent goal". A grid
/// that means nothing is just more ink.
class _SavingsTrendPainter extends CustomPainter {
  _SavingsTrendPainter({
    required this.points,
    required this.line,
    required this.good,
    required this.grid,
    required this.label,
    required this.faint,
  });

  /// (month label, rate %) oldest → newest.
  final List<(String, int)> points;
  final Color line, good, grid, label, faint;

  static const _target = 20; // the goal the explainer states
  static const _labelBand = 16.0; // room for the peak's figure
  static const _monthBand = 20.0; // room for the month names

  @override
  void paint(Canvas canvas, Size size) {
    if (points.isEmpty || size.width <= 0) return;
    final top = _labelBand;
    final bottom = size.height - _monthBand;
    final h = bottom - top;
    if (h <= 0) return;

    // Scale to the biggest of: the highest month, the target, or 30% — so a run
    // of poor months doesn't magnify a 2% bar into a mountain.
    final maxRate = points.map((p) => p.$2).fold(0, (a, b) => a > b ? a : b);
    final scaleMax =
        [maxRate, _target, 30].reduce((a, b) => a > b ? a : b) * 1.15;
    // Clamped to [top, bottom] — a very negative month (e.g. -100%) must
    // rest on the zero baseline, not plunge off the bottom of the card.
    double y(num pct) => (bottom - (pct / scaleMax) * h).clamp(top, bottom);
    double x(int i) => points.length == 1
        ? size.width / 2
        : (size.width - 24) * i / (points.length - 1) + 12;

    // Baseline.
    canvas.drawLine(
        Offset(0, bottom),
        Offset(size.width, bottom),
        Paint()
          ..color = grid
          ..strokeWidth = 1);

    // Target, dashed, with its own label — the one number that makes the rest
    // readable.
    final ty = y(_target);
    final dash = Paint()
      ..color = good.withValues(alpha: 0.55)
      ..strokeWidth = 1;
    for (double dx = 0; dx < size.width - 62; dx += 8) {
      canvas.drawLine(Offset(dx, ty), Offset(dx + 4, ty), dash);
    }
    final tp = TextPainter(
      text: TextSpan(
          text: 'tikslas $_target %',
          style: TextStyle(
              fontSize: 9.5, fontWeight: FontWeight.w700, color: good)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(size.width - tp.width, ty - tp.height - 2));

    // The line itself.
    final path = Path()..moveTo(x(0), y(points.first.$2));
    for (var i = 1; i < points.length; i++) {
      path.lineTo(x(i), y(points[i].$2));
    }
    final area = Path.from(path)
      ..lineTo(x(points.length - 1), bottom)
      ..lineTo(x(0), bottom)
      ..close();
    canvas.drawPath(
        area,
        Paint()
          ..shader = ui.Gradient.linear(
            Offset(0, top),
            Offset(0, bottom),
            [line.withValues(alpha: 0.26), line.withValues(alpha: 0.0)],
          ));
    canvas.drawPath(
        path,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 2.2
          ..strokeJoin = StrokeJoin.round
          ..color = line);

    // Only the best month carries a figure; the rest are read off the target.
    final peak = points.indexWhere((p) => p.$2 == maxRate);
    for (var i = 0; i < points.length; i++) {
      final o = Offset(x(i), y(points[i].$2));
      final isPeak = i == peak && maxRate > 0;
      canvas.drawCircle(
          o, isPeak ? 3.6 : 2.2, Paint()..color = isPeak ? good : line);
      if (isPeak) {
        final lp = TextPainter(
          text: TextSpan(
              text: '${points[i].$2} %',
              style: TextStyle(
                  fontSize: 11, fontWeight: FontWeight.w800, color: good)),
          textDirection: TextDirection.ltr,
        )..layout();
        lp.paint(
            canvas,
            Offset((o.dx - lp.width / 2).clamp(0.0, size.width - lp.width),
                o.dy - lp.height - 6));
      }
      final mp = TextPainter(
        text: TextSpan(
            text: points[i].$1, style: TextStyle(fontSize: 11, color: faint)),
        textDirection: TextDirection.ltr,
      )..layout();
      mp.paint(
          canvas,
          Offset((o.dx - mp.width / 2).clamp(0.0, size.width - mp.width),
              bottom + 5));
    }
  }

  @override
  bool shouldRepaint(_SavingsTrendPainter old) => old.points != points;
}

// ══════════════════════════════════════════════════════════════════════════════
// PLANNING TAB — budgets (data-suggested limits) + recurring
// ══════════════════════════════════════════════════════════════════════════════
class _Budget {
  _Budget(this.sec, this.limit);
  final String sec;
  double limit;
  bool? auto; // true = we suggested the limit from history; false = user-set
  bool get isAuto => auto ?? true; // null (hot-reload) → treat as suggested
  // When set, spend is only counted from this date forward — but only within
  // the calendar month it falls in (a mid-month budget shouldn't blame the
  // user for days before it existed). Any other viewed month (past or
  // future) counts in full, same as a budget with no start date at all.
  DateTime? startDate;
}

/// Set by the planning tab while the demo runs, so the walkthrough opens the
/// add-budget sheet through the button's own handler rather than a copy.
VoidCallback? _demoAddBudget;
final GlobalKey _kAddBudget = GlobalKey();

class _PlanningTab extends StatefulWidget {
  const _PlanningTab(
      {required this.all,
      required this.subs,
      this.demo = false,
      this.onVerdictChanged});
  final List<Map<String, dynamic>> all;
  final Map<String, dynamic> subs;

  /// Answering a review here also changes what Home shows. Home is not in the
  /// cached tab list, so it does not rebuild on its own — without this the badge
  /// on the dashboard kept its old count after the questions were answered.
  final VoidCallback? onVerdictChanged;

  /// Onboarding walkthrough: publish the add-budget handler and key.
  final bool demo;
  @override
  State<_PlanningTab> createState() => _PlanningTabState();
}

class _PlanningTabState extends State<_PlanningTab> {
  @override
  void dispose() {
    if (widget.demo && _demoAddBudget == _openAddSheet) _demoAddBudget = null;
    super.dispose();
  }

  late List<_Budget> _budgets;
  bool _showBanner = true;
  String? _selKey; // selected month (null = latest / "Šis mėnuo")

  // ── month scope ────────────────────────────────────────────────────────────
  List<String> get _monthKeys {
    final s = widget.all.map((t) => _ymOf(t)).toSet().toList()..sort();
    return s;
  }

  String get _curKey {
    final keys = _monthKeys;
    if (_selKey != null && keys.contains(_selKey)) return _selKey!;
    if (keys.isNotEmpty) return keys.last;
    // No transactions yet → fall back to the current calendar month so month math
    // never indexes an empty list.
    final n = DateTime.now();
    return '${n.year}-${n.month.toString().padLeft(2, '0')}';
  }

  int get _curMon => _moInt(_curKey);
  int get _curYear => int.parse(_curKey.substring(0, 4));
  List<Map<String, dynamic>> get _rows =>
      widget.all.where((t) => _dOf(t).startsWith(_curKey)).toList();

  int get _daysInMonth => DateTime(_curYear, _curMon + 1, 0).day;
  int get _elapsedDays {
    final now = DateTime.now();
    final curCal = '${now.year}-${now.month.toString().padLeft(2, '0')}';
    // Current month → days elapsed so far; earlier month → full month.
    if (_curKey == curCal) return now.day.clamp(1, _daysInMonth);
    return _daysInMonth;
  }

  // section label → colour key / icon (looked up from any tx in that section)
  final Map<String, String> _secColorKey = {};
  Color _colorOfSec(String sec) => _secColor[_secColorKey[sec]] ?? _muted;
  IconData _iconOfSec(String sec) => _secIcon[_secToIcon[sec]] ?? Icons.circle;

  // expenses only (positive €) in a section, over an arbitrary row set
  double _spentInSec(Iterable<Map<String, dynamic>> rows, String sec) => rows
      .where((t) => t['sec'] == sec && _aOf(t) < 0)
      .fold(0.0, (s, t) => s - _aOf(t).toDouble());

  // Whether a transaction dated `dateStr` (yyyy-MM-dd) counts toward budget
  // `b`, respecting its optional start date (see _Budget.startDate).
  bool _budgetCountsOn(_Budget b, String dateStr) {
    final sd = b.startDate;
    if (sd == null) return true;
    final sdYmd = _DashboardPreviewState._ymd(sd);
    if (sdYmd.substring(0, 7) != _curKey) return true;
    return dateStr.compareTo(sdYmd) >= 0;
  }

  // `_rows`, clipped to a budget's start date when it falls in the viewed month.
  Iterable<Map<String, dynamic>> _rowsForBudget(_Budget b) {
    if (b.startDate == null) return _rows;
    return _rows.where((t) => _budgetCountsOn(b, _dOf(t)));
  }

  // data-suggested monthly limit = a TYPICAL month + a little headroom.
  // Uses the median of complete months (robust to one-off spikes); if the section
  // only appears in the current partial month, extrapolates it to full-month pace.
  double _suggestLimit(String sec) {
    final months = _monthKeys;
    if (months.isEmpty) return 100;
    // complete months = everything except the current (partial) latest month
    final complete =
        months.length > 1 ? months.sublist(0, months.length - 1) : months;
    final vals = <double>[];
    for (final mk in complete) {
      final v =
          _spentInSec(widget.all.where((t) => _dOf(t).startsWith(mk)), sec);
      if (v > 0) vals.add(v);
    }
    double typical;
    if (vals.isEmpty) {
      final cur = _spentInSec(_rows, sec);
      typical = _elapsedDays > 0 ? cur / _elapsedDays * _daysInMonth : cur;
    } else {
      vals.sort();
      typical = vals[vals.length ~/ 2]; // median
    }
    final withHead = typical * 1.15; // ~15% headroom so a normal month fits
    if (withHead < 5) return 20;
    final step = withHead < 100 ? 10 : (withHead < 500 ? 25 : 50);
    return math.max(
        step.toDouble(), (withHead / step).ceil() * step.toDouble());
  }

  @override
  void initState() {
    super.initState();
    // Hand the demo director this tab's own add-budget handler.
    if (widget.demo) _demoAddBudget = _openAddSheet;
    for (final t in widget.all) {
      _secColorKey.putIfAbsent(_secOf(t), () => _seccOf(t));
    }
    // fallback colours for taxonomy sections the user has no transactions in yet
    for (final e in _taxonomy) {
      _secColorKey.putIfAbsent(e['sec'] as String, () => e['c'] as String);
    }
    // No budgets are created for the user — auto-creating them confused people
    // ("where did this limit come from?"). The add sheet offers a data-based
    // suggested limit (median of real spend) to accept or edit. What IS loaded
    // is whatever they set previously: this used to be a bare `[]`, so every
    // budget they created vanished the moment they left the screen.
    _budgets = [
      for (final b in DashboardStore.budgets())
        if (b['sec'] is String && b['limit'] is num)
          (_Budget(b['sec'] as String, (b['limit'] as num).toDouble())
            ..auto = b['auto'] as bool?
            ..startDate = b['startDate'] is String
                ? DateTime.tryParse(b['startDate'] as String)
                : null),
    ];
  }

  /// Persists the current budgets. Called after every add, edit and delete —
  /// there is no "save" button, so each change is the save.
  void _saveBudgets() {
    DashboardStore.setBudgets([
      for (final b in _budgets)
        {
          'sec': b.sec,
          'limit': b.limit,
          'auto': b.auto,
          'startDate': b.startDate?.toIso8601String(),
        },
    ]);
  }

  // pace-aware colour: red if already over, orange if trending over, else green
  Color _pace(double spent, double limit) {
    if (spent > limit) return const Color(0xFFE0574F);
    final projected =
        _elapsedDays > 0 ? spent / _elapsedDays * _daysInMonth : spent;
    if (projected > limit) return const Color(0xFFEE7A3A);
    return _good;
  }

  @override
  Widget build(BuildContext context) {
    final spentSoFar = _budgets.fold(
        0.0, (s, b) => s + _spentInSec(_rowsForBudget(b), b.sec));
    final totalLimit = _budgets.fold(0.0, (s, b) => s + b.limit);

    return SafeArea(
      bottom: false,
      child: ListView(
        padding: const EdgeInsets.only(bottom: 28),
        children: [
          _header(),
          // Taupymo tikslas moved out to _SavingsRateScreen (2026-08-27, per
          // request) — same screen the existing "Santaupų norma" % club/
          // streak card already opens, so both savings-related things live
          // in one place instead of split across two tabs.
          _monthFilter(),
          _sectionTitle('Biudžetai'),
          if (_budgets.isEmpty)
            // One self-contained card: intro + empty state + the add action.
            _budgetsEmpty()
          else ...[
            if (_showBanner) _banner(),
            _summaryCard(spentSoFar, totalLimit),
            for (final b in _budgets) _budgetRow(b),
            _addButton(),
          ],
          const SizedBox(height: 12),
        ],
      ),
    );
  }

