  // ── summary card: spent-so-far / total + projection area chart ───────────────
  Widget _summaryCard(double spent, double limit) {
    final pct = limit > 0 ? (spent / limit * 100).round() : 0;
    final secToBudget = {for (final b in _budgets) b.sec: b};
    // cumulative daily spend across all budgeted sections, day 1..today —
    // a section only starts counting once its own budget's start date hits.
    final cum = <double>[];
    var run = 0.0;
    for (var day = 1; day <= _elapsedDays; day++) {
      final ds = '$_curKey-${day.toString().padLeft(2, '0')}';
      run += _rows
          .where((t) {
            final b = secToBudget[t['sec']];
            return ds == t['d'] &&
                b != null &&
                _aOf(t) < 0 &&
                _budgetCountsOn(b, ds);
          })
          .fold(0.0, (s, t) => s - _aOf(t).toDouble());
      cum.add(run);
    }
    final projected = _elapsedDays > 0 && cum.isNotEmpty
        ? cum.last / _elapsedDays * _daysInMonth
        : 0.0;
    final onTrack = projected <= limit;

    return Container(
      margin: const EdgeInsets.fromLTRB(16, 0, 16, 12),
      padding: const EdgeInsets.fromLTRB(16, 16, 16, 14),
      decoration: BoxDecoration(
          color: _card,
          borderRadius: BorderRadius.circular(16),
          boxShadow: DS.e1),
      child: Column(children: [
        Row(crossAxisAlignment: CrossAxisAlignment.center, children: [
          Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(_eur(spent),
                style: TextStyle(
                    fontSize: 21,
                    fontWeight: FontWeight.w800,
                    color: _ink,
                    letterSpacing: -0.4)),
            Text(tr('išleista'), style: TextStyle(fontSize: 13, color: _muted)),
          ]),
          const Spacer(),
          // The ring sits between two big amounts; drawn at a fixed size it got
          // swallowed by them the moment the text around it scaled up. Tie it to
          // the same scale so the trio keeps its proportions.
          Builder(builder: (ctx) {
            final d = MediaQuery.textScalerOf(ctx).scale(62).clamp(62.0, 104.0);
            return SizedBox(
              width: d,
              height: d,
              child: Stack(alignment: Alignment.center, children: [
                CustomPaint(
                    size: Size(d, d),
                    painter: _RingProgressPainter(
                        pct / 100, onTrack ? _good : const Color(0xFFEE7A3A))),
                Text('$pct%',
                    style: TextStyle(
                        fontSize: 14,
                        fontWeight: FontWeight.w800,
                        color: _ink)),
              ]),
            );
          }),
          const Spacer(),
          Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
            Text(_eur(limit),
                style: TextStyle(
                    fontSize: 21,
                    fontWeight: FontWeight.w800,
                    color: _ink,
                    letterSpacing: -0.4)),
            Text(tr('visas biudžetas'),
                style: TextStyle(fontSize: 13, color: _muted)),
          ]),
        ]),
        const SizedBox(height: 16),
        SizedBox(
          height: 118,
          child: CustomPaint(
            size: Size.infinite,
            painter: _BudgetProjPainter(
                cum: cum,
                limit: limit,
                daysInMonth: _daysInMonth,
                elapsed: _elapsedDays,
                projected: projected,
                onTrack: onTrack),
          ),
        ),
        const SizedBox(height: 6),
        Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
          Text('1', style: TextStyle(fontSize: 12, color: _muted)),
          Text('8', style: TextStyle(fontSize: 12, color: _muted)),
          Text('16', style: TextStyle(fontSize: 12, color: _muted)),
          Text('24', style: TextStyle(fontSize: 12, color: _muted)),
        ]),
        const SizedBox(height: 8),
        Text(
          onTrack
              ? '${tr('Tokiu tempu mėnesį baigsi ~')}${_eur0(projected)} ${tr('— telpi į biudžetą.')}'
              : '${tr('Tokiu tempu peršoksi biudžetą ~')}${_eur0(projected - limit)} ${tr('— sulėtink.')}',
          style: TextStyle(
              fontSize: 13.5,
              fontWeight: FontWeight.w600,
              color: onTrack ? _good : const Color(0xFFEE7A3A)),
        ),
      ]),
    );
  }

  // ── one budget row: name + limit, spent/left, paced progress bar ─────────────
  Widget _budgetRow(_Budget b) {
    final spent = _spentInSec(_rowsForBudget(b), b.sec);
    final left = b.limit - spent;
    final frac = b.limit > 0 ? (spent / b.limit).clamp(0.0, 1.0) : 0.0;
    final col = _pace(spent, b.limit);
    return GestureDetector(
      onTap: () => _editBudget(b),
      child: Container(
        margin: const EdgeInsets.fromLTRB(16, 0, 16, 10),
        padding: const EdgeInsets.fromLTRB(14, 14, 14, 14),
        decoration: BoxDecoration(
            color: _card,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: _hair)),
        child: Column(children: [
          Row(children: [
            CategoryIcon(
                icon: _iconOfSec(b.sec), color: _colorOfSec(b.sec), size: 40),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(tr(b.sec),
                        style: TextStyle(
                            fontSize: 16.5,
                            fontWeight: FontWeight.w700,
                            color: _ink)),
                    Text(
                        b.startDate != null &&
                                _DashboardPreviewState._ymd(b.startDate!)
                                        .substring(0, 7) ==
                                    _curKey
                            ? '${tr('Nuo')} ${b.startDate!.day.toString().padLeft(2, '0')}.${b.startDate!.month.toString().padLeft(2, '0')} · ${tr('keisk')}'
                            : (b.isAuto
                                ? tr('Pasiūlyta pagal tavo išlaidas · keisk')
                                : tr('Tavo biudžetas · keisk')),
                        style: TextStyle(fontSize: 11.5, color: _muted)),
                  ]),
            ),
            Text(_eur(b.limit),
                style: TextStyle(
                    fontSize: 16.5, fontWeight: FontWeight.w800, color: _ink)),
            const SizedBox(width: 3),
            Icon(Icons.edit_rounded, size: 15, color: _faint),
          ]),
          const SizedBox(height: 10),
          Row(children: [
            Text('${_eur(spent)} ${tr('išleista')}',
                style: TextStyle(fontSize: 13.5, color: _muted)),
            const Spacer(),
            Text(
              left >= 0
                  ? '${_eur(left)} ${tr('liko')}'
                  : '${_eur(-left)} ${tr('virš pasiūlymo')}',
              style: TextStyle(
                  fontSize: 13.5, fontWeight: FontWeight.w700, color: col),
            ),
          ]),
          const SizedBox(height: 8),
          ClipRRect(
            borderRadius: BorderRadius.circular(6),
            child: Stack(children: [
              Container(height: 9, color: col.withValues(alpha: 0.14)),
              FractionallySizedBox(
                  widthFactor: frac, child: Container(height: 9, color: col)),
            ]),
          ),
        ]),
      ),
    );
  }

