// ACCOUNT TAB — net worth, assets, accounts (real balance data) + Settings
// ══════════════════════════════════════════════════════════════════════════════
class _AccountTab extends StatefulWidget {
  const _AccountTab({required this.balance, this.allTransactions});
  final Map<String, dynamic> balance;
  // Threaded through to _SettingsScreen so export uses the dashboard's live
  // data instead of DashboardStore.load()'s separate disk snapshot.
  final List<Map>? allTransactions;
  @override
  State<_AccountTab> createState() => _AccountTabState();
}

class _AccountTabState extends State<_AccountTab> {
  bool _promo = true;
  late List<Map<String, dynamic>> _assets = DashboardStore.manualAssets();

  // Bank balance = the live truth from Enable Banking (never touched by cash).
  double get _bankBalance =>
      ((widget.balance['current'] ?? 0) as num).toDouble();
  // Manually-added cash / savings the bank can't see.
  double get _assetsSum =>
      _assets.fold(0.0, (s, a) => s + ((a['amount'] as num?)?.toDouble() ?? 0));
  // Net worth = bank + cash. Spending analytics still use the bank balance only.
  double get _netWorth => _bankBalance + _assetsSum;
  List<Map<String, dynamic>> get _accounts =>
      ((widget.balance['accounts'] as List?) ?? const [])
          .cast<Map<String, dynamic>>();

  void _soon() => _snack(tr('Netrukus'));

  void _snack(String m) => ScaffoldMessenger.of(context)
    ..hideCurrentSnackBar()
    ..showSnackBar(SnackBar(
        content: Text(m), duration: const Duration(milliseconds: 3300)));

  @override
  Widget build(BuildContext context) {
    final spark =
        _cleanSeries(widget.balance['series']).map((p) => _vOf(p)).toList();
    // sub-sample the 245-pt series for a light sparkline
    final step = (spark.length / 60).ceil().clamp(1, 999);
    final thin = [for (var i = 0; i < spark.length; i += step) spark[i]];

    return SafeArea(
      bottom: false,
      child: ListView(
        padding: const EdgeInsets.only(bottom: 28),
        children: [
          _header(),
          _settingsRow(),
          // 2026-08-31: removed per explicit request — this promoted adding
          // arbitrary asset types (real estate, loans, ...) through the same
          // generic _assetDialog the "+ Pridėti grynų ar santaupų" row
          // below used to open. Now that "Grynieji" is its own dedicated,
          // purpose-built feature (Home hero button, receipt scan, manual
          // entry, its own onboarding), a generic "add any savings" surface
          // right next to it invited a second, conflicting way to create
          // cash-like entries — see _assetsCard's own note just below.
          _netWorthCard(),
          _assetsCard(),
          _totalBalanceCard(thin),
          _accountsCard(),
          _feedbackCard(),
        ],
      ),
    );
  }

  Widget _header() => Padding(
        padding: const EdgeInsets.fromLTRB(16, 6, 16, 12),
        child: Row(children: [
          Text(tr('Paskyra'),
              style: TextStyle(
                  fontSize: 30,
                  fontWeight: FontWeight.w800,
                  color: _ink,
                  letterSpacing: -0.5)),
        ]),
      );

  Widget _settingsRow() => Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
        child: GestureDetector(
          onTap: () => Navigator.of(context).push(MaterialPageRoute(
              builder: (_) =>
                  _SettingsScreen(liveTransactions: widget.allTransactions))),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
            decoration: BoxDecoration(
