  Future<void> _assetDialog({int? index}) async {
    final editing = index != null;
    final a = editing ? _assets[index] : null;
    // Assets are stored in EUR; show/enter them in the display currency.
    final amtDisp = ((a?['amount'] as num?) ?? 0).toDouble() * Money.rate;
    final amountCtl = TextEditingController(
        text: a != null
            ? (amtDisp == amtDisp.roundToDouble()
                ? amtDisp.toStringAsFixed(0)
                : amtDisp.toStringAsFixed(2))
            : '');
    final labelCtl =
        TextEditingController(text: (a?['label'] as String?) ?? '');
    final saved = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: _card,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
        title: Text(editing ? tr('Redaguoti') : tr('Pridėti grynų ar santaupų'),
            style: TextStyle(
                color: _ink, fontWeight: FontWeight.w700, fontSize: 18)),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          TextField(
            controller: amountCtl,
            autofocus: true,
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            style: TextStyle(
                color: _ink, fontSize: 22, fontWeight: FontWeight.w700),
            decoration: InputDecoration(
              prefixText: '${Money.symbol} ',
              prefixStyle: TextStyle(
                  color: _ink, fontSize: 22, fontWeight: FontWeight.w700),
              hintText: '0',
              hintStyle: TextStyle(color: _faint),
            ),
          ),
          const SizedBox(height: 10),
          TextField(
            controller: labelCtl,
            style: TextStyle(color: _ink),
            decoration: InputDecoration(
              hintText: tr('Pavadinimas (pvz. Grynieji, Santaupos)'),
              hintStyle: TextStyle(color: _faint),
            ),
          ),
        ]),
        actions: [
          if (editing)
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: Text(tr('Ištrinti'),
                    style: const TextStyle(
                        color: Color(0xFFD1453B),
                        fontWeight: FontWeight.w600))),
          TextButton(
              onPressed: () => Navigator.pop(ctx, null),
              child: Text(tr('Atšaukti'), style: TextStyle(color: _muted))),
          TextButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: Text(tr('Išsaugoti'),
                  style:
                      TextStyle(color: _purple, fontWeight: FontWeight.w700))),
        ],
      ),
    );
    if (saved == false && editing) {
      // "Ištrinti" → remove this asset.
      setState(() => _assets = [..._assets]..removeAt(index));
      await DashboardStore.setManualAssets(_assets);
      return;
    }
    if (saved != true) return; // cancelled
    final amount = double.tryParse(amountCtl.text
            .replaceAll('€', '')
            .replaceAll(Money.symbol, '')
            .replaceAll(',', '.')
            .trim()) ??
        0;
    if (amount <= 0) return;
    final label = labelCtl.text.trim();
    setState(() {
      final entry = <String, dynamic>{
        'id': a?['id'] ?? DateTime.now().microsecondsSinceEpoch.toString(),
        'label': label.isEmpty ? 'Grynieji' : label,
        // Typed in the display currency; store EUR so it round-trips everywhere.
        'amount': Money.rate > 0 ? amount / Money.rate : amount,
      };
      if (editing) {
        _assets[index] = entry;
      } else {
        _assets = [..._assets, entry];
      }
    });
    await DashboardStore.setManualAssets(_assets);
  }

