  // Prefers the live `_d['all']` the dashboard passed in — the exact data the
  // user is looking at — over DashboardStore.load()'s separate disk snapshot,
  // which can lag behind (a fresh scan or a local edit updates `_d`
  // immediately but persists to Hive on its own schedule). Exporting from the
  // stale copy is what caused "no transactions" while the dashboard clearly
  // had 130 of them. Falls back to disk only if this screen was somehow
  // reached without the live list.
  List<Map> _exportRows() {
    final live = widget.liveTransactions;
    final all = (live != null && live.isNotEmpty)
        ? live
        : ((DashboardStore.load()?['all'] as List?) ?? const [])
            .whereType<Map>()
            .toList();
    return List<Map>.from(all)
      ..sort((a, b) =>
          (b['d'] ?? '').toString().compareTo((a['d'] ?? '').toString()));
  }

  Future<void> _exportPdf() async {
    final rows = _exportRows();
    if (rows.isEmpty) {
      _snack(tr('Nėra sandorių eksportui'));
      return;
    }
    try {
      // Load Lato (bundled) so Lithuanian diacritics render — the PDF built-in
      // fonts don't cover ą/č/ę/ė/į/š/ų/ū/ž.
      final base =
          pw.Font.ttf(await rootBundle.load('assets/fonts/Lato-Regular.ttf'));
      final bold =
          pw.Font.ttf(await rootBundle.load('assets/fonts/Lato-Bold.ttf'));
      final doc = pw.Document();
      final total = rows.fold<double>(
          0, (s, t) => s + ((t['a'] as num?)?.toDouble() ?? 0));
      doc.addPage(pw.MultiPage(
        pageFormat: PdfPageFormat.a4,
        theme: pw.ThemeData.withFont(base: base, bold: bold),
        build: (ctx) => [
          pw.Text(tr('Vaultie — sandoriai'),
              style: pw.TextStyle(
                  fontSize: 20,
                  fontWeight: pw.FontWeight.bold,
                  color: PdfColor.fromInt(0xFF2F6BFF))),
          pw.SizedBox(height: 4),
          pw.Text(
              '${rows.length} ${tr('sandorių')} · ${tr('bendra suma')} ${total.toStringAsFixed(2)} €',
              style:
                  const pw.TextStyle(fontSize: 10, color: PdfColors.grey700)),
          pw.SizedBox(height: 14),
          pw.TableHelper.fromTextArray(
            headers: [
              tr('Data'),
              tr('Pavadinimas'),
              tr('Suma €'),
              tr('Kategorija')
            ],
            data: [
              for (final t in rows)
                [
                  (t['d'] ?? '').toString(),
                  (t['nm'] ?? '').toString(),
                  ((t['a'] as num?)?.toStringAsFixed(2) ?? ''),
                  (t['sec'] ?? '').toString(),
                ],
            ],
            headerStyle: pw.TextStyle(
                fontSize: 9,
                fontWeight: pw.FontWeight.bold,
                color: PdfColors.white),
            headerDecoration:
                const pw.BoxDecoration(color: PdfColor.fromInt(0xFF2F6BFF)),
            cellStyle: const pw.TextStyle(fontSize: 8.5),
            cellAlignments: {2: pw.Alignment.centerRight},
            oddRowDecoration:
                const pw.BoxDecoration(color: PdfColor.fromInt(0xFFF2F5FA)),
            columnWidths: {
              0: const pw.FlexColumnWidth(1.4),
              1: const pw.FlexColumnWidth(3),
              2: const pw.FlexColumnWidth(1.2),
              3: const pw.FlexColumnWidth(2),
            },
          ),
        ],
      ));
      final dir = await getTemporaryDirectory();
      final file = File('${dir.path}/vaultie_sandoriai.pdf');
      await file.writeAsBytes(await doc.save());
      await SharePlus.instance.share(
        ShareParams(files: [XFile(file.path)], subject: 'Vaultie sandoriai'),
      );
    } catch (_) {
      if (mounted) _snack(tr('Nepavyko eksportuoti'));
    }
  }

  Future<void> _exportCsv() async {
    // Same source/fallback as _exportRows() (unsorted order is fine for CSV).
    final all = _exportRows();
    if (all.isEmpty) {
      _snack(tr('Nėra sandorių eksportui'));
      return;
    }
    String cell(Object? v) {
      final s = (v ?? '').toString().replaceAll('"', '""');
      return '"$s"';
    }

    final buf = StringBuffer(
        '${tr('Data')},${tr('Pavadinimas')},${tr('Suma')},${tr('Kategorija')},${tr('Pakategorė')}\n');
    final rows = List<Map>.from(all)
      ..sort((a, b) =>
          (b['d'] ?? '').toString().compareTo((a['d'] ?? '').toString()));
    for (final t in rows) {
      buf.writeln([
        cell(t['d']),
        cell(t['nm']),
        cell((t['a'] as num?)?.toStringAsFixed(2) ?? ''),
        cell(t['sec']),
        cell(t['sub']),
      ].join(','));
    }
    try {
      final dir = await getTemporaryDirectory();
      final file = File('${dir.path}/vaultie_sandoriai.csv');
      await file.writeAsString(buf.toString());
      await SharePlus.instance.share(
        ShareParams(files: [XFile(file.path)], subject: 'Vaultie sandoriai'),
      );
    } catch (_) {
      if (mounted) _snack(tr('Nepavyko eksportuoti'));
    }
  }

  Future<void> _sendFeedback() async {
    final uri = Uri(
      scheme: 'mailto',
      path: 'support@vaultieapp.com',
      queryParameters: {'subject': 'Vaultie atsiliepimas'},
    );
    try {
      if (!await launchUrl(uri, mode: LaunchMode.externalApplication)) {
        if (mounted) _snack(tr('Parašyk mums: support@vaultieapp.com'));
      }
    } catch (_) {
      if (mounted) _snack(tr('Parašyk mums: support@vaultieapp.com'));
    }
  }

